INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'En el principio creó Dios los cielos y la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Y la tierra estaba desadornada y vacía; y las tinieblas estaban sobre la haz del abismo: y el Espíritu de Dios se movía sobre la haz de las aguas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Y dijo Dios: Sea la luz: y fue la luz.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Y vio Dios que la luz era buena: y apartó Dios a la luz de las tinieblas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Y llamó Dios a la luz Día; y a las tinieblas llamó Noche: y fue la tarde y la mañana un día.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Y dijo Dios: Sea un extendimiento en medio de las aguas, y haga apartamiento entre aguas y aguas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'E hizo Dios un extendimiento, y apartó las aguas que están debajo del extendimiento, de las aguas que están sobre el extendimiento: y fue así.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Y llamó Dios al extendimiento Cielos: y fue la tarde y la mañana el día segundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Y dijo Dios: Júntense las aguas que están debajo de los cielos en un lugar, y descúbrase la seca: y fue así.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Y llamó Dios a la seca, Tierra; y al juntamiento de las aguas llamó Mares: y vio Dios que era bueno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Y dijo Dios: Produzca la tierra yerba verde, yerba que haga simiente: árbol de fruto que haga fruto según su naturaleza, que su simiente esté en él sobre la tierra: y fue así.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Y produjo la tierra yerba verde, yerba que hace simiente según su naturaleza, y árbol que hace fruto, que su simiente está en él según su naturaleza: y vio Dios que era bueno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Y fue la tarde y la mañana el día tercero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, '¶ Y dijo Dios: Sean luminares en el extendimiento de los cielos para apartar el día y la noche: y sean por señales, y por tiempos determinados, y por días y años:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Y sean por luminares en el extendimiento de los cielos para alumbrar sobre la tierra: y fue así.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'E hizo Dios los dos luminares grandes: el luminar grande para que señorease en el día, y el luminar pequeño para que señorease en la noche, y las estrellas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Y púsolos Dios en el extendimiento de los cielos, para alumbrar sobre la tierra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'Y para señorear en el día y en la noche, y para apartar la luz y las tinieblas: y vio Dios que era bueno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Y fue la tarde y la mañana el día cuarto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, '¶ Y dijo Dios: Produzcan las aguas reptil de ánima viviente, y aves que vuelen sobre la tierra, sobre la haz del extendimiento de los cielos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Y creó Dios las grandes ballenas, y toda cosa viva, que anda arrastrando, que las aguas produjeron según sus naturalezas: y toda ave de alas según su naturaleza: y vio Dios que era bueno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Y bendíjolos Dios, diciendo: Fructificad y multiplicad, y henchíd las aguas en las mares; y las aves se multipliquen en la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Y fue la tarde y la mañana el día quinto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, '¶ Y dijo Dios: Produzca la tierra ánima viviente según su naturaleza, bestias, y serpientes, y animales de la tierra según su naturaleza: y fue así.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'E hizo Dios animales de la tierra según su naturaleza y bestias según su naturaleza; y todas serpientes de la tierra según su naturaleza: y vio Dios que era bueno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, '¶ Y dijo Dios: Hagamos al hombre a nuestra imagen, conforme a nuestra semejanza; y señoreen en los peces de la mar, y en las aves de los cielos, y en las bestias, y en toda la tierra, y en toda serpiente que anda arrastrando sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Y creó Dios al hombre a su imagen, a imagen de Dios le creó: macho y hembra los creó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Y bendíjolos Dios, y díjoles Dios: Fructificad y multiplicad, y henchíd la tierra, y sojuzgadla, y señoread en los peces de la mar, y en las aves de los cielos, y en todas las bestias, que se mueven sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Y dijo Dios: He aquí, os he dado toda yerba que hace simiente, que está sobre la haz de toda la tierra: y todo árbol en que hay fruto de árbol que haga simiente, seros ha para comer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Y a toda bestia de la tierra, y a todas las aves de los cielos, y a todo lo que se mueve sobre la tierra en que hay ánima viviente; toda verdura de yerba será para comer. Y fue así.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Y vio Dios todo lo que había hecho, y he aquí que era bueno en gran manera: y fue la tarde y la mañana el día sexto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Y fueron acabados los cielos y la tierra, y todo el ejército de ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Y acabó Dios en el día séptimo su obra que hizo, y reposó el día séptimo de toda su obra que había hecho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Y bendijo Dios al día séptimo, y santificóle: porque en él reposó de toda su obra que había creado Dios para hacer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Estos son los orígenes de los cielos y de la tierra cuando fueron creados, en el día en que hizo Jehová Dios la tierra y los cielos,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Y toda planta del campo antes que fuese en la tierra; y toda yerba del campo antes que naciese: porque aún no había hecho llover Jehová Dios sobre la tierra; ni aún había hombre, para que labrase la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Y un vapor subía de la tierra, que regaba toda la haz de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, '¶ Formó pues Jehová Dios al hombre del polvo de la tierra, y sopló en su nariz soplo de vida: y fue el hombre en ánima viviente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Y había plantado Jehová Dios un huerto en Edén al oriente, y puso allí al hombre que formó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Había también hecho producir Jehová Dios de la tierra todo árbol deseable a la vista, y bueno para comer; y el árbol de vida en medio del huerto, y el árbol de ciencia de bien y de mal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Y salía un río de Edén para regar el huerto, y desde allí se repartía en cuatro cabezas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'El nombre del uno era Fisón: este es el que cerca toda la tierra de Hevila, donde hay oro:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Y el oro de aquella tierra es bueno: hay allí también bedelio, y piedra cornerina.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'El nombre del segundo río es Gijón: este es el que cerca toda la tierra de Etiopía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Y el nombre del tercer río es Jidekel: este es el que va hacia el oriente de la Asiria. Y el cuarto río es Éufrates.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Tomó pues Jehová Dios al hombre, y púsole en el huerto de Edén, para que le labrase, y le guardase.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, '¶ Y mandó Jehová Dios al hombre, diciendo: De todo árbol del huerto comerás:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Mas del árbol de ciencia de bien y de mal, no comerás de él: porque el día que de él comieres, morirás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Y dijo Jehová Dios: No es bueno que el hombre esté solo: hacerle he ayuda que esté delante de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, '¶ Formó pues Jehová Dios de la tierra toda bestia del campo, y toda ave de los cielos, y trájolas a Adam, para que viese como las había de llamar: y todo lo que Adam llamó a alma viviente, eso es su nombre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Y puso Adam nombres a toda bestia, y a ave de los cielos, y a todo animal del campo: mas para Adam no halló ayuda, que estuviese delante de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, '¶ E hizo caer Jehová Dios sueño sobre el hombre, y adormecióse; y tomó una de sus costillas, y cerró la carne en su lugar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Y edificó Jehová Dios la costilla que tomó del hombre, en mujer, y trájola al hombre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Y dijo el hombre: Esta vez, hueso de mis huesos, y carne de mi carne. Esta será llamada Varona, porque del Varón fue tomada esta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Por tanto el varón dejará a su padre y a su madre, y allegarse ha a su mujer, y serán por una carne.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Y estaban ambos desnudos, Adam y su mujer, y no se avergonzaban.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Empero la serpiente era astuta más que todos los animales del campo, que Jehová Dios había hecho: la cual dijo a la mujer: Cuanto más que Dios dijo: No comáis de todo árbol del huerto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Y la mujer respondió a la serpiente: Del fruto de los árboles del huerto comemos;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Mas del fruto del árbol que está en medio del huerto dijo Dios; No comeréis de él, ni tocaréis en él, porque no muráis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Entonces la serpiente dijo a la mujer: No moriréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Mas sabe Dios, que en el día que comiereis de él, serán abiertos vuestros ojos; y seréis como dioses, sabiendo el bien y el mal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, '¶ Y vio la mujer que el árbol era bueno para comer, y que era deseable a los ojos, y árbol de codicia para entender: y tomó de su fruto, y comió, y dio también a su marido, y comió con ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Y fueron abiertos los ojos de ellos ambos, y conocieron que estaban desnudos: entonces cosieron hojas de higuera, e hiciéronse delantales.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, '¶ Y oyeron la voz de Jehová Dios, que se paseaba en el huerto al aire del día; y escondióse el hombre y su mujer de delante de Jehová Dios entre los árboles del huerto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, '¶ Y llamó Jehová Dios al hombre, y díjole: ¿Dónde estás tú?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Y él respondió: Oí tu voz en el huerto, y tuve miedo; porque estaba desnudo: y escondíme.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Y díjole: ¿Quién te enseñó, que estabas desnudo? ¿Has comido del árbol de que yo te mandé que no comieses?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Y el hombre respondió: La mujer que diste para estar conmigo, ella me dio del árbol, y comí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Entonces Jehová Dios dijo a la mujer: ¿Qué es esto que hiciste? Y dijo la mujer: La serpiente me engañó, y comí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Y Jehová Dios dijo a la serpiente: Porque hiciste esto, maldita serás más que todas las bestias, y que todos los animales del campo: sobre tu pecho andarás, y polvo comerás todos los días de tu vida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Y enemistad pondré entre ti y la mujer, y entre tu simiente y su simiente; esta te herirá en la cabeza, y tú le herirás en el calcañar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'A la mujer dijo: Multiplicando multiplicaré tus dolores, y tus preñeces: con dolor parirás los hijos, y a tu marido será tu deseo, y él se enseñoreará de ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Y al hombre dijo: Porque obedeciste a la voz de tu mujer, y comiste del árbol de que te mandé, diciendo: No comerás de él: Maldita será la tierra por amor de ti: con dolor comerás de ella todos los días de tu vida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Espinos y cardos te producirá, y comerás yerba del campo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'En el sudor de tu rostro comerás el pan, hasta que vuelvas a la tierra, porque de ella fuiste tomado: Porque polvo eres, y al polvo serás tornado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Y llamó el hombre el nombre de su mujer, Eva: por cuanto ella era madre de todos los vivientes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, '¶ Y Jehová Dios hizo al hombre y a su mujer túnicas de pieles, y vistiólos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Y dijo Jehová Dios: He aquí, el hombre es como uno de nos, sabiendo el bien y el mal: ahora pues, porque no meta su mano, y tome también del árbol de la vida, y coma, y viva para siempre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Y sacóle Jehová del huerto de Edén, para que labrase la tierra, de que fue tomado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, '¶ Y echó al hombre, y puso al oriente del huerto de Edén querubines, y una espada flamante que andaba alrededor, para guardar el camino del árbol de la vida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Y conoció Adam a su mujer Eva, la cual concibió y parió a Caín, y dijo: Ganado he un varón por Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Y otra vez parió a su hermano Abel. Y fue Abel pastor de ovejas, y Caín fue labrador de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, '¶ Y aconteció al cabo de días, que Caín trajo del fruto de la tierra un presente a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Y Abel trajo también de los primogénitos de sus ovejas, y de sus grosuras: y miró Jehová a Abel y a su presente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Y a Caín y a su presente no miró. Y ensañóse Caín en gran manera, y decayó su semblante.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, '¶ Entonces Jehová dijo a Caín: ¿Por qué te has ensañado? ¿y por qué ha decaído tu semblante?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, '¿Cómo, no serás ensalzado si bien hicieres: y si no hicieres bien, no estarás echado por tu pecado a la puerta? Con todo esto, a ti será su deseo; y tú te enseñorearás de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Y hablo Caín a su hermano Abel. Y aconteció que estando ellos en el campo, Caín se levantó contra Abel su hermano, y le mató.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, '¶ Y Jehová dijo a Caín: ¿Dónde está Abel tu hermano? Y él respondió: No sé: ¿Soy yo guarda de mi hermano?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Y él le dijo: ¿Qué has hecho? La voz de la sangre de tu hermano clama a mí desde la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Ahora, pues, maldito seas tú de la tierra, que abrió su boca para recibir la sangre de tu hermano de tu mano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Cuando labrares la tierra, no te volverá a dar su fuerza: vagabundo y extranjero serás en la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Y dijo Caín a Jehová: Grande es mi iniquidad de perdonar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'He aquí, me echas hoy de la haz de la tierra, y de tu presencia me esconderé: y seré vagabundo y extranjero en la tierra: y será, que cualquiera que me hallare, me matará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Y respondióle Jehová: Cierto cualquiera que matare a Caín, siete veces será castigado. Entonces Jehová puso una señal en Caín, para que no le matase cualquiera que le hallase.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Y salió Caín de delante de Jehová, y habitó en tierra de Nod, al oriente de Edén.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Y conoció Caín a su mujer, la cual concibió y parió a Jenoc: y edificó una ciudad, y llamó el nombre de la ciudad del nombre de su hijo, Jenoc.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Y nació a Jenoc Irad, e Irad engendró a Maviael, y Maviael engendró a Matusael, y Matusael engendró a Lamec.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, '¶ Y tomó para si Lamec dos mujeres, el nombre de la una fue Ada, y el nombre de la otra Sella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Y parió Ada a Jabel, el cual fue padre de los que habitan en tiendas, y de los que tienen ganados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Y el nombre de su hermano fue Jubal, el cual fue padre de todos los que tañen harpa y órgano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Y Sella también parió a Tubal-caín acicalador de toda obra de metal y de hierro: y la hermana de Tubal-caín fue Noema.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Y dijo Lamec a sus mujeres Ada y Sella: Oíd mi voz mujeres de Lamec, escuchád mi dicho: Que varón mataré por mi herida, y mancebo por mi golpe:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Que siete veces será vengado Caín, mas Lamec setenta veces siete.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, '¶ Y conoció Adam aun a su mujer, y parió un hijo, y llamó su nombre Set; Porque (dice) Dios me ha dado otra simiente por Abel, al cual mató Caín.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Y a Set también le nació un hijo, y llamó su nombre Enós. Entonces los hombres comenzaron a llamarse del nombre de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Este es el libro de las descendencias de Adam. El día que creó Dios al hombre, a la semejanza de Dios le hizo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Macho y hembra los creó, y bendíjolos, y llamó el nombre de ellos Adam, en el día en que fueron creados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Y vivió Adam ciento y treinta años, y engendró un hijo a su semejanza, conforme a su imagen, y llamó su nombre Set.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Y fueron los días de Adam, después que engendró a Set, ochocientos años: y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Y fueron todos los días que vivió Adam novecientos y treinta años, y murió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Y vivió Set ciento y cinco años, y engendró a Enós.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Y vivió Set, después que engendró a Enós, ochocientos y siete años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Y fueron todos los días de Set novecientos y doce años, y murió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Y vivió Enós noventa años, y engendró a Cainán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Y vivió Enós, después que engendró a Cainán, ochocientos y quince años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Y fueron todos los días de Enós novecientos y cinco años, y murió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Y vivió Cainán setenta años, y engendró a Malaleel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Y vivió Cainán, después que engendró a Malaleel, ochocientos y cuarenta años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Y fueron todos los días de Cainán novecientos y diez años, y murió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Y vivió Malaleel sesenta y cinco años, y engendró a Jared.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Y vivió Malaleel, después que engendró a Jared, ochocientos y treinta años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Y fueron todos los días de Malaleel ochocientos y noventa y cinco años, y murió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Y vivió Jared ciento y sesenta y dos años, y engendró a Jenoc.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Y vivió Jared, después que engendró a Jenoc, ochocientos años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Y fueron todos los días de Jared novecientos y sesenta y dos años, y murió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Y vivió Jenoc sesenta y cinco años, y engendró a Matusalem.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Y anduvo Jenoc con Dios, después que engendró a Matusalem, trescientos años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Y fueron todos los días de Jenoc trescientos y sesenta y cinco años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Y anduvo Jenoc con Dios, y desapareció, porque le llevó Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Y vivió Matusalem ciento y ochenta y siete años, y engendró a Lamec.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Y vivió Matusalem, después que engendró a Lamec, setecientos y ochenta y dos años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Y fueron todos los días de Matusalem novecientos y sesenta y nueve años, y murió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Y vivió Lamec ciento y ochenta y dos años, y engendró un hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Y llamó su nombre Noé, diciendo: Este nos consolará de nuestras obras, y del trabajo de nuestras manos de la tierra a la cual Jehová maldijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Y vivió Lamec, después que engendró a Noé, quinientos y noventa y cinco años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Y fueron todos los días de Lamec setecientos y setenta y siete años, y murió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Y siendo Noé de quinientos años, engendró a Sem, Cam, y a Jafet.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Y acaeció que cuando comenzaron los hombres a multiplicarse sobre la haz de la tierra, y les nacieron hijas,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Viendo los hijos de Dios las hijas de los hombres que eran hermosas, tomáronse mujeres escogiendo entre todas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Y dijo Jehová: No contenderá mi Espíritu con el hombre para siempre, porque ciertamente él es carne: mas serán sus días ciento y veinte años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Había gigantes en la tierra en aquellos días; y también después que entraron los hijos de Dios a las hijas de los hombres, y les engendraron hijos, estos fueron los valientes, que desde la antigüedad fueron varones de nombre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Y vio Jehová que la malicia de los hombres era mucha sobre la tierra, y que todo el intento de los pensamientos del corazón de ellos ciertamente era malo todo el tiempo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Y arrepintióse Jehová de haber hecho hombre en la tierra; y pesóle en su corazón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Y dijo Jehová: Raeré los hombres que he creado de sobre la haz de la tierra, desde el hombre hasta la bestia, y hasta el reptil, y hasta el ave de los cielos; porque me arrepiento de haberlos hecho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, '¶ Empero Noé halló gracia en los ojos de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Estas son las generaciones de Noé: Noé, varón justo, perfecto fue en sus generaciones: con Dios anduvo Noé.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Y engendró Noé tres hijos, a Sem, a Cam, y a Jafet.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Y corrompióse la tierra delante de Dios, e hinchióse la tierra de violencia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Y vio Dios la tierra, y he aquí que estaba corrompida, porque toda carne había corrompido su camino sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Y dijo Dios a Noé: El fin de toda carne ha venido delante de mí: porque la tierra está llena de violencia delante de ellos: y he aquí que yo los destruyo a ellos con la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Hazte un arca de madera de cedro: harás apartamientos en el arca, y embetunarla has por de dentro y por de fuera con betún.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Y de esta manera la harás: De trescientos codos la longura del arca, y de cincuenta codos su anchura, y de treinta codos su altura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Una ventana harás al arca, y a un codo la acabarás de la parte de arriba: y la puerta del arca pondrás a su lado de suelos bajos, segundos, y terceros le harás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Y yo, he aquí que yo traigo un diluvio de aguas sobre la tierra, para destruir toda carne, en que haya espíritu de vida debajo del cielo: todo lo que hubiere en la tierra, morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Mas yo estableceré mi concierto contigo, y entrarás en el arca tú, y tus hijos, y tu mujer, y las mujeres de tus hijos contigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Y de todo lo que vive, de toda carne, dos de cada uno meterás en el arca, para que tengan vida contigo: macho y hembra serán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'De las aves según su especie, y de las bestias según su especie, de todo reptil de la tierra según su especie, dos de cada uno entrarán a ti, para que tengan vida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Y tú tómate de toda vianda que se come, y júntatela, y será para ti y para ellos por mantenimiento.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'E hizo Noé conforme a todo lo que le mandó Dios: así lo hizo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Y Jehová dijo a Noé: Entra tú, y toda tu casa en el arca; porque a ti he visto justo delante de mí en esta generación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'De todo animal limpio te tomarás de siete en siete, macho y su hembra: mas de los animales que no son limpios, dos, macho y su hembra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'También de las aves de los cielos, de siete en siete, macho y hembra: para guardar en vida la simiente sobre la haz de toda la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Porque pasados aun siete días, yo lluevo sobre la tierra cuarenta días, y cuarenta noches: y raeré toda sustancia que hice, de sobre la haz de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'E hizo Noé conforme a todo lo que le mandó Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Y siendo Noé de seiscientos años, el diluvio de las aguas fue sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Y vino Noé, y sus hijos, y su mujer, y las mujeres de sus hijos con él al arca, por las aguas del diluvio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'De los animales limpios, y de los animales que no eran limpios, y de las aves, y de todo lo que anda arrastrando sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'De dos en dos entraron a Noé en el arca, macho y hembra, como mandó Dios a Noé.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, '¶ Y fue, que al séptimo día las aguas del diluvio fueron sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'El año de seiscientos de la vida de Noé, en el mes segundo, a los diez y siete días del mes, aquel día fueron rompidas todas las fuentes del grande abismo, y las ventanas de los cielos fueron abiertas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Y hubo lluvia sobre la tierra cuarenta días y cuarenta noches.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'En este mismo día entró Noé, y Sem, y Cam, y Jafet, hijos de Noé, la mujer de Noé, y las tres mujeres de sus hijos con él en el arca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Ellos y todos los animales según sus especies, y todas las bestias según sus especies, y todo reptil que anda arrastrando sobre la tierra según su especie, y toda ave según su especie, todo pájaro, toda cosa de alas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Y vinieron a Noé al arca de dos en dos, de toda carne, en que había espíritu de vida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Y los que vinieron, macho y hembra de toda carne vinieron, como le había mandado Dios: y cerró Jehová sobre él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Y fue el diluvio cuarenta días sobre la tierra; y las aguas se multiplicaron, y alzaron el arca, y fue alzada de sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Y prevalecieron las aguas, y multiplicáronse en gran manera sobre la tierra; y andaba el arca sobre la haz de las aguas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Y las aguas prevalecieron mucho en gran manera sobre la tierra; y fueron cubiertos todos los montes altos, que había debajo de todos los cielos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Quince codos encima prevalecieron las aguas; y fueron cubiertos los montes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Y murió toda carne que anda arrastrando sobre la tierra, en las aves, y en las bestias, y en los animales, y en todo reptil que anda arrastrando sobre la tierra, y en todo hombre:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Todo lo que tenía aliento de espíritu de vida en sus narices, de todo lo que había en la tierra, murió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Así rayó toda la sustancia que había sobre la haz de la tierra, desde el hombre hasta la bestia, hasta el reptil, y hasta el ave del cielo: y fueron raídos de la tierra, y quedó solamente Noé, y lo que con él estaba en el arca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Y prevalecieron las aguas sobre la tierra ciento y cincuenta días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Y acordóse Dios de Noé, y de todos los animales, y de todas las bestias que estaban con él en el arca: e hizo pasar Dios un viento sobre la tierra, y cesaron las aguas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Y cerráronse las fuentes del abismo, y las ventanas de los cielos, y la lluvia de los cielos fue detenida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Y tornaron las aguas de sobre la tierra, yendo y volviendo: y descrecieron las aguas al cabo de ciento y cincuenta días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Y reposó el arca en el mes séptimo, a los diez y siete días del mes, sobre los montes de Armenia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Y las aguas fueron descreciendo hasta el mes décimo: en el décimo, al primero del mes, se descubrieron las cabezas de los montes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Y fue que al cabo de cuarenta días Noé abrió la ventana del arca, que había hecho:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Y envió al cuervo, el cual salió, saliendo y tornando, hasta que las aguas se secaron de sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Y envió a la paloma de sí, para ver si las aguas se habían aliviado de sobre la haz de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Y no halló la paloma donde reposase la planta de su pie, y volvióse a él al arca, porque las aguas estaban aún sobre la haz de toda la tierra: Y él extendió su mano, y la tomó, y metióla consigo en el arca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Y esperó aún otros siete días, y volvió a enviar la paloma del arca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Y la paloma volvió a él a la hora de la tarde, y he aquí que traía una hoja de oliva tomada en su boca; y entendió Noé, que las aguas se habían aliviado de sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Y esperó aún otros siete días, y envió la paloma, la cual no tornó a volver a él más.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Y fue, que en el año de seiscientos y uno, en el mes primero, al primero del mes, las aguas se enjugaron de sobre la tierra; y quitó Noé la cubierta del arca, y miró, y he aquí que la haz de la tierra estaba enjuta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Y en el mes segundo, a los veinte y siete días del mes, se secó la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, '¶ Y habló Dios a Noé, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Sal del arca tú, y tu mujer, y tus hijos, y las mujeres de tus hijos contigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Todos los animales que están contigo de toda carne, de aves, y de bestias, y de todo reptil que anda arrastrando sobre la tierra, sacarás contigo; y vayan por la tierra, y fructifiquen, y multipliquen sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Entonces salió Noé, y sus hijos, y su mujer, y las mujeres de sus hijos con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Todos los animales, y todo reptil, y toda ave, todo lo que se mueve sobre la tierra según sus especies, salieron del arca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, '¶ Y edificó Noé altar a Jehová, y tomó de todo animal limpio, y de toda ave limpia, y ofreció holocausto en el altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Y olió Jehová olor de reposo: y dijo Jehová, en su corazón: No tornaré más a maldecir la tierra por causa del hombre; porque el intento del corazón del hombre malo es desde su niñez: ni volveré más a herir toda cosa viva, como he hecho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Todavía serán todos los tiempos de la tierra, es a saber, sementera, y siega, y frío y calor, verano e invierno, y día y noche: no cesarán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Y bendijo Dios a Noé y a sus hijos, y díjoles: Fructificad y multiplicad, y henchíd la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Y vuestro temor y vuestro pavor será sobre todo animal de la tierra, y sobre toda ave de los cielos, en todo lo que se moverá en la tierra, y en todos los peces de la mar: en vuestra mano son entregados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Todo lo que se mueve, que es vivo, tendréis por mantenimiento: como verdura de yerba os lo he dado todo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, '¶ Empero la carne con su alma, que es su sangre, no comeréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Porque ciertamente vuestra sangre, que es vuestras almas, yo la demandaré, de mano de todo animal la demandaré, y de mano del hombre, de mano del varón su hermano demandaré el alma del hombre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'El que derramare sangre de hombre en el hombre, su sangre será derramada; porque a imagen de Dios es hecho el hombre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Mas vosotros fructificad y multiplicad, y andád en la tierra, y multiplicad en ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, '¶ Y habló Dios a Noé y a sus hijos con él, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Yo: he aquí que yo establezco mi concierto con vosotros, y con vuestra simiente, después de vosotros,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'Y con toda alma viviente que está con vosotros, en aves, en animales, y en toda bestia de la tierra que está con vosotros, desde todos los que salieron del arca hasta todo animal de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Que yo estableceré mi concierto con vosotros que no será talada más toda carne con aguas de diluvio; y que no habrá más diluvio para destruir la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Y dijo Dios: Esta será la señal del concierto que yo pongo entre mí y vosotros, y toda alma viviente que está con vosotros, por siglos perpetuos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Mi arco pondré en las nubes, el cual será por señal de concierto entre mí y la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Y será, que cuando yo anublare nubes sobre la tierra, entonces mi arco parecerá en las nubes:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'Y acordarme he de mi concierto que está entre mí y vosotros, y toda alma viviente en toda carne: y no serán más las aguas por diluvio para destruir a toda carne.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Y estará el arco en las nubes, y verlo he para acordarme del concierto perpetuo entre Dios y toda alma viviente, con toda carne que está sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Dijo más Dios a Noé: Esta será la señal del concierto, que he establecido entre mí y toda carne, que está sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Y fueron los hijos de Noé, que salieron del arca, Sem, Cam, y Jafet: y Cam es el padre de Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Estos tres son los hijos de Noé, y de estos fue llena toda la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, '¶ Y comenzó Noé a labrar la tierra, y plantó una viña:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Y bebió del vino, y embriagóse, y descubrióse en medio de su tienda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Y vio Cam, el padre de Canaán, la desnudez de su padre, y díjolo a sus dos hermanos en la calle,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Entonces tomó Sem y Jafet la ropa, y pusiéronla sobre sus hombros de ambos, y andando hacia atrás, cubrieron la desnudez de su padre, teniendo vueltos los rostros, que no vieron la desnudez de su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, '¶ Y despertó Noé de su vino, y supo lo que había hecho con él su hijo el pequeño,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Y dijo: Maldito sea Canaán, siervo de siervos será a sus hermanos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Dijo más: Bendito Jehová el Dios de Sem, y séale Canaán siervo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Ensanche Dios a Jafet, y habite en las tiendas de Sem, y séale Canaán siervo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Y vivió Noé, después del diluvio, trescientos y cincuenta años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Y fueron todos los días de Noé novecientos y cincuenta años, y murió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Estas son las generaciones de los hijos de Noé: Sem, Cam, y Jafet, a los cuales nacieron hijos después del diluvio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Los hijos de Jafet fueron Gomer, y Magog, y Madai, y Javán, y Tubal, y Mosoc, y Tiras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Y los hijos de Gomer: Ascenez, y Rifat, y Togorma.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Y los hijos de Javán: Elisa, y Társis, Cetim, y Dodanim.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Por estos fueron partidas las islas de las Gentes en sus tierras, cada cual según su lengua, conforme a sus familias en sus naciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, '¶ Los hijos de Cam fueron Cus, y Mizraim, y Fut, y Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Y los hijos de Cus, Saba, Hevila, y Sabata, y Rahama, y Sabataca. Y los hijos de Rahama, Saba, y Dadán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Y Cus engendró a Nimrod. Este comenzó a ser poderoso en la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Este fue poderoso cazador delante de Jehová: por lo cual se dice: Como Nimrod poderoso cazador delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Y fue la cabecera de su reino Babel, y Arac, y Acad, y Calanne, en la tierra de Sennaar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'De aquesta tierra salió Assur, el cual edificó a Nínive, y a Recobot-ir, y a Cale,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Y a Resen entre Nínive y Cale, la cual es la ciudad grande.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Y Mizraim engendró a Ludim, y Anamim, y Laabim, y Neptuim,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Y a Fetrusim, y Casluim, de donde salieron los Filisteos, y a Caftorim.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, '¶ Y Canaán engendró a Sidón su primogénito, y a Jet,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'Y a Jebusi, y Amori, y Gergasi,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Y a Hevi, y a Arci, y a Cini,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Y a Aradi, Samari, y Hemati: y después se derramaron las familias de los Cananeos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Y fue el término de los Cananeos, desde Sidón viniendo a Gerar hasta Gaza, hasta entrar en Sodoma y Gomorra, Adma, y Seboim hasta Lasa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Estos son los hijos de Cam por sus familias, por sus lenguas, en sus tierras, en sus naciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, '¶ Y a Sem también le nacieron hijos; él fue padre de todos los hijos de Jeber, hermano de Jafet el mayor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Y los hijos de Sem fueron Elam, y Assur, y Arfajad, y Lud, y Aram.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Y los hijos de Aram: Hus, y Hul, y Geter, y Mes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arfajad engendró a Sale, y Sale engendró a Jeber.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Y a Jeber nacieron dos hijos: el nombre del uno fue Faleg, porque en sus días fue partida la tierra: y el nombre de su hermano, Jectán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Y Jectán engendró a Elmodad, y a Salef, y a Asarmot, y a Jaré,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Y a Adoram, y a Uzal, y a Decla,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Y a Hebal, y a Abimael, y a Saba,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Y a Ofir, y a Hevila, y a Jobab. Todos estos fueron hijos de Jectán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Y fue su habitación desde Messa, viniendo de Sefar, monte de oriente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Estos fueron los hijos de Sem por sus familias, por sus lenguas, en sus tierras, en sus naciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Estas son las familias de Noé por sus descendencias, en sus naciones: y de estos fueron divididas las naciones en la tierra después del diluvio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Era entonces toda la tierra de una lengua, y de unas mismas palabras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Y aconteció, que como se partieron de oriente, hallaron campo en la tierra de Sennaar, y asentaron allí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Y dijeron los unos a los otros: Dad acá, hagamos ladrillo, y cozámos lo con fuego. Y fuéles el ladrillo en lugar de piedra, y el betún en lugar de mezcla.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Y dijeron: Dad acá: Edifiquémosnos una ciudad, y una torre, que tenga la cabeza en el cielo: y hagámosnos nombrados; por ventura nos esparciremos sobre la haz de toda la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, '¶ Y descendió Jehová para ver la ciudad y la torre, que edificaban los hijos del hombre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Y dijo Jehová: He aquí, el pueblo es uno, y todos estos tienen un lenguaje, y ahora comienzan a hacer, y ahora no dejarán de ejecutar todo lo que han pensado hacer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Ahora pues, descendamos, y mezclemos allí sus lenguas, que ninguno entienda la lengua de su compañero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Así los esparció Jehová de allí sobre la haz de toda la tierra, y dejaron de edificar la ciudad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Por esto fue llamado el nombre de ella Babel, porque allí mezcló Jehová el lenguaje de toda la tierra, y de allí los esparció sobre la haz de toda la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, '¶ Estas son las generaciones de Sem: Sem de edad de cien años engendró a Arfajad, dos años después del diluvio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Y vivió Sem, después que engendró a Arfajad, quinientos años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Y Arfajad vivió treinta y cinco años, y engendró a Sale.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Y vivió Arfajad, después que engendró a Sale, cuatrocientos y tres años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Y vivió Sale treinta años, y engendró a Jeber.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Y vivió Sale, después que engendró a Jeber, cuatrocientos y tres años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Y vivió Jeber treinta y cuatro años, y engendró a Faleg.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Y vivió Jeber, después que engendró a Faleg, cuatrocientos y treinta años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Y vivió Faleg treinta años, y engendró a Reu.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Y vivió Faleg, después que engendró a Reu, doscientos y nueve años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Y Reu vivió treinta y dos años, y engendró a Sarug.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Y vivió Reu, después que engendró a Sarug, doscientos y siete años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Y vivió Sarug treinta años, y engendró a Nacor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Y vivió Sarug, después que engendró a Nacor, doscientos años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Y vivió Nacor veinte y nueve años, y engendró a Tare.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Y vivió Nacor, después que engendró a Tare, ciento y diez y nueve años, y engendró hijos e hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Y vivió Tare setenta años, y engendró a Abram, a Nacor, y a Arán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Y estas son las generaciones de Tare. Tare engendró a Abram, y a Nacor, y a Arán; y Arán engendró a Lot.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Y murió Arán antes de su padre Tare, en la tierra de su naturaleza, en Ur de los Caldeos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Y tomaron Abram y Nacor para sí mujeres: el nombre de la mujer de Abram fue Sarai, y el nombre de la mujer de Nacor, Melca, hija de Arán, padre de Melca, y padre de Jesca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Y Sarai fue estéril, que no tenía hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, '¶ Y tomó Tare a Abram su hijo, y a Lot hijo de Arán, hijo de su hijo, y a Sarai su nuera, mujer de Abram su hijo: y salió con ellos de Ur de los Caldeos, para ir a la tierra de Canaán: y vinieron hasta Harán: y asentaron allí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Y fueron los días de Tare doscientos y cinco años, y murió Tare en Harán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Empero Jehová había dicho a Abram: Vete de tu tierra, y de tu parentela, y de la casa de tu padre, a la tierra que yo te mostraré:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Y hacerte he en gran gente, y bendecirte he, y engrandeceré tu nombre, y serás bendición.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Y bendeciré a los que te bendijeren, y a los que te maldijeren maldeciré; y serán benditas en ti todas las familias de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Y fuése Abram, como Jehová le dijo, y fue con él Lot: y era Abram de edad de setenta y cinco años, cuando salió de Harán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Y tomó Abram a Sarai su mujer, y a Lot hijo de su hermano, y toda su hacienda que habían ganado, y las almas que habían hecho en Harán, y salieron para ir a tierra de Canaán: y llegaron a tierra de Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Y pasó Abram por aquella tierra hasta el lugar de Siquem, hasta el alcornoque de More: y el Cananeo estaba entonces en la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Y apareció Jehová a Abram, y díjole: A tu simiente daré esta tierra. Y edificó allí altar a Jehová, que le había aparecido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Y pasóse de allí al monte, al oriente de Bet-el, y tendió allí su tienda, Bet-el al occidente, y Hai al oriente. Y edificó allí altar a Jehová, e invocó el nombre de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Y movió Abram de allí caminando, y yendo hacia el mediodía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, '¶ Y hubo hambre en la tierra, y descendió Abram a Egipto para peregrinar allá; porque era grave la hambre en la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Y aconteció, que cuando llegó para entrar en Egipto, dijo a Sarai su mujer: He aquí ahora, yo conozco que eres mujer hermosa de vista:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Y será, que cuando te verán los Egipcios, dirán: Su mujer es. Y matarme han: y a ti darán la vida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Ahora pues, di que eres mi hermana, para que yo haya bien por causa tuya, y viva mi alma por amor de ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Y aconteció, que como entró Abram en Egipto, los Egipcios vieron la mujer que era hermosa en gran manera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Y viéronla los príncipes de Faraón, y alabáronla a Faraón, y fue llevada la mujer a casa de Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Y a Abram hizo bien por causa de ella, y tuvo ovejas, y vacas, y asnos, y siervos, y criadas, y asnas, y camellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, '¶ Mas Jehová hirió a Faraón y a su casa de grandes plagas por causa de Sarai mujer de Abram.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Entonces Faraón llamó a Abram, y díjole: ¿Qué es esto que has hecho conmigo? ¿Por qué no me declaraste, que era tu mujer?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, '¿Por qué dijiste: Es mi hermana? y yo la tomé para mí por mujer. Ahora pues, he aquí tu mujer, tóma la, y vete.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Entonces Faraón mandó acerca de él a varones, que le acompañaron, y a su mujer, y a todo lo que tenía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Así subió Abram de Egipto, hacia el mediodía, él y su mujer con todo lo que tenía, y con él Lot.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Y Abram iba cargado en gran manera en ganado, en plata y oro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Y volvió por sus jornadas de la parte del mediodía, hasta Bet-el, hasta el lugar donde había estado su tienda antes, entre Bet-el y Hai:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'Al lugar del altar que había hecho allí antes: e invocó allí Abram el nombre de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, '¶ Y asimismo Lot, que andaba con Abram, tenía ovejas, y vacas, y tiendas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'De tal manera que la tierra no los sufría para morar juntos: porque su hacienda era mucha, y no pudieron habitar juntos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Y hubo contienda entre los pastores del ganado de Abram, y los pastores del ganado de Lot: y el Cananeo y el Ferezeo habitaban entonces en la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Entonces Abram dijo a Lot: No haya ahora cuestión entre mí y ti, y entre mis pastores y los tuyos, porque varones hermanos somos nosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, '¿No está toda la tierra delante de ti? Yo te ruego que te apartes de mí: si tú fueres a la mano izquierda, yo iré a la derecha: y si tú a la derecha, yo a la izquierda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Y alzó Lot sus ojos, y vio toda la llanura del Jordán, que toda ella era de riego, antes que destruyese Jehová a Sodoma y a Gomorra, como un huerto de Jehová, como la tierra de Egipto entrando en Zoar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Entonces Lot escogió para sí toda la llanura del Jordán: y partióse Lot de oriente, y apartáronse el uno del otro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram asentó en la tierra de Canaán, y Lot asentó en las ciudades de la llanura, y puso sus tiendas hasta Sodoma.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Mas los hombres de Sodoma eran malos y pecadores para con Jehová en gran manera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, '¶ Y Jehová dijo a Abram, después que Lot se apartó de con él: Alza ahora tus ojos, y mira desde el lugar donde tú estás hacia el aquilón, y al mediodía, y al oriente, y al occidente;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Porque toda la tierra que tú ves, daré a ti y a tu simiente para siempre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Y pondré tu simiente como el polvo de la tierra; que si alguno podrá contar el polvo de la tierra, también tu simiente será contada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Levántate, ve por la tierra, por su longura y por su anchura, porque a ti la tengo de dar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Y asentó Abram su tienda, y vino, y moró en el alcornocal de Mamré, que es en Hebrón: y edificó allí altar a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Y aconteció en aquellos días, que Amrafel rey de Sennaar, Arioc rey de Elasar, Codor-laomor rey de Elam, y Tadal rey de las gentes,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Hicieron guerra contra Bara rey de Sodoma, y contra Bersa rey de Gomorra, y contra Senaab rey de Adama, y contra Semeber rey de Seboim, y contra el rey de Bala, la cual es Segor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Todos estos se juntaron en el valle de Siddim, que es el mar de sal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Doce años habían servido a Codor-laomor, y a los trece años se levantaron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Y a los catorce años vino Codor-laomor, y los reyes que estaban con él, e hirieron a Rafaim en Astarot-carnaím, y a Zuzim en Ham y a Emim en Save-cariataim.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'Y a los Horeos en el monte de Seir, hasta la llanura de Farán, que está junto al desierto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Y volvieron, y vinieron a En-mispat, que es Cádes, e hirieron todas las labranzas de los Amalecitas, y también al Amorreo, que habitaba en Hasasón-tamar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Y salió el rey de Sodoma, y el rey de Gomorra, y el rey de Adama, y el rey de Seboim, y el rey de Bala, que es Segor, y ordenaron contra ellos batalla en el valle de Siddim:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Es a saber, contra Codor-laomor rey de Elam, y Tadal rey de las gentes, y Amrafel rey de Sennaar, y Arioc rey de Elasar, cuatro reyes contra cinco.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Y el valle de Siddim era lleno de pozos de betún: y huyeron el rey de Sodoma, y el de Gomorra, y cayeron allí: y los demás huyeron al monte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Y tomaron toda la hacienda de Sodoma y de Gomorra, y todas sus vituallas, y fuéronse.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Tomaron también a Lot, hijo del hermano de Abram, y a su hacienda, y fuéronse; porque él moraba en Sodoma.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Y vino uno que escapó, y denunciólo a Abram Hebreo, que habitaba en el alcornocal de Mamré Amorreo, hermano de Escol, y hermano de Aner, los cuales estaban confederados con Abram.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Y oyó Abram, que su hermano era cautivo, y armó sus criados, los criados de su casa, trescientos y diez y ocho, y siguióles hasta Dan.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Y derramóse sobre ellos de noche él y sus siervos, e hirióles, y siguióles hasta Hoba, que está a la mano izquierda de Damasco.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Y volvió toda la hacienda, y también a Lot su hermano, y su hacienda volvió a traer, y también las mujeres y el pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Y salió el rey de Sodoma a recibirle, volviendo él de herir a Codor-laomor y a los reyes que estaban con él, al valle de Save, que es el valle del rey.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, '¶ Entonces Melquisedec, rey de Salem, sacó pan y vino, él cual era sacerdote del Dios altísimo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Y bendíjole, y dijo: Bendito sea Abram del Dios altísimo, poseedor de los cielos y de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Y bendito sea el Dios altísimo, que entregó tus enemigos en tu mano. Y él le dio los diezmos de todo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Entonces el rey de Sodoma dijo a Abram: Dáme las personas, y toma para ti la hacienda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Y respondió Abram al rey de Sodoma: Mi mano he alzado a Jehová Dios altísimo, poseedor de los cielos y de la tierra,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Que desde un hilo hasta la correa de un zapato, nada tomaré de todo lo que es tuyo, porque no digas: Yo enriquecí a Abram:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Sacando solamente lo que comieron los mancebos, y la parte de los varones que fueron conmigo Aner, Escol, y Mamré: los cuales tomarán su parte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Después de estas cosas fue palabra de Jehová a Abram en visión, diciendo: No temas Abram: Yo soy tu escudo, tu salario copioso en gran manera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Y respondió Abram: Señor Jehová; ¿qué me has de dar, que yo ando solo, y el mayordomo de mi casa, el Damasceno, Eliezer?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Dijo más Abram: He aquí, no me has dado simiente, y he aquí que el hijo de mi casa me hereda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Y luego la palabra de Jehová fue a él, diciendo: No te heredará este; mas el que saldrá de tus entrañas, aquel te heredará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Y sacóle fuera, y dijo: Mira ahora a los cielos, y cuenta las estrellas, si las puedes contar: y díjole: Así será tu simiente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Y creyó a Jehová, y contóselo por justicia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, '¶ Y díjole: Yo soy Jehová, que te saqué de Ur de los Caldeos, para darte esta tierra que la heredes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Y él respondió: Señor Jehová, ¿en qué conoceré que la tengo de heredar?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Y respondióle: Tómame una becerra de tres años, y una cabra de tres años, y un carnero de tres años; una tórtola también, y un palomino.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Y él tomó todas estas cosas, y partiólas por la mitad, y puso cada mitad en frente de su compañera: mas las aves no partió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Y descendían aves sobre los cuerpos muertos, y ojeábalas Abram.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Y fue, que poniéndose el sol, cayó sueño sobre Abram, y he aquí, un temor, una oscuridad grande que cayó sobre él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Entonces dijo a Abram: De cierto sepas, que tu simiente será peregrina en tierra no suya, y servirles han, y serán afligidos cuatrocientos años;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Mas también a la gente a quien servirán, juzgo yo; y después de esto saldrán con grande riqueza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Y tú vendrás a tus padres en paz, y serás sepultado en buena vejez.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Y en la cuarta generación volverán acá; porque aún no está cumplida la maldad del Amorreo hasta aquí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Y fue que puesto el sol, hubo una oscuridad: y he aquí un horno de humo, y una antorcha de fuego que pasó entre las mitades.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Aquel día hizo Jehová concierto con Abram, diciendo: A tu simiente daré esta tierra desde el río de Egipto hasta el río grande, el río de Éufrates:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Al Cineo, y al Cenezeo, y al Cadmoneo,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Y al Jetteo, y al Ferezeo, y a los Rafeos,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Al Amorreo, también, y al Cananeo y al Gergeseo, y al Jebuseo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Y Sarai, mujer de Abram, no le paría; y ella tenía una sierva Egipcia, que se llamaba Agar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Dijo, pues, Sarai a Abram: He aquí ahora, Jehová me ha vedado de parir: ruégote que entres a mi sierva, quizá tendré hijos de ella. Y obedeció Abram al dicho de Sarai.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Y tomó Sarai, la mujer de Abram, a Agar Egipcia su sierva, al cabo de diez años que había habitado Abram en la tierra de Canaán, y dióla a Abram su marido por mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, '¶ Y él entró a Agar, la cual concibió: y viéndose preñada, menospreciaba a su señora en sus ojos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Entonces Sarai dijo a Abram: Mi afrenta es sobre ti: yo puse mi sierva en tu seno, y viendo que se ha empreñado, soy menospreciada en sus ojos: juzgue Jehová entre mí y ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Y respondió Abram a Sarai: He ahí tu sierva en tu mano: haz con ella lo que bueno te pareciere. Entonces Sarai la afligió, y ella se huyó de delante de ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, '¶ Y hallóla el ángel de Jehová junto a una fuente de agua en el desierto: junto a la fuente que está en el camino del Sur:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Y díjo la: Agar sierva de Sarai: ¿Dónde? ¿De dónde vienes, y a dónde vas? Y ella respondió: Huyo de delante de Sarai mi señora.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Y díjole el ángel de Jehová: Vuélvete a tu señora, y humíllate debajo de su mano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Y díjole más el ángel de Jehová: Multiplicando multiplicaré tu simiente, que no será contada por la multitud.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Y díjole más el ángel de Jehová: He aquí, tú estás preñada, y parirás un hijo: y llamarás su nombre Ismael, porque oído ha Jehová tu aflicción.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Y él será hombre fiero: su mano contra todos, y las manos de todos contra él, y delante de todos sus hermanos habitará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Entonces ella llamó el nombre de Jehová, que hablaba con ella: Atta el roi, Tú, Dios, de vista: Porque dijo: ¿No he visto también aquí las espaldas del que me vio?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Por lo cual llamó al pozo: Pozo del Viviente, que me ve. He aquí, está entre Cádes, y Barad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, '¶ Y parió Agar a Abram un hijo; y llamó Abram el nombre de su hijo, que le parió Agar, Ismael.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Y Abram era de edad de ochenta y seis años, cuando parió Agar a Ismael.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Y siendo Abram de edad de noventa y nueve años, Jehová le apareció, y díjole: Yo soy el Dios Todopoderoso: Anda delante de mí, y sé perfecto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Y pondré mi concierto entre mí y ti, y multiplicarte he mucho en gran manera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Entonces Abram cayó sobre su rostro, y Dios habló con él, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Yo, he aquí mi concierto contigo: Serás por padre de muchedumbre de gentes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Y no se llamará más tu nombre Abram; mas será tu nombre Abraham; porque padre de muchedumbre de gentes te he puesto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Y multiplicarte he mucho en gran manera, y ponerte he en gentes; y reyes saldrán de ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Y estableceré mi concierto entre mí y ti, y entre tu simiente después de ti por sus generaciones por alianza perpetua, para ser a ti por Dios, y a tu simiente después de ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Y daré a ti, y a tu simiente después de ti, la tierra de tus peregrinaciones, toda la tierra de Canaán, en heredad perpetua: y serles he por Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Y dijo más Dios a Abraham: Tú empero mi concierto guardarás, tú y tu simiente después de ti por sus generaciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Este será mi concierto que guardaréis entre mí y vosotros, y tu simiente después de ti: Que será circuncidado entre vosotros todo varón:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Circuncidaréis, pues, la carne de vuestro prepucio, y será por señal del concierto entre mí y vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Y de edad de ocho días será circuncidado en vosotros todo varón por vuestras generaciones: el nacido en casa y el comprado a dinero de cualquier extranjero, que no fuere de tu simiente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Circuncidando será circuncidado el nacido en tu casa, y el comprado por tu dinero; y estará mi concierto en vuestra carne para alianza perpetua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Y el varón incircunciso que no hubiere circuncidado la carne de su prepucio, aquella persona será cortada de sus pueblos: mi concierto anuló.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Dijo también Dios a Abraham: A Sarai tu mujer no llamarás su nombre Sarai, mas Sara será su nombre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Y bendecirla he, y también te daré de ella un hijo, y bendecirla he, y será madre de naciones: reyes de pueblos serán de ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, '¶ Entonces Abraham cayó sobre su rostro, y rióse, y dijo en su corazón: ¿A hombre de cien años ha de nacer un hijo? ¿Y Sara, mujer de noventa años, ha de parir?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Y dijo Abraham a Dios: Ojalá Ismael viva delante de ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Y respondió Dios: Ciertamente Sara tu mujer te parirá un hijo, y llamarás su nombre Isaac, y confirmaré mi concierto con él por concierto a su simiente después de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Y por Ismael también te he oído: He aquí yo le bendeciré, y le haré fructificar, y multiplicar mucho en gran manera: doce príncipes engendrará; y ponerle he por gran gente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Mas mi concierto estableceré con Isaac, al cual te parirá Sara en este tiempo el año siguiente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Y acabó de hablar con él, y subió Dios de con Abraham.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, '¶ Entonces tomó Abraham a Ismael su hijo, y a todos los siervos nacidos en su casa, y a todos los comprados por su dinero, todo macho en los varones de la casa de Abraham, y circuncidó la carne de su prepucio en aquel mismo día, como Dios lo había hablado con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Era Abraham de edad de noventa y nueve años, cuando circuncidó él la carne de su prepucio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'E Ismael su hijo de trece años, cuando fue circuncidada la carne de su prepucio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'En aquel mismo día fue circuncidado Abraham, e Ismael su hijo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Y todos los varones de su casa, el siervo nacido en casa, y el comprado por dinero del extranjero, fueron circuncidados con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Y aparecióle Jehová en el alcornocal de Mamré, estando él sentado a la puerta de su tienda, cuando comenzaba el calor del día.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Y alzó sus ojos, y miró, y he aquí tres varones, que estaban junto a él: y como los vio, salió corriendo a recibirlos desde la puerta de su tienda, e inclinóse a tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Y dijo: Señor, si ahora he hallado gracia en tus ojos, ruégote que no pases de tu siervo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Tómese ahora un poco de agua, y lavad vuestros pies, y recostaos debajo de un árbol:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Y tomaré un bocado de pan, y sustentad vuestro corazón, después pasaréis; porque por eso habéis pasado cerca de vuestro siervo. Y ellos dijeron: Haz así como has hablado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Entonces Abraham fue a priesa a la tienda a Sara, y díjole: Toma presto tres medidas de flor de harina, amasa y haz panes cocidos debajo de la ceniza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Y corrió Abraham a las vacas, y tomó un becerro tierno y bueno, y dióle al mozo, y dióse priesa a aderezarlo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Tomó también manteca y leche, y el becerro que había aderezado, y púsolo delante de ellos; y él estaba junto a ellos debajo del árbol, y comieron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, '¶ Y dijéronle: ¿Dónde está Sara tu mujer? Y él respondió: Aquí en la tienda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Entonces dijo: Volviendo volveré a ti según el tiempo de la vida, y, he aquí, tendrá un hijo Sara tu mujer. Y Sara escuchaba a la puerta de la tienda: y ella estaba detrás de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Y Abraham y Sara eran viejos, entrados en días: ya a Sara había cesado la costumbre de las mujeres.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Y rióse Sara entre sí, diciendo: ¿Después que he envejecido, tendré deleite? Así mismo mi señor es ya viejo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Entonces Jehová dijo a Abraham: ¿Por qué se ha reído Sara, diciendo; De cierto tengo de parir, que soy ya vieja?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, '¿Esconderse ha de Jehová alguna cosa? Al tiempo señalado volveré a ti según el tiempo de la vida, y Sara tendrá un hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Entonces Sara negó, diciendo: No me reí, porque tuvo miedo. Y él dijo: No es así; porque te reíste.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, '¶ Y los varones se levantaron de allí, y miraron hacia Sodoma: y Abraham iba con ellos acompañándolos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Y Jehová dijo: ¿Encubro yo de Abraham lo que yo hago:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Habiendo de ser Abraham en gran gente y fuerte, y habiendo de ser benditas en él todas las naciones de la tierra?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Porque yo lo he conocido, que mandará a sus hijos y a su casa después de sí, que guarden el camino de Jehová, haciendo justicia y juicio, para que haga venir Jehová sobre Abraham lo que ha hablado sobre él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Entonces Jehová le dijo: El clamor de Sodoma y de Gomorra, porque se ha engrandecido, y el pecado de ellos, porque se ha agravado en gran manera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Descenderé ahora, y veré, si según su clamor que ha venido hasta mí, hayan hecho consumación: y si no, saberlo he.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Y apartáronse de allí los varones, y fueron a Sodoma: mas Abraham estuvo aún delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, '¶ Y acercóse Abraham, y dijo: ¿Destruirás también al justo con el impío?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Quizá hay cincuenta justos dentro de la ciudad: ¿destruirás también, y no perdonarás al lugar por cincuenta justos que estén dentro de él?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Nunca tal hagas, que hagas morir al justo con el impío: ¿y que sea el justo como el impío? Nunca tal hagas. El Juez de toda la tierra, ¿no ha de hacer derecho?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Entonces respondió Jehová: Si hallare en Sodoma cincuenta justos dentro de la ciudad, perdonaré a todo este lugar por amor de ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Y Abraham replicó, y dijo: He aquí, ahora que he comenzado a hablar a mi Señor, aunque soy polvo y ceniza;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Quizá faltarán de cincuenta justos, cinco: ¿destruirás por aquellos cinco, que falten, toda la ciudad? Y dijo: No la destruiré, si hallare allí cuarenta y cinco.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Y añadió más a hablarle, y dijo: ¿Quizá se hallarán allí cuarenta? Y respondió: No lo haré por cuarenta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Y dijo: No se enoje ahora mi Señor, si hablare: ¿Quizá se hallarán allí treinta? Y respondió: No lo haré si hallare allí treinta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Y dijo: He aquí ahora que he comenzado a hablar a mi Señor: ¿Quizá se hallarán allí veinte? Respondió: No destruiré por veinte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Y volvió a decir: No se enoje ahora mi Señor, si hablare solamente una vez: ¿Quizá se hallarán allí diez? Respondió: No destruiré por diez.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Y se fue Jehová después que acabó de hablar a Abraham: y Abraham se volvió a su lugar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Vinieron, pues, los dos ángeles a Sodoma a la tarde: y Lot estaba sentado a la puerta de Sodoma: y viéndolos Lot, levantóse a recibirlos, e inclinóse la faz a tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Y dijo: He aquí ahora, mis señores, ruégoos que vengáis a casa de vuestro siervo, y dormiréis, y lavaréis vuestros pies: y por la mañana os levantaréis, e iréis vuestro camino. Y ellos respondieron: No, que en la plaza dormiremos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Mas él porfió con ellos mucho, y viniéronse con él, y entraron en su casa, e hízoles banquete, y coció panes sin levadura, y comieron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Y antes que se acostasen, los varones de la ciudad, los varones de Sodoma, cercaron la casa desde el mozo hasta el viejo, todo el pueblo de cabo a cabo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Y llamaron a Lot, y dijéronle: ¿Dónde están los varones que vinieron a ti esta noche? Sácanoslos, para que los conozcamos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Entonces Lot salió a ellos a la puerta, y cerró las puertas tras sí;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Y dijo: Hermanos míos, ruégoos que no hagáis mal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'He aquí ahora, yo tengo dos hijas, que no han conocido varón; sacarlas he ahora a vosotros, y hacéd de ellas como bien os parecerá: solamente a estos varones no hagáis nada, porque por eso vinieron a la sombra de mi tejado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Y ellos respondieron: Quita allá. Y dijeron aun: Vino solo para habitar: ¿y juzgará juzgando? Ahora te haremos más mal que a ellos. Y hacían gran violencia al varón, a Lot: y llegáronse para quebrar las puertas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Entonces los varones extendieron su mano, y metieron a Lot consigo en casa, y cerraron las puertas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Y a los varones, que estaban a la puerta de la casa, hirieron con ceguedades, desde el pequeño hasta el grande; mas ellos se fatigaban por hallar la puerta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, '¶ Y dijeron los varones a Lot: ¿Tienes aun aquí alguno? Yernos, y tus hijos, y tus hijas, y todo lo que tienes en la ciudad, saca de este lugar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Porque destruimos este lugar, porque el clamor de ellos se ha engrandecido delante de Jehová; por tanto Jehová nos ha enviado para destruirlo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Entonces salió Lot, y habló a sus yernos, los que habían de tomar sus hijas, y díjoles: Levantáos, salíd de este lugar; porque ha de destruir Jehová esta ciudad: mas fue tenido como burlador en los ojos de sus yernos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Y como el alba subía, los ángeles dieron priesa a Lot, diciendo: Levántate, toma a tu mujer, y tus dos hijas, que se hallan aquí, porque no perezcas en el castigo de la ciudad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Y deteniéndose él, los varones asieron de su mano, y de la mano de su mujer, y de las manos de sus dos hijas, en la misericordia de Jehová que era sobre él: y sacáronle, y pusiéronle fuera de la ciudad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Y fue, que sacándoles fuera, dijo: Escápate: sobre tu alma no mires tras ti, ni pares en toda esta llanura, en el monte escápate, porque no perezcas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Y Lot les dijo: No, yo os ruego, señores míos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'He aquí ahora, ha hallado tu siervo gracia en tus ojos, y has engrandecido tu misericordia, que has hecho conmigo, dándome la vida: mas yo no podré escaparme en el monte, que quizá no se me pegue el mal, y muera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'He aquí ahora, esta ciudad está cercana para huir allá, la cual es pequeña, escaparme he ahora allí; ¿no es pequeña, y vivirá mi alma?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Y respondióle: He aquí, yo he recibido tus ruegos también por esto, para no destruir la ciudad de que has hablado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Dáte priesa, escápate allá; porque no podré hacer nada, hasta que hayas llegado allá. Por esto fue llamado el nombre de la ciudad Segor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'El sol salía sobre la tierra, cuando Lot llegó a Segor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Y Jehová llovió sobre Sodoma y sobre Gomorra azufre y fuego de Jehová desde los cielos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Y trastornó las ciudades, y toda aquella llanura con todos los moradores de aquellas ciudades, y el fruto de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, '¶ Entonces su mujer miró atrás de él, y fue vuelta estatua de sal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Y levantóse Abraham por la mañana al lugar donde había estado delante de Jehová;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Y miró hacia Sodoma y Gomorra, y hacia toda la tierra de aquella llanura miró; y he aquí que el humo subía de la tierra, como el humo de un horno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Y fue, que destruyendo Dios las ciudades de la llanura, Dios se acordó de Abraham, y envió a Lot de en medio de la destrucción, destruyendo las ciudades donde Lot estaba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, '¶ Empero Lot subió de Segor, y asentó en el monte, y sus dos hijas con él; porque tuvo miedo de quedar en Segor, y asentó en una cueva él y sus dos hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Entonces la mayor dijo a la menor: Nuestro padre es viejo, y no queda varón en la tierra que entre a nosotras conforme a la costumbre de toda la tierra:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Ven, demos a beber vino a nuestro padre, y durmamos con él, y conservaremos de nuestro padre generación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Y dieron a beber vino a su padre aquella noche: y entró la mayor, y durmió con su padre; y él no supo cuando la hija se acostó, ni cuando se levantó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'El día siguiente dijo la mayor a la menor: He aquí, yo dormí la noche pasada con mi padre; démosle a beber vino también esta noche, y entra, duerme con él, y conservaremos de nuestro padre generación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Y dieron a beber vino a su padre también aquella noche, y levantóse la menor, y durmió con él; y él no supo cuando la hija se acostó, ni cuando se levantó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Y concibieron las dos hijas de Lot, de su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Y parió la mayor un hijo, y llamó su nombre Moab: el cual es padre de los Moabitas hasta hoy.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'La menor también parió un hijo, y llamó su nombre Ben-ammi, el cual es padre de los Ammonitas hasta hoy.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'De allí se partió Abraham a la tierra del mediodía, y asentó entre Cádes y Sur; y peregrinó en Gerar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Y decía Abraham de Sara su mujer: Mi hermana es. Y Abimelec, rey de Gerar, envió, y tomó a Sara.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Empero Dios vino a Abimelec en sueños de noche, y díjole: He aquí, muerto eres por la mujer que tomaste, la cual es casada con marido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Mas Abimelec no había llegado a ella, y dijo: Señor: ¿matarás también la gente justa?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, '¿El no me dijo: Mi hermana es; y ella también dijo: Mi hermano es? Con sencillez de mi corazón, y con limpieza de mis manos he hecho esto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Y díjole Dios en sueños: Yo también sé que con entereza de tu corazón has hecho esto: y yo también te detuve de pecar contra mí, por tanto no te permití que tocases en ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Ahora, pues, vuelve la mujer a su marido, porque es profeta; y orará por ti, y vive. Y si tú no la volvieres, sepas que muriendo morirás con todo lo que fuere tuyo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Entonces Abimelec se levantó de mañana, y llamó a todos sus siervos, y dijo todas estas palabras en los oídos de ellos, y temieron los hombres en gran manera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Después llamó Abimelec a Abraham, y díjole: ¿Qué nos has hecho? ¿y qué pequé yo contra ti, que has metido sobre mí, y sobre mi reino tan gran pecado? Obras que no son de hacer has hecho conmigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Y dijo más Abimelec a Abraham: ¿Qué viste, para que hicieses esto?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Y Abraham respondió: Porque dije: Cierto no hay temor de Dios en este lugar: y matarme han por causa de mi mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Y también cierto mi hermana es, hija de mi padre, mas no hija de mi madre, y toméla por mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Y fue, que cuando Dios me hizo salir vagabundo de la casa de mi padre, yo le dije: Esta será tu misericordia que harás conmigo, que en todos los lugares donde viniéremos, digas de mí, Mi hermano es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Entonces Abimelec tomó ovejas y vacas, y siervos, y siervas, y dio a Abraham, y volvióle a Sara su mujer:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Y dijo Abimelec: He aquí, mi tierra está delante de ti, en lo que bien te pareciere, habita.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Y a Sara dijo: He aquí, he dado mil pesos de plata a tu hermano; he aquí, él te es por velo de ojos a todos los que estuvieron contigo, y con todos: y escarmienta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Entonces Abraham oró a Dios, y Dios sanó a Abimelec y a su mujer, y a sus siervas, y parieron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Porque cerrando había cerrado Jehová toda matriz de la casa de Abimelec, a causa de Sara mujer de Abraham.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Y visitó Jehová a Sara, como había dicho; e hizo Jehová con Sara como había hablado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Que concibió y parió Sara a Abraham un hijo en su vejez, en el tiempo que Dios dijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Y llamó Abraham el nombre de su hijo, que le nació, que le parió Sara, Isaac.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Y circuncidó Abraham a su hijo Isaac de ocho días, como Dios le mandó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Y era Abraham de cien años, cuando le nació Isaac su hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Entonces dijo Sara: Risa me ha hecho Dios; y cualquiera que lo oyere, se reirá conmigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Y dijo: ¿Quién dijera a Abraham, que Sara había de dar leche a hijos? que le he parido un hijo a su vejez.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Y creció el niño, y fue destetado; e hizo Abraham gran banquete el día que fue destetado Isaac.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, '¶ Y vio Sara al hijo de Agar la Egipcia, que había parido a Abraham, que se burlaba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Y dijo a Abraham: Echa a esta sierva y a su hijo, que el hijo de esta sierva no ha de heredar con mi hijo, con Isaac.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Este dicho pareció grave en gran manera a Abraham a causa de su hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Entonces dijo Dios a Abraham: No te parezca grave a causa del mozo y de tu sierva: en todo lo que te dijere Sara, oye en su voz; porque en Isaac te será llamada generación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Y también al hijo de la sierva pondré en gente, porque es tu simiente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Entonces Abraham se levantó muy de mañana, y tomó pan, y un cuero de agua, y diólo a Agar poniéndolo sobre su hombro; y dióle al muchacho, y envióla: y ella fue, y perdióse en el desierto de Beer-seba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, '¶ Y faltóle el agua del cuero, y echó el muchacho debajo de un árbol,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Y fuése, y sentóse en derecho, alejándose cuanto un tiro de arco, diciendo: No veré cuando el muchacho morirá; y sentóse en derecho, y alzó su voz y lloró.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Y oyó Dios la voz del muchacho: y el ángel de Dios dio voces a Agar desde los cielos, y díjole: ¿Qué has Agar? no hayas miedo; porque Dios ha oído la voz del muchacho en donde está.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Levántate, alza el muchacho, y tómale de tu mano; que en gran gente le tengo de poner.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Entonces abrió Dios sus ojos, y vio una fuente de agua; y fue, e hinchió el cuero de agua, y dio de beber al muchacho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Y fue Dios con el muchacho; y creció, y habitó en el desierto, y fue tirador de arco.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Y habitó en el desierto de Farán, y su madre le tomó mujer de la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, '¶ Y fue en aquel mismo tiempo, que habló Abimelec, y Ficol príncipe de su ejército a Abraham, diciendo: Dios es contigo en todo cuanto haces.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Ahora, pues, júrame aquí por Dios, que no faltarás a mí, y a mi hijo, y a mi nieto: conforme a la misericordia que yo hice contigo, harás tú conmigo, y con la tierra donde has peregrinado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Y respondió Abraham: Yo juraré.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Y Abraham reprendió a Abimelec a causa de un pozo de agua, que los siervos de Abimelec le habían tomado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Y respondió Abimelec: Yo no sé quien haya hecho esto: ni tampoco tú me lo hiciste saber, ni yo lo he oído hasta hoy.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Y tomó Abraham ovejas y vacas, y dio a Abimelec, e hicieron ambos alianza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Y puso Abraham siete corderas de la manada a parte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Y dijo Abimelec a Abraham: ¿Qué significan estas siete corderas, que has puesto a parte?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Y él respondió: Que estas siete corderas tomarás de mi mano, para que me sea en testimonio, que yo cavé este pozo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Por esto llamó a aquel lugar Beer-seba; por que allí juraron ambos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'E hicieron alianza en Beer-seba: y levantóse Abimelec, y Ficol príncipe de su ejército, y volviéronse a tierra de los Filisteos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Y plantó un bosque en Beer-seba, e invocó allí el nombre de Jehová Dios eterno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Y moró Abraham en tierra de los Filisteos muchos días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Y aconteció después de estas cosas, que tentó Dios a Abraham, y díjole: Abraham: Y él respondió: Heme aquí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Y dijo: Toma ahora a tu hijo, tu único, que amas, Isaac, y vete a tierra de Moria; y ofrécele allí en holocausto sobre uno de los montes que yo te diré.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Y Abraham madrugó por la mañana, y enalbardó su asno, y tomó consigo dos mozos suyos, y a Isaac su hijo: y cortó leña para el holocausto; y levantóse, y fue al lugar que Dios le dijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Al tercero día alzó Abraham sus ojos, y vio el lugar de lejos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Entonces dijo Abraham a sus mozos: Esperáos aquí con el asno, y yo y el muchacho iremos hasta allí, y adoraremos, y volveremos a vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Y tomó Abraham la leña del holocausto, y púsola sobre Isaac su hijo: y él tomó en su mano el fuego, y el cuchillo, y fueron ambos juntos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Entonces Isaac habló a Abraham su padre, y dijo: Padre mío: Y él respondió: Heme aquí, mi hijo. Y él dijo: He aquí el fuego y la leña: mas ¿dónde está el cordero para el holocausto?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Y respondió Abraham: Dios proveerá para sí cordero para el holocausto, hijo mío. E iban ambos juntos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Y como llegaron al lugar que Dios le había dicho, edificó allí Abraham un altar, y compuso la leña; y ató a Isaac su hijo, y púsole sobre el altar sobre la leña.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Y extendió Abraham su mano, y tomó el cuchillo, para degollar a su hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, '¶ Entonces el ángel de Jehová le dio voces del cielo, y dijo: Abraham, Abraham. Y él respondió: Heme aquí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Y dijo: No extiendas tu mano sobre el muchacho, ni le hagas nada; que ahora conozco que temes a Dios, que no me rehusaste a tu hijo, tu único.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Entonces alzó Abraham sus ojos, y miró, y he aquí un carnero a sus espaldas trabado en una mata por sus cuernos: y fue Abraham, y tomó el carnero, y ofreciólo en holocausto en lugar de su hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Y llamó Abraham el nombre de aquel lugar; Jehová verá. Por tanto se dice hoy del monte: Jehová verá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Y llamó el ángel de Jehová a Abraham la segunda vez desde el cielo,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Y dijo: Por mí mismo he jurado, dijo Jehová, que por cuanto has hecho esto, que no rehusaste a tu hijo, a tu único,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'Que bendiciendo te bendeciré, y multiplicando multiplicaré tu simiente como las estrellas del cielo, y como la arena que está a la ribera de la mar; y tu simiente poseerá las puertas de sus enemigos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'En tu simiente serán benditas todas las naciones de la tierra, por cuanto obedeciste a mi voz.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Y tornóse Abraham a sus mozos, y levantáronse, y fuéronse juntos a Beer-seba; y habitó Abraham en Beer-seba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Y aconteció después de estas cosas, que fue dada nueva a Abraham, diciendo: He aquí que también Melca ha parido hijos a Nacor tu hermano;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'A Hus su primogénito, y a Buz su hermano, y a Camuel padre de Aram,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Y a Cased, y a Asau, y a Feldas, y a Jedlaf, y a Batuel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Y Batuel engendró a Rebeca. Estos ocho parió Melca a Nacor hermano de Abraham.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Y su concubina, que se llamaba Reuma, parió también a Tabee, y a Gaham, y a Tahas, y a Maaca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Y fue la vida de Sara ciento y veinte y siete años: tantos fueron los años de la vida de Sara.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Y murió Sara en Cariat-arbe, que es Hebrón en la tierra de Canaán: y vino Abraham a endechar a Sara, y a llorarla.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Y levantóse Abraham de delante de su muerto, y habló a los hijos de Jet, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Peregrino y advenedizo soy entre vosotros: dádme heredad de sepultura con vosotros, y sepultaré mi muerto de delante de mí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Y respondieron los hijos de Jet a Abraham, y dijéronle:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Óyenos señor mío, príncipe de Dios eres entre nosotros; en lo mejor de nuestras sepulturas sepulta tu muerto; ninguno de nosotros te impedirá su sepultura para sepultar tu muerto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Y Abraham se levantó, e inclinóse al pueblo de la tierra, a los hijos de Jet.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Y habló con ellos, diciendo: Si tenéis voluntad que yo sepulte mi muerto de delante de mí, oídme, e interveníd por mí con Efrón hijo de Seor,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Que me dé la cueva doble que tiene al cabo de su heredad: por precio bastante me la dé en medio de vosotros por heredad de sepultura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Este Efrón habitaba entre los hijos de Jet: y respondió Efrón Jetteo a Abraham en oídos de los hijos de Jet, de todos los que entraban por la puerta de su ciudad, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'No, señor mío, óyeme: la heredad te doy, y la cueva que está en ella te doy también: delante de los hijos de mi pueblo te la doy; sepulta tu muerto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Y Abraham se inclinó delante del pueblo de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'Y respondió a Efrón en oídos del pueblo de la tierra, diciendo: Antes si te place, ruégote que me oigas: yo daré el precio de la heredad, tómalo de mí, y sepultaré allí mi muerto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Y respondió Efrón a Abraham, diciéndole:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Señor mío, escúchame: La tierra es de cuatrocientos siclos de plata entre mí y ti: ¿Qué es esto? entierra tu muerto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Entonces Abraham se convino con Efrón; y pesó Abraham a Efrón el dinero que dijo en oídos de los hijos de Jet, cuatrocientos siclos de plata corrientes por los mercaderes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Y quedó la heredad de Efrón, que estaba en Macpela enfrente de Mamré, la heredad y la cueva que estaba en ella, y todos los árboles que estaban en la heredad, y en todo su término alrededor,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Por de Abraham en posesión delante de los hijos de Jet, y de todos los que entraban por la puerta de la ciudad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Y después de esto sepultó Abraham a Sara su mujer en la cueva de la heredad de Macpela enfrente de Mamré, que es Hebrón en la tierra de Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Y quedó la heredad, y la cueva que estaba en ella, por de Abraham, en heredad de sepultura, de los hijos de Jet.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Y Abraham era ya viejo, y venido en días: y Jehová había bendecido a Abraham en todo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Y dijo Abraham a su siervo el más viejo de su casa, el que era señor en todo lo que tenía: Pon ahora tu mano debajo de mi muslo;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Y tomarte he juramento por Jehová, Dios de los cielos, y Dios de la tierra, que no tomes mujer para mi hijo de las hijas de Canaán, entre los cuales yo habito:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Mas que irás a mi tierra y a mi parentela, y tomarás de allá mujer para mi hijo Isaac.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Y el siervo le respondió: Quizá la mujer no querrá venir en pos de mí a esta tierra: ¿volveré pues tu hijo a la tierra de donde saliste?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Y Abraham le dijo: Guárdate que no vuelvas mi hijo allá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Jehová Dios de los cielos, que me tomó de la casa de mi padre, y de la tierra de mi naturaleza, y me habló, y me juró, diciendo: A tu simiente daré esta tierra; él enviará su ángel delante de ti, y tomarás de allá mujer para mi hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Y si la mujer no quisiere venir en pos de ti, serás limpio de este mi juramento: solamente que no vuelvas allá a mi hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Entonces el siervo puso su mano debajo del muslo de Abraham su señor, y juróle sobre este negocio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, '¶ Y el siervo tomó diez camellos de los camellos de su señor, y fue, llevando en su mano de lo mejor que su señor tenía; y levantóse, y fue a Aaram Naharaim, a la ciudad de Nacor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'E hizo arrodillar los camellos fuera de la ciudad a un pozo de agua, a la hora de la tarde, a la hora que salen las mozas por agua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Y dijo: Jehová, Dios de mi señor Abraham, haz encontrar ahora delante de mí hoy, y haz misericordia con mi señor Abraham.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'He aquí, yo estoy junto a la fuente de agua, y las hijas de los varones de esta ciudad salen por agua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Sea pues, que la moza a quien yo dijere: Abaja ahora tu cántaro, y beberé; y ella respondiere: Bebe; y también a tus camellos daré a beber: esta sea la que aparejaste a tu siervo Isaac; y en esto conoceré que habrás hecho misericordia con mi señor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Y aconteció, que antes que él acabase de hablar, he aquí Rebeca que salía, la cual había nacido a Batuel, hijo de Melca, mujer de Nacor hermano de Abraham, con su cántaro sobre su hombro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Y la moza era muy hermosa de vista, virgen, que varón no la había conocido: la cual descendió a la fuente, e hinchió su cántaro, y subía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Entonces el siervo corrió hacia ella, y dijo: Ruégote que me des a beber un poco de agua de tu cántaro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Y ella respondió: Bebe, señor mío. Y dióse priesa a abajar su cántaro sobre su mano, y dióle a beber.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Y acabando de darle a beber, dijo: También para tus camellos sacaré agua, hasta que acaben de beber.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Y dióse priesa, y vació su cántaro en la pila, y corrió otra vez al pozo para sacar agua, y sacó para todos sus camellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Y el varón estaba maravillado de ella callando, para saber si Jehová había prosperado su camino, o no.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Y fue, que como los camellos acabaron de beber, el varón sacó un pendiente de oro de medio siclo de peso; y dos ajorcas para sus manos de diez siclos de oro de peso,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Y dijo: ¿Hija de quién eres? Ruégote que me declares: ¿Hay lugar en casa de tu padre donde posemos?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Y ella respondió: Yo soy hija de Batuel, hijo de Melca, al cual parió a Nacor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Y díjole: También hay en nuestra casa paja y mucho forraje, y también lugar para posar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Entonces el varón se inclinó, y adoró a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Y dijo: Bendito sea Jehová, Dios de mi señor Abraham, que no quitó su misericordia y su verdad de mi señor, guiándome Jehová en el camino a casa de los hermanos de mi señor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Y la moza corrió; e hizo saber en casa de su madre estas cosas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Y Rebeca tenía un hermano que se llamaba Labán, el cual corrió fuera al varón a la fuente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Y fue, que como vio el pendiente y las ajorcas en las manos de su hermana, y como oyó las palabras de Rebeca su hermana, que decía: Así me dijo aquel varón; vino al varón; y, he aquí, él estaba junto a los camellos a la fuente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Y díjole: Ven, bendito de Jehová; ¿por qué estás fuera? Yo he limpiado la casa y el lugar para los camellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, '¶ Entonces el varón vino a casa; y Labán desató los camellos, y dio paja y forraje a los camellos, y agua para lavar los pies de él y los pies de los varones que venían con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Y pusieron delante de él de comer; mas él dijo: No comeré hasta que haya hablado mis palabras. Y él le dijo: Habla.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Entonces él dijo: Yo soy siervo de Abraham;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Y Jehová ha bendecido mucho a mi señor, y háse engrandecido; y le ha dado ovejas y vacas, plata y oro, siervos y siervas, camellos y asnos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Y Sara, mujer de mi señor, parió un hijo a mi señor después de su vejez, al cual ha dado todo cuanto tiene.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Y mi señor me hizo jurar, diciendo: No tomarás mujer para mi hijo de las hijas de los Cananeos, en cuya tierra yo habito:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Mas irás a la casa de mi padre, y a mi parentela, y tomarás de allá mujer para mi hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Y yo dije a mi señor: Quizá no querrá venir en pos de mí la mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Entonces él me respondió: Jehová, en cuya presencia yo he andado, enviará su ángel contigo, y prosperará tu camino, y tomarás mujer para mi hijo de mi linaje y de la casa de mi padre:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Entonces serás limpio de mi juramento, cuando hubieres llegado a mi linaje: y si no te la dieren, serás limpio de mi juramento.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Y vine hoy a la fuente, y dije: Jehová, Dios de mi señor Abraham, si tú prosperas hoy mi camino por el cual yo ando;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'He aquí, yo estoy junto a esta fuente de agua; sea pues, que la doncella que saliere por agua, a la cual yo dijere: Dáme ahora de beber un poco de agua de tu cántaro;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'Y ella me respondiere: Bebe tú, y también para tus camellos sacaré agua: esta sea la mujer que aparejó Jehová al hijo de mi señor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Y antes que acabase de hablar en mi corazón, he aquí Rebeca que salía con su cántaro sobre su hombro, y descendió a la fuente, y sacó agua: y yo la dije: Ruégote que me des a beber.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Y ella prestamente abajó su cántaro de encima de sí, y dijo: Bebe, y también a tus camellos daré a beber. Y bebí, y dio también de beber a mis camellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Entonces preguntéle, y dije: ¿Cúya hija eres? Y ella respondió: Hija de Batuel, hijo de Nacor, que le parió Melca. Entonces púsele un pendiente sobre su frente y ajorcas sobre sus manos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'E inclinéme, y adoré a Jehová, y bendije a Jehová, Dios de mi señor Abraham, que me había guiado por camino derecho para tomar la hija del hermano de mi señor para su hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Ahora pues, si vosotros hacéis misericordia y verdad con mi señor, declarádmelo: y si no, declarádmelo, y echaré, o a diestra, o a siniestra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Entonces Labán y Batuel respondieron, y dijeron: De Jehová ha salido esto, no podemos hablarte malo ni bueno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'He ahí Rebeca delante de ti; tómala, y vete, y sea mujer del hijo de tu señor, como lo ha dicho Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Y fue, que como el siervo de Abraham oyó sus palabras, inclinóse a tierra a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Y sacó el siervo vasos de plata, y vasos de oro, y vestidos, y dio a Rebeca: también dio cosas preciosas a su hermano, y a su madre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Y comieron y bebieron él y los varones que venían con él, y durmieron: y levantándose de mañana, dijo: Enviádme a mi señor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Entonces respondió su hermano y su madre: Espere la moza con nosotros a lo menos diez días, y después irá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Y él les dijo: No me detengáis, pues que Jehová ha prosperado mi camino: enviádme que me vaya a mi señor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Ellos respondieron entonces: Llamemos a la moza y preguntémosle.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Y llamaron a Rebeca, y dijéronle: ¿Irás tú con este varón? Y ella respondió: Sí; iré.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Entonces enviaron a Rebeca su hermana, y a su ama, y al siervo de Abraham, y a sus varones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Y bendijeron a Rebeca, y dijéronle: Nuestra hermana eres, seas en millares de millares: y tu generación posea la puerta de sus enemigos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Levantóse entonces Rebeca y sus mozas, y subieron sobre los camellos, y siguieron al varón: y el siervo tomó a Rebeca, y fuése.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Y venía Isaac del pozo del Viviente que me ve; porque él habitaba en la tierra del mediodía:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Y había salido Isaac a orar al campo a la hora de la tarde; y alzando sus ojos, miró; y, he aquí, los camellos que venían.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Rebeca también alzó sus ojos, y vio a Isaac, y descendió del camello.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Porque había preguntado al siervo: ¿Quién es este varón que viene por el campo hacia nosotros? Y el siervo había respondido: Este es mi señor. Ella entonces tomó el velo, y cubrióse.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Entonces el siervo contó a Isaac todo lo que había hecho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Y metióla Isaac a la tienda de su madre Sara, y tomó a Rebeca por mujer; y la amó: y consolóse Isaac después de la muerte de su madre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Y Abraham tomó otra mujer, cuyo nombre fue Cetura:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'La cual le parió a Zamram, y a Jecsán, y a Madán, y a Madián, y a Jesboc, y a Sue.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Y Jecsán engendró a Saba, y a Dadán; e hijos de Dadán fueron Assurim, y Latussim, y Laomim.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'E hijos de Madián; Efa, y Efer, y Jenoc, y Abida, y Eldaa. Todos estos fueron hijos de Cetura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Y Abraham dio todo lo que tenía a Isaac.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Y a los hijos de sus concubinas dio Abraham dones: y envióles de junto a Isaac su hijo, mientras él vivió, al oriente, a la tierra oriental.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, '¶ Estos empero fueron los días de la vida de Abraham que vivió ciento y setenta y cinco años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Y espiró y murió Abraham en buena vejez, viejo, y harto de días, y fue agregado a sus pueblos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Y sepultáronle Isaac e Ismael sus hijos en la cueva doble, en la heredad de Efrón hijo de Seor Jetteo, que estaba en frente de Mamré:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'La heredad que compró Abraham de los hijos de Jet; allí está sepultado y Sara su mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Y fue, que después de muerto Abraham, bendijo Dios a Isaac su hijo: y habitó Isaac junto al pozo del Viviente que me ve.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, '¶ Y estas son las generaciones de Ismael hijo de Abraham, que parió Agar Egipcia, sierva de Sara, a Abraham.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Estos pues son los nombres de los hijos de Ismael por sus nombres, por sus linajes. El primogénito de Ismael, Nabajot; y Cedar, y Adbeel, y Mabsam,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Y Masma, y Duma, y Massa,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar, y Tema, y Jetur, y Nafis, y Cedma:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Estos son los hijos de Ismael; y estos son sus nombres por sus villas y por sus palacios; doce príncipes por sus familias.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Y estos fueron los años de la vida de Ismael, ciento y treinta y siete años: y espiró y murió Ismael, y fue agregado a sus pueblos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Y habitaron desde Hevila hasta el Sur, que está en frente de Egipto viniendo a Assur: delante de todos sus hermanos cayó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Y estas fueron las generaciones de Isaac, hijo de Abraham: Abraham engendró a Isaac:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Y era Isaac de cuarenta años cuando tomó a Rebeca, hija de Batuel Arameo de Padan-aram, hermana de Labán Arameo, por su mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, '¶ Y oró Isaac a Jehová por su mujer que era estéril; y aceptólo Jehová, y concibió Rebeca su mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Y los hijos se combatían dentro de ella, y dijo: Si así había de ser, ¿para qué vivo yo? Y fue a consultar a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Y respondióle Jehová: Dos naciones hay en tu vientre, y dos pueblos serán divididos de tus entrañas; mas el un pueblo será más fuerte que el otro pueblo, y el mayor servirá al menor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Y como se cumplieron sus días para parir, he aquí mellizos en su vientre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Y salió el primero bermejo, y todo él velludo como una ropa; y llamaron su nombre Esaú.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Y después salió su hermano, trabada su mano al calcañar de Esaú: y fue llamado su nombre Jacob. Y era Isaac de edad de sesenta años cuando Rebeca los parió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Y crecieron los niños; y Esaú fue varón sabio en la caza, hombre del campo: Jacob empero era varón sincero, que estaba en las tiendas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Y amó Isaac a Esaú, porque comía de su caza. Mas Rebeca amaba a Jacob.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, '¶ Y guisó Jacob un guisado: y volviendo Esaú del campo cansado,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Dijo Esaú a Jacob: Ruégote que me des a comer de eso bermejo, eso bermejo, que estoy cansado. Por tanto fue llamado su nombre, Edom.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Y Jacob respondió: Véndeme hoy en este día tu primogenitura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Entonces dijo Esaú: He aquí, yo me voy a morir, ¿para qué pues me servirá la primogenitura?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Y dijo Jacob: Júrame hoy en este día. Y él le juró, y vendió su primogenitura a Jacob.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Entonces Jacob dio a Esaú del pan, y del guisado de las lantejas; y él comió, y bebió, y levantóse, y fuése. Y así menospreció Esaú la primogenitura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Y hubo hambre en la tierra además de la primera hambre, que fue en los días de Abraham: y fuése Isaac a Abimelec, rey de los Filisteos, en Gerar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Y apareciósele Jehová, y díjole: No desciendas a Egipto: habita en la tierra que yo te diré.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Habita en esta tierra, y yo seré contigo; y te bendeciré; porque a ti, y a tu simiente, daré todas estas tierras; y confirmaré el juramento que juré a Abraham tu padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Y yo multiplicaré tu simiente como las estrellas del cielo; y daré a tu simiente todas estas tierras: y todas las gentes de la tierra serán benditas en tu simiente;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Por cuanto oyó Abraham mi voz, y guardó mi observancia, mis mandamientos, mis estatutos, y mis leyes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Así habitó Isaac en Gerar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, '¶ Y los hombres de aquel lugar preguntaron de su mujer; y él respondió: Es mi hermana: Porque tuvo miedo de decir; Es mi mujer: Quizá, dijo él, los varones de aquel lugar me matarán por causa de Rebeca; porque era hermosa de vista.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Y fue, que como él estuvo allí muchos días, Abimelec, rey de los Filisteos, mirando por una ventana, vio a Isaac que jugaba con Rebeca su mujer:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Y llamó Abimelec a Isaac, y dijo: He aquí, ciertamente ella es tu mujer: ¿cómo pues dijiste: Es mi hermana? E Isaac le respondió: Porque dije: Quizá moriré por causa de ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Y Abimelec dijo: ¿Por qué nos has hecho esto? Por poco hubiera dormido alguno del pueblo con tu mujer, y hubieras traído sobre nosotros el pecado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Entonces Abimelec mandó a todo el pueblo, diciendo: El que tocare a este hombre, o a su mujer, muriendo morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, '¶ Y sembró Isaac en aquella tierra, y halló aquel año cien modios; y bendíjole Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Y el varón se engrandeció, y fue yendo y engrandeciéndose, hasta hacerse muy grande.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Y tuvo hato de ovejas, y hato de vacas, y grande apero; y los Filisteos le tuvieron envidia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Y todos los pozos que habían abierto los siervos de Abraham su padre en sus días, los Filisteos los habían cerrado, y henchido de tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Y dijo Abimelec a Isaac: Apártate de nosotros; porque mucho más fuerte que nosotros te has hecho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, '¶ E Isaac se fue de allí; y asentó sus tiendas en el valle de Gerar, y habitó allí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Y volvió Isaac, y abrió los pozos de agua, que habían abierto en los días de Abraham su padre, y que los Filisteos habían cerrado muerto Abraham: y llamólos de los nombres que su padre los había llamado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Y los siervos de Isaac cavaron en el valle, y hallaron allí un pozo de aguas vivas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Y los pastores de Gerar riñeron con los pastores de Isaac, diciendo: El agua es nuestra. Por eso llamó el nombre del pozo Esek, porque habían altercado con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Y abrieron otro pozo; y riñeron también sobre él: y llamó su nombre, Sitna.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, '¶ Y pasóse de allí, y abrió otro pozo, y no riñeron sobre él: y llamó su nombre Rehobot, y dijo: Porque ahora nos ha hecho ensanchar Jehová, y fructificarémos en la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Y de allí subió a Beer-seba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Y apareciósele Jehová aquella noche, y dijo: Yo soy el Dios de Abraham tu padre: no temas, que yo soy contigo; y yo te bendeciré, y multiplicaré tu simiente por causa de Abraham mi siervo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Y edificó allí altar, e invocó el nombre de Jehová, y tendió allí su tienda; y abrieron allí los siervos de Isaac un pozo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, '¶ Y Abimelec vino a él desde Gerar, y Ocozat amigo suyo, y Ficol capitán de su ejército.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Y díjoles Isaac: ¿Por qué venís a mí, pues que me habéis aborrecido, y me enviasteis que no estuviese con vosotros?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Y ellos respondieron: Hemos visto que Jehová es contigo; y dijimos: Haya ahora juramento entre nosotros; entre nosotros y ti: y haremos alianza contigo;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Que no nos hagas mal, como nosotros no te hemos tocado, y como solamente te hemos hecho bien, y te enviamos en paz: tú ahora, bendito de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Entonces él les hizo banquete, y comieron, y bebieron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Y madrugaron por la mañana, y juraron el uno al otro, e Isaac los envió, y partiéronse de él en paz.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Y fue que en aquel día vinieron los siervos de Isaac, y diéronle nuevas de los negocios del pozo que habían abierto, y dijéronle: Agua hemos hallado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Y llamóle Siba; por esta causa el nombre de aquella ciudad es Beer-seba hasta este día.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, '¶ Y como Esaú fue de cuarenta años, tomó por mujer a Judit, hija de Beeri Jetteo, y a Basemat hija de Elón Jetteo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Y fueron amargura de espíritu a Isaac, y a Rebeca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Y fue, que como Isaac envejeció, y sus ojos se oscurecieron de vista, llamó a Esaú su hijo el mayor, y díjole: Mi hijo: y él respondió: Heme aquí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Y él dijo: He aquí, ya soy viejo; no sé el día de mi muerte:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Toma pues ahora tus armas, tu aljaba y tu arco; y sal al campo; y toma para mí caza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Y házme guisados, como yo amo, y tráeme, y comeré, para que te bendiga mi alma antes que muera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Y Rebeca oyó, cuando hablaba Isaac a Esaú su hijo: y fuése Esaú al campo para tomar la caza que había de traer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Entonces Rebeca habló a Jacob su hijo, diciendo: He aquí, yo he oído a tu padre que hablaba con Esaú tu hermano, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Tráeme caza; y házme guisados, para que coma, y te bendiga delante de Jehová, antes que muera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Ahora pues, mi hijo, obedece a mi voz en lo que te mando.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Vé ahora al ganado; y tómame de allá dos cabritos de las cabras buenos, y yo haré de ellos guisados para tu padre, como él ama.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Y tú los llevarás a tu padre, y comerá, para que te bendiga antes de su muerte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Y Jacob dijo a Rebeca su madre: He aquí, Esaú mi hermano es hombre velloso, y yo hombre sin pelos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Quizá me tentará mi padre, y tenerme ha por burlador; y traeré sobre mí maldición y no bendición.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Y su madre le respondió: Hijo mío, sobre mí sea tu maldición: solamente obedece a mi voz, y vé, y tómame los.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Entonces él fue, y tomó, y trajo a su madre: y su madre hizo guisados, como su padre los amaba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Y tomó Rebeca los vestidos de Esaú, su hijo mayor, los preciosos, que ella tenía en casa, y vistió a Jacob su hijo menor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'E hízole vestir sobre sus manos, y sobre la cerviz donde no tenía pelos, las pieles de los cabritos de las cabras;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Y dio los guisados y pan, que había aderezado, en la mano de Jacob su hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Y él vino a su padre, y dijo: Padre mío. Y él respondió: Heme aquí, ¿quién eres, hijo mío?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Y Jacob dijo a su padre: Yo soy Esaú tu primogénito: yo he hecho como me dijiste: levántate ahora, y siéntate, y come de mi caza, para que me bendiga tu alma.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Entonces Isaac dijo a su hijo: ¿Qué es esto, que tan presto hallaste, hijo mío? Y él respondió: Porque Jehová tu Dios hizo que se encontrase delante de mí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'E Isaac dijo a Jacob: Llégate ahora, y palparte he, hijo mío, si eres mi hijo Esaú, o no.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Y llegóse Jacob a su padre Isaac, y él le palpó, y dijo: La voz, la voz es de Jacob; mas las manos, las manos de Esaú.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Y no le conoció, porque sus manos eran vellosas como las manos de Esaú; y bendíjole.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Y dijo: ¿Eres tú mi hijo Esaú? Y él respondió: Yo soy.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Y dijo: Llégame lo, y comeré de la caza de mi hijo, para que te bendiga mi alma; y él le llegó, y comió: y trájole vino, y bebió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Y díjole Isaac su padre: Llega ahora, y bésame, hijo mío.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Y él se llegó, y besóle, y olió el olor de sus vestidos, y bendíjole, y dijo: Mira, el olor de mi hijo, como el olor del campo que Jehová bendijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Y Dios te dé del rocío del cielo, y de las grosuras de la tierra, y abundancia de trigo y de mosto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Sírvante pueblos, y naciones se inclinen a ti. Sé señor de tus hermanos, e inclínense a ti los hijos de tu madre: malditos los que te maldijeren: y benditos los que te bendijeren.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Y fue, que en acabando Isaac de bendecir a Jacob, solamente saliendo había salido Jacob de delante de Isaac su padre, y Esaú su hermano vino de su caza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'E hizo también él guisados, y trajo a su padre; y dijo a su padre: Levántese mi padre, y coma de la caza de su hijo, para que me bendiga tu alma.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Entonces su padre Isaac le dijo: ¿Quién eres tú? Y él dijo: Yo soy tu hijo, tu primogénito Esaú.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, '¶ Entonces Isaac se estremeció de un grande estremecimiento, y dijo: ¿Quién es el que vino aquí, que tomó caza, y me trajo, y yo comí de todo antes que tú vinieses? yo le bendije y será bendito.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Como Esaú oyó las palabras de su padre, clamó con exclamación muy grande y muy amarga; y dijo a su padre: Bendíceme también a mí, padre mío.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Y él dijo: Vino tu hermano con engaño, y tomó tu bendición.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Y él respondió: Bien llamaron su nombre Jacob, que ya me ha engañado dos veces: tomóme mi primogenitura, y he aquí ahora, ha tomado mi bendición. Y dijo: ¿No me has guardado bendición?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Isaac respondió, y dijo a Esaú: He aquí, yo le he puesto por tu señor, y a todos sus hermanos le he dado por siervos; de trigo y de vino le he fortalecido; ¿qué pues te haré a ti ahora, hijo mío?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Y Esaú respondió a su padre: ¿No tienes que una sola bendición, padre mío? Bendíceme también a mí, padre mío. Y alzó Esaú su voz, y lloró.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Entonces Isaac su padre habló, y díjole: He aquí, en grosuras de la tierra será tu habitación; y del rocío de los cielos de arriba:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Y por tu espada vivirás, y a tu hermano servirás: mas será tiempo cuando te enseñorees, y descargues su yugo de tu cerviz.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, '¶ Y aborreció Esaú a Jacob por la bendición, con que su padre le había bendecido, y dijo en su corazón: Llegarse han los días del luto de mi padre, y yo mataré a Jacob mi hermano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Y fueron dichas a Rebeca las palabras de Esaú su hijo mayor; y ella envió, y llamó a Jacob su hijo menor, y díjole: He aquí, Esaú, tu hermano, se consuela sobre ti para matarte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Ahora pues, hijo mío, obedece a mi voz, y levántate, y húyete a Labán mi hermano, a Harán:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Y mora con él algunos días, hasta que el enojo de tu hermano se vuelva.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Hasta que se mitigue el furor de tu hermano de ti; y se olvide de lo que le has hecho: y yo enviaré, y te tomaré de allá; porque seré deshijada de vosotros ambos en un día.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Y dijo Rebeca a Isaac. Fastidio tengo de mi vida a causa de las hijas de Jet. Si Jacob toma mujer de las hijas de Jet, como estas, de las hijas de esta tierra, ¿para qué quiero la vida?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Entonces Isaac llamó a Jacob, y bendíjolo, y mandóle, diciendo: No tomes mujer de las hijas de Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Levántate, vé a Padan-aram a casa de Batuel, padre de tu madre, y toma de allí para ti mujer de las hijas de Labán, hermano de tu madre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Y el Dios omnipotente te bendiga, y te haga fructificar, y te multiplique, y seas en congregación de pueblos;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Y te dé la bendición de Abraham, y a tu simiente contigo; para que heredes la tierra de tus peregrinaciones, que Dios dio a Abraham.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Así envió Isaac a Jacob, el cual fue a Padan-aram, a Labán, hijo de Batuel Arameo, hermano de Rebeca, madre de Jacob y de Esaú.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Y vio Esaú como Isaac había bendecido a Jacob, y le había enviado a Padan-aram, para tomar para sí mujer de allá, cuando le bendijo: y que le mandó, diciendo: No tomarás mujer de las hijas de Canaán;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'Y que Jacob había obedecido a su padre y a su madre, y se había ido a Padan-aram.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Y vio Esaú que las hijas de Canaán parecían mal a Isaac su padre;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Y fuése Esaú a Ismael, y tomó para sí por mujer a Mahelet, hija de Ismael, hijo de Abraham, hermana de Nabajot, además de sus mujeres.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, '¶ Y salió Jacob de Beer-seba, y fue a Harán:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Y encontró con un lugar, y durmió allí porque ya el sol era puesto: y tomó de las piedras de aquel lugar y puso a su cabecera, y acostóse en aquel lugar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Y soñó, y he aquí una escalera que estaba en tierra y su cabeza tocaba en el cielo: y he aquí ángeles de Dios que subían y descendían por ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Y, he aquí, Jehová estaba encima de ella, el cual dijo: Yo soy Jehová, el Dios de Abraham tu padre, y el Dios de Isaac: la tierra, en que estás acostado, te daré a ti y a tu simiente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Y será tu simiente como el polvo de la tierra, y multiplicarás al occidente, y al oriente, y al aquilón, y al mediodía; y todas las familias de la tierra serán benditas en ti, y en tu simiente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Y, he aquí, yo soy contigo, y yo te guardaré por donde quiera que fueres, y yo te volveré a esta tierra, porque no te dejaré hasta tanto que haya hecho lo que te he dicho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Y despertó Jacob de su sueño, y dijo: Ciertamente Jehová está en este lugar, y yo no lo sabía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Y tuvo miedo; y dijo: ¡Cuán espantoso es este lugar! No es otra cosa que casa de Dios, y puerta del cielo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Y madrugó Jacob por la mañana, y tomó la piedra que había puesto a su cabecera, y púsola por título, y derramó aceite sobre su cabeza:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Y llamó el nombre de aquel lugar, Bet-el, y cierto Luza era el nombre de la ciudad primero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, '¶ E hizo Jacob voto, diciendo: Si fuere Dios conmigo, y me guardare en este viaje donde voy, y me diere pan para comer, y vestido para vestir;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'Y si tornare en paz a casa de mi padre, Jehová será mi Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Y esta piedra que he puesto por título será casa de Dios: y de todo lo que me dieres, diezmando lo diezmaré para ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Y alzó Jacob sus pies; y fue a la tierra de los hijos de oriente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Y miró, y vio un pozo en el campo: y he aquí tres rebaños de ovejas, que yacían cerca de él; porque de aquel pozo abrevaban los ganados: y había una gran piedra sobre la boca del pozo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Y juntábanse allí todos los rebaños, y revolvían la piedra de sobre la boca del pozo, y abrevaban las ovejas, y volvían la piedra sobre la boca del pozo a su lugar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Y díjoles Jacob: Hermanos míos, ¿de dónde sois? Y ellos respondieron: De Harán somos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Y él les dijo: ¿Conocéis a Labán, hijo de Nacor? Y ellos dijeron: Sí, le conocemos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Y él les dijo: ¿Tiene paz? Y ellos dijeron: Paz: y, he aquí, Raquel su hija viene con el ganado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Y él dijo: He aquí, aun el día es grande: no es aun tiempo de recoger el ganado, abrevad las ovejas, e id a apacentar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Y ellos respondieron: No podemos, hasta que se junten todos los rebaños, y revuelvan la piedra de sobre la boca del pozo, para que abrevemos las ovejas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Estando aun él hablando con ellos, Raquel vino con el ganado de su padre, porque ella era la pastora.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Y fue, que como Jacob vio a Raquel, hija de Labán hermano de su madre, y a las ovejas de Labán el hermano de su madre, llegó Jacob, y revolvió la piedra de sobre la boca del pozo, y abrevó el ganado de Labán hermano de su madre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Y Jacob besó a Raquel, y alzó su voz, y lloró:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Y Jacob dijo a Raquel, como era hermano de su padre, y como era hijo de Rebeca: y ella corrió, y dio las nuevas a su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Y fue, que como oyó Labán las nuevas de Jacob, hijo de su hermana, corrió a recibirle; y abrazóle, y besóle, y trájole a su casa: y él contó a Labán todas estas cosas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Y Labán le dijo: Ciertamente hueso mío, y carne mía eres. Y estuvo con él un mes de tiempo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, '¶ Y dijo Labán a Jacob: ¿Por ser tú mi hermano, me has de servir de balde? Declárame qué será tu salario.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Y Labán tenía dos hijas: el nombre de la mayor era Lia: y el nombre de la menor, Raquel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Y los ojos de Lia eran tiernos; y Raquel era de hermoso semblante, y de hermoso parecer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Y Jacob amó a Raquel, y dijo: Yo te serviré siete años por Raquel, tu hija menor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Y Labán respondió: Mejor es que te la dé a ti, que no que la dé a otro varón: está conmigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Así sirvió Jacob por Raquel siete años, y pareciéronle como pocos días, porque la amaba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Y dijo Jacob a Labán: Dáme mi mujer, porque mi tiempo es cumplido, para que entre a ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Entonces Labán congregó a todos los varones de aquel lugar, e hizo banquete.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Y fue, que a la tarde tomó a Lia su hija, y trájola a él, y él entró a ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Y dio Labán a Zelfa su sierva a su hija Lia por sierva.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, '¶ Y venida la mañana, he aquí que era Lia, y él dijo a Labán: ¿Qué es esto que me has hecho? ¿No te he servido por Raquel? ¿por qué pues me has engañado?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Y Labán respondió: No se hace así en nuestro lugar, que se dé la menor antes de la mayor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Cumple la semana de esta, y dársete ha también esta por el servicio que sirvieres conmigo otros siete años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'E hizo Jacob así, que cumplió la semana de aquella, y él le dio a Raquel su hija por mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Y dio Labán a Raquel su hija, a Bala su sierva por sierva.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Y entró también a Raquel, y la amó también más que a Lia: y sirvió con él aun otros siete años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, '¶ Y vio Jehová que Lia era aborrecida, y abrió su matriz; y Raquel era estéril.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Y concibió Lia, y parió un hijo, y llamó su nombre Rubén, porque dijo: Porque vio Jehová mi aflicción; por tanto ahora me amará mi marido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Y concibió otra vez, y parió un hijo, y dijo: Porque oyó Jehová, que yo era aborrecida, me ha dado también este. Y llamó su nombre Simeón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Y concibió otra vez, y parió un hijo, y dijo: Ahora esta vez será juntado mi marido conmigo, porque le he parido tres hijos: por tanto llamó su nombre Leví.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Y concibió otra vez, y parió un hijo, y dijo: Esta vez alabaré a Jehová. Por eso llamó su nombre Judá: y dejó de parir.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Y viendo Raquel que no paría a Jacob, tuvo envidia de su hermana, y decía a Jacob: Dáme hijos; y si no, yo soy muerta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Y Jacob se enojaba contra Raquel, y decía: ¿ Soy yo en lugar de Dios, que te impidió el fruto de tu vientre?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Y ella dijo: He aquí mi sierva Bala; entra a ella, y parirá sobre mis rodillas, y ahijarme he yo también de ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Así le dio a Bala su sierva por mujer; y Jacob entró a ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Y concibió Bala, y parió a Jacob un hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Y dijo Raquel: Juzgóme Dios, y también oyó mi voz, y dióme un hijo: Por tanto llamó su nombre Dan.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Y concibió otra vez Bala la sierva de Raquel, y parió el hijo segundo a Jacob.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Y dijo Raquel: De luchas de Dios he luchado con mi hermana, también he vencido. Y llamó su nombre Neftalí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Y viendo Lia que había dejado de parir, tomó a Zelfa su sierva, y dióla a Jacob por mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Y parió Zelfa, sierva de Lia, a Jacob un hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Y dijo Lia: Vino la buena ventura. Y llamó su nombre Gad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Y Zelfa, la sierva de Lia, parió otro hijo a Jacob.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Y dijo Lia: Para hacerme bienaventurada; porque las mujeres me dirán bienaventurada: y llamó su nombre Aser.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, '¶ Y fue Rubén en tiempo de la siega de los trigos, y halló mandrágoras en el campo, y trájolas a Lia su madre; y dijo Raquel a Lia: Ruégote que me des de las mandrágoras de tu hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Y ella respondió: ¿Es poco que hayas tomado mi marido, sino que también tomes las mandrágoras de mi hijo? Y dijo Raquel: Por tanto dormirá contigo está noche por las mandrágoras de tu hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Y cuando Jacob volvía del campo a la tarde, salió Lia a él, y díjole: A mí has de entrar; porque alquilando te he alquilado por las mandrágoras de mi hijo. Y durmió con ella aquella noche.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Y oyó Dios a Lia, y concibió, y parió a Jacob el quinto hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Y dijo Lia: Dios ha dado mi salario, por cuanto di mi sierva a mi marido: por eso llamó su nombre Isacar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Y concibió Lia otra vez, y parió el hijo sexto a Jacob.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Y dijo Lia: Dios me ha dado buena dádiva: esta vez morará conmigo mi marido, porque le he parido seis hijos. Y llamó su nombre Zabulón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Y después parió una hija, y llamó su nombre Dina.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, '¶ Y acordóse Dios de Raquel, y oyóla Dios, y abrió su matriz.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Y concibió, y parió un hijo; y dijo: Quitado ha Dios mi vergüenza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Y llamó su nombre José, diciendo: Añádame Jehová otro hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Y fue, que como Raquel parió a José, dijo Jacob a Labán: Envíame, e irme he a mi lugar, y a mi tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Dá me mis mujeres y mis hijos por las cuales he servido contigo; porque tú sabes el servicio que te he servido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Y Labán le respondió: Halle yo ahora gracia en tus ojos: experimentado he, que Jehová me ha bendecido por tu causa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Y dijo: Señálame tu salario, que yo lo daré.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Y él respondió: Tú sabes como te he servido, y cuanto ha sido tu ganado conmigo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Porque poco tenías antes de mí, y ha crecido en multitud, y Jehová te ha bendecido con mi entrada: y ahora ¿cuándo tengo de hacer también yo por mi casa?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Y él dijo: ¿Qué te daré? Jacob respondió: No me des nada: si hicieres conmigo esto, volveré a apacentar tus ovejas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Yo pasaré hoy por todas tus ovejas para quitar de allí toda oveja pintada y manchada; y todo carnero bermejo en los carneros: y lo pintado y manchado en las cabras; y esto será mi salario.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Y responderme ha mi justicia mañana, cuando viniere sobre mí mi salario delante de ti: todo lo que no fuere pintado ni manchado en las cabras, y bermejo en las ovejas, serme ha tenido por de hurto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Y dijo Labán: He aquí, ojalá fuese como tú dices.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Y apartó aquel día los machos cabríos cinchados y manchados, y todas las cabras pintadas y manchadas, todo lo que tenía alguna cosa blanca, y todo lo bermejo en las ovejas, y púsolo en la mano de sus hijos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Y puso tres días de camino entre sí y Jacob; y Jacob apacentaba las otras ovejas de Labán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Y tomóse Jacob varas de álamo verdes, y de almendro, y de castaño, y descortezó en ellas unas mondaduras blancas descubriendo la blancura de las varas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Y puso las varas que había mondado en las pilas, en los abrevaderos del agua, donde las ovejas venían a beber delante de las ovejas, las cuales se calentaban viniendo a beber.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Y calentábanse las ovejas delante de las varas, y parían las ovejas cinchados, pintados, y manchados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Y apartaba Jacob los corderos y poníalos con las ovejas, los cinchados, y todo lo que era bermejo en el hato de Labán. Y ponía su hato a parte, y no lo ponía con las ovejas de Labán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Y era, que todas las veces que se calentaban las tempranas, Jacob ponía las varas delante de las ovejas en las pilas, para que se calentasen delante de las varas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Y cuando venían las ovejas tardías, no las ponía: así eran las tardías para Labán, y las tempranas para Jacob.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Y multiplicó el varón muy mucho, y tuvo muchas ovejas, y siervas, y siervos, y camellos, y asnos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Y oía las palabras de los hijos de Labán, que decían: Jacob ha tomado todo lo que era de nuestro padre: y de lo que era de nuestro padre ha hecho toda esta gloria.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Miraba también Jacob el rostro de Labán, y veía que no era para con él como ayer y anteayer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'También Jehová dijo a Jacob: Vuélvete a la tierra de tus padres, y a tu parentela, que yo seré contigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Y envió Jacob, y llamó a Raquel y a Lia al campo, a sus ovejas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Y díjoles: Yo veo que el rostro de vuestro padre no es para conmigo como ayer y anteayer: y el Dios de mi padre ha sido conmigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Y vosotras sabéis, que con todas mis fuerzas he servido a vuestro padre:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Y vuestro padre me ha mentido, que me ha mudado el salario diez veces; mas Dios no le ha permitido, que me hiciese mal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Si él decía así: Los pintados serán tu salario; entonces todas las ovejas parían pintados: y si decía así: Los cinchados serán tu salario; entonces todas las ovejas parían cinchados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Y quitó Dios el ganado de vuestro padre; y diómelo a mí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Y fue que al tiempo que las ovejas se calentaban, yo alcé mis ojos, y ví en sueños, y he aquí, que los machos subían sobre las hembras cinchados, pintados, y pedriscados:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Y díjome el ángel de Dios en sueños: ¿Jacob? Y yo dije: Heme aquí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Y él dijo: Alza ahora tus ojos, y verás todos los machos que suben sobre las ovejas cinchados, pintados, y pedriscados; porque yo he visto todo lo que Labán te ha hecho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Yo soy el Dios de Bet-el, donde tú ungiste el título, y donde me prometiste voto. Levántate ahora, y sal de esta tierra, y vuélvete a la tierra de tu naturaleza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Y respondió Raquel, y Lia, y dijéronle: ¿Tenemos ya parte ni heredad en la casa de nuestro padre?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, '¿No nos tiene ya como por extrañas? que nos vendió, y aun comiendo ha comido nuestro dinero?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Porque toda la riqueza que Dios ha quitado a nuestro padre, nuestra es, y de nuestros hijos: ahora pues haz todo lo que Dios te ha dicho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Entonces Jacob se levantó, y alzó a sus hijos y a sus mujeres sobre los camellos;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Y guió todo su ganado, y toda su hacienda que había adquirido, el ganado de su ganancia que había adquirido en Padan-aram, para volverse a Isaac su padre en la tierra de Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Y Labán había ido a trasquilar sus ovejas: y Raquel hurtó los ídolos de su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Y hurtó Jacob el corazón de Labán Arameo en no hacerle saber como huía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Y huyó él con todo lo que tenía: y levantóse y pasó el río, y puso su rostro al monte de Galaad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, '¶ Y fue dicho a Labán al tercero día, como Jacob había huido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Y tomó a sus hermanos consigo, y fue tras él camino de siete días, y alcanzóle en el monte de Galaad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Y vino Dios a Labán Arameo en sueño aquella noche, y díjole: Guárdate que no digas a Jacob bueno ni malo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, '¶ Alcanzó pues Labán a Jacob, y Jacob había hincado su tienda en el monte: y Labán hincó con sus hermanos en el monte de Galaad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Y dijo Labán a Jacob: ¿Qué has hecho? ¿Qué me hurtaste el corazón, y has traído mis hijas como cautivadas a cuchillo?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, '¿Por qué te escondiste para huir, y me hurtaste, y no me hiciste saber, que yo te enviara con alegría, y con canciones, con tamboril, y vihuela?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, '¿Qué aun no me dejaste besar mis hijos y mis hijas? Ahora locamente has hecho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Poder hay en mi mano para haceros mal, mas el Dios de vuestro padre me habló anoche, diciendo: Guárdate que no digas a Jacob ni bueno ni malo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Y ya que te ibas, porque tenías deseo de la casa de tu padre, ¿por qué me hurtabas mis dioses?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Y Jacob respondió, y dijo a Labán: Porque tuve miedo: que dije, que quizá me robarías tus hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'En quien hallares tus dioses, no viva: delante de nuestros hermanos reconoce lo que yo tuviere, y tómatelo. Jacob no sabía que Raquel los había hurtado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Y entró Labán en la tienda de Jacob, y en la tienda de Lia, y en la tienda de las dos siervas, y no los halló: y salió de la tienda de Lia y vino a la tienda de Raquel:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Y Raquel tomó los ídolos, y púsolos en una albarda de un camello, y sentóse sobre ellos: y tentó Labán toda la tienda, y no los halló.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Y ella dijo a su padre: No se enoje mi señor, porque no me puedo levantar delante de ti; porque tengo la costumbre de las mujeres. Y él buscó, y no halló los ídolos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Entonces Jacob se enojó, y riñó con Labán, y respondió Jacob, y dijo a Labán: ¿Qué prevaricación es la mía? ¿qué es mi pecado, que has seguido en pos de mí?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Pues que has tentado todas mis alhajas, ¿qué has hallado de todas las alhajas de tu casa? Pon aquí delante de mis hermanos y tuyos, y juzguen entre nosotros ambos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Estos veinte años he estado contigo; que tus ovejas y tus cabras nunca movieron: nunca comí carnero de tus ovejas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Nunca te traje arrebatado, yo pagaba el daño: lo hurtado así de día como de noche, de mi mano lo requerias:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'De día me consumía el calor, y de noche la helada, y mi sueño se huía de mis ojos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Estos veinte años tengo en tu casa; catorce años te serví por tus dos hijas, y seis años por tus ovejas, y has mudado mi salario diez veces.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Si el Dios de mi padre, el Dios de Abraham, y el temor de Isaac no fuera conmigo, cierto vacío me enviaras ahora: mas vio Dios mi aflicción y el trabajo de mis manos, y te reprendió anoche.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Y respondió Labán, y dijo a Jacob: Las hijas, mis hijas son, y los hijos, mis hijos, y las ovejas, mis ovejas; y todo lo que tu ves, mío es: y a estas mis hijas ¿qué tengo de hacer hoy, o a sus hijos que han parido?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Ven pues ahora, y hagamos alianza yo y tú; y sea en testimonio entre mí y ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Entonces Jacob tomó una piedra, y levantóla por título:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Y dijo Jacob a sus hermanos: Cogéd piedras. Y tomaron piedras, e hicieron un majano; y comieron allí sobre aquel majano:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Y llamólo Labán Jegar-sahaduta: y Jacob lo llamó Galaad;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Porque Labán dijo: Este majano será testigo hoy entre mí y ti: por eso llamó su nombre Galaad,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'Y Mispa; porque dijo: Atalaye Jehová entre mí y ti, cuando nos escondieremos el uno del otro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Si afligieres mis hijas, o si tomares otras mujeres además de mis hijas, nadie está con nosotros: mas mira, Dios es testigo entre mí y ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Dijo mas Labán a Jacob: He aquí este majano, y he aquí este título que he fundado entre mí y ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Testigo sea este majano, y testigo sea este título, que ni yo pasaré contra ti este majano, ni tú pasarás contra mí este majano, ni este título para mal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'El Dios de Abraham, y el Dios de Nacor juzgue entre nosotros, el Dios de sus padres. Y Jacob juró por el temor de Isaac su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Y sacrificó Jacob sacrificio en el monte, y llamó a sus hermanos a comer pan; y comieron pan, y durmieron en el monte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Y madrugó Labán por la mañana, y besó sus hijos y sus hijas, y bendíjolos, y volvió, y tornóse a su lugar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Y Jacob se fue su camino, y saliéronle al encuentro ángeles de Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Y dijo Jacob, cuando los vio: El campo de Dios es este: y llamó el nombre de aquel lugar, Mahanaim.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Y envió Jacob mensajeros delante de sí a Esaú su hermano a la tierra de Seir, campo de Edom.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Y mandóles, diciendo: Direis así a mi señor Esaú: Así dice tu siervo Jacob: Con Labán he morado, y detenídome he hasta ahora.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Y tengo vacas, y asnos, y ovejas, y siervos, y siervas: y envió a decirlo a mi señor, por hallar gracia en tus ojos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Y los mensajeros volvieron a Jacob, diciendo: Venimos a tu hermano, a Esaú, y él también viene a recibirte, y cuatrocientos hombres con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Entonces Jacob tuvo gran temor, y angustióse; y partió el pueblo que tenía consigo, y las ovejas, y las vacas, y los camellos en dos cuadrillas;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Y dijo: Si viniere Esaú a la una cuadrilla, y la hiriere, la otra cuadrilla escapará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, '¶ Y dijo Jacob: Dios de mi padre Abraham, y Dios de mi padre Isaac, Jehová, que me dijiste: Vuélvete a tu tierra, y a tu parentela, y yo te haré bien:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Menor soy yo que todas las misericordias, y que toda la verdad que has hecho con tu siervo: que con mi bordón pasé a este Jordán; y ahora estoy sobre dos cuadrillas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Líbrame ahora de la mano de mi hermano, de la mano de Esaú; porque le temo: quizá no venga, y me hiera, y a la madre con los hijos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Y tú has dicho, yo te haré bien, y pondré tu simiente como la arena de la mar, que no se puede contar por la multitud.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, '¶ Y durmió allí aquella noche, y tomó de lo que le vino a la mano un presente para su hermano Esaú:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Doscientas cabras, y veinte machos de cabrío; doscientas ovejas, y veinte carneros;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Treinta camellas paridas con sus crias; cuarenta vacas, y diez novillos; veinte asnas, y diez borricos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Y diólo en mano de sus siervos, cada manada por si, y dijo a sus siervos: Pasád delante de mí, y ponéd espacio entre manada y manada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Y mandó al primero, diciendo: Si Esaú mi hermano te encontrare, y te preguntare, diciendo: ¿Cúyo eres? Y ¿dónde vas? ¿Y para quién es esto, que llevas delante de ti?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Entonces dirás: Presente es de tu siervo Jacob, que envía a mi señor Esaú: y, he aquí, también él viene tras nosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Y mandó también al segundo, también al tercero, y a todos los que iban tras aquellas manadas, diciendo: Conforme a esto hablaréis a Esaú, cuando le hallareis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Y diréis también: He aquí, tu siervo Jacob viene tras nosotros. Porque dijo: Apaciguaré su ira con el presente que va delante de mí, y después veré su rostro; quizá le será acepto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Y pasó el presente delante de él, y él durmió aquella noche en el real.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Y levantóse aquella noche, y tomó sus dos mujeres, y sus dos siervas, y sus once hijos, y pasó el vado de Jaboc.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Y tomólos, y pasólos el arroyo, y pasó lo que tenía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, '¶ Y quedó Jacob solo: y luchó con él un varón, hasta que el alba subía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, '¶ Y como vio que no podía con él, tocó la palma de su anca; y la palma del anca de Jacob se descoyuntó luchando con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Y dijo: Déjame, que el alba sube. Y él dijo: No te dejaré, sino me bendices.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Y él le dijo: ¿Cómo es tu nombre? Y él respondió: Jacob.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Y él dijo: No se dirá más tu nombre Jacob, sino Israel; porque has peleado con Dios y con los hombres, y has vencido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Entonces Jacob le preguntó, y dijo: Declárame ahora tu nombre. Y él respondió: ¿Por qué preguntas por mi nombre? Y bendíjole allí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Y llamó Jacob el nombre de aquel lugar, Fanuel: Porque ví a Dios cara a cara, y mi alma fue librada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Y salióle el sol, como pasó a Fanuel; y cojeaba de su anca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Por esto no comen los hijos de Israel el nervio encogido que está en la palma del anca hasta hoy; porque tocó la palma del anca de Jacob en el nervio encogido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Y alzando Jacob sus ojos miró, y, he aquí, venía Esaú, y los cuatrocientos hombres con él: entonces él repartió los niños entre Lia y Raquel, y las dos siervas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Y puso las siervas y sus niños delante: luego a Lia y a sus niños: y a Raquel y a José los postreros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Y él pasó delante de ellos, e inclinóse a tierra siete veces, hasta que llegó a su hermano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Y Esaú corrió delante de él, y abrazóle, y echóse sobre su cuello, y besóle, y lloraron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Y alzó sus ojos, y vio las mujeres, y los niños, y dijo: ¿Qué te han estos? Y él respondió: Son los niños que Dios ha dado a tu siervo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Y llegaron las siervas, ellas y sus niños, e inclináronse.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Y llegó Lia con sus niños, e inclináronse: y después llegó José, y Raquel, y también se inclinaron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Y él dijo: ¿Qué te ha todo este escuadrón que he encontrado? Y él respondió: Porque hallase gracia en los ojos de mi señor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Y dijo Esaú: Harto tengo yo, hermano mío; sea para ti lo que es tuyo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Y dijo Jacob: No, yo te ruego; Si he ahora hallado gracia en tus ojos, toma mi presente de mi mano; que por eso he visto tu rostro, como quien ve el rostro de Dios; y házme placer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Toma ahora mi bendición que te es traída, porque Dios me ha hecho merced, y todo lo que hay aquí es mío. Y porfió con él, y tomólo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Y dijo: Anda, y vamos: y yo iré delante de ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Y él le dijo: Mi señor sabe que los niños son tiernos, y que tengo ovejas y vacas paridas: y si las fatigan, en un día morirán todas las ovejas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Pase ahora mi señor delante de su siervo; y yo me iré de mi espacio al paso de la hacienda, que va delante de mí, y al paso de los niños, hasta que llegue a mi señor a Seir.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Y Esaú dijo: Dejaré ahora contigo del pueblo que viene conmigo. Y él dijo: ¿Para qué esto? Halle yo gracia en los ojos de mi señor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, '¶ Así se volvió Esaú aquel día por su camino a Seir.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Y Jacob se partió a Socot, y edificó para sí allí casa; e hizo cabañas para su ganado: por tanto llamó el nombre de aquel lugar Socot.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Y vino Jacob sano a la ciudad de Siquem, que es en la tierra de Canaán, cuando venía de Padan-aram, y asentó delante de la ciudad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Y compró una parte del campo, donde tendió su tienda, de mano de los hijos de Jamor padre de Siquem, por cien piezas de moneda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Y asentó allí altar, y llamóle: El Fuerte Dios de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Y salió Dina la hija de Lia, que había parido a Jacob, por ver las hijas de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Y vióla Siquem, hijo de Jamor Heveo, príncipe de aquella tierra, y tomóla, y echóse con ella; y afligióla.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Y apegóse su alma con Dina, la hija de Jacob, y enamoróse de la moza, y habló al corazón de la moza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Y habló Siquem a Jamor su padre, diciendo: Tómame esta moza por mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Y oyó Jacob, que había ensuciado a Dina su hija, estando sus hijos con su ganado en el campo; y calló Jacob hasta que ellos viniesen.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Y salió Jamor, padre de Siquem, a Jacob, para hablar con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Y los hijos de Jacob vinieron del campo en oyéndolo, y entristeciéronse los varones, y ensañáronse mucho, porque hizo vileza en Israel, echándose con la hija de Jacob, que no se debía de hacer así.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Y Jamor habló con ellos, diciendo: El alma de mi hijo Siquem se ha apegado con vuestra hija: ruégoos que se la deis por mujer:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Y consagrád con nosotros: dádnos vuestras hijas, y tomád vosotros las nuestras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Y habitád con nosotros: porque la tierra estará delante de vosotros: morád y negociád en ella, y tomád en ella posesión.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Siquem también dijo a su padre y a sus hermanos: Halle yo gracia en vuestros ojos: y yo daré lo que vosotros me dijereis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Aumentád sobre mí mucho ajuar y dones, que yo daré cuanto me dijereis; y dádme la moza por mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, '¶ Y respondieron los hijos de Jacob a Siquem, y a Jamor, su padre, con engaño, y hablaron; porque había ensuciado a Dina su hermana:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Y dijéronles: No podemos hacer esto, que demos nuestra hermana a hombre que tiene prepucio; porque a nosotros es abominación:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Mas con esta condición os haremos placer. Si fuereis como nosotros, que se circuncide en vosotros todo varón;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Entonces os daremos nuestras hijas, y tomaremos nosotros las vuestras; y habitaremos con vosotros, y seremos un pueblo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Y si no nos oyereis, para circuncidaros, tomaremos nuestra hija, e irnos hemos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Y parecieron bien sus palabras a Jamor, y a Siquem hijo de Jamor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Y no dilató el mozo de hacer aquello, porque la hija de Jacob le había agradado: y él era el más honrado de toda la casa de su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Entonces vino Jamor y Siquem su hijo a la puerta de su ciudad, y hablaron a los varones de su ciudad, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Estos varones son pacíficos con nosotros, y habitarán la tierra; y granjearán en ella, que, he aquí, la tierra es ancha de lugares delante de ellos, nosotros tomaremos sus hijas por mujeres, y darles hemos las nuestras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Mas con esta condición nos harán placer los varones, de habitar con nosotros, para que seamos un pueblo: Si se circuncidare en nosotros todo varón, como ellos son circuncidados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Sus ganados y su hacienda, y todas sus bestias será nuestro: solamente que consintamos con ellos, y habitarán con nosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Y obedecieron a Jamor, y a Siquem su hijo, todos los que salían por la puerta de la ciudad; y circuncidaron a todo varón, cuantos salían por la puerta de la ciudad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Y fue, que al tercero día cuando ellos estaban doloridos, los dos hijos de Jacob, Simeón y Leví, hermanos de Dina, tomaron cada uno su espada, y vinieron contra la ciudad animosamente, y mataron a todo varón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Y a Jamor, y a Siquem su hijo, mataron a filo de espada; y tomaron a Dina de casa de Siquem, y saliéronse.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Y los hijos de Jacob vinieron a los muertos, y saquearon la ciudad: por cuanto habían ensuciado a su hermana.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Sus ovejas, y vacas, y sus asnos, y lo que había en la ciudad y en el campo, tomaron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Y toda su hacienda, y todos sus niños, y sus mujeres llevaron cautivas, y robaron; y todo lo que había en casa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Entonces dijo Jacob a Simeón y a Leví: Turbado me habéis, que me habéis hecho abominable con los moradores de aquesta tierra, el Cananeo y el Ferezeo, teniendo yo pocos hombres: y juntarse han contra mí, y herirme han, y seré destruido yo y mi casa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Y ellos respondieron: ¿Había él de tratar a nuestra hermana como a una ramera?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Y dijo Dios a Jacob: Levántate, sube a Bet-el, y está allí: y haz allí altar al Dios, que te apareció cuando huías de tu hermano Esaú.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Entonces Jacob dijo a su familia, y a todos los que estaban con él: Quitád los dioses ajenos que hay entre vosotros, y limpiaos, y mudád vuestros vestidos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Y levantémonos, y subamos a Bet-el: y allí haré altar al Dios que me respondió en el día de mi angustia, y ha sido conmigo en el camino que he andado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Así dieron a Jacob todos los dioses ajenos que había en su poder, y los zarcillos que estaban en sus orejas; y Jacob los escondió debajo de un alcornoque, que estaba en Siquem.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Y partiéronse; y el terror de Dios fue sobre las ciudades que estaban en sus alrededores, y no siguieron tras los hijos de Jacob.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Y vino Jacob a Luza, que era en tierra de Canaán, esta es Bet-el; él y todo el pueblo que con él estaba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Y edificó allí altar, y llamó al lugar, El-bet-el; porque allí le había aparecido Dios cuando huía de su hermano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, '¶ Entonces murió Débora, ama de Rebeca, y fue sepultada a las raíces de Bet-el, debajo de un alcornoque; y llamó su nombre, Allón-bacut.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, '¶ Y aparecióse otra vez Dios a Jacob cuando fue vuelto de Padan-aram, y bendíjole.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Y díjole Dios: Tu nombre es Jacob, no se llamará más tu nombre Jacob, mas Israel será tu nombre: y llamó su nombre Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Y díjole Dios: Yo soy el Dios omnipotente, crece y multiplícate: gente, y compañía de gente, saldrá de ti; y reyes saldrán de tus lomos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Y la tierra, que yo he dado a Abraham y a Isaac, te daré a ti; y a tu simiente después de ti daré la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Y fuése de él Dios, del lugar donde había hablado con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Y Jacob puso un título en el lugar donde había hablado con él, un título de piedra: y derramó sobre él derramadura, y echó sobre él aceite.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Y llamó Jacob el nombre de aquel lugar donde Dios había hablado con él, Bet-el.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, '¶ Y partieron de Bet-el, y había aun como medía legua de tierra para venir a Efrata; y parió Raquel, y hubo trabajo en su parto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Y fue, que como hubo trabajo en su parir, díjole la partera: No temas, que aun este hijo también tendrás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Y fue, que saliéndosele el alma, porque murió, llamó su nombre Ben-oni; mas su padre le llamó Ben-jamín.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Así murió Raquel; y fue sepultada en el camino de Efrata, esta es Belén.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Y puso Jacob un título sobre su sepultura; este es el título de la sepultura de Raquel, hasta hoy.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, '¶ Y partió Israel, y tendió su tienda de la otra parte de la torre de Eder.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Y fue que morando Israel en aquella tierra, fue Rubén, y durmió con Bala la concubina de su padre: lo cual oyó Israel. Y fueron los hijos de Israel doce.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Los hijos de Lia: el primogénito de Jacob, Rubén; y Simeón, y Leví, y Judá, e Isacar, y Zabulón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Los hijos de Raquel: José, y Ben-jamín.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Y los hijos de Bala, sierva de Raquel: Dan, y Neftalí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Y los hijos de Zelfa, sierva de Lia: Gad, y Aser. Estos fueron los hijos de Jacob, que le nacieron en Padan-aram.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Y vino Jacob a Isaac su padre a Mamré, ciudad de Arbee, esta es Hebrón, donde habitó Abraham e Isaac.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Y fueron los días de Isaac ciento y ochenta años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Y espiró Isaac y murió; y fue recogido a sus pueblos viejo, y harto de días, y sepultáronle Esaú y Jacob sus hijos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Y estas son las generaciones de Esaú, el cual es Edom.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esaú tomó sus mujeres de las hijas de Canaán: a Ada, hija de Elón Jetteo; y Oolibama, hija de Ana, hija de Sebeón Heveo;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'Y Basemat, hija de Ismael, hermana de Nabajot.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Y Ada parió a Esaú a Elifaz; y Basemat parió a Rahuel;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Y Oolibama parió a Jehús, y a Jelón, y a Coré: estos son los hijos de Esaú, que le nacieron en la tierra de Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Y Esaú tomó sus mujeres, y sus hijos, y sus hijas, y todas las personas de su casa, y sus ganados, y todas sus bestias, y toda su hacienda, que había adquirido en la tierra de Canaán, y fuése a otra tierra de delante de Jacob su hermano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Y porque la hacienda de ellos era grande, y no podían habitar juntos; ni la tierra de su peregrinación los podía sostener a causa de sus ganados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Y Esaú habitó en el monte de Seir: Esaú es Edom.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Estos son los linajes de Esaú, padre de Edom en el monte de Seir.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Estos son los nombres de los hijos de Esaú: Elifaz, hijo de Ada, mujer de Esaú; Rahuel, hijo de Basemat, mujer de Esaú.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Y los hijos de Elifaz fueron: Temán, Omar, Sefo, Gatam, y Cenez.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Y Tamna fue concubina de Elifaz, hijo de Esaú, la cual parió a Elifaz a Amalec. Estos son los hijos de Ada, mujer de Esaú.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Y los hijos de Rahuel fueron: Nahat, Zara, Samma, y Meza. Estos son los hijos de Basemat, mujer de Esaú.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Estos fueron los hijos de Oolibama, mujer de Esaú, hija de Ana, que fue hija de Sebeón, la cual parió a Esaú, a Jehús, Jelón, y Coré.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Estos son los duques de los hijos de Esaú: Los hijos de Elifaz primogénito de Esaú: el duque Temán, el duque Omar, el duque Sefo, el duque Cenez.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'El duque Coré, el duque Gatam, y el duque Amalec. Estos son los duques de Elifaz en la tierra de Edom: estos son los hijos de Ada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Y estos son los hijos de Rahuel, hijo de Esaú; el duque Nahat, el duque Zara, el duque Samma, y el duque Meza. Estos son los duques que salieron de Rahuel, en la tierra de Edom: estos son los hijos de Basemat, mujer de Esaú.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Y estos son los hijos de Oolibama, mujer de Esaú: el duque Jehús, el duque Jelón, y el duque Coré. Estos son los duques que salieron de Oolibama, mujer de Esaú, hija de Ana.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Estos pues son los hijos de Esaú y sus duques: Él es Edom.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Y estos son los hijos de Seir Horeo, moradores de la tierra: Lotán, Sobal, Sebeón, Ana.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Disón, Aser, y Disán. Estos son los duques de los Horeos, hijos de Seir en la tierra de Edom.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Los hijos de Lotán fueron: Hori y Hemam: y Tanna fue hermana de Lotán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Y los hijos de Sobal fueron: Alván, Manahat, Ebal, Sefo, y Onán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Y los hijos de Sebeón fueron: Aja, y Ana. Este Ana es el que encontró los mulos en el desierto, cuando apacentaba los asnos de Sebeón su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Los hijos de Ana fueron: Disón, y Oolibama, hija de Ana.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Y estos fueron los hijos de Disón: Hamdán, Esebán, Jetrán, y Charán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Y estos fueron los hijos de Eser: Balaán, Zaván, y Acam.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Y estos fueron los hijos de Disán: Hus, y Arán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Y estos fueron los duques de los Horeos: el duque Lotán, el duque Sobal, el duque Sebeón, el duque Ana,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'El duque Disón, el duque Eser, el duque Disán. Estos fueron los duques de los Horeos, por sus ducados en la tierra de Seir.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, '¶ Y estos fueron los reyes que reinaron en la tierra de Edom, antes que reinase rey sobre los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Y reinó en Edom, Bela hijo de Beor: y el nombre de su ciudad fue Denaba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Y murió Bela, y reinó por él Jobab, hijo de Zara de Bosra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Y murió Jobab, y reinó por él Husam, de tierra de Temán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Y murió Husam, y reinó por él Adad, hijo de Badad, el que hirió a Madián en el campo de Moab: y el nombre de su ciudad fue Avit.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Y murió Adad, y reinó por él Semla de Masreca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Y murió Semla, y reinó en su lugar Saul de Rohobot del río.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Y murió Saul, y reinó por él Balanán, hijo de Acobor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Y murió Balanán, hijo de Acobor, y reinó por él Adar: y el nombre de su ciudad fue Fau: y el nombre de su mujer Meetabel, hija de Matred, hija de Mezaab.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Estos pues son los nombres de los duques de Esaú por sus linajes, y sus lugares, por sus nombres: el duque Tanna, el duque Alva, el duque Jetet,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'El duque Oolibama, el duque Ela, el duque Finón,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'El duque Cenez, el duque Temán, el duque Mabsar,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'El duque Magdiel, y el duque Hiram. Estos fueron los duques de Edom por sus habitaciones en la tierra de su heredad. Este es Esaú padre de los Idumeos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Y habitó Jacob en la tierra donde peregrinó su padre, en la tierra de Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Estas fueron las generaciones de Jacob: José, cuando fue de edad de diez y siete años, apacentaba las ovejas con sus hermanos; y era mozo, con los hijos de Bala, y con los hijos de Zelfa, las mujeres de su padre: y José traía la mala fama de ellos a su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'E Israel amaba a José más que a todos sus hijos, porque le había habido en su vejez: e hízole una ropa de diversos colores.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Y viendo sus hermanos que su padre le amaba más que a todos sus hermanos, aborrecíanle, y no le podían hablar pacíficamente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Y soñó José un sueño, y contólo a sus hermanos; y ellos añadieron a aborrecerle más.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Y díjoles: Oíd ahora este sueño que he soñado:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'He aquí que atábamos manojos en medio del campo; y he aquí que mi manojo se levantaba, y estaba derecho: y que vuestros manojos estaban al rededor y se inclinaban al mío.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Y respondiéronle sus hermanos: ¿Has de reinar sobre nosotros? ¿o háste de enseñorear sobre nosotros? Y añadieron a aborrecerle más a causa de sus sueños y de sus palabras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Y soñó más otro sueño, y contólo a sus hermanos, diciendo: He aquí que he soñado otro sueño: Y he aquí que el sol y la luna, y once estrellas se inclinaban a mí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Y contólo a su padre y a sus hermanos, y su padre le reprendió, y díjole: ¿Qué sueño es este que soñaste? ¿Hemos de venir yo y tu madre, y tus hermanos a inclinarnos a ti a tierra?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Y sus hermanos le tuvieron envidia; mas su padre miraba el negocio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, '¶ Y fueron sus hermanos a apacentar las ovejas de su padre en Siquem.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Y dijo Israel a José: Tus hermanos apacientan las ovejas en Siquem, ven y enviarte he a ellos. Y él respondió: Heme aquí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Y él le dijo: Vé ahora, mira como están tus hermanos, y como están las ovejas, y tráeme la respuesta. Y envióle del valle de Hebrón, y vino a Siquem.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Y hallóle un hombre andando él perdido por el campo, y preguntóle aquel hombre, diciendo: ¿Qué buscas?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Y él respondió: Busco a mis hermanos: ruégote que me muestres donde pastan.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Y aquel hombre respondió: Ya se han ido de aquí: y yo les oí decir: Vamos a Dotaín: entonces José fue tras sus hermanos, y hallólos en Dotaín.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Y como ellos le vieron de lejos, antes que llegase cerca de ellos, pensaron contra él para matarle.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Y dijeron el uno al otro: He aquí, viene el soñador.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Ahora pues veníd, y matémosle, y echémosle en una cisterna, y diremos: Alguna mala bestia le tragó: y veremos que serán sus sueños.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Y como Rubén oyó esto, escapóle de sus manos, y dijo: No le matemos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Y díjoles Rubén: No derrameis sangre: echádle en esta cisterna, que está en el desierto; y no metáis mano en él: por escaparle de sus manos, para hacerlo volver a su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Y fue, que como José llegó a sus hermanos, ellos hicieron desnudar a José su ropa, la ropa de colores que tenía sobre sí,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Y tomáronle, y echáronle en la cisterna, y la cisterna estaba vacía, que no había agua en ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Y asentáronse a comer pan: y alzando los ojos miraron, y, he aquí, una compañía de Ismaelitas, que venía de Galaad, y sus camellos traían especias y cera y almáciga, e iban para llevar a Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, '¶ Entonces Judá dijo a sus hermanos: ¿Qué provecho que matemos a nuestro hermano, y encubramos su sangre?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Andád, y vendámosle a los Ismaelitas, y no sea nuestra mano sobre él, que nuestro hermano nuestra carne es. Y sus hermanos acordaron con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Y como pasaron los Madianitas mercaderes, ellos sacaron a José de la cisterna, y trajéronle arriba, y vendiéronle a los Ismaelitas por veinte pesos de plata: y llevaron a José a Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Y Rubén volvió a la cisterna, y, he aquí José no estaba dentro; y rompió sus vestidos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Y tornó a sus hermanos, y dijo: El mozo no parece, y yo ¿adónde iré yo?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Entonces ellos tomaron la ropa de José, y degollaron un cabrito de las cabras, y tiñeron la ropa con la sangre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Y enviaron la ropa de colores, y trajéronla a su padre, y dijeron: Esta hemos hallado: conoce ahora si es la ropa de tu hijo, o no.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Y él la conoció, y dijo: La ropa de mi hijo es; alguna mala bestia le tragó: despedazado ha sido José.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Entonces Jacob rompió sus vestidos, y puso saco sobre sus lomos, y enlutóse por su hijo muchos días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Y levantáronse todos sus hijos y todas sus hijas para consolarle; mas él no quiso tomar consolación, y dijo: Porque tengo de descender a mi hijo enlutado hasta la sepultura. Y lloróle su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Y los Madianitas le vendieron en Egipto a Potifar, eunuco de Faraón, capitán de los de la guardia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Y aconteció en aquel tiempo, que Judá descendió de con sus hermanos, y fuése a un varón Odollamita, que se llamaba Hira.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Y vio allí Judá una hija de un hombre Cananeo, el cual se llamaba Sua: y tomóla, y entró a ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'La cual concibió, y parió un hijo, y llamó su nombre Her.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Y concibió otra vez, y parió un hijo, y llamó su nombre Onán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Y tornó otra vez a concebir, y parió un hijo, y llamó su nombre Sela. Y estaba en Chezib cuando le parió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Y Judá tomó mujer a su primogénito Her, la cual se llamaba Tamar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Y Her, el primogénito de Judá, fue malo en los ojos de Jehová; y matóle Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Entonces Judá dijo a Onán: Entra a la mujer de tu hermano, y haz parentesco con ella, y levanta simiente a tu hermano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Y sabiendo Onán que la simiente no había de ser suya, era que cuando entraba a la mujer de su hermano corrompía en tierra, por no dar simiente a su hermano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Y desagradó en ojos de Jehová lo que hacía, y matóle también a él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Y Judá dijo a Tamar su nuera: Estáte viuda en casa de tu padre, hasta que crezca Sela mi hijo; porque dijo: Que quizá no muera él también como sus hermanos. Y fuése Tamar, y estúvose en casa de su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Y pasaron muchos días, y murió la hija de Sua, mujer de Judá: y Judá se consoló: y subió a los trasquiladores de sus ovejas él e Hira, su amigo Odollamita, a Tamnas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Y fue dado aviso a Tamar, diciendo: He aquí tu suegro sube a Tamnas a trasquilar sus ovejas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Entonces ella quitó de sobre sí los vestidos de su viudez, y cubrióse con un velo; y arrebozóse, y púsose a la puerta de las aguas que están junto al camino de Tamnas; porque veía que había crecido Sela, y ella no era dada a él por mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Y vióla Judá, y túvola por ramera; porque ella había cubierto su rostro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Y apartóse del camino hacia ella, y díjola: Ea pues, ahora yo entraré a ti: Porque no sabía que era su nuera. Y ella dijo: ¿Qué me has de dar, si entrares a mí?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'El respondió: Yo te enviaré de las ovejas un cabrito de las cabras. Y ella dijo: Hásme de dar prenda hasta que lo envíes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Entonces él dijo: ¿Qué prenda te daré? Ella respondió: Tu anillo, y tu manto, y tu bordón que tienes en tu mano. Y él se lo dió; y entró a ella, la cual concibió de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Y levantóse y fuése: y quitóse el velo de sobre sí, y vistióse las ropas de su viudez.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Y Judá envió el cabrito de las cabras por mano de su amigo el Odollamita, para que tomase la prenda de mano de la mujer: y no la halló.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Y preguntó a los hombres de aquel lugar, diciendo: ¿Dónde está la ramera de las aguas junto al camino? Y ellos le dijeron: No ha estado aquí ramera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Entonces él se volvió a Judá, y dijo: No la hallé: y también los hombres del lugar dijeron: No ha estado aquí ramera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Y Judá dijo: Tómeselo para sí, porque no seamos menospreciados: he aquí, yo he enviado este cabrito, y tú no la hallaste.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Y fue que como desde a tres meses, fue dado aviso a Judá, diciendo: Tamar tu nuera ha fornicado, y aun cierto está preñada de las fornicaciones. Y Judá dijo: Sacádla, y sea quemada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Y ella, cuando la sacaban, envió a decir a su suegro: Del varón cuyas son estas cosas, estoy preñada. Y dijo más: Conoce ahora cuyas son estas cosas, el anillo, y el manto, y el bordón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Entonces Judá lo conoció, y dijo: Más justa es que yo, por cuanto no la he dado a Sela mi hijo. Y nunca más la conoció.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Y aconteció que al tiempo de parir, he aquí, mellizos en su vientre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Y fue que cuando paría, dio la mano el uno, y la partera tomólo, y ató a su mano un hilo de grana, diciendo: Este salió primero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Y aconteció que tornando él a meter la mano, he aquí, su hermano salió, y dijo: ¿Por qué has rompido sobre ti rotura? Y llamó su nombre Fares.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Y después salió su hermano el que tenía en su mano el hilo de grana, y llamó su nombre Zara.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Y descendido José a Egipto, compróle Potifar, eunuco de Faraón, capitán de los de la guardia, varón Egipciano, de mano de los Ismaelitas, que le habían llevado allá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Mas Jehová fue con José, y fue varón prosperado: y estaba en la casa de su señor el Egipciano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Y vio su señor que Jehová era con él, y que todo lo que él hacía, Jehová lo prosperaba en su mano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Así halló José gracia en sus ojos, y servíale: y él le hizo mayordomo de su casa, y le entregó en poder todo lo que tenía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Y aconteció, que desde entonces que le dio el cargo de su casa, y de todo lo que tenía, Jehová bendijo la casa del Egipciano a causa de José, y fue la bendición de Jehová sobre todo lo que tenía así en casa como en el campo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Y dejó todo lo que tenía en la mano de José, ni con él sabía nada más que del pan que comía: y José era de hermoso semblante, y bello de vista.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, '¶ Y aconteció después de esto, que la mujer de su señor alzó sus ojos sobre José, y dijo: Duerme conmigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Y él no quiso; y dijo a la mujer de su señor: He aquí que mi señor no sabe conmigo lo que hay en casa, que todo lo que tiene ha puesto en mi mano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'No hay otro mayor que yo en esta casa, y ninguna cosa me ha defendido sino a ti, por cuanto tú eres su mujer: ¿cómo pues haría yo este grande mal, que pecaría contra Dios?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Y fue, que hablando ella a José cada día, y no la escuchando él para acostarse junto a ella, para estar con ella:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Aconteció que él vino un día como los otros a casa para hacer su oficio, y no había nadie de los de casa allí en casa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Y ella le tomó por su ropa, diciendo: Duerme conmigo. Entonces él dejóle su ropa en las manos, y huyó, y salióse fuera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, '¶ Y fue, que como ella vio que le había dejado su ropa en sus manos, y había huido fuera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Llamó a los de casa, y hablóles, diciendo: Mirád; hános traído un hombre Hebreo, para que hiciese burla de nosotros. Vino a mí para dormir conmigo, y yo di grandes voces.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Y viendo él, que yo alzaba la voz, y gritaba, dejó junto a mí su ropa, y huyó, y salióse fuera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Y ella puso su ropa cerca de sí, hasta que vino su señor a su casa:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Y ella le habló semejantes palabras, diciendo: Vino a mí el siervo Hebreo, que nos trajiste, para deshonrarme:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Y como yo alcé mi voz y grité, él dejó su ropa junto a mí, y huyó fuera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Y fue, que como su señor oyó las palabras que su mujer le habló, diciendo: Como esto, que digo, me ha hecho tu siervo, su furor se encendió,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Y tomó su señor a José, y púsole en la casa de la cárcel, donde estaban los presos del rey, y estuvo allí en la casa de la cárcel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, '¶ Mas Jehová fue con José, y llegó a él su misericordia, y dio su gracia en ojos del príncipe de la casa de la cárcel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Y el príncipe de la casa de la cárcel entregó en mano de José todos los presos, que estaban en la casa de la cárcel, y todo lo que hacían allí, él lo hacía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Ninguna cosa veía el príncipe de la cárcel en su mano, porque Jehová era con él: y lo que él hacía, Jehová lo prosperaba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Y aconteció después de estas cosas, que pecaron el maestresala del rey de Egipto, y el panadero, contra su señor, el rey de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Y Faraón se enojó contra sus dos eunucos, contra el principal de los maestresalas, y contra el principal de los panaderos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Y púsoles en la cárcel de la casa del capitán de los de la guardia, en la casa de la cárcel, donde José estaba preso.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Y el capitán de los de la guardia dio cargo de ellos a José, y él les servía; y estuvieron días en la cárcel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Y soñaron sueño ambos a dos, cada uno su sueño, una misma noche; cada uno conforme a la declaración de su sueño, el maestresala y el panadero del rey de Egipto, que estaban presos en la cárcel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Y vino a ellos José por la mañana, y miróles, y pareció que estaban tristes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Y él preguntó a aquellos eunucos de Faraón, que estaban con él en la cárcel de la casa de su señor, diciendo: ¿Por qué están hoy malos vuestros rostros?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Y ellos le dijeron: Hemos soñado sueño, y no hay quien lo declare. Entonces José les dijo: ¿No son de Dios las declaraciones? Contádmelo ahora.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, '¶ Entonces el príncipe de los maestresalas contó su sueño a José, y díjole: Yo soñaba que veía una vid delante de mí:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Y en la vid tres sarmientos; y ella como que florecía, salía su renuevo, maduraron sus racimos de uvas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Y que el vaso de Faraón estaba en mi mano; y que yo tomaba las uvas, y las exprimía en el vaso de Faraón, y daba el vaso en la mano de Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Y díjole José: Esta es su declaración: Los tres sarmientos son tres días:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Al cabo de tres días Faraón levantará tu cabeza, y te hará volver en tu asiento; y darás el vaso a Faraón en su mano, como solías cuando eras su maestresala.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Por tanto acordarte has de mí dentro de ti, cuando tuvieres bien; y ruégote que tengas conmigo misericordia, que hagas mención de mí a Faraón, y me saques de esta casa:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Porque he sido hurtado de la tierra de los Hebreos: y tampoco he hecho aquí porqué me hubiesen de poner en cárcel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Y viendo el príncipe de los panaderos que había declarado bien, dijo a José: También yo soñaba que veía tres canastillos blancos sobre mi cabeza:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Y en el canastillo más alto había de todas las viandas de Faraón de obra de panadero; y que las comían las aves del canastillo de sobre mi cabeza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Entonces respondió José, y dijo: Esta es su declaración: Los tres canastillos tres días son:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Al cabo de tres días quitará Faraón tu cabeza de ti, y te hará colgar en la horca, y aves comerán tu carne de sobre ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Y fue al tercero día el día del nacimiento de Faraón, e hizo banquete a todos sus siervos: y alzó la cabeza del príncipe de los maestresalas, y la cabeza del príncipe de los panaderos entre sus siervos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'E hizo volver al príncipe de los maestresalas a su oficio, y dio el vaso en mano de Faraón:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Y al príncipe de los panaderos hizo ahorcar, como le había declarado José.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Y el príncipe de los maestresalas no se acordó de José, mas olvidóse de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Y aconteció que pasados dos años Faraón soñó. Parecíale que estaba junto al río,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Y que del río subían siete vacas, hermosas de vista, y gruesas de carne: que pacían en el prado:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Y que otras siete vacas subían tras ellas del río, feas de vista, y magras de carne, y que se paraban cerca de las vacas hermosas a la orilla del río:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Y que las vacas, feas de vista y magras de carne, tragaban a las siete vacas, hermosas de vista y gruesas. Y despertó Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Y durmióse, y soñó la segunda vez: Que siete espigas llenas y hermosas subían de una caña:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Y que otras siete espigas menudas y abatidas del solano salían después de ellas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Y que las siete espigas menudas tragaban a las siete espigas gruesas y llenas. Y despertóse Faraón, y he aquí que era sueño.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Y acaeció que a la mañana su espíritu se atormentó y envió, e hizo llamar a todos los magos de Egipto, y a todos sus sabios; y contóles Faraón sus sueños; y no había quien los declarase a Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, '¶ Entonces el príncipe de los maestresalas habló a Faraón, diciendo: De mis pecados me acuerdo hoy:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Faraón se enojó contra sus siervos; y a mí me echó en la cárcel de la casa del capitán de los de la guardia, a mí y al príncipe de los panaderos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Y yo y él soñámos sueño una misma noche, cada uno conforme a la declaración de su sueño, soñámos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Y allí con nosotros estaba un mozo Hebreo, siervo del capitán de los de la guardia: y contámoselo, y él nos declaró nuestros sueños, y declaró a cada uno conforme a su sueño:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Y aconteció que como él nos declaró, así fue: a mí me hizo volver a mi asiento; y al otro hizo colgar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Entonces Faraón envió, y llamó a José, e hiciéronle salir corriendo de la cárcel: y trasquiláronle, y mudáronle sus vestidos; y vino a Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Y Faraón dijo a José: Yo he soñado sueño, y no hay quien lo declare: y yo he oído decir de ti, que oyes sueños para declararlos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Y José respondió a Faraón, diciendo: Sin mí, Dios responda paz a Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Entonces Faraón dijo a José: En mi sueño parecíame que estaba a la orilla del río:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Y que del río subían siete vacas gruesas de carne, y hermosas de forma, que pacían en el prado:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Y que otras siete vacas subían después de ellas, magras y feas de forma mucho, y flacas de carne: no he visto otras semejantes en toda la tierra de Egipto en fealdad:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Y que las vacas flacas y feas tragaban a las siete vacas primeras gruesas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Y que entraban en sus entrañas, y no se conocía que hubiesen entrado en sus entrañas; porque el parecer de ellas era aun malo, como de primero; y desperté.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Ví también soñando, que siete espigas subían en una caña llenas y hermosas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Y que otras siete espigas menudas, secas, abatidas del solano subían después de ellas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Y que las espigas menudas tragaban a las siete espigas hermosas; y lo he dicho a los magos, y no hay quien me lo declare.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Entonces José respondió a Faraón: El sueño de Faraón es un mismo. Dios ha mostrado a Faraón lo que él hace:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Las siete vacas hermosas siete años son; y las espigas hermosas son siete años: el sueño es un mismo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Y las siete vacas magras y feas, que subían tras ellas, siete años son; y las siete espigas menudas y secas del solano, siete años serán de hambre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Esto es lo que yo respondo a Faraón: Lo que Dios hace, ha mostrado a Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'He aquí, siete años vienen de grande hartura en toda la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Y levantarse han tras ellos siete años de hambre, que toda la hartura será olvidada en la tierra de Egipto; y la hambre consumirá la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Y aquella abundancia no será conocida a causa de la hambre de después; la cual será gravísima.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Y en segundar el sueño a Faraón dos veces significa que la cosa es firme de parte de Dios, y que Dios se apresura a hacerla.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Por tanto ahora provea Faraón a algún varón prudente y sabio, y póngale sobre la tierra de Egipto:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Haga Faraón, y ponga gobernadores sobre la provincia; y quinte la tierra de Egipto en los siete años de la hartura;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Y junten toda la provisión de estos buenos años que vienen; y alleguen el trigo debajo de la mano de Faraón para mantenimiento de las ciudades y guarden:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Y esté aquel mantenimiento en depósito para la tierra para los siete años de la hambre, que serán en la tierra de Egipto, y la tierra no perecerá de hambre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, '¶ Y el negocio pareció bien a Faraón, y a sus siervos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Y dijo Faraón a sus siervos: ¿Hemos de hallar otro hombre como este, en quien haya Espíritu de Dios?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Y dijo Faraón a José: Pues que Dios te ha hecho saber todo esto, no hay entendido ni sabio como tú.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Tú serás sobre mi casa; y por tu dicho se gobernará todo mi pueblo: solamente en la silla seré yo mayor que tú.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Dijo más Faraón a José: He aquí, yo te he puesto sobre toda la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Entonces Faraón quitó su anillo de su mano, y púsolo en la mano de José; e hízole vestir de ropas de lino finísimo; y puso un collar de oro en su cuello;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'E hízole subir en su segundo carro, y pregonaron delante de él Abrec; y púsole sobre toda la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Y dijo Faraón a José: Yo Faraón: y sin ti ninguno alzará su mano ni su pie en toda la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, '¶ Y llamó Faraón el nombre de José, Safenat-paneat: y dióle por mujer a Asenet, hija de Potifera, príncipe de On. Y salió José por la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Y José era de edad de treinta años, cuando fue presentado delante de Faraón, rey de Egipto: y salió José de delante de Faraón, y pasó por toda la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'E hizo la tierra aquellos siete años de la hartura a montones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Y juntó todo el mantenimiento de los siete años que fueron en la tierra de Egipto; y dio mantenimiento en las ciudades, poniendo en cada ciudad el mantenimiento del campo de sus al rededores.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Y juntó José trigo como arena de la mar, mucho en gran manera, hasta no poderse contar, porque no tenía número.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Y nacieron a José dos hijos antes que viniese el año de la hambre: los cuales le parió Asenet, hija de Potifera, príncipe de On.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Y llamó José el nombre del primogénito, Manasés: Porque, dice, me hizo olvidar Dios de todo mi trabajo, y de toda la casa de mi padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Y el nombre del segundo llamó Efraím: Porque, dice, crecer me hizo Dios en la tierra de mi aflicción.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Y cumpliéronse los siete años de la hartura, que fue en la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Y comenzaron a venir los siete años de la hambre, como José había dicho: y hubo hambre en todas las provincias, y en toda la tierra de Egipto había pan.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Y hubo hambre en toda la tierra de Egipto, y el pueblo clamó a Faraón por pan. Y dijo Faraón a todo Egipto: Andád a José; lo que él os dijere haréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Y había hambre sobre toda la haz de la tierra. Entonces José abrió todo donde había, y vendió a los Egipcios: porque la hambre había crecido en la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Y toda la tierra venía a Egipto para comprar de José; porque por toda la tierra había crecido la hambre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Y viendo Jacob que en Egipto había alimentos, dijo a sus hijos: ¿Por qué os estáis mirando?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Y dijo: He aquí yo he oído que hay alimentos en Egipto; descendéd allá, y comprád para nosotros de allá, para que vivamos, y no nos muramos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Y descendieron los diez hermanos de José a comprar trigo a Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Mas a Ben-jamín, hermano de José, no envió Jacob con sus hermanos, porque dijo: Porque no le acontezca algún desastre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Y vinieron los hijos de Israel a comprar entre los que venían; porque había hambre en la tierra de Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, '¶ Y José era el señor de la tierra, que vendía el trigo a todo el pueblo de la tierra: y llegaron los hermanos de José, e inclináronse a él la haz sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Y José como vio a sus hermanos, conociólos, e hizo que no los conocía; y hablóles ásperamente, y díjoles: ¿De dónde habéis venido? Ellos respondieron: De la tierra de Canaán a comprar alimentos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Y José conoció a sus hermanos, mas ellos no le conocieron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Entonces José se acordó de los sueños que había soñado de ellos, y díjoles: Espiones sois: por ver lo descubierto de la tierra habéis venido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Y ellos le respondieron: No, señor mío; mas tus siervos han venido a comprar alimentos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Todos nosotros somos hijos de un varón, hombres de verdad somos: tus siervos nunca fueron espiones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Y él les dijo: No: a ver lo descubierto de la tierra habéis venido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Ellos respondieron: Tus siervos somos doce hermanos, hijos de un varón en la tierra de Canaán: y, he aquí, el menor está con nuestro padre hoy, y otro no parece.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Y José les dijo: Eso es lo que yo os he dicho, diciendo que sois espiones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'En esto seréis probados: Vive Faraón, que no saldréis de aquí, sino cuando vuestro hermano menor viniere aquí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Enviád uno de vosotros, y tome a vuestro hermano; y vosotros quedád presos; y vuestras palabras serán probadas, si hay verdad con vosotros: y si no, vive Faraón que sois espiones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Y juntóles en la cárcel tres días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Y al tercero día díjoles José: Hacéd esto, y vivíd: Yo temo a Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Si sois hombres de verdad, quede preso en la casa de vuestra cárcel uno de vuestros hermanos: y vosotros id, llevád el alimento para la hambre de vuestra casa:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Y traerme heis a vuestro hermano menor, y serán verificadas vuestras palabras; y no moriréis. Y ellos lo hicieron así.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Y decían el uno al otro: Verdaderamente nosotros hemos pecado contra nuestro hermano, que vimos el angustia de su alma, cuando nos rogaba, y no oímos: por eso ha venido sobre nosotros esta angustia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Entonces Rubén les respondió, diciendo: ¿No os lo decía yo, diciendo: No pequéis contra el mozo, y no oísteis? He aquí también su sangre es requerida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Y ellos no sabían que entendía José; porque había intérprete entre ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Y apartóse de ellos, y lloró: después volvió a ellos, y hablóles, y tomó de ellos a Simeón, y emprisionóle delante de ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Y mandó José que hinchesen sus sacos de trigo, y les volviesen su dinero de cada uno de ellos en su saco, y les diesen comida para el camino: y fue hecho con ellos así.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Y ellos pusieron su trigo sobre sus asnos, y fuéronse de allí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Y abriendo el uno su saco para dar de comer a su asno, en el mesón, vio su dinero que estaba en la boca de su costal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Y dijo a sus hermanos: Mi dinero es vuelto, y hélo aquí también en mi saco. Entonces el corazón se les sobresaltó, y espantados el uno al otro, dijeron: ¿Qué es esto que nos ha hecho Dios?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, '¶ Y venidos a Jacob su padre en tierra de Canaán, contáronle todo lo que les había acaecido, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Aquel varón, señor de la tierra, nos habló ásperamente, y nos trató como a espiones de la tierra:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Y nosotros le dijimos: Hombres de verdad somos; nunca fuimos espiones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Doce hermanos somos, hijos de nuestro padre; el uno no parece, y el menor está hoy con nuestro padre en la tierra de Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Y aquel varón, señor de la tierra, nos dijo: En esto conoceré que sois hombres de verdad: Dejád conmigo el uno de vuestros hermanos, y tomád para la hambre de vuestras casas; y andád,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Y traédme a vuestro hermano el menor, para que yo sepa que no sois espiones, sino hombres de verdad, y daros he a vuestro hermano, y negociaréis en la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Y aconteció, que vaciando ellos sus sacos, he aquí que en el saco de cada uno estaba el trapo de su dinero: y viendo ellos y su padre los trapos de sus dineros, tuvieron temor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Entonces su padre Jacob les dijo: Deshijádome habéis: José no parece, y Simeón no parece, y a Ben-jamín tomaréis: sobre mí son todas estas cosas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Y Rubén habló a su padre, diciendo: Mis dos hijos harás morir, si no te lo volviere: dále en mi mano, que yo le volveré a ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Y él dijo: No descenderá mi hijo con vosotros: que su hermano es muerto, y él solo ha quedado: y si le aconteciere algún desastre en el camino donde vais, haréis descender mis canas con dolor a la sepultura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Y la hambre era grande en la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Y aconteció que como acabaron de comer el trigo que trajeron de Egipto, díjoles su padre: Volvéd, comprád para nosotros un poco de alimento.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Y respondióle Judá, diciendo: Protestando nos protestó aquel varón, diciendo: No veréis mi rostro sin vuestro hermano con vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Si enviares nuestro hermano con nosotros, descenderemos, y comprarte hemos alimento.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Y si no le enviares, no descenderemos; porque aquel varón nos dijo: No veréis mi rostro sin vuestro hermano con vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Y dijo Israel: ¿Por qué me hicisteis mal declarando al varón, que teníais más hermano?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Y ellos respondieron: Preguntando nos preguntó aquel varón por nosotros, y por nuestra parentela, diciendo: ¿Vive aun vuestro padre? ¿Tenéis más hermano? Y declarámosle conforme a estas palabras: ¿Podíamos nosotros saber que había de decir: Hacéd venir a vuestro hermano?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Entonces Judá dijo a Israel su padre: Envía al mozo conmigo, y levantarnos hemos, e iremos, porque vivamos y no muramos nosotros: y tú, y nuestros niños.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Yo salgo por fiador, de mi mano le requerirás: si yo no te le volviere, y le pusiere delante de ti, cargue yo con la culpa para siempre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Que si no nos hubiéramos detenido, cierto ahora hubiéramos ya vuelto dos veces.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Entonces Israel su padre les respondió: Pues que así es, hacédlo: tomád de lo mejor de la tierra en vuestros vasos, y llevád a aquel varón un presente, un poco de resina, y un poco de miel, especias, y almáciga, piñones, y almendras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Y tomád en vuestras manos doblado dinero; y llevád en vuestra mano el dinero vuelto en las bocas de vuestros costales, quizá fue yerro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Y tomád vuestro hermano, y levantáos, y volvéd a aquel varón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Y el Dios omnipotente os dé misericordias delante de aquel varón, y os suelte al otro vuestro hermano, y a este Ben-jamín: y yo como deshijado, deshijado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Entonces aquellos varones tomaron el presente, y tomaron en su mano doblado dinero, y a Ben-jamín; y levantáronse y descendieron a Egipto, y presentáronse delante de José.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, '¶ Y José vio con ellos a Ben-jamín, y dijo al que presidía en su casa: Mete aquellos varones en casa, y degüella víctima, y apareja; porque estos varones comerán conmigo al mediodía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Y el varón hizo como José dijo, y metió aquel varón a los hombres en casa de José.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Y aquellos hombres tuvieron temor, cuando fueron metidos en casa de José, y decían: Por el dinero que fue vuelto en nuestros costales la primera vez nos han metido, para revolver sobre nosotros, y dar sobre nosotros, y tomarnos por siervos a nosotros, y a nuestros asnos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Y llegáronse a aquel varón, que presidía en casa de José, y habláronle a la entrada de la casa,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'Y dijeron: Ay, señor mío, nosotros descendimos al principio a comprar alimentos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Y aconteció que como venímos al mesón, y abrímos nuestros costales, he aquí que el dinero de cada uno estaba en la boca de su costal, nuestro dinero por su peso: y hémoslo vuelto en nuestras manos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Y hemos traído en nuestras manos otro dinero para comprar alimentos: nosotros no sabemos quien haya puesto nuestro dinero en nuestros costales.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Y él respondió: Paz a vosotros; no temáis: vuestro Dios, y el Dios de vuestro padre, os dio el tesoro en vuestros costales: vuestro dinero vino a mí. Y sacó a Simeón a ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Y metió aquel varón a aquellos hombres en casa de José: y dio agua; y lavaron sus pies, y dio de comer a sus asnos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Y ellos apercibieron el presente entre tanto que venía José, al mediodía, porque habían oído que allí habían de comer pan.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Y vino José a casa; y ellos trajeron a casa el presente que tenían en su mano, e inclináronse a él hasta tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Entonces él les preguntó como estaban, y dijo: ¿Vuestro padre, el viejo que dijisteis, vale bien? ¿es aun vivo?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Y ellos respondieron: Bien va a tu siervo nuestro padre; aun vive. E inclináronse, e hicieron reverencia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Y alzando él sus ojos vio a Ben-jamín su hermano, hijo de su madre, y dijo: ¿Es este vuestro hermano menor, de quien me dijisteis? Y dijo: Dios haya misericordia de ti, hijo mío.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Entonces José se apresuró, que se encendieron sus entrañas sobre su hermano, y procuró de llorar: y entróse en la cámara, y lloró allí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, '¶ Y lavó su rostro, y salió y esforzóse, y dijo: Ponéd pan.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Y pusiéronle a él a parte, y a ellos a parte, y a los Egipcios que comían con él, a parte; porque los Egipcios no pueden comer con los Hebreos pan, que es abominación a los Egipcios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Y asentáronse delante de él el mayor conforme a su mayoría, y el menor conforme a su menoría: y aquellos hombres estaban espantados el uno al otro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Y él tomó presentes de delante de sí para ellos: y el presente de Ben-jamín fue aumentado más que los presentes de todos ellos en cinco partes. Y ellos bebieron, y alegráronse con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Y él mandó al que presidía en su casa, diciendo: Hinche los costales de aquestos varones de alimentos, cuanto pudieren llevar, y pon el dinero de cada uno en la boca de su costal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Y mi copa, la copa de plata, pondrás en la boca del costal del menor con el dinero de su trigo. Y él hizo como José dijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Venida la mañana, los hombres fueron despedidos con sus asnos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'En saliendo ellos de la ciudad, que aun no se habían alejado, José dijo al que presidía en su casa: Levántate, y sigue a aquellos hombres: y cuando los tomares, díles: ¿Por qué habéis tornado mal por bien?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, '¿No es esta la copa en que bebe mi señor? ¿y en que suele adivinar? mal habéis hecho en lo que hicisteis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Y como él los alcanzó, díjoles estas palabras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Y ellos le respondieron: ¿Por qué dice mi señor tales cosas? Nunca tal hagan tus siervos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'He aquí, el dinero que hallamos en la boca de nuestros costales te volvimos a traer desde la tierra de Canaán: ¿cómo pues habíamos de hurtar de casa de tu señor plata ni oro?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Aquel en quien fuere hallada de tus siervos, que muera, y aun nosotros seremos siervos de mi señor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Y él dijo: También ahora sea conforme a vuestras palabras: aquel en quien se hallare, será mi siervo, y vosotros seréis sin culpa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Ellos entonces diéronse priesa, y derribaron cada uno su costal a tierra, y abrieron cada uno su costal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Y buscó, desde el mayor comenzó, y acabó en el menor: y la copa fue hallada en el costal de Ben-jamín.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Entonces ellos rompieron sus vestidos, y cargó cada uno su asno, y volvieron a la ciudad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Y llegó Judá y sus hermanos a casa de José, y él estaba aun allí, y postráronse delante de él en tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Y díjoles José: ¿Qué obra es esta que habéis hecho? ¿No sabéis vosotros que un hombre como yo adivinando adivina?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, '¶ Entonces Judá dijo: ¿Qué diremos a mi señor? ¿Qué hablaremos? o ¿con qué nos justificaremos? Dios ha descubierto la maldad de tus siervos: he aquí, nosotros somos siervos de mi señor, nosotros también, y aquel en cuyo poder fue hallada la copa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Y él respondió: Nunca yo tal haga: el varón en cuyo poder fue hallada la copa; aquel será mi siervo: vosotros id en paz a vuestro padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Entonces Judá se llegó a él, y dijo: Ay, señor mío, ruégote que hable tu siervo una palabra en oídos de mi señor, y no se encienda tu enojo contra tu siervo, pues que tú eres como Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mi señor preguntó a sus siervos, diciendo: ¿Tenéis padre, o hermano?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Y nosotros respondimos a mi señor: Tenemos un padre viejo, y un mozo nacido en su vejez, pequeño, y un hermano suyo murió, y él quedó solo de su madre, y su padre le ama.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Y tú dijiste a tus siervos: Traédmelo, y yo pondré mis ojos sobre él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Y nosotros dijimos a mi señor: El mozo no puede dejar a su padre; porque si dejare a su padre, el padre morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Y dijiste a tus siervos: Si vuestro hermano menor no descendiere con vosotros, no veais más mi rostro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Aconteció pues, que como venímos a mi padre tu siervo, contámosle las palabras de mi señor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Y dijo nuestro padre: Volvéd: comprádnos un poco de alimento.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Y nosotros respondimos: No podemos ir: si nuestro hermano menor fuere con nosotros, iremos: porque no podemos ver el rostro del varón, no estando con nosotros nuestro hermano el menor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Entonces tu siervo, mi padre, nos dijo: Vosotros sabéis, que dos hijos me parió mi mujer;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Y el uno salió de conmigo, y de él dije: De cierto que fue despedazado; y hasta ahora no le he visto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Y si tomareis también a este de delante de mí, y le aconteciere algún desastre, haréis descender mis canas con dolor a la sepultura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Y ahora como yo viniere a tu siervo, mi padre, y el mozo no fuere conmigo, porque su alma está ligada con el alma de él,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Será, que como él no vea al mozo, morirá: y tus siervos harán descender las canas de tu siervo nuestro padre con dolor a la sepultura:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Porque tu siervo salió por fiador por el mozo con mi padre, diciendo: Si no te le volviere, entonces yo seré culpado a mi padre todos los días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Ruégote, pues, que quede ahora tu siervo por el mozo por siervo de mi señor, y el mozo vaya con sus hermanos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Porque ¿cómo vendré yo a mi padre sin el mozo? Por no ver el mal que a mi padre vendrá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Entonces José no pudo contenerse delante de todos los que estaban junto a él, y clamó: Hacéd salir de conmigo a todos. Y no quedó nadie con él para darse a conocer José a sus hermanos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Entonces dio su voz con lloro; y oyeron los Egipcios; y oyó también la casa de Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Y dijo José a sus hermanos: Yo soy José: ¿vive aun mi padre? Y sus hermanos no le pudieron responder, porque estaban turbados delante de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Entonces José dijo a sus hermanos: Llegáos ahora a mí. Y ellos se llegaron. Y él dijo: Yo soy José vuestro hermano, el que vendisteis a Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Ahora pues, no os entristezcáis; ni os pese de haberme vendido acá; que para vida me envió Dios delante de vosotros:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Que ya han sido dos años de hambre en medio de la tierra, y aun quedan cinco años, que ni habrá arada ni siega.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Y Dios me envió delante de vosotros para que vosotros quedaseis en la tierra, y para daros vida por grande libertad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Así que ahora, no me enviasteis vosotros acá, sino Dios, que me ha puesto por padre de Faraón, y por señor a toda su casa, y por enseñoreador en toda la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Dáos priesa: íd a mi padre y decídle: Así dice tu hijo José: Dios me ha puesto por señor de todo Egipto, ven a mí, no te detengas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Y habitarás en la tierra de Gosén, y estarás cerca de mí, tú y tus hijos; y los hijos de tus hijos; tus ganados, y tus vacas, y todo lo que tienes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Y yo te alimentaré allí, que aun quedan cinco años de hambre, porque no perezcas de pobreza tú y tu casa, y todo lo que tienes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Y, he aquí, vuestros ojos ven, y los ojos de mi hermano Ben-jamín, que mi boca os habla.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Y haréis saber a mi padre toda mi gloria en Egipto, y todo lo que habéis visto: y dáos priesa, y traed a mi padre acá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Y echóse sobre el cuello de Ben-jamín su hermano, y lloró: y Ben-jamín también lloró sobre su cuello.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Y besó a todos sus hermanos, y lloró sobre ellos: y después sus hermanos hablaron con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, '¶ Y la fama fue oída en la casa de Faraón, diciendo: Los hermanos de José han venido. Y plugo en los ojos de Faraón, y en los ojos de sus siervos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Y dijo Faraón a José: Di a tus hermanos: Hacéd esto; cargád vuestras bestias, e id, volvéd a la tierra de Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Y tomád a vuestro padre, y vuestras familias, y veníd a mi; que yo os daré lo bueno de la tierra de Egipto, y comeréis la grosura de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Y tú manda: Hacéd esto; tomáos de la tierra de Egipto carros para vuestros niños y vuestras mujeres: y tomád a vuestro padre, y veníd.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Y no se os dé nada de vuestras alhajas, porque el bien de la tierra de Egipto será vuestro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, '¶ E hiciéronlo así los hijos de Israel: y dióles José carros conforme al dicho de Faraón, y dióles mantenimiento para el camino.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'A todos ellos dio a cada uno mudas de vestidos: y a Ben-jamín dio trescientos pesos de plata, y cinco mudas de vestidos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Y a su padre envió esto; diez asnos cargados de lo mejor de Egipto, y diez asnas cargadas de trigo y pan, y comida para su padre para el camino.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Y despidió a sus hermanos, y fuéronse: y díjoles: No riñáis por el camino.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Y vinieron de Egipto: y llegaron a la tierra de Canaán a Jacob su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Y diéronle las nuevas diciendo: José vive aun: y él es señor en toda la tierra de Egipto: y su corazón se desmayó, que no los creía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Y ellos le contaron todas las palabras de José, que él les había hablado: y viendo él los carros que José enviaba para llevarle, el espíritu de Jacob su padre revivió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Entonces dijo Israel: Basta; aun José mi hijo vive: yo iré y verle he antes que muera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Y partióse Israel con todo lo que tenía, y vino a Beer-seba, y sacrificó sacrificios al Dios de su padre Isaac.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Y habló Dios a Israel en visiones de noche, y dijo: Jacob, Jacob. Y él respondió: Heme aquí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Y dijo: Yo soy el Dios, el Dios de tu padre; no temas de descender a Egipto; porque yo te pondré allí en gran gente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Yo descenderé contigo a Egipto; y yo también te haré volver; y José pondrá su mano sobre tus ojos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Y levantóse Jacob de Beer-seba, y tomaron los hijos de Israel a su padre Jacob, y a sus niños, y a sus mujeres en los carros que Faraón había enviado para llevarle.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Y tomaron sus ganados, y su hacienda que habían adquirido en la tierra de Canaán, y viniéronse a Egipto, Jacob, y toda su simiente consigo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Sus hijos, y los hijos de sus hijos consigo: sus hijas, y las hijas de sus hijos; y a toda su simiente trajo consigo en Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, '¶ Y estos son los nombres de los hijos de Israel, que entraron en Egipto, Jacob, y sus hijos. El primogénito de Jacob, Rubén.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Y los hijos de Rubén: Jenoc, y Fallu, y Jesrón, y Carmi.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Y los hijos de Simeón: Lamuel, y Lamín, y Ahod, y Jaquín, y Sohar, y Saul hijo de la Cananea.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Y los hijos de Leví: Gersón, y Cahat, y Merari.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Y los hijos de Judá: Her, y Onán, y Sela, y Fares, y Zara; mas Her, y Onán murieron en la tierra de Canaán. Y los hijos de Fares fueron Jesrón, y Hamul.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Y los hijos de Isacar: Tola, y Fua, y Job, y Simerón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Y los hijos de Zabulón: Sared, y Elón, y Jahelel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Estos fueron los hijos de Lia que parió a Jacob en Padan-aram, y a Dina su hija: todas las almas de los hijos y de las hijas fueron treinta y tres.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Y los hijos de Gad: Sefón, y Agui, y Jesebón, y Suni, y Heri, y Arodi, y Areli.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Y los hijos de Aser: Jamna, y Jesua, y Jessui, y Beria, y Sara hermana de ellos. Los hijos de Beria: Jeber, y Melquiel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Estos fueron los hijos de Zelfa, la que Labán dio a su hija Lia, y parió estos a Jacob, diez y seis almas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Y los hijos de Raquel, mujer de Jacob: José, y Ben-jamín.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Y nacieron a José en la tierra de Egipto, que le parió Asenet, hija de Potifera, príncipe de On: Manasés y Efraím.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Y los hijos de Ben-jamín: Bela, y Becor, y Asbel, y Gera, y Naamán, y Equi, y Ros, y Mofim, y Ofim, y Ared.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Estos fueron los hijos de Raquel que nacieron a Jacob, todas las almas, catorce.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Y los hijos de Dan: Husín.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Y los hijos de Neftalí: Jasiel, y Gumi, y Jeser, y Sallem.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Estos fueron los hijos de Bala, la que dio Labán a Raquel su hija, y parió estos a Jacob, todas las almas, siete.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Todas las personas que vinieron con Jacob a Egipto, que salieron de su muslo, sin las mujeres de los hijos de Jacob, todas las personas fueron sesenta y seis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Y los hijos de José, que le nacieron en Egipto, dos personas. Todas las almas de la casa de Jacob, que entraron en Egipto fueron setenta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Y envió a Judá delante de sí a José para que le viniese a ver a Gosén, y llegaron a la tierra de Gosén.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, '¶ Y José unció su carro, y vino a recibir a Israel su padre a Gosén, y mostrósele: y echóse sobre su cuello, y lloró sobre su cuello asaz.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Entonces Israel dijo a José: Muera yo ahora, pues que ya he visto tu rostro: que aun vives.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Y José dijo a sus hermanos, y a la casa de su padre: Yo subiré, y haré saber a Faraón, y decirle he: Mis hermanos y la casa de mi padre, que estaban en la tierra de Canaán, han venido a mí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Y los hombres son pastores de ovejas, porque son hombres ganaderos: y han traído sus ovejas y sus vacas; y todo lo que tenían.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Y cuando Faraón os llamare, y dijere: ¿Qué es vuestro oficio?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Entonces diréis: Hombres de ganado han sido tus siervos desde nuestra mocedad hasta ahora, nosotros y nuestros padres: para que moréis en la tierra de Gosén, porque los Egipcios abominan a todo pastor de ovejas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Y José vino, e hizo saber a Faraón, y dijo: Mi padre y mis hermanos, y sus ovejas, y sus vacas, con todo lo que tienen, han venido de la tierra de Canaán; y, he aquí, están en la tierra de Gosén.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Y de los postreros de sus hermanos tomó cinco varones, y presentólos delante de Faraón:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Y Faraón dijo a sus hermanos: ¿Qué son vuestros oficios? Y ellos respondieron a Faraón: Pastores de ovejas son tus siervos, así nosotros, como nuestros padres.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Y dijeron a Faraón: Por morar en esta tierra hemos venido; porque no hay pasto para las ovejas de tus siervos, que la hambre es grave en la tierra de Canaán, por tanto ahora rogámoste que habiten tus siervos en la tierra de Gosén.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Entonces Faraón habló a José, diciendo: Tu padre y tus hermanos han venido a ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'La tierra de Egipto delante de ti está, en lo mejor de la tierra haz habitar a tu padre y a tus hermanos: habiten en la tierra de Gosén: y si entiendes que hay entre ellos hombres valientes, ponerlos has por mayorales del ganado sobre lo que es mío.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Y metió José a Jacob su padre, y presentóle delante de Faraón; y Jacob bendijo a Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Y dijo Faraón a Jacob: ¿Cuántos son los días de los años de tu vida?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Y Jacob respondió a Faraón: Los días de los años de mi peregrinación son ciento y treinta años: pocos y malos han sido los días de los años de mi vida: y no han llegado a los días de los años de la vida de mis padres, en los días de sus peregrinaciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Y Jacob bendijo a Faraón, y salióse de delante de Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Así José hizo habitar a su padre y a sus hermanos, y dióles posesión en la tierra de Egipto en lo mejor de la tierra, en la tierra de Rameses como Faraón mandó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Y alimentaba José a su padre y a sus hermanos, y a toda la casa de su padre, de pan, hasta la boca del niño.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, '¶ Y no había pan en toda la tierra, y la hambre era muy grave: y desfalleció de hambre la tierra de Egipto, y la tierra de Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Y José recogió todo el dinero que se halló en la tierra de Egipto, y en la tierra de Canaán por los alimentos que compraban de él: y metió José el dinero en casa de Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Y acabado el dinero de la tierra de Egipto, y de la tierra de Canaán, vino todo Egipto a José, diciendo: Dános pan: ¿por qué moriremos delante de ti, que se ha acabado el dinero?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Y José dijo: Dad vuestros ganados, y yo os daré por vuestros ganados, si se ha acabado el dinero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Y ellos trajeron sus ganados a José, y José les dio alimentos por caballos, y por el ganado de las ovejas, y por el ganado de las vacas, y por asnos: y sustentólos de pan por todos sus ganados aquel año.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Y acabado aquel año, vinieron a él el segundo año, y dijéronle: No encubriremos de nuestro señor, que ciertamente se ha acabado el dinero, ni ganado de nuestro señor ha quedado delante de nuestro señor; mas que nuestros cuerpos, y nuestra tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, '¿Por qué moriremos delante de tus ojos así nosotros como nuestra tierra? Cómpranos a nosotros y a nuestra tierra por pan; y seremos nosotros y nuestra tierra siervos de Faraón: y da simiente para que vivamos, y no nos muramos, y no se asuele la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Entonces José compró toda la tierra de Egipto para Faraón: porque los Egipcios vendieron cada uno sus tierras, porque la hambre se fortaleció sobre ellos: y fue la tierra de Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Y al pueblo hízole pasar a las ciudades desde el un cabo del término de Egipto hasta el otro cabo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Solamente la tierra de los sacerdotes no compró, por cuanto los sacerdotes tenían ración de Faraón, y ellos comían su ración que Faraón les daba: por eso no vendieron su tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, '¶ Y José dijo al pueblo: He aquí yo os he comprado hoy, a vosotros y a vuestra tierra para Faraón: veis aquí simiente, y sembraréis la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Y será que de los frutos daréis el quinto a Faraón: y las cuatro partes serán vuestras para sembrar las tierras, y para vuestro mantenimiento, y de los que están en vuestras casas, y para que coman vuestros niños.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Y ellos respondieron: La vida nos has dado: hallemos gracia en ojos de mi señor, que seamos siervos de Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Entonces José lo puso por fuero hasta hoy sobre la tierra de Egipto, a Faraón el quinto: salvo que la tierra de los sacerdotes sola no fue de Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Así habitó Israel en la tierra de Egipto, en la tierra de Gosén, y aposesionáronse en ella, y aumentáronse, y multiplicaron en gran manera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Y vivió Jacob en la tierra de Egipto diez y siete años, y fueron los días de Jacob, los años de su vida, ciento y cuarenta y siete años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, '¶ Y llegáronse los días de Israel para morir, y llamó a José su hijo, y díjole: Si he hallado ahora gracia en tus ojos, yo te ruego que pongas tu mano debajo de mi muslo, y harás conmigo misericordia y verdad. Ruégote que no me entierres en Egipto:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Mas cuando durmiere con mis padres, llevarme has de Egipto, y sepultarme has en el sepulcro de ellos. Y él respondió: Yo haré como tú dices.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Y él dijo: Júrame. Y él le juró. Entonces Israel se inclinó a la cabecera de la cama.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Y fue, que después de estas cosas, fue dicho a José: He aquí, tu padre está enfermo. Y él tomó consigo a sus dos hijos, Manasés y Efraím:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Y fue hecho saber a Jacob, diciendo: He aquí, José tu hijo viene a ti. Entonces Israel se esforzó, y asentóse sobre la cama;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Y dijo a José: El Dios omnipotente me apareció en Luza, en la tierra de Canaán; y me bendijo,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'Y díjome: He aquí, yo te hago crecer, y te multiplicaré, y te pondré por compañía de pueblos: y esta tierra daré a tu simiente después de ti, por heredad perpetua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Y ahora tus dos hijos, que te nacieron en la tierra de Egipto antes que yo viniese a ti, a la tierra de Egipto, míos son; Efraím y Manasés, como Rubén y Simeón serán míos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Y los que después de ellos has engendrado serán tuyos: por el nombre de sus hermanos serán llamados en sus heredades.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Y yo, cuando venía de Padan-aram, Raquel se me murió en la tierra de Canaán en el camino, como media legua de tierra viniendo a Efrata: y sepultéla allí en el camino de Efrata, que es Belén.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, '¶ Y vio Israel los hijos de José, y dijo: ¿Quién son estos?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Y respondió José a su padre: Mis hijos son, que Dios me ha dado aquí. Y él dijo: Allégalos ahora a mí, y bendecirlos he.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Y los ojos de Israel eran ya agravados de la vejez que no podía ver. E hízolos llegar a él, y él los besó y abrazó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Y dijo Israel a José: Yo no pensaba ver tu rostro; y, he aquí, Dios me ha hecho ver también tu simiente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Entonces José los sacó de entre sus rodillas, e inclinóse a tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Y tomólos José a ambos, Efraím a su diestra, a la siniestra de Israel; y a Manasés a su siniestra, a la diestra de Israel, e hízolos llegar a él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Entonces Israel extendió su diestra, y púsola sobre la cabeza de Efraím, que era el menor, y su siniestra sobre la cabeza de Manasés haciendo entender a sus manos, aunque Manasés era el primogénito.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Y bendijo a José, y dijo: El Dios en cuya presencia anduvieron mis padres Abraham e Isaac: el Dios que me mantiene desde que yo soy hasta este día,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'El ángel que me escapa de todo mal, bendiga a estos mozos: y mi nombre sea llamado en ellos, y el nombre de mis padres Abraham e Isaac, y multipliquen en multitud en medio de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Entonces viendo José que su padre ponía la mano derecha sobre la cabeza de Efraím, pesóle en sus ojos; y tomó la mano de su padre, por quitarla de sobre la cabeza de Efraím a la cabeza de Manasés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Y dijo José a su padre: No así, padre mío, porque este es el primogénito: pon tu diestra sobre su cabeza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Mas su padre no quiso, y dijo: Yo lo sé, hijo mío, yo lo sé: también él será en pueblo, y él también crecerá: mas su hermano menor será más grande que él, y su simiente será plenitud de gentes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Y bendíjolos aquel día, diciendo: En ti bendecirá Israel, diciendo: Póngate Dios como a Efraím, y como a Manasés. Y puso a Efraím delante de Manasés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Y dijo Israel a José: He aquí, yo muero; mas Dios será con vosotros, y os hará volver a la tierra de vuestros padres.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Y yo te he dado a ti una parte sobre tus hermanos, que yo tomé de mano del Amorreo con mi espada y con mi arco.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Y llamó Jacob a sus hijos, y dijo: Juntáos y declararos he lo que os ha de acontecer en los postreros días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Juntáos y oíd, hijos de Jacob, y oíd a vuestro padre Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Rubén, tú eres mi primogénito, mi fortaleza, y el principio de mi vigor: principal en dignidad, principal en fortaleza:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Corriente como las aguas, no seas el principal; por cuanto subiste al lecho de tu padre; entonces te envileciste subiendo a mi estrado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeón y Leví, hermanos; armas de iniquidad sus armas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'En su secreto no entre mi alma, ni mi honra se junte en su compañía; que en su furor mataron varón, y en su voluntad arrancaron muro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Maldito su furor que es fuerte: y su ira, que es dura: yo los apartaré en Jacob, y los esparciré en Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Judá, tú, alabarte han tus hermanos: tu mano en la cerviz de tus enemigos: los hijos de tu padre se inclinarán a ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Cachorro de león Judá: de la presa subiste, hijo mío: encorvóse, echóse como león, y como león viejo, ¿quién lo despertará?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'No será quitado el cetro de Judá, y el legislador de entre sus pies, hasta que venga Siloh, y a él se congregarán los pueblos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Atando a la vid su pollino, y a la cepa el hijo de su asna; lavó en el vino su vestido, y en la sangre de uvas su cobertura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Los ojos bermejos del vino, los dientes blancos de la leche.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, '¶ Zabulón en puertos de mar habitará, y en puerto de navíos: y su término será hasta Sidón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Isacar, asno de hueso echado entre dos líos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Y vio que el descanso era bueno, y que la tierra era deleitosa, y abajó su hombro para llevar, y sirvió en tributo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan, juzgará a su pueblo, como una de las tribus de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Será Dan serpiente junto al camino, víbora junto a la senda, que muerde los talones de los caballos, y hace caer por detrás al cabalgador de ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Tu salud esperé, oh Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad, ejército le acometerá; mas al fin él acometerá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'El pan de Aser será grueso, y él dará deleites de rey.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Neftalí, cierva dejada que dará dichos hermosos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, '¶ Ramo fructífero José, ramo fructífero junto a fuente; las doncellas van sobre el muro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Y amargáronle, y asaeteáronle, y aborreciéronle los señores de saetas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Mas su arco quedó en fortaleza, y los brazos de sus manos se corroboraron por las manos del fuerte Dios de Jacob: de allí apacentó la piedra de Israel:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Del Dios de tu padre, el cual te ayudará, y del Omnipotente, el cual te bendecirá con bendiciones de los cielos de arriba, con bendiciones del abismo que está abajo, con bendiciones de pechos y de matriz.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Las bendiciones de tu padre fueron mayores que las bendiciones de mis progenitores: hasta el término de los collados eternos serán sobre la cabeza de José y sobre la mollera del Nazareno de sus hermanos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, '¶ Ben-jamín, lobo arrebatador: a la mañana comerá la presa, y a la tarde repartirá los despojos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Todos estos fueron las tribus de Israel, doce: y esto fue lo que su padre les dijo: y bendíjoles: a cada uno por su bendición los bendijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Y mandóles, y díjoles: Yo soy congregado con mi pueblo; sepultádme con mis padres en la cueva, que está en el campo de Efrón el Jetteo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'En la cueva que está en el campo de la dobladura, que está delante de Mamré en la tierra de Canaán, la cual compró Abraham con el mismo campo de Efrón el Jetteo para heredad de sepultura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Allí sepultaron a Abraham, y a Sara su mujer: allí sepultaron a Isaac, y a Rebeca su mujer: allí también sepulté yo a Lia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Compra del campo y de la cueva que está en él, de los hijos de Jet.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Y como acabó Jacob de dar mandamientos a sus hijos, encogió sus pies en la cama, y espiró; y fue congregado con sus padres.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Entonces José se echó sobre el rostro de su padre, y lloró sobre él, y besóle.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Y mandó José a sus siervos médicos que embalsamasen a su padre: y los médicos embalsamaron a Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Y cumpliéronle cuarenta días, porque así cumplían los días de los embalsamados, y lloráronle los Egipcios setenta días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, '¶ Y pasados los días de su luto, habló José a los de la casa de Faraón, diciendo: Si he hallado ahora gracia en vuestros ojos, ruégoos que habléis en oídos de Faraón, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mi padre me conjuró, diciendo: He aquí, yo muero, en mi sepulcro, que yo cavé para mí en la tierra de Canaán, allí me sepultarás: ruego pues que vaya yo ahora, y sepultaré a mi padre, y volveré.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Y Faraón dijo: Vé, y sepulta a tu padre, como él te conjuró.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Entonces José subió a sepultar a su padre, y subieron con él todos los siervos de Faraón, los ancianos de su casa, y todos los ancianos de la tierra de Egipto,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'Y toda la casa de José, y sus hermanos, y la casa de su padre; solamente dejaron en la tierra de Gosén sus niños, y sus ovejas, y sus vacas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Y subieron también con él carros y gente de a caballo, e hízose un escuadrón muy grande.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Y llegaron hasta la Era de Atad, que es de la otra parte del Jordán, y lamentaron allí de grande lamentación y muy grave: e hizo a su padre llanto por siete días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Y viendo los moradores de la tierra, los Cananeos, el llanto en la Era de Atad, dijeron: Llanto grande es este de los Egipcios: por eso fue llamado su nombre Abel-mizraím, que es de la otra parte del Jordán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'E hicieron sus hijos con él, como él les mandó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Y lleváronle sus hijos a la tierra de Canaán, y sepultáronle en la cueva del campo de la dobladura, que había comprado Abraham con el mismo campo en heredad de sepultura, de Efrón el Jetteo, delante de Mamré.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Y tornóse José a Egipto, él y sus hermanos, y todos los que subieron con él a sepultar a su padre, después que le hubo sepultado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, '¶ Y viendo los hermanos de José, que su padre era muerto, dijeron: Quizá nos aborrecerá José, y nos dará el pago de todo el mal que le hicimos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Y enviaron a decir a José: Tu padre mandó antes de su muerte, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Así diréis a José: Ruégote que perdones ahora la maldad de tus hermanos, y su pecado, porque mal te galardonaron: por tanto ahora rogámoste que perdones la maldad de los siervos del Dios de tu padre. Y José lloró mientras le hablaban.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Y vinieron también sus hermanos; y postráronse delante de él, y dijeron: Hénos aquí por tus siervos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Y respondióles José: No tengáis miedo: ¿Soy yo en lugar de Dios?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Vosotros pensasteis mal sobre mí; mas Dios lo pensó por bien, para hacer lo que hoy vemos, para dar vida a mucho pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Ahora pues no tengáis miedo, yo os sustentaré a vosotros y a vuestros hijos. Así los consoló, y les habló al corazón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, '¶ Y estuvo José en Egipto, él y la casa de su padre: y vivió José ciento y diez años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Y vio José de Efraím los hijos terceros: también los hijos de Maquir, hijo de Manasés, fueron criados sobre las rodillas de José.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Y José dijo a sus hermanos: Yo me muero; mas Dios visitando os visitará: y os hará subir de aquesta tierra a la tierra, que juró a Abraham, a Isaac, y a Jacob.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Y conjuró José a los hijos de Israel, diciendo: Visitando os visitará Dios; y haréis llevar de aquí mis huesos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Y murió José de edad de ciento y diez años, y embalsamáronle, y fue puesto en un arca en Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Estos son los nombres de los hijos de Israel, que entraron en Egipto con Jacob, cada uno entró con su familia:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Rubén, Simeón, Leví, y Judá,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isacar, Zabulón, y Ben-jamín,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan, y Neftalí, Gad y Aser.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Y todas las almas que salieron del muslo de Jacob fueron setenta. Y José estaba en Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Y murió José, y todos sus hermanos, y toda aquella generación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Y los hijos de Israel crecieron, y multiplicaron y fueron aumentados y corroborados grandemente, e hinchióse la tierra de ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Levantóse entre tanto un nuevo rey sobre Egipto, que no conocía a José, el cual dijo a su pueblo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'He aquí, el pueblo de los hijos de Israel es mayor y más fuerte que nosotros:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Ahora pues, seamos sabios para con él, porque no se multiplique: y acontezca, que viniendo guerra, él también se junte con nuestros enemigos, y pelee contra nosotros, y se vaya de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Entonces pusieron sobre él comisarios de tributos que los molestasen con sus cargas: y edificaron a Faraón las ciudades de los bastimentos, Fitom y Rameses.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Empero cuanto más lo molestaban, tanto más se multiplicaba, y crecía: tanto que ellos se fastidiaban de los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Y los Egipcios hicieron servir a los hijos de Israel con dureza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Y amargaron su vida con servidumbre dura, en barro y ladrillo, y en toda labor del campo, y en todo su servicio en el cual se servían de ellos con dureza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, '¶ Y habló el rey de Egipto a las parteras de las Hebreas, una de las cuales se llamaba Séfora, y otra Pua, y díjoles:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Cuando parteareis a las Hebreas, y mirareis los asientos, si fuere hijo, matádle: y si fuere hija, entonces viva.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Mas las parteras temieron a Dios: y no hicieron como les dijo el rey de Egipto, y daban la vida a los niños.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Y el rey de Egipto hizo llamar a las parteras, y díjoles: ¿Por qué habéis hecho esto, que habéis dado vida a los niños?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Y las parteras respondieron a Faraón: Porque las mujeres Hebreas no son como las Egipcias, porque son robustas, y paren antes que la partera venga a ellas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'E hizo Dios bien a las parteras; y el pueblo se multiplicó, y se corroboraron en gran manera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Y por haber las parteras temido a Dios, él les hizo casas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, '¶ Entonces Faraón mandó a todo su pueblo, diciendo: Echád en el río todo hijo que naciere, y a toda hija dad la vida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Un varón de la familia de Leví fue, y tomó por mujer una hija de Leví:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'La cual concibió, y parióle un hijo, y viéndole que era hermoso, escondióle tres meses.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Y no pudiendo tenerle más escondido, tomó una arquilla de juncos, y calafateóla con pez y betún, y puso en ella al niño, y púsole en un carrizal a la orilla del río.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Y paróse una hermana suya lejos para ver lo que le acontecería.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Y la hija de Faraón descendió a lavarse al río, y paseándose sus doncellas por la ribera del río, ella vio la arquilla en el carrizal, y envió una criada suya a que la tomase.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Y como la abrió vio al niño, y he aquí el niño que lloraba: y teniendo compasión de él, dijo: De los niños de los Hebreos es este.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Entonces su hermana dijo a la hija de Faraón: ¿Iré a llamarte de las Hebreas, una ama, que te crie este niño?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Y la hija de Faraón respondió: Vé. La doncella entonces fue, y llamó a la madre del niño:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'A la cual dijo la hija de Faraón: Lleva este niño, y críamele, y yo te lo pagaré. Y la mujer tomó el niño, y crióle.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Y como creció el niño, ella le trajo a la hija de Faraón, la cual le prohijó, y púsole por nombre Moisés, diciendo: Porque de las aguas le saqué.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, '¶ Y en aquellos días acaeció que creció Moisés, y salió a sus hermanos, y vio sus cargas: y vio un varón Egipcio, que hería a un Hebreo de sus hermanos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Y miró a todas partes, y viendo que no parecía nadie, hirió al Egipcio, y escondióle en la arena.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Y salió el siguiente día, y viendo a dos Hebreos que reñían, dijo al malo: ¿Por qué hieres a tu prójimo?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Y él respondió: ¿Quién te ha a ti puesto por príncipe y juez sobre nosotros? ¿Piensas matarme, como mataste al Egipcio? Entonces Moisés tuvo miedo, y dijo: Ciertamente esta cosa es descubierta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, '¶ Y oyendo Faraón este negocio, procuró matar a Moisés; mas Moisés huyó de delante de Faraón, y habitó en la tierra de Madián, y sentóse junto a un pozo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'El sacerdote de Madián tenía siete hijas, las cuales vinieron a sacar agua para henchir las pilas, y dar de beber a las ovejas de su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Mas los pastores vinieron, y echáronlas; entonces Moisés se levantó, y defendiólas, y abrevó sus ovejas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Y volviendo ellas a Raguel, su padre, díjoles él: ¿Por qué habéis hoy venido tan presto?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Y ellas respondieron: Un varón Egipcio nos defendió de mano de los pastores, y también nos sacó el agua, y abrevó las ovejas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Y dijo a sus hijas: ¿Y dónde está? ¿Por qué habéis dejado ese hombre? llamádle para que coma pan.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Y Moisés acordó de morar con aquel varón, y él dio a Moisés a su hija Séfora.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'La cual le parió un hijo, y él le puso nombre Gersom, porque dijo: Peregrino soy en tierra ajena.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, '¶ Y aconteció, que después de muchos días el rey de Egipto murió: y los hijos de Israel suspiraron a causa de la servidumbre, y clamaron, y su clamor subió a Dios desde su servidumbre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Y oyó Dios el gemido de ellos, y acordóse de su concierto con Abraham, Isaac, y Jacob.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Y miró Dios a los hijos de Israel, y reconocióles Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Y apacentando Moisés las ovejas de Jetro su suegro, sacerdote de Madián, llevó las ovejas detrás del desierto, y vino a Horeb, monte de Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Y apareciósele el ángel de Jehová en una llama de fuego en medio de un zarzal: y él miró, y vio que el zarzal ardía en fuego, y el zarzal no se consumía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Entonces Moisés dijo: Ahora yo iré, y veré esta grande visión, por qué causa el zarzal no se queme.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, '¶ Y viendo Jehová que iba a ver, llamóle Dios de medio del zarzal, y dijo: Moisés, Moisés: Y él respondió: Heme aquí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Y dijo: No te llegues acá: quita tus zapatos de tus pies, porque el lugar en que tú estás, tierra santa es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Y dijo: Yo soy el Dios de tu padre, Dios de Abraham, Dios de Isaac, Dios de Jacob. Entonces Moisés cubrió su rostro, porque tuvo miedo de mirar a Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Y dijo Jehová: Viendo he visto la aflicción de mi pueblo, que está en Egipto; y he oído su clamor a causa de sus exactores, por lo cual yo he entendido sus dolores.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Y he descendido para librarlos de mano de los Egipcios: yo los sacaré de esta tierra a una tierra buena y ancha, a tierra que corre leche y miel; a los lugares del Cananeo, del Jetteo, del Amorreo, del Ferezeo, del Heveo, y del Jebuseo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'El clamor de los hijos de Israel ha venido ahora delante de mí: y también he visto la opresión con que los Egipcios les oprimen.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Ven pues ahora, y enviarte he a Faraón, para que saques a mi pueblo, los hijos de Israel, de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, '¶ Entonces Moisés respondió a Dios: ¿Quién soy yo, para que vaya a Faraón, y saque de Egipto a los hijos de Israel?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Y él le respondió: Porque yo seré contigo: y esto te será por señal, de que yo te he enviado: Después que hubieres sacado a este pueblo de Egipto, serviréis a Dios sobre este monte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Y dijo Moisés a Dios: He aquí, yo vengo a los hijos de Israel, y les digo: El Dios de vuestros padres me ha enviado a vosotros: y si ellos me preguntan: ¿Cuál es su nombre? ¿Qué les responderé?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Y respondió Dios a Moisés: YO SOY EL QUE SOY. Y dijo: Así dirás a los hijos de Israel: YO SOY, me ha enviado a vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Y dijo más Dios a Moisés: Así dirás a los hijos de Israel: Jehová, el Dios de vuestros padres, el Dios de Abraham, Dios de Isaac, y Dios de Jacob, me ha enviado a vosotros. Este es mi nombre para siempre; y este es mi memorial por todos los siglos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Vé, y junta los ancianos de Israel, y díles: Jehová, el Dios de vuestros padres, el Dios de Abraham, de Isaac, y de Jacob, me apareció, diciendo: Visitando os he visitado, y a lo que os es hecho en Egipto;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Y dije: Yo os sacaré de la aflicción de Egipto a la tierra del Cananeo, y del Jetteo, y del Amorreo, y del Ferezeo, y del Heveo, y del Jebuseo, a una tierra que corre leche y miel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Y oirán tu voz, e irás tú, y los ancianos de Israel al rey de Egipto, y decirle heis: Jehová, el Dios de los Hebreos, nos ha encontrado: por tanto nosotros iremos ahora camino de tres días por el desierto, para que sacrifiquemos a Jehová nuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Mas yo sé, que el rey de Egipto no os dejará ir, sino por mano fuerte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Mas yo extenderé mi mano, y heriré a Egipto con todas mis maravillas, que haré en él; y entonces os dejará ir.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Y yo daré a este pueblo gracia en los ojos de los Egipcios, para que cuando os partiereis, no salgáis vacíos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Y demandará cada mujer a su vecina y a su huéspeda vasos de plata, vasos de oro, y vestidos, los cuales pondréis sobre vuestros hijos, y vuestras hijas: y despojaréis a Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Entonces Moisés respondió, y dijo: He aquí que ellos no me creerán, ni oirán mi voz, porque dirán: No te ha aparecido Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Y Jehová dijo: ¿Qué es eso, que tienes en tu mano? Y él respondió: Una vara.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Y él le dijo: Echala en tierra. Y él la echó en tierra, y tornóse una culebra: y Moisés huía de ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Entonces dijo Jehová a Moisés: Extiende tu mano, y tómala por la cola. Y él extendió su mano, y tomóla, y tornóse en la vara en su mano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Por esto creerán, que Jehová el Dios de tus padres, se te ha aparecido: el Dios de Abraham, Dios de Isaac, y Dios de Jacob.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Y díjole más Jehová: Mete ahora tu mano en tu seno: Y él metió la mano en su seno: y como la sacó, he aquí que su mano estaba leprosa, como la nieve.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Y dijo: Vuelve a meter tu mano en tu seno. Y él volvió a meter su mano en su seno; y volviéndola a sacar del seno, he aquí que era vuelta como la otra carne.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Si aconteciere, que no te creyeren, ni obedecieren a la voz de la primera señal, creerán a la voz de la postrera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Y si aun no creyeren a estas dos señales, ni oyeren tu voz, tomarás de las aguas del río, y derramas en tierra, y volverse han aquellas aguas que tú tomarás del río, volverse han en sangre en la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, '¶ Entonces dijo Moisés a Jehová: Ay, Señor, yo no soy hombre de palabras de ayer, ni de anteayer, ni aun desde que tú hablas a tu siervo: porque soy pesado de boca y pesado de lengua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Y Jehová le respondió: ¿Quién dio la boca al hombre? ¿O, quién hizo al mudo y al sordo? ¿al que ve y al ciego? ¿No soy yo Jehová?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Vé pues ahora, que yo seré en tu boca, y te enseñaré lo que hayas de hablar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, '¶ Y él dijo: Ay, Señor, envía por mano del que has de enviar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Entonces Jehová se enojó contra Moisés, y dijo: ¿No conozco yo a tu hermano Aarón, Levita; que él hablará? Y aun, he aquí, que él te saldrá a recibir, y en viéndote, se alegrará de su corazón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Tú hablarás a él y pondrás en su boca las palabras, y yo seré en tu boca, y en la suya, y os enseñaré lo que hayáis de hacer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Y él hablará por ti al pueblo, y él te será por boca, y tu serás a él por Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Y tomarás esta vara en tu mano, con la cual harás las señales.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, '¶ Así se fue Moisés, y volviendo a su suegro Jetro, díjole: Yo iré ahora, y volveré a mis hermanos, que están en Egipto, para ver si aun viven. Y Jetro dijo a Moisés: Vé en paz.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Dijo también Jehová a Moisés en Madián: Vé, y vuélvete a Egipto; porque todos los que te procuraban la muerte, son muertos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Entonces Moisés tomó a su mujer y sus hijos, y púsoles sobre un asno, y volvióse a tierra de Egipto: tomó también Moisés la vara de Dios en su mano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Y dijo Jehová a Moisés: Cuando fueres vuelto a Egipto, mira que hagas delante de Faraón todas las maravillas, que yo he puesto en tu mano: yo empero endureceré su corazón para que no deje ir al pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Y dirás a Faraón: Jehová ha dicho así: Israel es mi hijo, mi primogénito:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Y yo te he dicho, que dejes ir a mi hijo, para que me sirva: y no has querido dejarle ir; por tanto, he aquí, yo mato a tu hijo, tu primogénito.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Y aconteció en el camino, que en una posada le encontró Jehová, y le quiso matar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Entonces Séfora arrebató un pedernal, y cortó el prepucio de su hijo, y echóle a sus pies, diciendo: Porque tú me eres esposo de sangre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Entonces se apartó de él. Y ella le dijo: Esposo de sangre, a causa de la circuncisión.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, '¶ Y Jehová dijo a Aarón: Vé a recibir a Moisés al desierto. Y él fue, y encontróle en el monte de Dios, y le besó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Entonces Moisés contó a Aarón todas las palabras de Jehová, que le enviaba, y todas las señales, que le había dado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, '¶ Y fueron Moisés y Aarón, y juntaron todos los ancianos de los hijos de Israel,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Y Aarón habló todas las palabras que Jehová había dicho a Moisés, e hizo las señales delante de los ojos del pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Y el pueblo creyó: y oyendo, que Jehová había visitado a los hijos de Israel, y que había visto su aflicción, inclináronse, y adoraron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Después de esto Moisés y Aarón entraron a Faraón, y dijéronle: Jehová, el Dios de Israel, dice así: Deja ir mi pueblo a celebrarme fiesta en el desierto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Y Faraón respondió: ¿Quién es Jehová, para que yo oiga su voz, y deje ir a Israel? Yo no conozco a Jehová, ni tampoco dejaré ir a Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Y ellos dijeron: El Dios de los Hebreos nos ha encontrado: por tanto nosotros iremos ahora camino de tres días por el desierto, y sacrificaremos a Jehová nuestro Dios: porque no nos encuentre con pestilencia, o espada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Entonces el rey de Egipto les dijo: Moisés, y Aarón: ¿Por qué hacéis cesar al pueblo de su obra? Id a vuestros cargos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Dijo también Faraón: He aquí, el pueblo de la tierra es ahora mucho, y vosotros los hacéis cesar de sus cargos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Y mandó Faraón aquel mismo día a los cuadrilleros del pueblo que tenían cargo del pueblo, y a los gobernadores de él, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'De aquí a delante no daréis paja al pueblo para hacer el ladrillo, como ayer y anteayer; vayan ellos, y cójanse la paja;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Y ponerles heis la tarea del ladrillo que hacían antes, y no les disminuiréis nada; porque están ociosos, y por eso dan voces, diciendo: Vamos, y sacrificaremos a nuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Agrávese la servidumbre sobre ellos, para que se ocupen en ella, y no miren a palabras de mentira.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Y saliendo los cuadrilleros del pueblo, y sus gobernadores, hablaron al pueblo, diciendo: Así ha dicho Faraón: Yo no os doy paja.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Id vosotros, y tomáos paja, donde la hallareis: que nada se disminuirá de vuestra tarea.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Entonces el pueblo se derramó por toda la tierra de Egipto a coger hojarascas en lugar de paja.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Y los cuadrilleros los apremiaban, diciendo: Acabád vuestra obra, la tarea del día en su día, como cuando se os daba paja.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Y azotaban a los gobernadores de los hijos de Israel, que los cuadrilleros de Faraón habían puesto sobre ellos, diciendo: ¿Por qué no habéis cumplido vuestra tarea de ladrillo ni ayer ni hoy, como antes?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Y los gobernadores de los hijos de Israel vinieron, y quejáronse a Faraón, diciendo: ¿Por qué lo haces así con tus siervos?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'No se da paja a tus siervos, y con todo eso nos dicen: Hacéd el ladrillo. Y he aquí, tus siervos son azotados, y tu pueblo peca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Y él respondió: Estáis ociosos, ociosos: y por eso decís: Vamos y sacrifiquemos a Jehová,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Id pues ahora, trabajád. Paja no se os dará, y daréis la tarea del ladrillo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, '¶ Entonces los gobernadores de los hijos de Israel se vieron en aflicción, cuando les era dicho: No se disminuirá nada de vuestro ladrillo, de la tarea del día en su día.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Y encontrando a Moisés y a Aarón que estaban delante de ellos cuando salían de Faraón,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Dijéronles: Mire Jehová sobre vosotros, y juzgue, que habéis hecho heder nuestro olor delante de Faraón, y de sus siervos, dándoles la espada en las manos para que nos maten.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, '¶ Entonces Moisés se volvió a Jehová, y dijo: Señor, ¿por qué afliges a este pueblo? ¿Para qué me enviaste?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Porque desde que yo vine a Faraón para hablarle en tu nombre, ha afligido a este pueblo, y tú tampoco has librado a tu pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Y Jehová respondió a Moisés: Ahora verás lo que yo haré a Faraón: porque con mano fuerte los ha de dejar ir, y con mano fuerte los ha de echar de su tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Y habló Dios a Moisés, y díjole: Yo soy Jehová;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Y yo aparecí a Abraham, a Isaac, y a Jacob en Dios Omnipotente, mas en mi nombre Jehová no me notifiqué a ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Y también establecí mi concierto con ellos que les daría la tierra de Canaán; la tierra de sus peregrinaciones, y en la cual fueron extranjeros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Y así mismo yo he oído el gemido de los hijos de Israel; que los Egipcios les hacen servir; y heme acordado de mi concierto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Por tanto dirás a los hijos de Israel: Yo soy Jehová: Y yo os sacaré de debajo de las cargas de Egipto, y os libraré de su servidumbre, y os redimiré con brazo extendido, y con juicios grandes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Y yo os tomaré por mi pueblo, y seré vuestro Dios: y sabréis que yo soy Jehová vuestro Dios, que os saco de debajo de las cargas de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Y yo os meteré en la tierra, por la cual alcé mi mano, que la daría a Abraham, a Isaac, y a Jacob, y yo os la daré por heredad. Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'De esta manera habló Moisés a los hijos de Israel: mas ellos no escuchaban a Moisés a causa de la congoja de espíritu, y de la dura servidumbre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, '¶ Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Entra, y habla a Faraón rey de Egipto, que deje ir de su tierra a los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Y respondió Moisés delante de Jehová, diciendo: He aquí, los hijos de Israel, no me escuchan; ¿cómo pues, me escuchará Faraón, mayormente siendo yo incircunciso de labios?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Entonces Jehová habló a Moisés y a Aarón, y dióles mandamiento para los hijos de Israel, y para Faraón rey de Egipto, para que sacasen a los hijos de Israel, de la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, '¶ Estas son las cabezas de las familias de sus padres: Los hijos de Rubén, el primogénito de Israel; Jenoc, y Fallu, Jesrón, y Carmi: estas son las familias de Rubén.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Los hijos de Simeón; Jamuel, y Jamín, y Ahod, y Jaquín, y Soher, y Saul, hijo de una mujer Cananea: estas son las familias de Simeón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Estos son los nombres de los hijos de Leví por sus linajes; Gersón, y Caat, y Merari. Y los años de la vida de Leví fueron ciento y treinta y siete años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Y los hijos de Gersón fueron Lebna, y Semeí, por sus familias.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Y los hijos de Caat fueron Amram, e Isaar, y Hebrón, y Oziel. Y los años de la vida de Caat fueron ciento y treinta y tres años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Y los hijos de Merari fueron Moholi, y Musi. Estas son las familias de Leví por sus linajes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Y Amram se tomó por mujer a Jocabed su tía; la cual le parió a Aarón, y a Moisés. Y los años de la vida de Amram fueron ciento y treinta y siete años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Y los hijos de Isaar fueron Coré, y Nefeg, y Zecri.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Y los hijos de Oziel; Misael y Elisafán, y Setri.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Y Aarón se tomó por mujer a Elisabet, hija de Aminadab, hermana de Naasón, la cual le parió a Nadab, y a Abiú, y a Eleazar, y a Itamar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Y los hijos de Coré fueron Aser, y Elcana, y Abiasaf. Estas son las familias de los Coritas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Y Eleazar, hijo de Aarón, se tomó mujer de las hijas de Futiel, la cual le parió a Finees: y estas son las cabezas de los padres de los Levitas por sus familias.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Este es Aarón y Moisés, a los cuales Jehová dijo: Sacád a los hijos de Israel de la tierra de Egipto por escuadrones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Estos son los que hablaron a Faraón rey de Egipto, para sacar de Egipto a los hijos de Israel. Este era Moisés y Aarón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Cuando Jehová habló a Moisés en la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Entonces Jehová habló a Moisés, diciendo: Yo soy Jehová: di a Faraón rey de Egipto todas las cosas, que yo te digo a ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Y Moisés respondió delante de Jehová: He aquí, yo soy incircunciso de labios: ¿cómo pues me ha de oír Faraón?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Y Jehová dijo a Moisés: Mira, yo te he constituido por Dios de Faraón: y tu hermano Aarón será tu profeta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Tú dirás todas las cosas que yo te mandaré; y Aarón, tu hermano, hablará a Faraón, que deje ir de su tierra a los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Y yo endureceré el corazón de Faraón, y multiplicaré en la tierra de Egipto mis señales y mis maravillas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Y Faraón no os oirá; mas yo pondré mi mano sobre Egipto, y sacaré mis ejércitos, mi pueblo, los hijos de Israel, de la tierra de Egipto, por grandes juicios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Y sabrán los Egipcios, que yo soy Jehová, cuando extenderé mi mano sobre Egipto, y sacaré los hijos de Israel de en medio de ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'E hizo Moisés y Aarón como Jehová les mandó; así lo hicieron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Moisés entonces era de edad de ochenta años, y Aarón de edad de ochenta y tres, cuando hablaron a Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Y habló Jehová a Moisés y a Aarón, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Si Faraón os respondiere, diciendo: Mostrád algún milagro: dirás a Aarón: Toma tu vara, y échala delante de Faraón, para que se torne culebra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, '¶ Y vino Moisés y Aarón a Faraón, e hicieron como Jehová lo había mandado: y echó Aarón su vara delante de Faraón y de sus siervos, y tornóse culebra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Entonces llamó también Faraón sabios y encantadores, e hicieron también lo mismo los encantadores de Egipto con sus encantamentos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Que echó cada uno su vara, las cuales se volvieron en culebras: mas la vara de Aarón tragó las varas de ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Y el corazón de Faraón se endureció, y no los escuchó, como Jehová lo había dicho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, '¶ Entonces Jehová dijo a Moisés: El corazón de Faraón está agravado, que no quiere dejar ir el pueblo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Vé pues por la mañana a Faraón, he aquí que él sale a las aguas; y pónte a la orilla del río delante de él; y toma en tu mano la vara que se volvió en culebra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Y díle: Jehová, el Dios de los Hebreos, me ha enviado a ti, diciendo: Deja ir a mi pueblo; para que me sirvan en el desierto: y he aquí que hasta ahora no has querido oír.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Así pues ha dicho Jehová: En esto conocerás, que yo soy Jehová: he aquí, yo heriré con la vara, que tengo en mi mano, el agua que está en el río, y volverse ha en sangre:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Y los peces que están en el río, morirán, y el río hederá, y fatigarse han los Egipcios bebiendo el agua del río.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Y Jehová dijo a Moisés: Di a Aarón: Toma tu vara, y extiende tu mano sobre las aguas de Egipto, sobre sus ríos, sobre sus arroyos, y sobre sus estanques, y sobre todos sus recogimientos de aguas, para que se vuelvan en sangre, y haya sangre por toda la región de Egipto así en los vasos de madera, como en los de piedra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Y Moisés y Aarón hicieron como Jehová lo mandó, y alzando la vara hirió las aguas que estaban en el río en presencia de Faraón y de sus siervos, y todas las aguas que estaban en el río, se volvieron en sangre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Asimismo los peces, que estaban en el río, murieron; y el río se corrompió, que los Egipcios no pudieron beber de él: y hubo sangre por toda la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Y los encantadores de Egipto hicieron lo mismo con sus encantamentos: y el corazón de Faraón se endureció, y no los escuchó, como Jehová lo había dicho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Y tornando Faraón volvióse a su casa, y no puso su corazón aun en esto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Y en todo Egipto hicieron pozos al rededor del río para beber, porque no podían beber de las aguas del río.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Y cumpliéronse siete días después que Jehová hirió el río.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Entonces Jehová dijo a Moisés: Entra a Faraón, y díle: Jehová ha dicho así: Deja ir a mi pueblo para que me sirvan:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Y si no le quisieres dejar ir, he aquí, yo hiero con ranas todos tus términos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Y el río criará ranas, las cuales subirán, y vendrán a tu casa, y a la cámara de tu cama, y sobre tu cama, y en las casas de tus siervos, y en tu pueblo, y en tus hornos, y en tus artesas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Y las ranas subirán sobre ti, y sobre tu pueblo, y sobre todos tus siervos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Y Jehová dijo a Moisés: Di a Aarón: Extiende tu mano con tu vara sobre los ríos, riberas, y estanques para que haga subir ranas sobre la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Entonces Aarón extendió su mano sobre las aguas de Egipto, y subieron ranas, que cubrieron la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Y los encantadores hicieron lo mismo con sus encantamentos, e hicieron subir ranas sobre la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Entonces Faraón llamó a Moisés, y a Aarón, y díjoles: Orád a Jehová, que quite las ranas de mí, y de mi pueblo; y yo dejaré ir el pueblo, para que sacrifiquen a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Y dijo Moisés a Faraón: Señálame cuando oraré por ti, y por tus siervos, y por tu pueblo, para que las ranas sean quitadas de ti, y de tus casas; y que solamente se queden en el río.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Y él dijo: Mañana. Y Moisés respondió: Conforme a tu palabra, para que conozcas que no hay otro como Jehová nuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Y las ranas se irán de ti, y de tus casas, y de tus siervos, y de tu pueblo; y solamente se quedarán en el río.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Entonces salió Moisés y Aarón de con Faraón; y Moisés clamó a Jehová sobre el negocio de las ranas que había puesto a Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'E hizo Jehová conforme a la palabra de Moisés; y las ranas murieron de las casas, de los cortijos, y de los campos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Y cogiéronlas a montones, y la tierra hedió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, '¶ Y viendo Faraón que le habían dado reposo, agravó su corazón, y no los escuchó, como Jehová lo había dicho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Entonces Jehová dijo a Moisés: Di a Aarón: Extiende tu vara, y hiere el polvo de la tierra; para que se vuelva en piojos por toda la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Y ellos lo hicieron así. Y Aarón extendió su mano con su vara; e hirió el polvo de la tierra, el cual se tornó en piojos, así en los hombres como en las bestias: Todo el polvo de la tierra se tornó en piojos en toda la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Y los encantadores hicieron así también para sacar piojos con sus encantamentos, mas no pudieron. Y había piojos así en los hombres como en las bestias.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Entonces los magos dijeron a Faraón: Dedo de Dios es este. Mas el corazón de Faraón se endureció, y no los escuchó, como Jehová lo había dicho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, '¶ Y Jehová dijo a Moisés: Levántate de mañana, y pónte delante de Faraón; he aquí, él sale a las aguas; y díle: Jehová ha dicho así: Deja ir a mí pueblo para que me sirva:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Porque si no dejares ir a mi pueblo, he aquí, yo envío sobre ti, y sobre tus siervos, y sobre tu pueblo, y sobre tus casas toda suerte de moscas; y las casas de los Egipcios se henchirán de toda suerte de moscas, y asimismo la tierra donde ellos estuvieren.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Y aquel día yo apartaré la tierra de Gosén, en la cual mi pueblo habita, que ninguna suerte de moscas haya en ella, para que sepas que yo soy Jehová en medio de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Y yo pondré redención entre mi pueblo y el tuyo. Esta señal será mañana.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Y Jehová lo hizo así: que vino toda suerte de moscas molestísimas sobre la casa de Faraón, y sobre las casas de sus siervos, y sobre toda la tierra de Egipto, y la tierra fue corrompida a causa de ellas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Entonces Faraón llamó a Moisés y a Aarón, y díjoles: Andád, sacrificád a vuestro Dios en la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Y Moisés respondió: No conviene que hagamos así, porque sacrificaríamos a Jehová nuestro Dios la abominación de los Egipcios. He aquí, si sacrificásemos la abominación de los Egipcios delante de ellos, ¿no nos apedrearían?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Camino de tres días iremos por el desierto; y sacrificaremos a Jehová nuestro Dios, como él nos dirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Y dijo Faraón: Yo os dejaré ir para que sacrifiquéis a Jehová vuestro Dios en el desierto, con tal que no vayáis más lejos: orád por mí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Y respondió Moisés: He aquí, en saliendo yo de contigo, rogaré a Jehová que las suertes de moscas se vayan de Faraón, y de sus siervos, y de su pueblo mañana, con tal que Faraón no falte más no dejando ir al pueblo a sacrificar a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Entonces Moisés salió de con Faraón, y oró a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Y Jehová hizo conforme a la palabra de Moisés, y quitó todas las suertes de moscas de Faraón, y de sus siervos, y de su pueblo; que no quedó una.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Mas Faraón agravó aun esta vez su corazón, y no dejó ir el pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Entonces Jehová dijo a Moisés: Entra a Faraón, y díle: Jehová, el Dios de los Hebreos, dice así: Deja ir a mi pueblo, para que me sirvan:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Porque si no lo quieres dejar ir, y aun los detuvieres,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'He aquí, la mano de Jehová será sobre tus ganados que están en el campo, caballos, asnos, camellos, vacas, y ovejas con pestilencia gravísima:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Y Jehová hará separación entre los ganados de Israel, y los de Egipto, que nada muera de todo lo de los hijos de Israel:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Y Jehová señaló tiempo, diciendo: Mañana hará Jehová esta cosa en la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Y el día siguiente Jehová hizo esta cosa, que todo el ganado de Egipto murió; mas del ganado de los hijos de Israel no murió uno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Entonces Faraón envió a ver, y he aquí que del ganado de los hijos de Israel no había muerto uno. Y el corazón de Faraón se agravó, y no dejó ir al pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, '¶ Y Jehová dijo a Moisés y a Aarón: Tomáos vuestros puños llenos de la ceniza de un horno, y espárzala Moisés hacia el cielo delante de Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Y volverse ha en polvo sobre toda la tierra de Egipto, que en los hombres y en las bestias se volverá en sarna que eche vejigas, por toda la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Y ellos tomaron la ceniza del horno, y pusiéronse delante de Faraón, y esparcióla Moisés hacia el cielo, y vino una sarna que echaba vejigas así en los hombres como en las bestias:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Que los magos no podían estar delante de Moisés a causa de la sarna, porque hubo sarna en los magos, y en todos los Egipcios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Y Jehová endureció el corazón de Faraón para que no los oyese, como Jehová lo había dicho a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, '¶ Entonces Jehová dijo a Moisés: Levántate de mañana, y ponte delante de Faraón, y díle: Jehová, el Dios de los Hebreos, dice así: Deja ir mi pueblo para que me sirva.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Porque de otra manera esta vez yo envío todas mis plagas a tu corazón, y en tus siervos, y en tu pueblo, para que entiendas, que no hay otro como yo en toda la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Porque ahora yo extenderé mi mano para herirte a ti y a tu pueblo de pestilencia, y serás quitado de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Porque a la verdad yo te he puesto para declarar en ti mi poderío, y que mi nombre sea contado en toda la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Tú aun te ensalzas contra mi pueblo para no dejarlos ir.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Pues he aquí que mañana a estas horas yo haré llover granizo muy grave, cual nunca fue en Egipto, desde el día que se fundó hasta ahora.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Envía pues, recoge tu ganado, y todo lo que tienes en el campo; porque todo hombre o animal que se hallare en el campo y no fuere recogido a casa, el granizo descenderá sobre él, y morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'El de los siervos de Faraón, que temió la palabra de Jehová, hizo huir sus siervos y su ganado a casa:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Mas el que no puso en su corazón la palabra de Jehová, dejó sus siervos y sus ganados en el campo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Y Jehová dijo a Moisés: Extiende tu mano hacia el cielo, para que venga granizo en toda la tierra de Egipto sobre los hombres y sobre las bestias, y sobre toda la yerba del campo en la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Y Moisés extendió su vara hacia el cielo, y Jehová hizo truenos, y fuego discurría por la tierra: y llovió Jehová granizo sobre la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Y hubo granizo, y fuego mezclado entre el granizo, muy grande cual nunca fue en toda la tierra de Egipto; desde que fue habitada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Y aquel granizo hirió en toda la tierra de Egipto todo lo que estaba en el campo, así hombres como bestias: asimismo toda la yerba del campo hirió el granizo, y quebró todos los árboles del campo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Solamente en la tierra de Gosén, donde los hijos de Israel estaban, no hubo granizo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, '¶ Entonces Faraón envió a llamar a Moisés y a Aarón, y díjoles: Yo he pecado esta vez. Jehová es justo, y yo y mi pueblo impío.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Orád a Jehová, y cesen los truenos de Dios y el granizo; y yo os dejaré ir, y no quedaréis más aquí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Y respondióle Moisés: En saliendo yo de la ciudad extenderé mis manos a Jehová, y los truenos cesarán, y no habrá más granizo, para que sepas que de Jehová es la tierra:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Mas yo conozco a ti y a tus siervos de antes que temieseis de la presencia del Dios Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'El lino y la cebada fueron heridos; porque la cebada estaba ya espigada, y el lino en caña.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Mas el trigo y el centeno no fueron heridos, porque eran tardíos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Y salido Moisés de con Faraón de la ciudad, extendió sus manos a Jehová, y cesaron los truenos y el granizo; y la lluvia no cayó más sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Y viendo Faraón, que la lluvia había cesado, y el granizo y los truenos, perseveró en pecar, y agravó su corazón él y sus siervos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Y el corazón de Faraón se endureció, y no dejó ir los hijos de Israel, como Jehová lo había dicho por mano de Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Y Jehová dijo a Moisés: Entra a Faraón, porque yo he agravado su corazón, y el corazón de sus siervos, para dar entre ellos estas mis señales:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'Y para que cuentes a tus hijos y a tus nietos las cosas que yo hice en Egipto, y mis señales, que yo di entre ellos: y para que sepáis que yo soy Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Entonces vino Moisés y Aarón a Faraón, y dijéronle: Jehová, el Dios de los Hebreos, ha dicho así: ¿Hasta cuando no querrás humillarte delante de mí? Deja ir a mi pueblo, para que me sirvan:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Y si aun rehusas de dejarle ir, he aquí que yo traeré mañana langosta en tus términos,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'La cual cubrirá la haz de la tierra, que la tierra no pueda ser vista, y ella comerá lo que quedó salvo, lo que os ha quedado del granizo: y comerá todo árbol que os produce fruto en el campo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Y henchirse han tus casas; y las casas de todos tus siervos, y las casas de todos los Egipcios, cual nunca vieron tus padres, ni tus abuelos desde que ellos fueron sobre la tierra hasta hoy. Y volvióse, y salió de con Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Entonces los siervos de Faraón le dijeron: ¿Hasta cuándo nos ha de ser este por lazo? Deja ir estos hombres, para que sirvan a Jehová su Dios: ¿Aun no sabes que Egipto está destruido?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Y Moisés y Aarón fueron tornados a llamar a Faraón, el cual les dijo: Andád, servíd a Jehová vuestro Dios. ¿Quién y quién son los que han de ir?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Y Moisés respondió: Nosotros hemos de ir con nuestros niños, y con nuestros viejos, con nuestros hijos y con nuestras hijas: con nuestras ovejas y con nuestras vacas hemos de ir; porque tenemos solemnidad de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Y él les dijo: Así sea Jehová con vosotros como yo os dejaré ir a vosotros y a vuestros niños: mirád la malicia que está delante de vuestro rostro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'No será así. Andád ahora los varones, y servíd a Jehová; porque esto es lo que vosotros demandasteis. Y echáronlos de delante de Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, '¶ Entonces Jehová dijo a Moisés: Extiende tu mano sobre la tierra de Egipto para langosta, para que suba sobre la tierra de Egipto; y pazca todo lo que el granizo dejó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Y extendió Moisés su vara sobre la tierra de Egipto, y Jehová trajo un viento oriental sobre la tierra todo aquel día, y toda aquella noche; y a la mañana el viento oriental trajo la langosta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Y subió la langosta sobre toda la tierra de Egipto, y asentóse en todos los términos de Egipto, en gran manera grave: antes de ella no hubo tal langosta; ni después de ella vendrá otra tal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Y cubrió la haz de toda la tierra, y la tierra se oscureció, y comió toda la yerba de la tierra, y todo el fruto de los árboles, que había dejado el granizo, que no quedó cosa verde en árboles ni en la yerba del campo por toda la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, '¶ Entonces Faraón hizo llamar a priesa a Moisés y a Aarón, y dijo: Yo he pecado contra Jehová vuestro Dios, y contra vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Mas yo ruego ahora que perdones mi pecado solamente esta vez, y que oréis a Jehová vuestro Dios, que quite de mí solamente esta muerte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Y salió de con Faraón, y oró a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Y Jehová volvió un viento occidental fortísimo, y quitó la langosta, y echóla en el mar Bermejo: ni aun una langosta quedó en todo el término de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Y Jehová endureció el corazón de Faraón, y no envió los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, '¶ Y Jehová dijo a Moisés: Extiende tu mano hacia el cielo, para que sean tinieblas sobre la tierra de Egipto, tales que cualquiera las palpe.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Y extendió Moisés su mano hacia el cielo; y fueron tinieblas oscuras tres días por toda la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Ninguno vio a su prójimo, ni nadie se levantó de su lugar en tres días; mas todos los hijos de Israel tenían luz en sus habitaciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, '¶ Entonces Faraón hizo llamar a Moisés, y dijo: Id, servíd a Jehová; solamente queden vuestras ovejas y vuestras vacas; vayan también vuestros niños con vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Y Moisés respondió: Tú también nos darás en nuestras manos sacrificios y holocaustos; que sacrifiquemos a Jehová nuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Nuestros ganados irán también con nosotros: no quedará ni aun una uña; porque de ellos hemos de tomar para servir a Jehová nuestro Dios: que tampoco nosotros sabemos, aun con qué hemos de servir a Jehová, hasta que vengamos allá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Mas Jehová endureció el corazón de Faraón, y no quiso dejarlos ir.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Y díjole Faraón: Vete de mí, guárdate que no veas más mi rostro, porque en cualquier día, que vieres mi rostro, morirás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Y Moisés respondió: Bien has dicho: yo no veré más tu rostro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Y Jehová dijo a Moisés: Una plaga aun traeré sobre Faraón, y sobre Egipto: después de la cual él os dejará ir de aquí, y enviando os echará de aquí del todo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Habla ahora al pueblo, que cada uno demande a su vecino, y cada una a su vecina, vasos de plata y de oro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Y Jehová dio gracia al pueblo en los ojos de los Egipcios. También Moisés era muy gran varón en la tierra de Egipto delante de los siervos de Faraón, y delante del pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, '¶ Y dijo Moisés: Jehová ha dicho así: A la media noche yo saldré por medio de Egipto:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Y morirá todo primogénito en tierra de Egipto, desde el primogénito de Faraón, que está asentado en su trono, hasta el primogénito de la sierva, que está tras la muela; y todo primogénito de las bestias.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Y habrá gran clamor por toda la tierra de Egipto, cual nunca fue, ni nunca será.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Mas en todos los hijos de Israel no habrá perro que mueva su lengua, desde el hombre hasta la bestia, para que sepáis que hará diferencia Jehová entre los Egipcios y los Israelitas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Y descenderán a mí todos estos tus siervos, e inclinados delante de mí dirán: Sal tú, y todo el pueblo que está debajo de ti. Y después de esto yo saldré. Y salióse muy enojado de delante de Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Y Jehová dijo a Moisés: Faraón no os oirá, para que mis maravillas se multipliquen en la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Y Moisés y Aarón hicieron todos estos prodigios delante de Faraón: mas Jehová había endurecido el corazón de Faraón, y no envió a los hijos de Israel de su tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Y habló Jehová a Moisés, y a Aarón en la tierra de Egipto, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Este mes os será cabeza de los meses: este os será primero en los meses del año.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Hablád a toda la congregación de Israel, diciendo: A los diez de aqueste mes tómese cada uno un cordero por las familias de los padres, un cordero cada familia:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Mas si la familia fuere pequeña que no baste a comer el cordero, entonces tomará a su vecino cercano de su casa, y según el número de las personas, cada uno según su comida, echaréis la cuenta sobre el cordero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'El cordero será a vosotros perfecto macho, de un año, el cual tomaréis de las ovejas, o de las cabras:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Y guardarlo heis hasta el catorceno día de este mes: y sacrificarlo ha toda la compañía de la congregación de Israel entre las dos tardes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Y tomarán de la sangre, y pondrán en los dos postes, y en los bates de las casas, en las cuales lo han de comer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Y aquella noche comerán la carne asada al fuego, y panes sin levadura: con yerbas amargas lo comerán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Ninguna cosa comeréis de él cruda, no cocida en agua, sino asada al fuego; su cabeza con sus pies y sus intestinos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Ninguna cosa dejaréis de él hasta la mañana; y lo que habrá quedado hasta la mañana, quemarlo heis en el fuego.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Y comerlo heis así: Ceñidos vuestros lomos, y vuestros zapatos en vuestros pies: y vuestro bordón en vuestra mano, y comerlo heis apresuradamente. Esta es la pascua de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Y yo pasaré por la tierra de Egipto aquesta noche; y heriré a todo primogénito en la tierra de Egipto, así en los hombres como en las bestias: y haré juicios en todos los dioses de Egipto. Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Y la sangre os será por señal en las casas donde vosotros estuviereis; y veré la sangre, y pasaré por encima de vosotros, y no habrá en vosotros plaga de mortandad, cuando yo heriré la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Y seros ha este día en memoria; y celebrarlo heis solemne a Jehová por vuestras edades: por estatuto perpetuo lo celebraréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Siete días comeréis panes sin levadura; mas el primer día haréis que no haya levadura en vuestras casas: porque cualquiera que comiere leudado, desde el primer día hasta el séptimo, aquella alma será cortada de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'El primer día os será santa convocación, y así mismo el séptimo día os será santa convocación: ninguna obra se hará en ellos, solamente lo que toda persona hubiere de comer, esto solamente se aderece para vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Y guardaréis los ácimos, porque en aqueste mismo día saqué vuestros ejércitos de la tierra de Egipto: por tanto guardaréis este día por vuestras edades por costumbre perpetua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'En el primero, a los catorce días del mes, a la tarde, comeréis los panes sin levadura, hasta los veinte y uno del mes a la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Por siete días no se hallará levadura en vuestras casas; porque cualquiera que comiere leudado, así extranjero como natural de la tierra, aquella alma será cortada de la congregación de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Ninguna cosa leudada comeréis: en todas vuestras habitaciones comeréis panes sin levadura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Y Moisés convocó a todos los ancianos de Israel, y díjoles: Sacád, y tomáos corderos por vuestras familias, y sacrificád la pascua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Y tomád un manojo de hisopo, y mojádlo en la sangre que estará en un lebrillo, y untád los bates y los dos postes con la sangre que estará en el lebrillo; y ninguno de vosotros salga de las puertas de su casa hasta la mañana.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Porque Jehová pasará hiriendo a los Egipcios; y como verá la sangre en el bate, y en los dos postes, Jehová pasará aquella puerta, y no dejará entrar al heridor en vuestras casas para herir.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Y guardaréis esto por estatuto para vosotros y para vuestros hijos para siempre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Y será, que cuando entrareis en la tierra que Jehová os dará, como habló, y guardareis este rito;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Y cuando os dijeren vuestros hijos: ¿Qué rito es este vuestro?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Vosotros responderéis: Esta es la víctima de la pascua de Jehová, el cual pasó por encima de las casas de los hijos de Israel en Egipto, cuando hirió a los Egipcios, y libró nuestras casas. Entonces el pueblo se inclinó, y adoró.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Y los hijos de Israel fueron, e hicieron como Jehová había mandado a Moisés y a Aarón, así lo hicieron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, '¶ Y aconteció que a la media noche Jehová hirió a todo primogénito en la tierra de Egipto, desde el primogénito de Faraón, que estaba sentado sobre su trono, hasta el primogénito del cautivo que estaba en la cárcel, y a todo primogénito de los animales.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, '¶ Y levantóse aquella noche Faraón, él y todos sus siervos, y todos los Egipcios, y había un gran clamor en Egipto; porque no había casa donde no hubiese muerto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'E hizo llamar a Moisés y a Aarón de noche, y díjoles: Levantáos; salíd de en medio de mi pueblo vosotros y los hijos de Israel; e id, servíd a Jehová, como habéis dicho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Tomád también vuestras ovejas, también vuestras vacas, como habéis dicho, e ídos, y bendecídme también a mí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Y los Egipcios apremiaban al pueblo, dándose priesa a echarlos de la tierra, porque decían: Todos somos muertos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Y llevó el pueblo su masa antes que se leudase, sus masas atadas, en sus sábanas sobre sus hombros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'E hicieron los hijos de Israel conforme al mandamiento de Moisés, demandando a los Egipcios vasos de plata, y vasos de oro, y vestidos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Y Jehová dio gracia al pueblo delante de los Egipcios, y prestáronles, y ellos despojaron a los Egipcios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Y partieron los hijos de Israel de Rameses a Socot como seiscientos mil hombres de a pie, sin los niños.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Y también subió con ellos grande multitud de diversa suerte de gentes, y ovejas y vacas, y ganados muy muchos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Y cocieron la masa, que habían sacado de Egipto e hicieron tortas sin levadura; porque no habían leudado; porque echándolos los Egipcios no habían podido detenerse, ni aun aparejarse comida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'El tiempo que los hijos de Israel habitaron en Egipto, fue cuatrocientos y treinta años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Y pasados cuatrocientos y treinta años en el mismo día salieron todos los ejércitos de Jehová de la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Esta es noche de guardar a Jehová, por haberlos sacado en ella de la tierra de Egipto. Esta noche deben guardar a Jehová todos los hijos de Israel por sus edades.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Y Jehová dijo a Moisés y a Aarón: Esta será la ordenanza de la pascua. Ningún extraño comerá de ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Y todo siervo humano comprado por dinero, comerá de ella después que le hubieres circuncidado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'El extranjero, y el salariado no comerán de ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'En una casa se comerá, y no llevarás de aquella carne fuera de casa, ni quebraréis hueso en él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Toda la congregación de Israel le sacrificará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Mas si algún extranjero peregrinare contigo, y quisiere hacer la pascua a Jehová, séale circuncidado todo varón, y entonces se llegará a hacerla, y será como el natural de la tierra, y ningún incircunciso comerá de ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'La misma ley será para el natural y para el extranjero que peregrinare entre vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Y todos los hijos de Israel hicieron como Jehová lo mandó a Moisés y a Aarón, así lo hicieron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Y en aquel mismo día Jehová sacó a los hijos de Israel de la tierra de Egipto por sus escuadrones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Y Jehová habló a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Santifícame todo primogénito, la abertura de toda matriz en los hijos de Israel así de los hombres como de las bestias: porque mío es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Y Moisés dijo al pueblo: Tenéd memoria de aqueste día, en el cual habéis salido de Egipto, de la casa de servidumbre, como Jehová os ha sacado de aquí con mano fuerte, por tanto no comeréis leudado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Vosotros salís hoy en el mes de Abib.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Y cuando Jehová te hubiere metido en la tierra del Cananeo, y del Jetteo, y del Amorreo, y del Heveo, y del Jebuseo, la cual juró a tus padres, que te daría, tierra que corre leche y miel, harás este servicio en aqueste mes:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Siete días comerás por leudar; y el séptimo día será fiesta a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Por los siete días se comerán los panes sin levadura; y no será visto en ti ni leudado ni levadura en todo tu término.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Y contarás en aquel día a tu hijo, diciendo: Por esto que Jehová hizo conmigo cuando me sacó de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Y serte ha como una señal sobre tu mano, y como un memorial delante de tus ojos, para que la ley de Jehová esté en tu boca; por cuanto con mano fuerte te sacó Jehová de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Por tanto tú guardarás este rito en su tiempo de año en año.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, '¶ Y cuando Jehová te hubiere metido en la tierra del Cananeo, como te ha jurado a ti y a tus padres, y cuando te la hubiere dado:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Harás pasar a Jehová todo lo que abriere la matriz: y todo primogénito que abriere la matriz de tus animales, los machos serán de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Mas todo primogénito de asno redimirás con cordero: y si no lo redimieres, cortarle has la cabeza. Asimismo redimirás todo humano primogénito de tus hijos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Y cuando mañana te preguntare tu hijo, diciendo: ¿Qué es esto? Decirle has: Jehová nos sacó con mano fuerte de Egipto, de casa de servidumbre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Y endureciéndose Faraón para no dejarnos ir, Jehová mató en la tierra de Egipto a todo primogénito desde el primogénito humano hasta el primogénito de la bestia: y por esta causa yo sacrifico a Jehová todo primogénito macho, y redimo todo primogénito de mis hijos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Serte ha pues como una señal sobre tu mano, y por un memorial delante de tus ojos: que Jehová nos sacó de Egipto con mano fuerte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, '¶ Y como Faraón dejó ir al pueblo, Dios no los llevó por el camino de la tierra de los Filisteos, que estaba cerca, porque dijo Dios: Que quizá no se arrepienta el pueblo, cuando vieren la guerra, y se vuelvan a Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Mas hizo Dios al pueblo que rodease por el camino del desierto del mar Bermejo: y subieron los hijos de Israel de la tierra de Egipto armados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Tomó también consigo Moisés los huesos de José, el cual había juramentado a los hijos de Israel, diciendo: Visitando os visitará Dios, y haréis subir mis huesos de aquí con vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Y partidos de Socot asentaron campo en Etam a la entrada del desierto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Y Jehová iba delante de ellos de día en una columna de nube, para guiarlos por el camino: y de noche en una columna de fuego para alumbrarles, para que anduviesen de día y de noche.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Nunca se partió de delante del pueblo la columna de nube de día, ni de noche la columna de fuego.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Habla a los hijos de Israel, que den la vuelta, y asienten su campo delante de Pihahirot, entre Magdal y la mar hacia Baalzefón: delante de él asentaréis el campo junto a la mar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Porque Faraón dirá de los hijos de Israel: Encerrados están en la tierra, el desierto los ha encerrado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Y yo endureceré el corazón de Faraón para que los siga, y seré glorificado en Faraón y en todo su ejército, y sabrán los Egipcios, que yo soy Jehová. Y ellos lo hicieron así.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Y fue dado aviso al rey de Egipto como el pueblo se huía: y el corazón de Faraón y de sus siervos se volvió contra el pueblo, y dijeron: ¿Qué hemos hecho, que hemos dejado ir a Israel, que no nos sirva?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Y unció su carro, y tomó consigo su pueblo;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Y tomó seiscientos carros escogidos, y todos los carros de Egipto, y los capitanes sobre todos ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Y endureció Jehová el corazón de Faraón rey de Egipto, y siguió a los hijos de Israel; y los hijos de Israel habían ya salido con gran poder.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Y siguiéndolos los Egipcios, tomáronlos asentado el campo junto a la mar junto a Fihahirot delante de Baalzefón, toda la caballería y carros de Faraón, su gente de a caballo y todo su ejército.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, '¶ Y como Faraón llegó, los hijos de Israel alzaron sus ojos, y he aquí los Egipcios que venían tras ellos, y temieron en gran manera, y clamaron los hijos de Israel a Jehová:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Y dijeron a Moisés: ¿No había sepulcros en Egipto, que nos has sacado para que muramos en el desierto? ¿Por qué lo has hecho así con nosotros, que nos has sacado de Egipto?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, '¿No es esto lo que te hablábamos en Egipto, diciendo: Déjanos servir a los Egipcios? Que mejor nos fuera servir a los Egipcios, que morir nosotros en el desierto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Y Moisés dijo al pueblo: No tengáis miedo; estádos quedos, y ved la salud de Jehová, que él hará hoy con vosotros; porque los Egipcios, que hoy habéis visto, nunca más para siempre los veréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Jehová peleará por vosotros, y vosotros callaréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Entonces Jehová dijo a Moisés: ¿Por qué me das voces? Di a los hijos de Israel que marchen.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Y tú alza tu vara, y extiende tu mano sobre la mar, y pártela, y entren los hijos de Israel por medio de la mar en seco.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Y yo, he aquí, yo endurezco el corazón de los Egipcios, para que los sigan; y yo me glorificaré en Faraón, y en todo su ejército, y en sus carros, y en su caballería:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Y sabrán los Egipcios, que yo soy Jehová, cuando me glorificaré en Faraón, en sus carros y en su gente de a caballo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, '¶ Y el ángel de Dios, que iba delante del campo de Israel, se quitó, e iba en pos de ellos: y asimismo la columna de nube, que iba delante de ellos, se quitó, y se puso a sus espaldas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'E iba entre el campo de los Egipcios, y el campo de Israel, y había nube y tinieblas, y alumbraba la noche, y en toda aquella noche nunca llegaron los unos a los otros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Y extendió Moisés su mano sobre la mar, e hizo Jehová, que la mar se retirase por un gran viento oriental toda aquella noche, y tornó la mar en seco, y las aguas fueron partidas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Entonces los hijos de Israel entraron por medio de la mar en seco; teniendo las aguas como un muro a su diestra y a su siniestra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Y siguiéndolos los Egipcios, entraron tras ellos hasta el medio de la mar, toda la caballería de Faraón, sus carros, y su gente de a caballo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, '¶ Y aconteció a la vela de la mañana, que Jehová miró al campo de los Egipcios en la columna de fuego y nube, y alborotó el campo de los Egipcios;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Y quitóles las ruedas de sus carros, y trastornólos gravemente. Entonces los Egipcios dijeron: Huyamos de delante de Israel; porque Jehová pelea por ellos contra los Egipcios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Y Jehová dijo a Moisés: Extiende tu mano sobre la mar, para que las aguas se vuelvan sobre los Egipcios, sobre sus carros, y sobre su caballería.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Y Moisés extendió su mano sobre la mar, y la mar se volvió en su fuerza cuando amanecía, y los Egipcios iban hacia ella: y Jehová derribó a los Egipcios en medio de la mar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Y volvieron las aguas, y cubrieron los carros y la caballería; y todo el ejército de Faraón, que había entrado tras ellos en la mar: no quedó de ellos ni uno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Y los hijos de Israel fueron por medio de la mar en seco, teniendo las aguas por muro a su diestra y a su siniestra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Así salvó Jehová aquel día a Israel de mano de los Egipcios; e Israel vio a los Egipcios muertos a la orilla de la mar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Y vio Israel aquel grande hecho que Jehová hizo contra los Egipcios; y el pueblo temió a Jehová, y creyeron a Jehová, y a Moisés su siervo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Entonces cantó Moisés y los hijos de Israel esta canción a Jehová, y dijeron: Yo cantaré a Jehová, porque se ha magnificado grandemente, echando en la mar al caballo y al que subía en él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Jehová es mi fortaleza, y mi canción, el cual me es por salud: este es mi Dios, y a este adoraré: Dios de mi padre, y a este ensalzaré.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Jehová, varón de guerra: Jehová es su nombre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Los carros de Faraón, y a su ejército echó en la mar, y sus escogidos príncipes fueron hundidos en el mar Bermejo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Los abismos los cubrieron, como una piedra, descendieron a los profundos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Tu diestra, oh Jehová, ha sido magnificada en fortaleza; tu diestra, oh Jehová, ha quebrantado al enemigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Y con la multitud de tu grandeza has trastornado a los que se levantaron contra ti: enviaste tu furor, el cual los tragó como a hojarasca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Con el soplo de tus narices las aguas se amontonaron; paráronse las corrientes, como en un montón; los abismos se cuajaron en medio de la mar:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'El enemigo dijo: Perseguiré, prenderé, repartiré despojos, mi alma se henchirá de ellos: sacaré mi espada, destruirlos ha mi mano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Soplaste con tu viento, cubriólos la mar: hundiéronse como plomo en las vehementes aguas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, '¿Quién como tú, oh Jehová? ¿quién como tú, magnífico en santidad, terrible en loores, hacedor de maravillas?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'En extendiendo tu diestra, la tierra los tragó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Llevaste con tu misericordia a este pueblo, al cual salvaste; llevástele con tu fortaleza a la habitación de tu santuario.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Oiránlo los pueblos, y temblarán; dolor tomará a los moradores de Palestina.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Entonces los príncipes de Edom se turbarán, a los robustos de Moab temblor los tomará: desleirse han todos los moradores de Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Caiga sobre ellos temblor y espanto: a la grandeza de tu brazo enmudezcan como una piedra, hasta que haya pasado tu pueblo, oh Jehová, hasta que haya pasado este pueblo, que tú rescataste.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Tú los meterás y los plantarás en el monte de tu heredad, en el lugar de tu morada, que tú has aparejado, oh Jehová, en el santuario del Señor, que han afirmado tus manos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Jehová reinará por el siglo, y más adelante.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Porque Faraón entró cabalgando con sus carros y su gente de a caballo en la mar; y Jehová volvió a traer sobre ellos las aguas de la mar; mas los hijos de Israel fueron en seco por medio de la mar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Y María profetisa, hermana de Aarón, tomó el adufre en su mano; y todas las mujeres salieron en pos de ella con adufres y corros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Y María les respondía: Cantád a Jehová; porque se ha magnificado grandemente, echando en la mar al caballo, y al que subía en él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, '¶ E hizo Moisés que partiese Israel del mar Bermejo, y salieron al desierto del Sur, y anduvieron tres días por el desierto que no hallaron agua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Y llegaron a Mará, y no pudieron beber las aguas de Mará, porque eran amargas; y por eso le pusieron nombre Mará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, '¶ Entonces el pueblo murmuró contra Moisés, y dijo: ¿Qué hemos de beber?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Y Moisés clamó a Jehová, y Jehová le enseñó un árbol, el cual como metió dentro de las aguas, las aguas se endulzaron. Allí les dio estatutos y derechos; y allí los tentó,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Y dijo: Si oyendo oyeres la voz de Jehová tu Dios, e hicieres lo recto delante de sus ojos, y escuchares a sus mandamientos, y guardares todos sus estatutos, ninguna enfermedad de las que envié a los Egipcios, te enviaré a ti; porque yo soy Jehová tu sanador.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Y vinieron a Elim, donde había doce fuentes de aguas, y setenta palmas, y asentaron allí junto a las aguas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Y partiendo de Elim, toda la congregación de los hijos de Israel vino al desierto de Sin, que es entre Elim y Sinaí: a los quince días del segundo mes después que salieron de la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Y toda la congregación de los hijos de Israel murmuró contra Moisés y Aarón en el desierto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Y decíanles los hijos de Israel; ¡Oh, si hubiéramos muerto por mano de Jehová en la tierra de Egipto, cuando nos sentábamos a las ollas de las carnes, cuando comíamos pan a hartura! que nos habéis sacado a este desierto, para matar de hambre a toda esta multitud.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Y Jehová dijo a Moisés: He aquí, yo os lloveré del cielo pan; y el pueblo saldrá, y cogerá para cada un día; para que yo lo tiente, si anda en mi ley, o no.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Mas al sexto día aparejarán lo que han de meter, que será el doble de lo que solían coger cada día.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Entonces dijo Moisés y Aarón a todos los hijos de Israel: A la tarde sabréis que Jehová os ha sacado de la tierra de Egipto:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Y a la mañana veréis la gloria de Jehová, porque él ha oído vuestras murmuraciones contra Jehová: que nosotros ¿qué somos, para que vosotros murmuréis contra nosotros?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Y dijo Moisés: Jehová os dará a la tarde carne para comer, y a la mañana pan a hartura: porque Jehová ha oído vuestras murmuraciones, con que habéis murmurado contra él: que nosotros ¿qué somos? vuestras murmuraciones no son contra nosotros, sino contra Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Y dijo Moisés a Aarón: Di a toda la congregación de los hijos de Israel: Acercáos en la presencia de Jehová, que él ha oído vuestras murmuraciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, '¶ Y hablando Aarón a toda la congregación de los hijos de Israel, miraron hacia el desierto, y, he aquí, la gloria de Jehová que apareció en la nube.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Y Jehová habló a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Yo he oído las murmuraciones de los hijos de Israel: háblales, diciendo: Entre las dos tardes comeréis carne, y mañana os hartaréis de pan, y sabréis que yo soy Jehová vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, '¶ Y como se hizo tarde, subieron codornices, que cubrieron el real: y a la mañana descendió rocío al rededor del real.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Y como el rocío cesó de descender, he aquí, sobre la haz del desierto una cosa menuda, redonda, menuda como una helada sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Y viéndolo los hijos de Israel, dijeron cada uno a su compañero: Este es man: porque no sabían que era. Entonces Moisés les dijo: Este es el pan, que Jehová os da para comer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Esto es lo que Jehová ha mandado: Cogeréis de él cada uno según pudiere comer: un gomer por cabeza conforme al número de vuestras personas: tomaréis cada uno para los que están en su tienda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Y los hijos de Israel lo hicieron así, que cogieron, unos más, otros menos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Y después medíanlo por gomer, y no sobraba al que había cogido mucho, ni faltaba al que había cogido poco: cada uno cogió conforme a lo que había de comer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Y díjoles Moisés: Ninguno deje nada de ello para mañana.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Mas ellos no obedecieron a Moisés; y algunos dejaron de ello para otro día, y crió gusanos, y pudrióse; y enojóse contra ellos Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Y cogíanlo cada mañana cada uno según lo que había de comer: y como el sol calentaba, derretíase.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'En el sexto día cogieron doblada comida, dos gomeres para cada uno: y todos los príncipes de la congregación vinieron a Moisés, e hiciéronselo saber.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Y él les dijo: Esto es lo que ha dicho Jehová: Mañana es el santo sábado del reposo de Jehová, lo que hubiereis de cocer, cocédlo: y lo que hubiereis de cocinar, cocinádlo: y todo lo que os sobrare, ponédlo en guarda para mañana.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Y ellos lo guardaron hasta la mañana, de la manera que Moisés había mandado, y no se pudrió, ni hubo en él gusano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Y dijo Moisés: Comédlo hoy, porque hoy es sábado de Jehová: hoy no lo hallaréis en el campo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'En los seis días lo cogeréis; y el séptimo día es sábado, en el cual no se hallará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Y aconteció que algunos del pueblosalieron en el séptimo día a coger, y no hallaron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Y Jehová dijo a Moisés; ¿Hasta cuando no queréis guardar mis mandamientos, y mis leyes?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Mirád que Jehová os dio el sábado, y por eso os da en el sexto día pan para dos días. Estése pues cada uno en su estancia, y nadie salga de su lugar en el séptimo día.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Así el pueblo reposó el séptimo día.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Y la casa de Israel la llamó man; y era como simiente de cilantro, blanco, y su sabor como de hojuelas con miel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Y dijo Moisés: Esto es lo que Jehová ha mandado: Henchirás un gomer de él para que se guarde para vuestros descendientes, que vean el pan que yo os di a comer en el desierto, cuando yo os saqué de la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Y dijo Moisés a Aarón: Toma un vaso, y pon en él un gomer lleno de man, y pónlo delante de Jehová, para que sea guardado para vuestros descendientes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Y Aarón lo puso delante del testimonio en guarda, como Jehová lo mandó a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Así comieron los hijos de Israel man cuarenta años, hasta que entraron en la tierra habitada: man comieron hasta que llegaron al término de la tierra de Canaán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Y un gomer es la décima parte del efa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Y toda la compañía de los hijos de Israel partió del desierto de Sin por sus jornadas, al mandamiento de Jehová, y asentaron el campo en Rafidim, y no había agua para que el pueblo bebiese.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Y riñó el pueblo con Moisés, y dijeron: Dádnos agua, que bebamos. Y Moisés les dijo: ¿Por qué reñis conmigo? ¿Por qué tentáis a Jehová?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Así que el pueblo tuvo allí sed de agua, y murmuró contra Moisés, y dijo: ¿Por qué nos hiciste subir de Egipto, para matarnos de sed a nosotros y a nuestros hijos, y a nuestros ganados?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, '¶ Entonces Moisés clamó a Jehová diciendo: ¿Qué haré con este pueblo? De aquí a un poco me apedrearán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Y Jehová dijo a Moisés: Pasa delante del pueblo; y toma contigo de los ancianos de Israel, y toma también en tu mano tu vara, con que heriste el río, y vé:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'He aquí que yo estoy delante de ti allí sobre la peña en Horeb: y herirás la peña, y saldrán de ella aguas, y beberá el pueblo. Y Moisés lo hizo así en presencia de los ancianos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Y llamó el nombre de aquel lugar, Massa y Meriba, por la rencilla de los hijos de Israel; y porque tentaron a Jehová, diciendo: ¿Si está Jehová entre nosotros, o no?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, '¶ Y vino Amalec, y peleó con Israel en Rafidim.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Y dijo Moisés a Josué: Escógenos varones, y sal, pelea con Amalec: mañana yo estaré sobre la cumbre del collado, y la vara de Dios en mi mano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'E hizo Josué como le dijo Moisés, peleando con Amalec: y Moisés, y Aarón, y Jur subieron a la cumbre del collado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Y era que como alzaba Moisés su mano, Israel prevalecía; mas como él abajaba su mano, prevalecía Amalec.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Y las manos de Moisés eran pesadas, y tomaron una piedra, y pusiéronla debajo de él, y él se sentó sobre ella; y Aarón y Jur sustentaban sus manos, el uno de una parte y el otro de otra, y hubo en sus manos firmeza hasta que se puso el sol.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Y Josué deshizo a Amalec y a su pueblo a filo de espada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, '¶ Y Jehová dijo a Moisés: Escribe esto por memoria en el libro, y pon en oídos de Josué; que rayendo raeré del todo la memoria de Amalec de debajo del cielo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Y Moisés edificó altar, y llamó su nombre Jehová-nissi:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Y dijo: Porque la mano sobre el trono de Jehová, que Jehová tendrá guerra con Amalec, de generación en generación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Y oyó Jetro sacerdote de Madián, suegro de Moisés, todas las cosas que Dios había hecho con Moisés, y con Israel su pueblo, como Jehová había sacado a Israel de Egipto:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Y tomó Jetro, suegro de Moisés, a Séfora la mujer de Moisés, después que él la envió:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'Y a sus dos hijos, el uno se llamaba Gersom; porque dijo: Peregrino he sido en tierra ajena;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'Y el otro se llamaba Eliezer, porque dijo: El Dios de mi padre me ayudó; y me escapó de la espada de Faraón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Y llegó Jetro, el suegro de Moisés, y sus hijos, y su mujer, a Moisés en el desierto, donde tenía el campo, al monte de Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Y dijo a Moisés: Yo tu suegro Jetro vengo a ti, y tu mujer, y sus dos hijos con ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Y Moisés salió a recibir a su suegro, e inclinóse, y besóle: y preguntáronse el uno al otro como estaban; y vinieron a la tienda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Y Moisés contó a su suegro todas las cosas que Jehová había hecho a Faraón y a los Egipcios por causa de Israel; y todo el trabajo que habían pasado en el camino, y como los había librado Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Y alegróse Jetro de todo el bien, que Jehová había hecho a Israel, que le había escapado de mano de los Egipcios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Y Jetro dijo: Bendito sea Jehová, que os escapó de mano de los Egipcios, y de la mano de Faraón, que escapó al pueblo de la mano de los Egipcios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Ahora conozco que Jehová es grande más que todos los dioses; porque en lo que se ensoberbecieron contra ellos, los castigó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Y tomó Jetro, el suegro de Moisés, holocausto y sacrificios para Dios: y vino Aarón, y todos los ancianos de Israel a comer pan con el suegro de Moisés delante de Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, '¶ Y aconteció, que otro día Moisés se asentó a juzgar al pueblo; y el pueblo estuvo sobre Moisés desde la mañana hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Y viendo el suegro de Moisés todo lo que él hacía con el pueblo, dijo: ¿Qué es esto que haces tú con el pueblo? ¿Por qué te sientas tú solo, y todo el pueblo está sobre ti desde la mañana hasta la tarde?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Y Moisés respondió a su suegro: Porque el pueblo viene a mí para consultar a Dios:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Cuando tienen negocios, y vienen a mí, y yo juzgo entre el uno y el otro, y declaro las ordenanzas de Dios, y sus leyes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Entonces el suegro de Moisés le dijo: No haces bien:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Desfallecerás del todo tú y también este pueblo que está contigo; porque el negocio es más pesado que tú; no podrás hacerlo tú solo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Oye ahora mi voz, yo te aconsejaré, y Dios será contigo. Está tú por el pueblo delante de Dios, y trata tú los negocios con Dios:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Y enséñales las ordenanzas y las leyes, y muéstrales el camino por donde anden, y lo que han de hacer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Y tú proveerás de todo el pueblo varones de virtud, temerosos de Dios, varones de verdad, que aborrezcan la avaricia; y pondrás sobre ellos príncipes sobre mil, sobre ciento, sobre cincuenta, y sobre diez:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Los cuales juzgarán al pueblo en todo tiempo: y será, que todo negocio grave te traerán a ti, y todo negocio pequeño juzgarán ellos; y alivia la carga de sobre ti, y llevarla han contigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Si esto hicieres, y lo que Dios te mandare, tú podrás estar, y todo este pueblo también se irá en paz a su lugar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Entonces Moisés oyó la voz de su suegro, e hizo todo lo que él dijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Y escogió Moisés varones de virtud de todo Israel, y púsolos por cabezas sobre el pueblo, príncipes sobre mil, sobre ciento, sobre cincuenta, y sobre diez;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Los cuales juzgaban al pueblo en todo tiempo: el negocio arduo traíanlo a Moisés, y todo negocio pequeño juzgaban ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Y despidió Moisés a su suegro, y fuése a su tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Al tercero mes de la salida de los hijos de Israel de la tierra de Egipto, en aquel día vinieron al desierto de Sinaí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Y partieron de Rafidim, y vinieron al desierto de Sinaí, y asentaron en el desierto, y asentó allí Israel delante del monte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Y Moisés subió a Dios: y Jehová le llamó desde el monte, diciendo: Así dirás a la casa de Jacob, y denunciarás a los hijos de Israel:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Vosotros visteis lo que hice a los Egipcios, y como os tomé sobre alas de águilas, y os he traído a mí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Ahora pues si oyendo oyereis mi voz, y guardareis mi concierto, vosotros seréis mi tesoro sobre todos los pueblos; porque mía es toda la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Y vosotros seréis mi reino de sacerdotes y gente santa. Estas son las palabras que dirás a los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Entonces vino Moisés, y llamó a los ancianos del pueblo, y propuso en presencia de ellos todas estas palabras, que Jehová le había mandado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Y todo el pueblo respondió a una, y dijeron: Todo lo que Jehová ha dicho, haremos. Y Moisés relató las palabras del pueblo a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Y Jehová dijo a Moisés: He aquí, yo vengo a ti en una nube espesa, para que el pueblo oiga mientras yo hablo contigo, y también para que te crean para siempre. Y Moisés denunció las palabras del pueblo a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, '¶ Y Jehová dijo a Moisés: Vé al pueblo, y santifícalos hoy y mañana, y laven sus vestidos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Y estén apercebidos para el tercero día; porque al tercero día Jehová descenderá a ojos de todo el pueblo sobre el monte de Sinaí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Y señalarás término al pueblo al rededor, diciendo: Guardáos, no subáis al monte, ni toquéis a su término: cualquiera que tocare el monte, que muera de muerte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'No le tocará mano, mas será apedreado, o asaeteado: sea animal, o sea hombre, no vivirá. En habiendo sonado luengamente el cuerno, subirán al monte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Y descendió Moisés del monte al pueblo, y santificó al pueblo, y lavaron sus vestidos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Y dijo al pueblo: Estád apercebidos para el tercero día: no lleguéis a mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, '¶ Y aconteció al tercero día cuando vino la mañana, que vinieron truenos y relámpagos, y grave nube sobre el monte; y un sonido de bocina muy fuerte: y estremecióse todo el pueblo que estaba en el real.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Y Moisés sacó del real al pueblo a recibir a Dios, y pusiéronse a lo bajo del monte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Y todo el monte de Sinaí humeaba, porque Jehová había descendido sobre él en fuego: y el humo de él subía, como el humo de un horno, y todo el monte se estremeció en gran manera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Y el sonido de la bocina iba esforzándose en gran manera: Moisés hablaba, y Dios le respondía en voz.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Y descendió Jehová sobre el monte de Sinaí, sobre la cumbre del monte, y llamó Jehová a Moisés a la cumbre del monte: Y Moisés subió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Y Jehová dijo a Moisés: Desciende, requiere al pueblo, que no derriben el término por ver a Jehová; que caerá multitud de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Y también los sacerdotes que se llegan a Jehová, se santifiquen, porque Jehová no haga en ellos portillo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Y Moisés dijo a Jehová: El pueblo no podrá subir al monte de Sinaí; porque tú nos has requerido, diciendo: Señala términos al monte, y santifícalo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Y Jehová le dijo: Vé, desciende, y subirás tú y Aarón contigo: mas los sacerdotes y el pueblo no derriben el término por subir a Jehová, porque no haga en ellos portillo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Entonces Moisés descendió al pueblo, y habló con ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Y habló Dios todas estas palabras, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Yo soy Jehová tu Dios, que te saqué de la tierra de Egipto, de casa de siervos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'No tendrás dioses ajenos delante de mí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'No te harás imagen, ni ninguna semejanza de cosa que esté arriba en el cielo, ni abajo en la tierra, ni en las aguas debajo de la tierra:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'No te inclinarás a ellas, ni las honrarás: porque yo soy Jehová tu Dios, fuerte, zeloso, que visito la maldad de los padres sobre los hijos, sobre los terceros y sobre los cuartos, a los que me aborrecen;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'Y que hago misericordia en millares a los que me aman, y guardan mis mandamientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'No tomarás el nombre de Jehová tu Dios en vano; porque no dará por inocente Jehová al que tomare su nombre en vano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Acordarte has del día del sábado, para santificarlo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Seis días trabajarás, y harás toda tu obra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Mas el séptimo día será sábado a Jehová tu Dios: no hagas obra ninguna, tú; ni tu hijo, ni tu hija; ni tu siervo, ni tu criada; ni tu bestia, ni tu extranjero, que está dentro de tus puertas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Porque en seis días hizo Jehová los cielos y la tierra, la mar y todas las cosas que en ellos hay; y en el día séptimo reposó: por tanto Jehová bendijo al día del sábado, y lo santificó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Honra a tu padre y a tu madre, porque tus días se alarguen sobre la tierra, que Jehová tu Dios te da.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'No matarás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'No cometerás adulterio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'No hurtarás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'No hablarás contra tu prójimo falso testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'No codiciarás la casa de tu prójimo, no codiciarás la mujer de tu prójimo, ni su siervo, ni su criada, ni su buey, ni su asno, ni cosa alguna de tu prójimo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, '¶ Todo el pueblo oía las voces, y el sonido de la bocina y veía las llamas, y el monte que humeaba: Y viéndolo el pueblo temblaron, y pusiéronse de lejos,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Y dijeron a Moisés: Habla tú con nosotros, que nosotros oiremos: y no hable Dios con nosotros, porque no muramos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Entonces Moisés respondió al pueblo: No temáis; que por tentaros vino Dios, y porque su temor esté en vuestra presencia, para que no pequéis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Entonces el pueblo se puso de lejos, y Moisés se llegó a la oscuridad, en la cual estaba Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, '¶ Y Jehová dijo a Moisés: Así dirás a los hijos de Israel: Vosotros habéis visto, que he hablado desde el cielo con vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'No hagáis conmigo dioses de plata, ni dioses de oro os haréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Altar de tierra harás para mí, y sacrificarás sobre él tus holocaustos, y tus pacíficos, tus ovejas, y tus vacas: en cualquier lugar donde yo hiciere que esté la memoria de mi nombre, vendré a ti, y te bendeciré.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Y si me hicieres altar de piedras, no las labres de cantería; porque si alzares tu pico sobre él, tú lo ensuciarás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Y no subirás por gradas a mi altar, porque tu desnudez no sea descubierta junto a él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Y estos son los derechos que les propondrás:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Si comprares siervo Hebreo, seis años servirá; mas al séptimo saldrá horro de balde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Si entró solo, solo saldrá: si era marido de mujer, saldrá él y su mujer con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Si su amo le hubiere dado mujer, y ella le hubiere parido hijos o hijas, la mujer y sus hijos serán de su amo, mas él saldrá solo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Y si el siervo dijere: Yo amo a mi señor, a mi mujer, y a mis hijos, no saldré horro:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Entonces su amo lo hará llegar a los jueces, y hacerlo ha llegar a la puerta, o al poste; y su amo le horadará la oreja con una lesna, y será su siervo para siempre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Y cuando alguno vendiere su hija por sierva, no saldrá como suelen salir los siervos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Si no agradare a su señor, por lo cual no la tomó por esposa, permitirle ha que se rescate; y no la podrá vender a pueblo extraño cuando la desechare.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Mas si la hubiere desposado con su hijo, hará con ella según la costumbre de las hijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Si le tomare otra, no disminuirá su alimento, ni su vestido, ni su tiempo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Y si ninguna de estas tres cosas hiciere, ella saldrá de gracia sin dinero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, '¶ El que hiriere a alguno, y muriere, él morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Mas el que no asechó, sino que Dios lo puso en sus manos, entonces yo te pondré lugar al cual huirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Ítem, si alguno se ensoberbeciere contra su prójimo, y le matare por engaño, de mi altar le quitarás para que muera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Ítem, el que hiriere a su padre, o a su madre, morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, '¶ Ítem, el que hurtare alguno, y le vendiere, y fuere hallado en sus manos, morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, '¶ Ítem, el que maldijere a su padre, o a su madre, morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Ítem, si algunos riñeren, y alguno hiriere a su prójimo con piedra o con el puño, y no muriere, mas cayere en cama;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'Si se levantare y anduviere fuera sobre su bordón, entonces el que le hirió, será absuelto; solamente le dará lo que holgó, y hacerle ha curar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Ítem, si alguno hiriere a su siervo o a su sierva, con palo, y muriere debajo de su mano, será castigado:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Mas si durare por un día o dos, no será castigado, porque su dinero es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Ítem, si algunos riñeren, e hirieren a alguna mujer preñada, y salieren sus criaturas, mas no hubiere muerte, será penado conforme a lo que impusiere el marido de la mujer, y pagará por jueces.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Mas si hubiere muerte, entonces pagarás alma por alma.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Ojo por ojo, diente por diente, mano por mano, pie por pie,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Quemadura por quemadura, herida por herida, golpe por golpe,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Ítem, cuando alguno hiriere el ojo de su siervo, o el ojo de su sierva, y le dañare, por su ojo le ahorrará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Y si sacare el diente de su siervo, o el diente de su sierva, por su diente le ahorrará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, '¶ Ítem, si algún buey acorneare hombre o mujer, y muriere, el buey será apedreado, y su carne no será comida, mas el dueño del buey será absuelto:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Mas si el buey era acorneador desde ayer y anteayer, y a su dueño le fue hecho requerimiento, y no lo hubiere guardado, y matare hombre o mujer, el buey será apedreado, y también su dueño morirá:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Si le fuere impuesto rescate, entonces dará por el rescate de su persona cuanto le fuere impuesto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Haya acorneado hijo, o haya acorneado hija, conforme a este juicio se hará con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Si el buey acorneare siervo, o sierva, pagará treinta siclos de plata a su señor, y el buey será apedreado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, '¶ Ítem, si alguno abriere alguna cisterna, o cavare cisterna, y no la cubriere, y cayere allí buey o asno,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'El dueño de la cisterna pagará el dinero restituyendo a su dueño; y lo que fue muerto será suyo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, '¶ Ítem, si el buey de alguno hiriere al buey de su prójimo, y muriere, entonces venderán el buey vivo, y partirán el dinero de él; y el muerto también partirán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Mas si era notorio que el buey era acorneador de ayer y anteayer, y su dueño no lo hubiere guardado, pagará buey por buey, y el muerto será suyo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Cuando alguno hurtare buey, u oveja, y lo degollare, o vendiere, por aquel buey pagará cinco bueyes, y por aquella oveja cuatro ovejas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Si el ladrón fuere hallado en la mina, y fuere herido, y muriere, el que le hirió no será culpado de su muerte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Si el sol hubiere salido sobre él, él será reo de muerte, pagando pagará: si no tuviere, será vendido por su hurto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Si fuere hallado con el hurto en la mano, buey, o asno, u oveja, vivos, pagará dos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Si alguno paciere tierra o viña, y metiere su bestia, y comiere la tierra de otro, lo mejor de su tierra y lo mejor de su viña pagará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Cuando saliere el fuego, y hallare espinas, y fuere quemado montón, o haza, o tierra, el que encendió el fuego pagará lo quemado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, '¶ Cuando alguno diere a su prójimo plata, o vasos a guardar, y fuere hurtado de la casa de aquel hombre, si el ladrón se hallare, pagará el doble:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Si el ladrón no se hallare, entonces el dueño de la casa será llegado a los jueces para jurar si ha metido su mano en la hacienda de su prójimo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Sobre todo negocio de fraude, sobre buey, sobre asno, sobre oveja, sobre vestido, sobre toda cosa perdida, cuando alguno dijere: Que esto es; la causa de ambos vendrá delante de los jueces, y el que los jueces condenaren, pagará el doble a su prójimo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Si alguno hubiere dado a su prójimo asno, o buey, u oveja, o cualquiera otro animal a guardar, y se muriere, o se perniquebrare, o fuere cautivado sin verlo nadie:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Juramento de Jehová será entre ambos, que no metió su mano en la hacienda de su prójimo. Y su dueño se contentará, y el otro no pagará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Mas si le hubiere sido hurtado, pagar lo ha a su dueño.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Mas si le hubiere sido arrebatado, traerle ha testimonio, y no pagará lo arrebatado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, '¶ Ítem, cuando alguno hubiere tomado emprestado de su prójimo, y fuere perniquebrado o muerto, ausente su dueño, pagará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Si su dueño estaba presente, no pagará. Si era de alquiler, el vendrá por su alquile.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, '¶ Ítem, cuando alguno engañare a alguna virgen que no fuere desposada, y durmiere con ella, dotarla ha por su mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Si su padre no quisiere dársela, él le pesará plata conforme al dote de las vírgenes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, '¶ A la hechicera no darás la vida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, '¶ Cualquiera que tuviere ayuntamiento con bestia, morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, '¶ El que sacrificare a dioses, sino a solo Jehová, morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, '¶ Y al extranjero no engañaras, ni angustiarás, porque extranjeros fuisteis vosotros en la tierra de Egipto,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'A ninguna viuda ni huérfano afligiréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Que si tú afligiendo los afligieres, y ellos clamando clamaren a mí, yo oyendo oiré su clamor;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Y mi furor se encenderá, y mataros he a cuchillo, y vuestras mujeres serán viudas, y vuestros hijos huérfanos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, '¶ Si dieres a mi pueblo dinero emprestado, al pobre que está contigo, no te habrás con él como usurero, no le impondréis usura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Si tomares en prenda el vestido de tu prójimo, a puesta del sol se lo volverás:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Porque solo aquello es su cobertura, aquel es el vestido de sus carnes en que ha de dormir: y será, que cuando él clamare a mí, yo entonces lo oiré, porque soy misericordioso.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, '¶ A los dioses no injuriarás, ni maldecirás al príncipe en tu pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, '¶ Tu plenitud, ni tu lágrima, no dilatarás, el primogénito de tus hijos me darás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Así harás de tu buey, de tu oveja: siete días estará con su madre, y al octavo día me lo darás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, '¶ Y serme heis varones santos: y carne arrebatada en el campo no comeréis, echarla heis al perro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'No admitirás falso rumor. No pongas tu mano con el impío para ser testigo falso.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, '¶ No seguirás a los muchos para mal hacer, ni responderás en pleito acostándote tras los muchos para hacer tuerto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Ni al pobre honrarás en su causa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, '¶ Si encontrares el buey de tu enemigo, o su asno errado, volviendo se lo volverás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Si vieres el asno del que te aborrece echado debajo de su carga, ¿dejarlo has entonces desamparado? ayudando ayudarás con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'No pervertirás el derecho de tu mendigo en su pleito.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'De palabra de mentira te alejarás; y no matarás al inocente y justo; porque yo no justificaré al impío.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'No recibirás presente; porque el presente ciega a los que ven, y pervierte las palabras justas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, '¶ Ítem, al extranjero no angustiarás; pues que vosotros sabéis el alma del extranjero, que fuisteis extranjeros en la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, '¶ Seis años sembrarás tu tierra, y allegarás su cosecha:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Mas al séptimo la dejarás y soltarás, para que coman los pobres de tu pueblo; y lo que quedare comerán las bestias del campo: así harás de tu viña y de tu olivar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, '¶ Seis días harás tus negocios; y al séptimo día holgarás, porque huelgue tu buey, y tu asno; y tome refrigerio el hijo de tu sierva, y el extranjero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, '¶ Y en todo lo que os he dicho, seréis avisados. Y nombre de otros dioses no mentaréis, ni se oirá en vuestra boca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, '¶ Tres veces en el año me celebraréis fiesta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'La fiesta de las cenceñas guardarás: siete días comerás los panes sin levadura, de la manera que yo te mandé, en el tiempo del mes de Abib, porque en él saliste de Egipto, y no serán vistas mis faces en vacío.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Ítem, la fiesta de la segada de los primeros frutos de tus trabajos que hubieres sembrado en el campo. Y la fiesta de la cosecha a la salida del año, cuando cogieres tus trabajos del campo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Tres veces en el año parecerá todo varón tuyo delante del Señor Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, '¶ No sacrificarás sobre pan leudo la sangre de mi sacrificio, ni el sebo de mi cordero quedará de la noche hasta la mañana.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, '¶ Las primicias de los primeros frutos de tu tierra traerás a la casa de Jehová tu Dios. No guisarás el cabrito con la leche de su madre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, '¶ He aquí, yo envío el ángel delante de ti, para que te guarde en el camino, y te meta al lugar que yo he aparejado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Guárdate delante de él, y oye su voz, no le seas rebelde, porque él no perdonará a vuestra rebelión; porque mi nombre está en medio de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Porque si oyendo oyeres su voz, e hicieres todo lo que yo te dijere, seré enemigo a tus enemigos, y afligiré a los que te afligieren.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Porque mi ángel irá delante de ti, y te meterá al Amorreo, y al Jetteo, y al Ferezeo, y al Cananeo, y al Heveo, y al Jebuseo, los cuales yo haré cortar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'No te inclinarás a sus dioses, ni los servirás, ni harás como ellos hacen, antes los destruirás del todo, y quebrantarás del todo sus estatuas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Mas a Jehová vuestro Dios serviréis, y él bendecirá tu pan, y tus aguas, y yo quitaré enfermedad de en medio de ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'No habrá amovedera ni estéril en tu tierra, y yo cumpliré el número de tus días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Yo enviaré mi terror delante de ti, y haré atónito a todo pueblo donde tú entrares; y te daré la cerviz de todos tus enemigos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Y yo enviaré la avispa delante de ti, que eche fuera al Heveo, y al Cananeo, y al Jetteo, de delante de ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, '¶ No lo echaré de delante de ti en un año, porque no se asuele la tierra, y se aumenten contra ti las bestias del campo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Poco a poco lo echaré de delante de ti, hasta que tú multipliques, y tomes la tierra por heredad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Y yo pondré tu término desde el mar Bermejo hasta la mar de Palestina: y desde el desierto, hasta el río; porque yo pondré en vuestras manos los moradores de la tierra, y tú los echarás de delante de ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'No harás alianza con ellos, ni con sus dioses.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'En tu tierra no habitarán, porque quizá no te hagan pecar contra mí, sirviendo a sus dioses: porque te será por tropezón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Y a Moisés dijo: Sube a Jehová, tú y Aarón, Nadab y Abiú, y setenta de los ancianos de Israel, e inclinaros heis desde lejos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Mas Moisés solo se llegará a Jehová, y ellos no se lleguen cerca; ni suba con él el pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Y Moisés vino, y contó al pueblo todas las palabras de Jehová, y todos los derechos; y todo el pueblo respondió a una voz, y dijeron: Todas las palabras que Jehová ha dicho, haremos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Y Moisés escribió todas las palabras de Jehová: y levantándose por la mañana edificó un altar al pie del monte, y doce títulos según las doce tribus de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Y envió a los mancebos de los hijos de Israel, los cuales ofrecieron holocaustos, y sacrificaron pacíficos a Jehová, becerros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Y Moisés tomó la mitad de la sangre, y púsola en tazones: y la otra mitad de la sangre esparció sobre el altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Y tomó el libro de la alianza, y leyó a oídos del pueblo, los cuales dijeron: Todas las cosas que Jehová ha dicho, haremos, y obedeceremos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Entonces Moisés tomó la sangre, y rocío sobre el pueblo, y dijo: He aquí la sangre de la alianza, que Jehová ha hecho con vosotros sobre todas estas cosas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, '¶ Y subieron Moisés, y Aarón, Nadab, y Abiú, y setenta de los ancianos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Y vieron al Dios de Israel; y había debajo de sus pies como la hechura de un ladrillo de zafiro, y como el ser del cielo sereno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Mas no extendió su mano sobre los príncipes de los hijos de Israel; y vieron a Dios, y comieron y bebieron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Entonces Jehová dijo a Moisés: Sube a mí al monte, y espera allá; y yo te daré unas tablas de piedra, y la ley y mandamientos que yo he escrito para enseñarlos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Y levantóse Moisés, y Josué su ministro; y Moisés subió al monte de Dios;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Y dijo a los ancianos: Esperádnos aquí hasta que volvamos a vosotros: y he aquí, Aarón y Jur están con vosotros: el que tuviere negocios, lleguese a ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Entonces Moisés subió al monte, y una nube cubrió el monte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Y la gloria de Jehová reposó sobre el monte de Sinaí, y la nube lo cubrió por seis días: y al séptimo día llamó a Moisés de en medio de la nube.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Y el parecer de la gloria de Jehová era como un fuego quemante en la cumbre del monte, a ojos de los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Y entró Moisés en medio de la nube, y subió al monte: y estuvo Moisés en el monte cuarenta días, y cuarenta noches.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Y Jehová habló a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Habla a los hijos de Israel que tomen para mi ofrenda: de todo varón, cuyo corazón la diere de su voluntad, tomaréis mi ofrenda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Y esta será la ofrenda que tomaréis de ellos: Oro, y plata, y cobre;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'Y cárdeno, y púrpura, y carmesí, y lino fino, y pelos de cabras;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'Y cueros de carneros teñidos de rojo, y cueros de tejones, y madera de cedro;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Aceite para la luminaria, especias para el aceite de la unción y para el sahumerio aromático;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Piedras oniquinas, y piedras de engastes para el efod, y para el pectoral.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Y hacerme han santuario, y yo habitaré entre ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Conforme a todo lo que yo te mostraré, es a saber, la semejanza del tabernáculo, y la semejanza de todos sus vasos; así haréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, '¶ Harán también un arca de madera de cedro; la longura de ella será de dos codos y medio; y su anchura de codo y medio; y su altura de codo y medio:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Y cubrirla has de oro puro, de dentro y de fuera la cubrirás: y harás sobre ella una corona de oro al derredor:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Y para ella harás de fundición cuatro sortijas de oro, que pongas a sus cuatro esquinas; las dos sortijas al un lado de ella, y las otras dos sortijas al otro lado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Y harás unas barras de madera de cedro, las cuales cubrirás de oro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Y meterás las barras por las sortijas a los lados del arca, para llevar el arca con ellas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Las barras se estarán en las sortijas del arca; no se quitarán de ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Y pondrás en el arca el testimonio que yo te daré.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, '¶ Y harás una cubierta de oro fino: la longura de ella será de dos codos y medio, y su anchura de codo y medio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Harás también dos querubines de oro, hacerlo has de martillo, a los dos cabos de la cubierta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Y harás el un querubín al un cabo de la una parte, y el otro querubín al otro cabo de la otra parte de la cubierta, harás los querubines a sus dos cabos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Y los querubines extenderán por encima las alas, cubriendo con sus alas la cubierta, las faces de ellos, la una en frente de la otra, mirando a la cubierta las faces de los querubines.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Y pondrás la cubierta sobre el arca, encima, y en el arca pondrás el testimonio, que yo te daré.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Y de allí me testificaré a ti, y hablaré contigo de sobre la cubierta, de entre los dos querubines que estarán sobre el arca del testimonio, todo lo que yo te mandaré para los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, '¶ Harás asimismo una mesa de madera de cedro: su longura será de dos codos, y de un codo su anchura; y su altura de codo y medio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Y cubrirla has de oro puro, y hacerle has una corona de oro al rededor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Hacerle has también una moldura al derredor de anchura de una mano, a la cual moldura harás una corona de oro al rededor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Y hacerle has cuatro sortijas de oro, las cuales pondrás a las cuatro esquinas que estarán a sus cuatro pies.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Las sortijas estarán delante de la moldura por lugares para las barras, para llevar la mesa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Y harás las barras de madera de cedro, y cubrirlas has de oro, y con ellas será llevada la mesa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Harás también sus platos y sus cucharones, y sus cubiertas, y sus tazones con que se cubrirá el pan: de oro fino las harás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Y pondrás sobre la mesa el pan de la proposición delante de mí continuamente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, '¶ Ítem, harás un candelero de oro puro; de martillo se hará el candelero: su pie, y su caña, sus copas, sus manzanas y sus flores, serán de lo mismo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Y saldrán seis cañas de sus lados; las tres cañas del candelero del un lado suyo; y las otras tres cañas del candelero del otro su lado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Tres copas almendradas en la una caña, una manzana y una flor; y tres copas almendradas en la otra caña, una manzana y una flor; y así en las seis cañas que salen del candelero:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Y en el candelero cuatro copas almendradas, sus manzanas, y sus flores.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Una manzana debajo de las dos cañas, de lo mismo; otra manzana debajo de las otras dos cañas, de lo mismo; otra manzana debajo de las otras dos cañas, de lo mismo, en las seis cañas que salen del candelero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Sus manzanas y sus cañas serán de lo mismo; todo ello de martillo de una pieza, de puro oro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Y hacerle has siete candilejas, las cuales encenderás para que alumbren a la parte de su delantera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Y sus despabiladeras y sus paletas de oro puro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'De un talento de oro fino lo harás, con todos estos vasos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, '¶ Y mira, y haz conforme a su semejanza, que te ha sido mostrada en el monte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Y el tabernáculo harás de diez cortinas de lino torcido, cárdeno, y púrpura, y carmesí: y harás querubines de obra de artífice.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'La longura de la una cortina de veinte y ocho codos; y la anchura de la misma cortina de cuatro codos: todas las cortinas tendrán una medida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Las cinco cortinas estarán juntas la una con la otra, y las otras cinco cortinas juntas la una con la otra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Y harás lazadas de cárdeno en la orilla de la una cortina, en el cabo, en la juntura: y así harás en la orilla de la postrera cortina en la juntura segunda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Cincuenta lazadas harás en la una cortina, y otras cincuenta lazadas harás en el cabo de la cortina que está en la segunda juntura: las lazadas estarán contrapuestas la una a la otra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Harás también cincuenta corchetes de oro con los cuales juntarás las cortinas la una con la otra, y hacerse ha un tabernáculo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Harás asimismo cortinas de pelos de cabras para una cubierta sobre el tabernáculo: once cortinas harás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'La longura de la una cortina será de treinta codos, y la anchura de la misma cortina de cuatro codos: una medida tendrán las once cortinas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Y juntarás por sí las cinco cortinas, y las seis cortinas por sí, y doblarás la sexta cortina delante de la faz de la tienda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Y harás cincuenta lazadas en la orilla de la una cortina, al cabo en la juntura, y otras cincuenta lazadas en la orilla de la segunda cortina en la otra juntura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Harás asimismo cincuenta corchetes de alambre, los cuales meterás por las lazadas, y juntarás la tienda, y será una.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Y la demasía que sobra en las cortinas de la tienda, es a saber, la mitad de la una cortina, que sobra, sobrará a las espaldas del tabernáculo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Y un codo de la una parte, y otro codo de la otra, que sobra en la longura de las cortinas de la tienda, sobrará sobre los lados del tabernáculo de la una parte y de la otra para cubrirlo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Harás también a la tienda un cobertor de cueros de carneros teñidos de rojo: y otro cobertor de cueros de tejones encima.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Y harás tablas para el tabernáculo de madera de cedro estantes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'La longura de cada tabla será de diez codos, y de codo y medio la anchura de la misma tabla.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Dos quicios tendrá cada tabla trabadas la una con la otra: así harás todas las tablas del tabernáculo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Y harás las tablas para el tabernáculo, veinte tablas al lado del mediodía, al austro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Y harás cuarenta basas de plata para debajo de las veinte tablas, dos basas debajo de la una tabla a sus dos quicios, y dos basas debajo de la otra tabla a sus dos quicios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Y al otro lado del tabernáculo a la parte del aquilón, veinte tablas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Y sus cuarenta basas de plata, dos basas debajo de la una tabla, y dos basas debajo de la otra tabla.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Y al lado del tabernáculo al occidente harás seis tablas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Y harás dos tablas para las esquinas del tabernáculo a los dos rincones:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Las cuales se juntarán por abajo, y asimismo se juntarán por su alto a una misma sortija, así será de las otras dos: estarán a las dos esquinas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Así que serán ocho tablas, con sus basas de plata, diez y seis basas; dos basas debajo de la una tabla, y dos basas debajo de la otra tabla.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Harás también cinco barras de madera de cedro para las tablas del un lado del tabernáculo;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'Y otras cinco barras para las tablas del otro lado del tabernáculo, y otras cinco barras para el otro lado del tabernáculo, que está al occidente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Y la barra del medio pasará por medio de las tablas del un cabo al otro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Y cubrirás las tablas de oro, y sus sortijas harás de oro, para meter por ellas las barras, y cubrirás de oro las barras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, '¶ Y alzarás el tabernáculo conforme a su traza, que te fue mostrada en el monte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Harás también un velo de cárdeno, y púrpura, y carmesí, y de lino torcido; será hecho de obra de artífice con querubines.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Y ponerlo has sobre cuatro columnas de cedro cubiertas de oro, sus capiteles de oro, sobre cuatro basas de plata.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Y pondrás el velo debajo de los corchetes, y meterás allí del velo a dentro, el arca del testimonio; y aquel velo os hará separación entre el santo lugar y el lugar santísimo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Y pondrás la cubierta sobre el arca del testimonio en el lugar santísimo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Y la mesa pondrás fuera del velo, y el candelero en frente de la mesa al lado del tabernáculo al mediodía; y la mesa pondrás al lado del aquilón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, '¶ Y harás a la puerta del tabernáculo un pabellón de cárdeno, y púrpura, y carmesí, y lino torcido, de obra de bordador.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Y harás para el pabellón cinco columnas de cedro, las cuales cubrirás de oro, con sus capiteles de oro, y hacerle has de fundición cinco basas de metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Harás también un altar de madera de cedro de cinco codos de longura, y de otros cinco codos de anchura: será cuadrado el altar, y su altura de tres codos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Y harás sus cuernos a sus cuatro esquinas: sus cuernos serán de lo mismo, y cubrirlo has de metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Harás también sus calderones para limpiar su ceniza, y sus badiles, y sus lebrillos, y sus garfios, y sus palas, todos sus vasos harás de metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Hacerle has también una criba de metal de hechura de red, y harás sobre la red cuatro sortijas de metal a sus cuatro esquinas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Y ponerla has dentro del cerco del altar abajo, y llegará aquella red hasta el medio del altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Y harás barras para el altar, barras de madera de cedro, las cuales cubrirás de metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Y sus barras se meterán por las sortijas, y estarán aquellas barras a ambos lados del altar, cuando hubiere de ser llevado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Hueco de tablas lo harás de la manera que te fue mostrado en el monte: así lo harán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, '¶ Asimismo harás el patio del tabernáculo al lado del mediodía, al austro: el patio tendrá las cortinas de lino torcido, de cien codos de longura cada un lado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Sus columnas serán veinte, y sus basas veinte de metal, los capiteles de las columnas y sus molduras de plata.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Y de la misma manera al lado del aquilón, en la longura habrá cortinas de cien codos en longura, y sus columnas veinte, con sus veinte basas de metal: los capiteles de las columnas y sus molduras de plata.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Y la anchura del patio al lado del occidente tendrá cortinas de cincuenta codos, y sus columnas serán diez, con sus diez basas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Y en la anchura del patio al lado del levante, al oriente habrá cincuenta codos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Y las cortinas del un lado serán de quince codos, sus columnas tres, con sus tres basas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Al otro lado, quince cortinas, sus columnas tres, con sus tres basas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Y a la puerta del patio habrá un pabellón de veinte codos, de cárdeno, y púrpura, y carmesí, y lino torcido de obra de bordador: sus columnas serán cuatro con sus cuatro basas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Todas las columnas del patio al rededor serán ceñidas de plata; mas sus capiteles serán de plata, y sus basas de metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'La longura del patio será de cien codos, y la anchura cincuenta con cincuenta, y la altura de cinco codos de lino torcido, y sus basas de metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Todos los vasos del tabernáculo en todo su servicio, y todas sus estacas, y todas las estacas del patio serán de metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, '¶ Y tú mandarás a los hijos de Israel, que te tomen aceite de olivas, claro, molido, para la luminaria, para hacer arder continuamente las lámparas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'En el tabernáculo del testimonio del velo a fuera, que estará delante del testimonio; las cuales pondrá en orden Aarón y sus hijos desde la tarde hasta la mañana delante de Jehová por estatuto perpetuo por sus generaciones de los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Y tú haz llegar a ti a Aarón tu hermano, y a sus hijos consigo de entre los hijos de Israel, para que sean mis sacerdotes, Aarón, Nadab y Abiú, Eleazar, e Itamar hijos de Aarón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Y harás vestidos santos para Aarón tu hermano, para honra, y hermosura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Y tú hablarás a todos los que fueren sabios de corazón, los cuales yo he henchido de espíritu de sabiduría, para que hagan los vestidos de Aarón para santificarle, para que sea mi sacerdote.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Los vestidos que harán, serán estos: El pectoral, y el efod, y el manto, y la túnica listada, la mitra, y el cinto. Y hagan los santos vestidos a Aarón tu hermano, y a sus hijos, para que sean mis sacerdotes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Los cuales tomarán oro, y cárdeno, y púrpura, y carmesí, y lino fino,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Y harán el efod de oro, y cárdeno, y púrpura, y carmesí, y lino torcido de obra de bordador.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Tendrá dos hombreras que se junten a sus dos lados, y así se juntará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Y el artificio de su cinta que estará sobre él, será de su misma obra, de lo mismo, es a saber, de oro, cárdeno, y púrpura, y carmesí, y lino torcido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Y tomarás dos piedras oniquinas, y grabarás en ellas los nombres de los hijos de Israel;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Los seis de sus nombres en la una piedra, y los otros seis nombres en la otra piedra conforme a sus nacimientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'De obra de maestro de piedras harás grabar de grabaduras de sello aquellas dos piedras de los nombres de los hijos de Israel; harásles al derredor engastes de oro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Y aquellas dos piedras pondrás sobre los hombros del efod, serán piedras de memoria a los hijos de Israel; y Aarón llevará los nombres de ellos delante de Jehová en sus dos hombros por memoria.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Y harás los engastes de oro;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'Y dos cadenas pequeñas de fino oro, las cuales harás de hechura de trenza, y pondrás las cadenas de hechura de trenza en los engastes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Ítem, harás el pectoral del juicio; de obra artificiosa hacerlo has conforme a la obra del efod, de oro, y cárdeno, y púrpura, y carmesí, y lino torcido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Será cuadrado doblado, de un palmo de longura, y de un palmo de anchura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Y henchirlo has de pedrería con cuatro ordenes de piedras. El orden: un rubí, una esmeralda, y una crisólita, el primer orden.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'El segundo orden, un carbunclo, un zafiro, y un diamante.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'El tercer orden, un topacio, una turquesa, y un ametisto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'Y el cuarto orden, un tarsis, un ónix, y un jaspe, engastadas en oro en sus engastes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Y serán aquellas piedras según los nombres de los hijos de Israel, doce según sus nombres, como grabaduras de sello, cada uno, según su nombre, serán a las doce tribus.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Harás también en el pectoral cadenas pequeñas de hechura de trenzas de oro fino.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Y harás en el pectoral dos sortijas de oro, las cuales dos sortijas pondrás a los dos cabos del pectoral.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Y pondrás las dos trenzas de oro en las dos sortijas, en los cabos del pectoral.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Y los otros dos cabos de las dos trenzas sobre los dos engastes, y ponerlas has a los lados del efod en la parte delantera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Harás también otras dos sortijas de oro, las cuales pondrás en los dos cabos del pectoral en su orilla que está al cabo del efod de la parte de abajo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Harás asimismo otras dos sortijas de oro las cuales pondrás a los dos lados del efod, abajo en la parte delantera, delante de su juntura, sobre el cinto del efod.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Y juntarán el pectoral con sus sortijas a las sortijas del efod con un cordón de cárdeno, para que esté sobre el cinto del efod, y no se aparte el pectoral del efod.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Y llevará Aarón los nombres de los hijos de Israel en el pectoral del juicio sobre su corazón, cuando entrare en el santuario en memoria delante de Jehová continuamente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Y pondrás en el pectoral del juicio Urim y Tumim para que estén sobre el corazón de Aarón, cuando entrare delante de Jehová: y llevará Aarón el juicio de los hijos de Israel sobre su corazón siempre delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Harás el manto del efod todo de cárdeno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Y tendrá el collar de su cabeza en medio de él, el cual tendrá un borde al rededor de obra de tejedor, como un collar de un coselete, que no se rompa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Y harás en sus orladuras granadas de cárdeno, y púrpura, y carmesí, por sus orladuras al derredor; y unas campanillas de oro entre ellas al rededor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Una campanilla de oro y una granada, otra campanilla de oro y otra granada, por las orladuras del manto al derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Y estará sobre Aarón cuando ministrare, y oírse ha su sonido cuando él entrare en el santuario delante de Jehová, y cuando saliere: Y no morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Ítem, harás una plancha de oro fino, y grabarás en ella de grabadura de sello, Santidad a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Y ponerla has con un cordón cárdeno, y estará sobre la mitra; delante la delantera de la mitra estará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Y estará sobre la frente de Aarón, y Aarón llevará el pecado de las santificaciones, que los hijos de Israel santificaren en todas las ofrendas de sus santificaciones, y sobre su frente estará continuamente, para que hayan gracia delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Ítem, bordarás una túnica de lino, y harás una mitra de lino, harás también un cinto de obra de recamador:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Mas a los hijos de Aarón harás túnicas: hacerles has también cintos, y hacerles has chapeos para honra y hermosura;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Y con ellos vestirás a Aarón tu hermano, y a sus hijos con él; y ungirlos has y henchirás sus manos, y santificarlos has para que sean mis sacerdotes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Y hacerles has pañetes de lino para cubrir la carne vergonzosa: serán desde los lomos hasta los muslos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Y estarán sobre Aarón y sobre sus hijos cuando entraren en el tabernáculo del testimonio, o cuando se llegaren al altar para servir en el santuario; y no llevarán pecado, y no morirán. Estatuto perpetuo para él, y para su simiente después de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Y esto es lo que les harás para santificarlos para que sean mis sacerdotes. Toma un novillo hijo de vaca, y dos carneros perfectos;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'Y panes sin levadura, y tortas sin levadura amasadas con aceite, y hojaldres sin levadura untadas con aceite, las cuales cosas harás de flor de harina de trigo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Y ponerlas has en un canastillo, y ofrecerlas has en el canastillo con el novillo y los dos carneros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Y harás llegar a Aarón y a sus hijos a la puerta del tabernáculo del testimonio, y lavarlos has con agua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Y tomarás las vestiduras, y vestirás a Aarón la túnica y el manto del efod, y el efod, y el pectoral, y ceñirle has con el cinto del efod.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Y pondrás la mitra sobre su cabeza, y la corona de la santidad pondrás sobre la mitra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Y tomarás el aceite de la unción, y derramarás sobre su cabeza, y ungirlo has.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Y harás llegar sus hijos, y vestirles has las túnicas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Y ceñirles has el cinto, a Aarón y a sus hijos, y apretarles has los chapeos, y tendrán el sacerdocio por fuero perpetuo: y henchirás las manos de Aarón y de sus hijos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, '¶ Y harás llegar el novillo delante del tabernáculo del testimonio, y Aarón y sus hijos pondrán sus manos sobre la cabeza del novillo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Y matarás el novillo delante de Jehová a la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Y tomarás de la sangre del novillo, y pondrás sobre los cuernos del altar con tu dedo, y toda la otra sangre echarás al cimiento del altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Y tomarás todo el sebo que cubre los intestinos, y el redaño de sobre el hígado, y los dos riñones, y el sebo que está sobre ellos, y encenderlos has sobre el altar:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Empero la carne del novillo, y su pellejo, y su estiércol quemarás a fuego fuera del campo: es expiación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Y tomarás el un carnero, y Aarón y sus hijos pondrán sus manos sobre la cabeza del carnero:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Y matarás el carnero, y tomarás su sangre, y rociarás sobre el altar al rededor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Y cortarás el carnero por sus piezas, y lavarás sus intestinos, y sus piernas, y ponerlas has sobre sus piezas y sobre su cabeza:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Y quemarás todo el carnero sobre el altar: holocausto es a Jehová, olor de holganza, ofrenda encendida es a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, '¶ Ítem, tomarás el segundo carnero, y Aarón y sus hijos pondrán sus manos sobre la cabeza del carnero,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Y matarás el carnero, y tomarás de su sangre, y pondrás sobre la ternilla de la oreja derecha de Aarón, y sobre la ternilla de las orejas de sus hijos, y sobre el dedo pulgar de las manos derechas de ellos, y sobre el dedo pulgar de los pies derechos de ellos, y esparcirás la sangre sobre el altar al derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Y tomarás de la sangre, que estará sobre el altar, y del aceite de la unción, y esparcirás sobre Aarón, y sobre sus vestiduras y sobre sus hijos, y sobre sus vestiduras con él, y él será santificado y sus vestiduras, y sus hijos, y las vestiduras de sus hijos con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Luego tomarás del carnero el sebo, y la cola, y el sebo que cubre los intestinos, y el redaño del hígado, y los dos riñones, y el sebo que está sobre ellos, y la espalda derecha, porque es carnero de consagraciones:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Y una hogaza de pan, y una torta de pan de aceite, y una hojaldre del canasto de las cenceñas, que está delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Y ponerlo has todo en las manos de Aarón, y en las manos de sus hijos, y mecerlo has en mecedura delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Después tomarlo has de sus manos, y encenderlo has sobre el altar sobre el holocausto por olor de holganza delante de Jehová. Ofrenda encendida es a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Y tomarás el pecho del carnero de las consagraciones, el cual es de Aarón, y mecerlo has por ofrenda mecida delante de Jehová, y será tu porción.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Y apartarás el pecho de la mecedura, y la espalda de la santificación que fue mecido, y que fue santificado del carnero de las consagraciones de Aarón y de sus hijos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Y será para Aarón, y para sus hijos por fuero perpetuo de los hijos de Israel; porque es apartamiento: y será apartado de los hijos de Israel de sus sacrificios pacíficos: apartamiento de ellos será para Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Y las vestiduras santas que son de Aarón, serán de sus hijos después de él para ser ungidos con ellas, y para ser con ellas consagrados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Siete días los vestirá el sacerdote de sus hijos, que en su lugar viniere al tabernáculo del testimonio a servir en el santuario.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Y tomarás el carnero de las consagraciones, y cocerás su carne en el lugar del santuario.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Y Aarón y sus hijos comerán la carne del carnero, y el pan que está en el canastillo, a la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Y comerán aquellas cosas con las cuales fueron expiados para henchir sus manos para ser santificados. Y el extranjero no comerá, porque son santidad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Y si sobrare algo de la carne de las consagraciones y del pan hasta la mañana, lo que hubiere sobrado quemarás con fuego: no se comerá, porque es santidad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Así pues harás a Aarón y a su hijos, conforme a todas las cosas que yo te he mandado: por siete días los consagrarás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, '¶ Y sacrificarás el novillo de la expiación cada día por las expiaciones, y expiarás el altar expiándotelo, y ungirlo has para santificarlo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Por siete días expiarás el altar, y lo santificarás, y será el altar santidad de santidades: cualquiera cosa que tocare al altar, será santificada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, '¶ Y lo que harás sobre el altar será esto: dos corderos de un año; cada día continuamente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'El un cordero harás a la mañana, y el otro cordero harás entre las dos tardes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Y una diezma de flor de harina amasada con aceite molido la cuarta parte de un hin: y la derramadura será la cuarta parte de un hin de vino con cada cordero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Y el otro cordero harás entre las dos tardes conforme al presente de la mañana, y conforme a su derramadura harás, por olor de holganza: será ofrenda encendida a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Esto será holocausto continuo por vuestras edades a la puerta del tabernáculo del testimonio delante de Jehová, en el cual me concertaré con vosotros para hablaros allí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, '¶ Y allí testificaré de mí a los hijos de Israel, y será santificado con mi gloria.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Y santificaré el tabernáculo del testimonio, y el altar: y a Aarón y a sus hijos santificaré para que sean mis sacerdotes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Y yo habitaré entre los hijos de Israel, y serles he por Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Y conocerán que yo soy Jehová su Dios, que los saqué de la tierra de Egipto para habitar en medio de ellos: Yo Jehová su Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Harás asimismo un altar de sahumerio de perfume: de madera de cedro lo harás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Su longura será de un codo, y su anchura de un codo; será cuadrado; y su altura de dos codos, y sus cuernos serán de el mismo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Y cubrirlo has de oro puro, su techumbre, y sus paredes al rededor, y sus cuernos: y hacerle has al derredor una corona de oro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Hacerle has también dos sortijas de oro debajo de su corona, a sus dos esquinas, en sus ambos lados, para meter las barras con que será llevado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Y harás las barras de madera de cedro, y cubrirlas has de oro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Y ponerlo has delante del velo que está junto al arca del testimonio, delante de la cubierta que está sobre el testimonio, donde yo te testificaré de mí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Y quemará sobre él Aarón sahumerio de especias cada mañana, el cual quemará cuando aderezare las lámparas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Y cuando Aarón encenderá las lámparas entre las dos tardes, quemará el sahumerio continuamente delante de Jehová por vuestras edades.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'No ofreceréis sobre él sahumerio ajeno, ni holocausto, ni presente, ni tampoco derramaréis sobre él derramadura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Y expiará Aarón sobre sus cuernos una vez en el año con la sangre de la expiación de las reconciliaciones, una vez en el año expiará sobre él en vuestras edades. Santidad de santidades será a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, '¶ Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Cuando tomares el número de los hijos de Israel por la cuenta de ellos, cada uno dará a Jehová el rescate de su alma, cuando los contares, y no habrá en ellos mortandad por haberlos contado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Esto dará cualquiera que pasare por la cuenta, medio siclo conforme al siclo del santuario. El siclo es de veinte óbolos: la mitad de un siclo será la ofrenda a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Cualquiera que pasare por la cuenta de veinte años arriba dará la ofrenda a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Ni el rico aumentará, ni el pobre disminuirá de medio siclo, cuando dieren la ofrenda a Jehová para hacer expiación por vuestras personas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Y tomarás de los hijos de Israel el dinero de las expiaciones, y darlo has para la obra del tabernáculo del testimonio; y será por memorial a los hijos de Israel delante de Jehová para expiar vuestras personas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, '¶ Habló más Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Harás también una fuente de metal con su basa de metal para lavar, y ponerla has entre el tabernáculo del testimonio, y el altar: y pondrás en ella agua;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Y de ella se lavarán Aarón y sus hijos sus manos y sus pies:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Cuando entraren en el tabernáculo del testimonio, lavarse han con agua, y no morirán: y cuando se llegaren al altar para ministrar, para encender a Jehová la ofrenda encendida;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Entonces se lavarán las manos y los pies, y no morirán. Y esto tendrán por estatuto perpetuo, él y su simiente por sus generaciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, '¶ Habló más Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Y tú tomarte has de las principales especias, de mirra excelente quinientos siclos, y de canela aromática la mitad de esto, es a saber, doscientos y cincuenta: y de cálamo aromático doscientos y cincuenta:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'Y de casia quinientos al peso del santuario: y de aceite de olivas un hin.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Y harás de ello el aceite de la santa unción, ungüento de ungüento, obra de perfumador, el cual será el aceite de la santa unción.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Con él ungirás el tabernáculo del testimonio, y el arca del testimonio;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'Y la mesa, y todos sus vasos; y el candelero, y todos sus vasos; y el altar del perfume,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'Y el altar del holocausto y todos sus vasos, y la fuente y su basa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Y consagrarlos has, y serán santidad de santidades: cualquiera cosa que tocare en ellos, será santificada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Ungirás también a Aarón y a sus hijos, y santificarlos has para que sean mis sacerdotes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, '¶ Y hablarás a los hijos de Israel, diciendo: Este será mi aceite de la santa unción por vuestras edades.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Sobre carne de hombre no será untado, ni haréis otro semejante conforme a su composición: santo es, tenerlo heis vosotros por santo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Cualquiera que compusiere ungüento semejante, y que pusiere de él sobre algún extraño, será cortado de sus pueblos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, '¶ Dijo más Jehová a Moisés: Tómate especias aromáticas; es a saber, estacte, y uña, y gálbano aromático, e incienso limpio en igual peso:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Y harás de ello una confección aromática de obra de perfumador, mezclada, pura, y santa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Y molerás de ella pulverizando, y de ella pondrás delante del testimonio en el tabernáculo del testimonio donde yo te testificaré de mí: Santidad de santidades os será.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, '¶ La confección que harás, no os haréis otra según su composición: Santidad te será para Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Cualquiera que hiciere otra como ella para olerla, será cortado de sus pueblos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Mira, yo he llamado por su nombre a Beseleel hijo de Uri, hijo de Jur, de la tribu de Judá,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Y lo he henchido de espíritu de Dios, en sabiduría, y en inteligencia, y en ciencia, y en todo artificio,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Para inventar invenciones para obrar en oro, y en plata, y en metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'Y en artificio de piedras para engastar, y en artificio de madera, para obrar en toda obra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Y he aquí que yo he puesto con él a Ooliab, hijo de Aquisamec de la tribu de Dan: y he puesto sabiduría en el ánimo de todo sabio de corazón, para que hagan todo lo que te he mandado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'El tabernáculo del testimonio, y el arca del testimonio, y la cubierta que estará sobre ella, y todos los vasos del tabernáculo,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'Y la mesa y sus vasos, y el candelero limpio y todos sus vasos, y el altar del perfume,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'Y el altar del holocausto, y todos sus vasos, y la fuente, y su basa,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'Y las vestiduras del servicio, y las santas vestiduras, para Aarón el sacerdote, y las vestiduras de sus hijos, para que sean sacerdotes,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'Y el aceite de la unción, y el perfume aromático para el santuario, el cual harán conforme a todo lo que yo te he mandado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, '¶ Habló más Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Y tú hablarás a los hijos de Israel, diciendo: Con todo eso vosotros guardaréis mis sábados; porque es señal entre mí y vosotros por vuestras edades, para que sepáis que yo soy Jehová, que os santifico;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Así que guardaréis el sábado porque santo es a vosotros: El que lo profanare, muriendo morirá: porque cualquiera que hiciere obra alguna en él, aquella alma será cortada de en medio de sus pueblos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Seis días se hará obra; y el séptimo día sábado de reposo será santo a Jehová: cualquiera que hiciere obra el día del sábado, muriendo morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Guardarán pues el sábado los hijos de Israel, haciendo sábado por sus edades, pacto perpetuo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Señal es para siempre entre mí y los hijos de Israel; porque en seis días hizo Jehová los cielos y la tierra, y en el séptimo día cesó, y reposó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, '¶ Y dio a Moisés, como acabó de hablar con él en el monte de Sinaí, dos tablas del testimonio, tablas de piedra escritas con el dedo de Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Mas viendo el pueblo que Moisés tardaba de descender del monte, juntóse entonces el pueblo contra Aarón, y dijéronle: Levántate, háznos dioses que vayan delante de nosotros: porque a este Moisés, aquel varón que nos sacó de la tierra de Egipto, no sabemos que le haya acontecido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Y Aarón les dijo: Apartád los zarcillos de oro que están en las orejas de vuestras mujeres, y de vuestros hijos, y de vuestras hijas, y traédmelos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Entonces todo el pueblo apartó los zarcillos de oro que tenían en sus orejas, y trajéronlos a Aarón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'El cual los tomó de las manos de ellos, y formólo con buril, e hizo de ello un becerro de fundición, y dijeron: Israel, estos son tus dioses que te sacaron de tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Y viéndolo Aarón, edificó un altar delante de él, y pregonó Aarón, y dijo: Mañana será fiesta a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Y el día siguiente madrugaron, y ofrecieron holocaustos, y presentaron pacíficos: y el pueblo se asentó a comer y a beber, y levantáronse a regocijarse.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, '¶ Entonces Jehová dijo a Moisés: Anda, desciende; porque tu pueblo, que sacaste de tierra de Egipto, se ha corrompido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Presto se han apartado del camino que yo les mandé; y se han hecho un becerro de fundición, y lo han adorado, y han sacrificado a él, y han dicho: Israel, estos son tus dioses, que te sacaron de tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Dijo más Jehová a Moisés: Yo he visto a este pueblo, que cierto es pueblo de dura cerviz.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Ahora pues déjame, que se encienda mi furor en ellos, y los consuma, y a ti yo te pondré sobre gran gente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Entonces Moisés oró a la faz de Jehová su Dios, y dijo: Oh, Jehová, ¿por qué se encenderá tu furor en tu pueblo, que tú sacaste de la tierra de Egipto con gran fortaleza, y con mano fuerte?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, '¿Por qué han de decir los Egipcios, diciendo: Con mal los sacó, para matarlos en los montes, y para raerlos de sobre la haz de la tierra? Vuélvete de la ira de tu furor, y arrepiéntete del mal de tu pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Acuérdate de Abraham, de Isaac, y de Israel tus siervos, a los cuales has jurado por ti mismo, y dícholes: Yo multiplicaré vuestra simiente como las estrellas del cielo: y daré a vuestra simiente toda esta tierra que he dicho, y tomarla han por heredad para siempre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Entonces Jehová se arrepintió del mal, que dijo, que había de hacer a su pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, '¶ Y volvióse Moisés, y descendió del monte trayendo en su mano las dos tablas del testimonio, las tablas escritas por sus ambas partes: de una parte y de otra estaban escritas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Y las tablas eran obra de Dios, y la escritura era escritura de Dios grabada sobre las tablas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Y oyendo Josué la voz del pueblo que gritaba, dijo a Moisés: Alarido de pelea hay en el campo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Y él respondió: No es alarido de respuesta de fuertes, ni alarido de respuesta de flacos: alarido de cantar oigo yo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Y aconteció, que como él llegó al campo, y vio el becerro, y las danzas, el furor se le encendió a Moisés, y arrojó las tablas de sus manos, y quebrólas al pie del monte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Y tomó el becerro que habían hecho, y quemólo en el fuego, y moliólo hasta volverlo en polvos, y esparció los polvos sobre las aguas, y diólo a beber a los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, '¶ Y dijo Moisés a Aarón: ¿Qué te ha hecho este pueblo, que has traído sobre él tan gran pecado?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Y respondió Aarón: No se enoje mi señor, tú conoces el pueblo, que es inclinado a mal:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Porque me dijeron: Háznos dioses que vayan delante de nosotros; que a este Moisés, el varón que nos sacó de tierra de Egipto, no sabemos que le ha acontecido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Y yo les respondí: ¿Quién tiene oro? apartádlo. Y diéronmelo, y echélo en el fuego, y salió este becerro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, '¶ Y viendo Moisés el pueblo, que estaba desnudo, (porque Aarón le había desnudado para vergüenza entre sus enemigos,)');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Púsose Moisés a la puerta del real, y dijo: ¿Quién es de Jehová? Venga conmigo. Y juntáronse con él todos los hijos de Leví.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Y él les dijo: Así dijo Jehová, el Dios de Israel: Ponéd cada uno su espada sobre su muslo: pasád y volvéd de puerta a puerta por el campo, y matád cada uno a su hermano, y a su amigo, y a su pariente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Y los hijos de Leví lo hicieron conforme al dicho de Moisés, y cayeron del pueblo en aquel día como tres mil hombres.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Entonces Moisés dijo: Hoy os habéis consagrado a Jehová, porque cada uno se ha consagrado en su hijo, y en su hermano, para que él dé hoy sobre vosotros bendición.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, '¶ Y aconteció que el día siguiente Moisés dijo al pueblo: Vosotros habéis pecado un gran pecado: mas yo subiré ahora a Jehová, quizá le aplacaré sobre vuestro pecado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Entonces volvió Moisés a Jehová, y dijo: Yo te ruego: este pueblo ha pecado un pecado grande, porque se hicieron dioses de oro,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Que perdones ahora su pecado, y si no, ráeme ahora de tu libro, que has escrito.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Y Jehová respondió a Moisés: Al que pecare contra mí, a este raeré yo de mi libro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Vé pues ahora, lleva a este pueblo donde te he dicho: he aquí, mi ángel irá delante de ti, que en el día de mi visitación yo visitaré en ellos su pecado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'E hirió Jehová al pueblo, porque habían hecho el becerro que hizo Aarón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Y Jehová dijo a Moisés: Vé, sube de aquí, tu y el pueblo, que sacaste de la tierra de Egipto, a la tierra, de la cual yo juré a Abraham, Isaac, y Jacob, diciendo: A tu simiente la daré:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Y yo enviaré delante de ti el ángel, y echaré fuera al Cananeo, y al Amorreo, y al Jetteo, y al Ferezeo, y al Heveo, y al Jebuseo,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'A la tierra que corre leche y miel: porque yo no subiré en medio de ti, porque eres pueblo de dura cerviz, porque yo no te consuma en el camino.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Y oyendo el pueblo esta mala palabra, pusieron luto, y ninguno puso sobre si sus atavíos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Y Jehová dijo a Moisés: Di a los hijos de Israel: Vosotros sois pueblo de dura cerviz: en un momento subiré en medio de ti, y te consumiré: quítate pues ahora tus atavíos que yo sabré lo que te tengo de hacer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Entonces los hijos de Israel se despojaron de sus atavíos desde el monte Oreb.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Y Moisés tomó el tabernáculo, y extendiólo fuera del campo, lejos del campo, y llamóle: El tabernáculo del testimonio: y fue, que cualquiera que requería a Jehová, salía al tabernáculo del testimonio, que estaba fuera del campo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Y era, que cuando salía Moisés al tabernáculo, todo el pueblo se levantaba, y estaba cada uno en pie a la puerta de su tienda, y miraban en pos de Moisés, hasta que él entraba en el tabernáculo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Y cuando Moisés entraba en el tabernáculo, la columna de nube descendía, y se ponía a la puerta del tabernáculo, y Jehová hablaba con Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Y viendo todo el pueblo la columna de la nube, que estaba a la puerta del tabernáculo, todo el pueblo se levantaba; cada uno a la puerta de su tienda, y adoraba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Y hablaba Jehová a Moisés cara a cara, como habla cualquiera a su compañero, y volvíase al campo: mas el mozo Josué, hijo de Nun, su criado, nunca se apartaba de en medio del tabernáculo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, '¶ Y dijo Moisés a Jehová: Mira, tú me dices a mí: Saca este pueblo, y tú no me has aun declarado, a quien has de enviar conmigo: y tú dices: Yo te he conocido por nombre, y aun has hallado gracia en mis ojos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Ahora pues, si he hallado ahora gracia en tus ojos, ruégote que me muestres tu camino, para que te conozca; porque halle gracia en tus ojos: y mira, que tu pueblo es aquesta gente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, '¶ Y él dijo: Mi faz irá contigo, y te haré descansar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Y él le respondió: Si tu faz no ha de ir conmigo, no nos saques de aquí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, '¿Y en qué se parecerá aquí, que he hallado gracia en tus ojos, yo y tu pueblo, sino en andar tú con nosotros, y que yo y tu pueblo seamos apartados de todos los pueblos que están sobre la haz de la tierra?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Y Jehová dijo a Moisés: También haré esto que has dicho, por cuanto has hallado gracia en mis ojos, y yo te he conocido por nombre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Él entonces dijo: Ruégote que me muestres tu gloria.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Y él respondió: Yo haré pasar todo mi bien delante de tu rostro, y llamaré por el nombre de Jehová delante de ti; y habré misericordia del que tendré misericordia, y seré clemente al que seré clemente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Dijo más: No podrás ver mi faz; porque no me verá hombre, y vivirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Y dijo más Jehová: He aquí lugar junto a mí, y tú estarás sobre la peña.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Y será, que cuando pasare mi gloria, yo te pondré en un resquicio de la peña, y te cubriré con mi mano hasta que yo haya pasado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Después yo apartaré mi mano, y verás mis espaldas, mas mi rostro no se verá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Y Jehová dijo a Moisés: Alísate dos tablas de piedra como las primeras, y yo escribiré sobre aquellas tablas las palabras que estaban sobre las tablas primeras que quebraste.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Apercíbete pues para mañana, y sube por la mañana en el monte de Sinaí, y estáme allí sobre la cumbre del monte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Y no suba hombre contigo, ni parezca alguno en todo el monte: ni oveja ni buey pazcan delante del monte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Y él alisó dos tablas de piedra como las primeras, y levantóse por la mañana, y subió al monte de Sinaí, como Jehová le mandó, y tomó en su mano las dos tablas de piedra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, '¶ Y Jehová descendió en una nube, y estuvo allí con él, y llamó en el nombre de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Y pasando Jehová por delante de él, clamó: Jehová, Jehová, fuerte, misericordioso, y piadoso; luengo de iras, y grande en misericordia y verdad:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Que guarda la misericordia en millares; que suelta la iniquidad, la rebelión, y el pecado: y que absolviendo no absolverá; que visita la iniquidad de los padres sobre los hijos, y sobre los hijos de los hijos, sobre los terceros y sobre los cuartos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, '¶ Entonces Moisés apresurándose abajó la cabeza en tierra y encorvóse:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Y dijo: Si ahora he hallado gracia en tus ojos, Señor, vaya ahora el Señor en medio de nosotros, porque este es pueblo de dura cerviz; y perdona nuestra iniquidad, y nuestro pecado, y poséenos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, '¶ Y él dijo: He aquí, yo hago concierto delante de todo tu pueblo: haré maravillas, que no han sido hechas en toda la tierra, ni en todas las gentes, y verá todo el pueblo, en medio del cual tú estás, la obra de Jehová; porque ha de ser cosa terrible, la que yo hago contigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, '¶ Guárdate de lo que yo te mando hoy: he aquí que yo echo de delante de tu presencia al Amorreo, y al Cananeo, y al Jetteo, y al Ferezeo, y al Heveo, y al Jebuseo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Guárdate que no hagas alianza con los moradores de la tierra donde has de entrar, porque no sean por tropezadero en medio de ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Mas derribaréis sus altares, y quebraréis sus estatuas, y talaréis sus bosques.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Porque no te inclinarás a dios ajeno, que Jehová, cuyo nombre es Zeloso, Dios zeloso es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Por tanto no harás alianza con los moradores de aquella tierra; porque ellos fornicarán en pos de sus dioses, y sacrificarán a sus dioses, y llamarte han y comerás de sus sacrificios:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'O tomando de sus hijas para tus hijos, y fornicando sus hijas en pos de sus dioses, harán también fornicar tus hijos en pos de los dioses de ellas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'No harás dioses de fundición para ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'La fiesta de las cenceñas guardarás: siete días comerás por leudar, como te he mandado, en el tiempo del mes de Abib, porque en el mes de Abib saliste de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Toda abertura de matriz mía es; y todo tu ganado que será macho, abertura de la vaca, y de la oveja, será mío.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Empero el primogénito del asno redimirás con cordero; y si no lo redimieres, cortarle has la cabeza. Todo primogénito de tus hijos redimirás; y no serán vistos vacíos delante de mí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Seis días trabajarás, mas en el séptimo día cesarás: en la arada y en la siega cesarás.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Y la fiesta de las semanas te harás a los principios de la siega del trigo; y la fiesta de la cosecha a la vuelta del año.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Tres veces en el año será visto todo varón tuyo delante del Señoreador Jehová, Dios de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Porque yo echaré las gentes de delante tu faz, y ensancharé tu término: y ninguno codiciará tu tierra, cuando tú subieres para ser visto delante de Jehová tu Dios tres veces en el año.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'No sacrificarás sobre leudo la sangre de mi sacrificio: ni quedará de la noche para la mañana el sacrificio de la fiesta de la pascua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'El principio de los primeros frutos de tu tierra meterás en la casa de Jehová tu Dios. No cocerás el cabrito en la leche de su madre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Y Jehová dijo a Moisés: Escríbete estas palabras, porque conforme a estas palabras he hecho la alianza contigo, y con Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, '¶ Y él estuvo allí con Jehová cuarenta días, y cuarenta noches: no comió pan, ni bebió agua: y escribió en tablas las palabras de la alianza, las diez palabras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Y aconteció, que descendiendo Moisés del monte de Sinaí con las dos tablas del testimonio en su mano, como descendió del monte, él no sabía que la tez de su rostro resplandecía, después que hubo hablado con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Y miró Aarón y todos los hijos de Israel a Moisés, y he aquí que la tez de su rostro era resplandeciente, y hubieron miedo de llegarse a él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Y llamólos Moisés, y tornaron a él Aarón y todos los príncipes de la congregación: y Moisés les habló.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Y después se llegaron todos los hijos de Israel, a los cuales mandó todas las cosas que Jehová le había dicho en el monte de Sinaí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Y cuando hubo acabado Moisés de hablar con ellos, puso un velo sobre su rostro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Y cuando venía Moisés delante de Jehová para hablar con él, quitaba el velo, hasta que salía; y salido hablaba con los hijos de Israel, lo que le era mandado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Y veían los hijos de Israel el rostro de Moisés que la tez de su rostro era resplandeciente, y volvía Moisés a poner el velo sobre su rostro, hasta que entraba a hablar con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'E hizo juntar Moisés toda la congregación de los hijos de Israel, y díjoles: Estas son las cosas, que Jehová ha mandado que hagáis:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Seis días se hará obra; mas el día séptimo os será santo, sábado de reposo a Jehová, cualquiera que hiciere en él obra, morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'No encenderéis fuego en todas vuestras moradas en el día del sábado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Y habló Moisés a toda la congregación de los hijos de Israel, diciendo: Esto es lo que Jehová ha mandado, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Tomád de entre vosotros ofrenda para Jehová: todo liberal de su corazón la traerá a Jehová, oro, plata, y metal,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'Y cárdeno, y púrpura, y carmesí, y lino fino, y pelos de cabras,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'Y cueros rojos de carneros, y cueros de tejones, y madera de cedro,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'Y aceite para la luminaria, y especias aromáticas para el aceite de la unción, y para el perfume aromático,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Y piedras de ónix, y las piedras de los engastes para el efod y para el pectoral.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Y todo sabio de corazón, que habrá entre vosotros, vendrán y harán todas las cosas que ha mandado Jehová:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'El tabernáculo, su tienda, y su cobertura, y sus sortijas, y sus tablas, sus barras, sus columnas, y sus basas;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'El arca y sus barras, la cubierta, y el velo de la tienda;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'La mesa y sus barras, y todos sus vasos, y el pan de la proposición;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'Y el candelero de la luminaria, y sus vasos, y sus candilejas, y el aceite de la luminaria;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'Y el altar del perfume y sus barras, y el aceite de la unción, y el perfume aromático, y el pabellón de la puerta para la entrada del tabernáculo;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'El altar del holocausto, y su criba de metal, y sus barras, y todos sus vasos, y la fuente, y su basa;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'Las cortinas del patio, sus columnas, y sus basas, y el pabellón de la puerta del patio;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'Las estacas del tabernáculo, y las estacas del patio, y sus cuerdas;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'Las vestiduras del servicio para ministrar en el santuario; es a saber, las santas vestiduras de Aarón el sacerdote, y las vestiduras de sus hijos para servir en el sacerdocio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, '¶ Y salió toda la congregación de los hijos de Israel de delante de Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Y vino todo varón a quien su corazón levantó, y todo aquel a quien su espíritu le dio voluntad, y trajeron ofrenda a Jehová para la obra del tabernáculo del testimonio, y para toda su obra, y para las santas vestiduras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Y vinieron así hombres como mujeres, todo voluntario de corazón, y trajeron ajorcas, y zarcillos, y anillos, y brazaletes, y toda joya de oro, y cualquiera ofrecía ofrenda de oro a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Todo hombre que se hallaba con cárdeno, o púrpura, o carmesí, o lino fino, o pelos de cabras, o cueros rojos de carneros, o cueros de tejones, lo traía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Cualquiera que ofrecía ofrenda de plata, o de metal, traía la ofrenda a Jehová: y todo hombre que se hallaba con madera de cedro, la traía para toda la obra del servicio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Ítem, todas las mujeres sabias de corazón hilaban de sus manos, y traían lo que habían hilado, cárdeno, o púrpura, o carmesí, o lino fino.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Y todas las mujeres, cuyo corazón las levantó en sabiduría, hilaron pelos de cabras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Y los príncipes trajeron las piedras de ónix, y las piedras de los engastes para el efod, y el pectoral;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'Y la especia aromática, y aceite para la luminaria, y para el aceite de la unción, y para el perfume aromático.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Todo hombre y mujer que tuvieron corazón voluntario para traer para toda la obra que Jehová había mandado por Moisés que hiciesen, trajeron los hijos de Israel ofrenda voluntaria a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, '¶ Y dijo Moisés a los hijos de Israel: Mirád, Jehová ha llamado por su nombre a Beseleel, hijo de Uri, hijo de Jur, de la tribu de Judá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Y lo ha henchido de Espíritu de Dios, en sabiduría, en inteligencia, y en ciencia, y en todo artificio;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'Para inventar invenciones para obrar en oro, y en plata, y en metal;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'Y en obra de pedrería para engastar, y en obra de madera, para obrar en toda obra de invención:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Y ha puesto en su corazón para que pueda enseñar él y Ooliab, hijo de Aquisamec, de la tribu de Dan.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Y los ha henchido de sabiduría de corazón para que hagan toda obra de artificio, y de invención, y de recamado, en cárdeno, y en púrpura, y en carmesí, y en lino fino, y en telar, para que hagan toda obra, e inventen toda invención.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'E hizo Beseleel, y Ooliab, y todo hombre sabio de corazón, a quien Jehová dio sabiduría e inteligencia para que supiesen hacer toda la obra del servicio del santuario, todas las cosas que había mandado Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Y Moisés llamó a Beseleel y a Ooliab, y a todo varón sabio de corazón, en cuyo corazón había dado Jehová sabiduría, y a todo hombre a quien su corazón levantó para llegarse a la obra para hacer en ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Y tomaron de delante de Moisés toda la ofrenda que los hijos de Israel habían traído para la obra del servicio del santuario para hacerla, y ellos le traían aun ofrenda voluntaria cada mañana.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Y vinieron todos los maestros que hacían toda la obra del santuario, cada uno de la obra que hacía,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'Y hablaron a Moisés, diciendo: El pueblo trae mucho más de lo que es menester para hacer la obra para el ministerio, que Jehová ha mandado que se haga.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Entonces Moisés mandó pregonar por el campo, diciendo: Ningún hombre ni mujer hagan más obra para ofrecer al santuario. Y así fue el pueblo prohibido de ofrecer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Y tenían hacienda abasto para hacer toda la obra, y sobraba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, '¶ Y todos los sabios de corazón entre los que hacían la obra, hicieron el tabernáculo de diez cortinas, de lino torcido, y de cárdeno, y de púrpura, y de carmesí, las cuales hicieron de obra de artífice con querubines.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'La longura de la una cortina era de veinte y ocho codos, y la anchura de cuatro codos, todas las cortinas tenían una misma medida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Y juntó las cinco cortinas la una con la otra, y las otras cinco cortinas juntó la una con la otra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'E hizo las lazadas de cárdeno en la orilla de la una cortina, en el cabo a la juntura y así hizo en la orilla en el cabo de la segunda cortina, en la juntura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Cincuenta lazadas hizo en la una cortina, y otras cincuenta en la segunda cortina, en el cabo, en la juntura, las unas lazadas en frente de las otras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Hizo también cincuenta corchetes de oro con los cuales juntó las cortinas la una con la otra, e hízose un tabernáculo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Hizo asimismo cortinas de pelos de cabras para la tienda sobre el tabernáculo, e hízolas once.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'La longura de la una cortina era de treinta codos, y la anchura de cuatro codos, las once cortinas tenían una misma medida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Y juntó por sí las cinco cortinas, y las seis cortinas por sí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'E hizo cincuenta lazadas en la orilla de la postrera cortina en la juntura, y otras cincuenta lazadas en la orilla de la otra cortina en la juntura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Hizo también cincuenta corchetes de metal para juntar la tienda que fuese una.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'E hizo un cobertor para la tienda de cueros rojos de carnero, y otro cobertor encima de cueros de tejones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, '¶ E hizo las tablas para el tabernáculo de madera de cedro estantes.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'La longura de cada tabla de diez codos, y de codo y medio la anchura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Cada tabla tenía dos quicios enclavijados el uno delante del otro, así hizo todas las tablas del tabernáculo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'E hizo las tablas para el tabernáculo, veinte tablas al lado del austro, al mediodía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Hizo también las cuarenta basas de plata debajo de las veinte tablas; dos basas debajo de la una tabla para sus dos quicios, y otras dos basas debajo de la otra tabla para sus dos quicios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Y en el otro lado del tabernáculo, en el lado del aquilón, hizo otras veinte tablas,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'Con sus cuarenta basas de plata, dos basas debajo de la una tabla, y otras dos basas debajo de la otra tabla.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Y en el lado occidental del tabernáculo hizo seis tablas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'A las esquinas del tabernáculo en los dos lados hizo dos tablas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Las cuales se juntaban por abajo, y asimismo por arriba a una sortija; y así hizo a la una y a la otra en las dos esquinas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Y así eran ocho tablas, y sus basas de plata diez y seis, dos basas debajo de cada tabla.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'E hizo las barras de madera de cedro, cinco para las tablas del un lado del tabernáculo,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'Y otras cinco barras para las tablas del otro lado del tabernáculo, y otras cinco barras para las tablas del lado del tabernáculo a las esquinas del occidente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'E hizo que la barra del medio pasase por medio de las tablas del un cabo al otro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Y cubrió las tablas de oro, e hizo de oro las sortijas de ellas por donde pasasen las barras, y cubrió de oro las barras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, '¶ Hizo asimismo el velo de cárdeno, y púrpura, y carmesí, y lino torcido, el cual hizo de obra de artífice con querubines.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'E hizo para él cuatro columnas de cedro, y cubriólas de oro, los capiteles de las cuales eran de oro, e hizo para ellas cuatro basas de plata de fundición.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, '¶ Hizo asimismo el velo para la puerta del tabernáculo de cárdeno, y púrpura, y carmesí, y lino torcido, de obra de recamador;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'Con sus cinco columnas y sus capiteles, y cubrió las cabezas de ellas y sus molduras de oro, y sus cinco basas hizo de metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Hizo también Beseleel el arca de madera de cedro, su longura era de dos codos y medio, y de codo y medio su anchura, y su altura de otro codo y medio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Y cubrióla de oro puro por de dentro y por de fuera, e hízole una corona de oro al rededor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Y fundióle cuatro sortijas de oro a sus cuatro esquinas, en el un lado dos sortijas, y en el otro lado otras dos sortijas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Hizo también las barras de madera de cedro, y cubriólas de oro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Y metió las barras por las sortijas a los lados del arca para llevar el arca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, '¶ Hizo asimismo la cubierta de oro puro: su longura de dos codos y medio, y su anchura de codo y medio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Ítem, hizo los dos querubines de oro, los cuales hizo de martillo, a los dos cabos de la cubierta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'El un querubín de esta parte al un cabo, y el otro querubín de la otra parte al otro cabo de la cubierta: hizo los querubines a sus dos cabos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Y los querubines extendían sus alas por encima cubriendo con sus alas la cubierta; y sus rostros el uno contra el otro, los rostros de los querubines a la cubierta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, '¶ Hizo también la mesa de madera de cedro, su longura de dos codos, y su anchura de un codo, y de codo y medio su altura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Y cubrióla de oro puro, e hízole una corona de oro al derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Hízole también una moldura de anchura de una mano al rededor, a la cual moldura hizo la corona de oro al derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Hízole también de fundición cuatro sortijas de oro, y púsolas a las cuatro esquinas, que estaban a los cuatro pies de ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Delante de la moldura estaban las sortijas, por las cuales se metiesen las barras para llevar la mesa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Hizo también las barras de madera de cedro para llevar la mesa, y cubriólas de oro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Ítem, hizo los vasos que habían de estar sobre la mesa, sus platos, y sus cucharones, y sus cubiertas, y sus tazones con que se había de cubrir el pan, de oro fino.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, '¶ Hizo asimismo el candelero de oro puro, el cual hizo de martillo: su pie, y su caña, sus copas, sus manzanas, y sus flores eran de lo mismo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'De sus lados salían seis cañas, las tres cañas del un lado del candelero, y las otras tres cañas del otro lado del candelero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'En la una caña había tres copas almendradas, una manzana, y una flor: y en la otra caña otras tres copas almendradas, otra manzana y otra flor: y así en todas las seis cañas que salían del candelero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Y en el mismo candelero había cuatro copas almendradas, sus manzanas, y sus flores.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Y una manzana debajo de las unas dos cañas de lo mismo, y otra manzana debajo de las otras dos cañas de lo mismo, y otra manzana debajo de las otras dos cañas de lo mismo, por las seis cañas que salían de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Sus manzanas y sus cañas eran de lo mismo, todo era una pieza de martillo de oro puro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Hizo asimismo sus candilejas siete, y sus despabiladeras, y sus paletas de oro puro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'De un talento de oro puro lo hizo a él y a todos sus vasos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, '¶ Hizo también el altar del perfume de madera de cedro: un codo su longura, y otro codo su anchura, cuadrado: y dos codos su altura, y sus cuernos eran de la misma pieza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Y cubriólo de oro puro, su mesa y sus paredes al rededor, y sus cuernos: e hízole una corona de oro al derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Hízole también dos sortijas de oro debajo de la corona en las dos esquinas a los dos lados, para pasar por ellas las barras con que había de ser llevado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Y las barras hizo de madera de cedro, y cubriólas de oro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, '¶ Hizo asimismo el aceite de la unción santo, y el perfume aromático fino, de obra de perfumador.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'E hizo el altar del holocausto de madera de cedro, su longura de cinco codos, y su anchura de otros cinco codos, cuadrado, y de tres codos su altura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'E hízole sus cuernos a sus cuatro esquinas, los cuales eran de la misma pieza, y cubriólo de metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Hizo asimismo todos los vasos del altar, calderones, y badiles, y lebrillos, y garfios, y palas: todos sus vasos hizo de metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'E hizo la criba para el altar de hechura de red de metal, en su cerco debajo hasta el medio de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'E hizo de fundición cuatro sortijas para la criba de metal a los cuatro cabos para meter las barras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'E hizo las barras de madera de cedro, y cubriólas de metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Y metió las barras por las sortijas a los lados del altar para llevarlo con ellas, el cual hizo hueco de tablas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, '¶ Ítem, hizo la fuente de metal y su basa de metal de los espejos de las que velaban a la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, '¶ Ítem, hizo el patio a la parte del mediodía austral; las cortinas del patio eran de cien codos de lino torcido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Sus columnas veinte, y las basas de ellas veinte de metal: los capiteles de las columnas y sus molduras de plata.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Y a la parte del aquilón cortinas de cien codos: sus columnas veinte, y las basas de ellas veinte, de metal: los capiteles de las columnas y sus molduras de plata.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'A la parte del occidente cortinas de cincuenta codos: sus columnas diez, y las basas de ellas diez: los capiteles de las columnas y sus molduras de plata.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Y a la parte oriental al oriente, cortinas de cincuenta codos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Al un lado cortinas de quince codos, sus tres columnas con sus tres basas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Al otro lado de la una parte y de la otra de la puerta del patio, cortinas de a quince codos, sus tres columnas, con sus tres basas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Todas las cortinas del patio al derredor eran de lino torcido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Y las basas de las columnas, de metal: los capiteles de las columnas y sus molduras, de plata. Y las cubiertas de las cabezas de ellas, de plata, asimismo todas las columnas del patio tenían molduras de plata.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, '¶ Y el pabellón de la puerta del patio de obra de recamado de cárdeno, y púrpura, y carmesí, y lino torcido: la longura de veinte codos, y la altura en la anchura de cinco codos y conforme a las cortinas del patio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Y sus columnas cuatro con sus basas cuatro de metal, y sus corchetes de plata, y las cubiertas de los capiteles de ellas, y sus molduras, de plata.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Y todas las estacas del tabernáculo y del patio al rededor de metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Estas son las cuentas del tabernáculo, del tabernáculo del testimonio, lo cual fue contado por dicho de Moisés por mano de Itamar hijo de Aarón, sacerdote, para el ministerio de los Levitas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Y Beseleel, hijo de Uri, hijo de Jur, de la tribu de Judá, hizo todas las cosas que Jehová mandó a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Y con él Ooliab, hijo de Aquisamec, de la tribu de Dan, maestro e ingeniero, y recamador en cárdeno, y púrpura, y carmesí, y lino fino.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, '¶ Todo el oro gastado en la obra, en toda la obra del santuario, el cual fue oro de ofrenda, fue veinte y nueve talentos, y sietecientos y treinta siclos, al siclo del santuario.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Y la plata de los contados de la congregación fue cien talentos, y mil y sietecientos y setenta y cinco siclos, al siclo del santuario.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Medio por cabeza, medio siclo, al siclo del santuario, a todos los que pasaron por cuenta de edad de veinte años y arriba, que fueron seiscientos y tres mil y quinientos y cincuenta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Hubo además cien talentos de plata para hacer de fundición las basas del santuario, y las basas del velo, en cien basas cien talentos, a talento por basa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Y de mil y siete cientos y setenta y cinco siclos hizo los capiteles de las columnas, y cubrió los capiteles de ellas, y las ciñó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Y el metal de la ofrenda fue setenta talentos, y dos mil y cuatrocientos siclos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Del cual hizo las basas de la puerta del tabernáculo del testimonio, y el altar de metal, y su criba de metal, y todos los vasos del altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'Y las basas del patio al derredor, y las basas de la puerta del patio, y todas las estacas del tabernáculo, y todas las estacas del patio al rededor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Y del cárdeno, y púrpura, y carmesí, hicieron las vestiduras del ministerio para ministrar en el santuario; y asimismo hicieron las santas vestiduras que eran para Aarón, como Jehová lo mandó a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Hizo también el efod de oro, cárdeno, y púrpura, y carmesí, y lino torcido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Y extendieron las planchas de oro, y cortaron los hilos para tejer entre el cárdeno, y entre la púrpura, y entre el carmesí, y entre el lino, por obra de artífice.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Hiciéronle los espaldares que se juntasen, y juntábanse en sus dos lados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Y el cinto del efod, que estaba sobre él, era de lo mismo, conforme a su obra de oro, cárdeno, y púrpura, y carmesí, y lino torcido, como Jehová lo había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Y labraron las piedras oniquinas cercadas de engastes de oro, grabadas de grabadura de sello con los nombres de los hijos de Israel:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Y púsolas sobre las hombreras del efod, por piedras de memoria a los hijos de Israel, como Jehová lo había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Hizo también el pectoral de obra de artífice, como la obra del efod, de oro, cárdeno, y púrpura, y carmesí, y lino torcido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Era cuadrado: doblado hicieron el pectoral, su longura era de un palmo, y de otro palmo su anchura, doblado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Y engastaron en él cuatro ordenes de piedras. El orden era un rubí, una esmeralda, y una crisólita, el primer orden.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'El segundo orden, un carbunclo, un zafiro, y un diamante.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'El tercer orden, un topacio, una turquesa, y un ametisto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'Y el cuarto orden, un tarsis, un ónix, y un jaspe, cercadas y engastadas en sus engastes de oro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Las cuales piedras eran conforme a los nombres de los hijos de Israel doce, conforme a los nombres de ellos, de grabadura de sello, cada una conforme a su nombre, según las doce tribus.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Hicieron también sobre el pectoral las cadenas pequeñas de hechura de trenza, de oro puro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Hicieron asimismo los dos engastes, y las dos sortijas de oro, las cuales dos sortijas de oro pusieron en los dos cabos del pectoral.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Y pusieron las dos trenzas de oro en aquellas dos sortijas en los cabos del pectoral.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Y los dos cabos de las dos trenzas pusieron en los dos engastes, los cuales pusieron sobre las hombreras del efod en la parte delantera de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'E hicieron otras dos sortijas de oro, que pusieron en los dos cabos del pectoral en su orilla a la parte baja del efod.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Hicieron más otras dos sortijas de oro, las cuales pusieron en las dos hombreras del efod abajo en la parte delantera, delante de su juntura sobre el cinto del efod.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Y ataron el pectoral de sus sortijas a las sortijas del mismo efod con un cordón de cárdeno, para que estuviese sobre el cinto del mismo efod, y el pectoral no se apartase del efod, como Jehová lo había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Hizo también el manto del efod de obra de tejedor todo de cárdeno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Con su collar en medio de él, como el collar de un coselete, con un borde al rededor del collar, porque no se rompiese.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'E hicieron en las orillas del manto las granadas de cárdeno, y púrpura, y carmesí, y lino torcido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Hicieron también las campanillas de oro puro, las cuales campanillas pusieron entre las granadas por las orillas del manto al derredor, entre las granadas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Una campanilla y una granada, una campanilla y una granada, en las orillas del manto, al rededor, para ministrar, como Jehová lo mandó a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'E hicieron las túnicas de lino fino de obra de tejedor para Aarón, y para sus hijos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'Asimismo la mitra de lino fino, y las orladuras de los chapeos de lino fino, y los pañetes de lino, de lino torcido.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Ítem, el cinto de lino torcido, y de cárdeno, y púrpura, y carmesí, de obra de recamador, como Jehová lo mandó a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Ítem, hicieron la plancha, la corona de la santidad, de oro puro, y escribieron en ella de grabadura de sello el rotulo, Santidad a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Y pusieron sobre ella un cordón de cárdeno para ponerla sobre la mitra encima, como Jehová lo había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, '¶ Y fue acabada toda la obra del tabernáculo, del tabernáculo del testimonio. E hicieron los hijos de Israel como Jehová lo había mandado a Moisés: así lo hicieron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Y trajeron el tabernáculo a Moisés; el tabernáculo y todos sus vasos, sus corchetes, sus tablas, sus barras, y sus columnas y sus basas,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'Y la cobertura de pieles rojas de carneros, y la cobertura de pieles de tejones, y el velo del pabellón,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'El arca del testimonio, y sus barras, y la cubierta,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'La mesa, todos sus vasos, y el pan de la proposición,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'El candelero limpio, sus candilejas, las candilejas de la ordenanza, y todos sus vasos, y el aceite de la luminaria,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'Y el altar de oro, y el aceite de la unción, y el perfume aromático, y el pabellón para la puerta del tabernáculo,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'El altar de metal, y su criba de metal, sus barras, y todos sus vasos, y la fuente y su basa,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'Las cortinas del patio, y sus columnas y sus basas, y el pabellón para la puerta del patio, y sus cuerdas, y sus estacas, y todos los vasos del servicio del tabernáculo, del tabernáculo del testimonio,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Las vestiduras del servicio para ministrar en el santuario, las santas vestiduras para Aarón el sacerdote, y las vestiduras de sus hijos para ministrar en el sacerdocio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Conforme a todas las cosas que Jehová había mandado a Moisés, así hicieron los hijos de Israel toda la obra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Y vio Moisés toda la obra, y he aquí que la habían hecho como Jehová había mandado; y bendíjolos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Y Jehová habló a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'En el día del mes primero, el primero del mes harás levantar el tabernáculo, el tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Y pondrás en él el arca del testimonio, y cubrirla has con el velo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Y meterás la mesa, y ponerla has en orden: y meterás el candelero, y encenderás sus lámparas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Y pondrás el altar de oro para el perfume delante del arca del testimonio: y pondrás el pabellón de la puerta del tabernáculo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Después pondrás el altar del holocausto delante de la puerta del tabernáculo, del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Luego pondrás la fuente entre el tabernáculo del testimonio y el altar: y pondrás agua en ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Finalmente pondrás el patio al rededor, y el pabellón de la puerta del patio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Y tomarás el aceite de la unción, y ungirás el tabernáculo, y todo lo que estará en él, y santificarlo has con todos sus vasos, y será santo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Y ungirás también el altar del holocausto, y todos sus vasos: y santificarás el altar, y será el altar santidad de santidades.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Asimismo ungirás la fuente y su basa, y santificarla has.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Y harás llegar a Aarón y a sus hijos a la puerta del tabernáculo del testimonio, y lavarlos has con agua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Y harás vestir a Aarón las santas vestiduras, y ungirle has, y consagrarle has, para que sea mi sacerdote.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Después harás llegar sus hijos, y vestirles has las túnicas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Y ungirles has como ungiste a su padre, y serán mis sacerdotes: y será, que su unción les será por sacerdocio perpetuo por sus generaciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'E hizo Moisés conforme a todo lo que Jehová le mandó: así lo hizo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Así en el mes primero, en el segundo año al primero del mes, el tabernáculo fue levantado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'E hizo Moisés levantar el tabernáculo, y puso sus basas, y puso sus tablas, y puso sus barras, e hizo alzar sus columnas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Y tendió la tienda sobre el tabernáculo, y puso el cobertor sobre el tabernáculo encima, como Jehová había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Y tomó, y puso el testimonio en el arca; y puso las barras sobre el arca: y la cubierta sobre el arca encima.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Y metió el arca en el tabernáculo: y puso el velo de la tienda, y cubrió el arca del testimonio, como Jehová había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Y puso la mesa en el tabernáculo del testimonio al lado del aquilón del pabellón fuera del velo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Y sobre ella puso por orden los panes delante de Jehová, como Jehová había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Y puso el candelero en el tabernáculo del testimonio en frente de la mesa, al lado del mediodía del pabellón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Y encendió las lámparas delante de Jehová, como Jehová había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Puso también el altar de oro en el tabernáculo del testimonio, delante del velo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Y encendió sobre él el perfume aromático, como Jehová había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Puso asimismo el pabellón de la puerta del tabernáculo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Y puso el altar del holocausto a la puerta del tabernáculo, del tabernáculo del testimonio: y ofreció sobre el holocausto y presente, como Jehová había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Y puso la fuente entre el tabernáculo del testimonio y el altar: y puso en ella agua para lavar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Y lavaban en ella Moisés, y Aarón, y sus hijos sus manos y sus pies.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Cuando entraban en el tabernáculo del testimonio, y cuando se llegaban al altar se lavaban, como Jehová había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Finalmente levantó el patio en derredor del tabernáculo y del altar, y puso el pabellón de la puerta del patio: y así acabó Moisés la obra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, '¶ Entonces una nube cubrió el tabernáculo del testimonio, y la gloria de Jehová hinchió el tabernáculo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Y no podía Moisés entrar en el tabernáculo del testimonio, porque la nube estaba sobre él, y la gloria de Jehová lo tenía lleno.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Y cuando la nube se alzaba del tabernáculo, los hijos de Israel se movían en todas sus partidas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Y si la nube no se alzaba, no se partían, hasta el día que ella se alzaba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Porque la nube de Jehová estaba de día sobre el tabernáculo, y el fuego estaba de noche en él, en ojos de toda la casa de Israel en todas sus partidas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Y llamó Jehová a Moisés, y habló con él desde el tabernáculo del testimonio, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Habla a los hijos de Israel, y díles: Cuando alguno de entre vosotros ofreciere ofrenda a Jehová de animales, de vacas, o de ovejas haréis vuestra ofrenda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Si su ofrenda fuere holocausto de vacas, macho perfecto lo ofrecerá; a la puerta del tabernáculo del testimonio lo ofrecerá, según su voluntad, delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Y pondrá su mano sobre la cabeza del holocausto, y él lo aceptará para expiarlo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Entonces degollará el becerro en la presencia de Jehová, y los sacerdotes, hijos de Aarón, ofrecerán la sangre, y rociarla han sobre el altar al derredor, el cual está a la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Y desollará el holocausto, y cortarlo ha en sus piezas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Y los hijos de Aarón sacerdote pondrán fuego sobre el altar, y compondrán la leña sobre el fuego.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Luego los sacerdotes, hijos de Aarón, compondrán las piezas, la cabeza y el redaño, sobre la leña, que está sobre el fuego que está encima del altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Y sus intestinos y sus piernas lavará con agua, y el sacerdote hará perfume de todo sobre el altar; y esto será holocausto, ofrenda encendida de olor de holganza a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, '¶ Y si su ofrenda fuere de ovejas, de los corderos, o de las cabras para holocausto, macho perfecto lo ofrecerá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Y degollarlo ha al lado del altar al aquilón delante de Jehová; y los sacerdotes, hijos de Aarón, rociarán su sangre sobre el altar al derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Y cortarlo ha en sus piezas, y su cabeza y su redaño; y el sacerdote las compondrá sobre la leña que está sobre el fuego, que está encima del altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Y sus entrañas, y sus piernas lavará con agua, y ofrecerlo ha todo el sacerdote, y hará de ello perfume sobre el altar; y esto será holocausto, ofrenda encendida de olor de holganza a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, '¶ Y si el holocausto se hubiere de ofrecer a Jehová de aves, ofrecerá su ofrenda de tórtolas, o de palominos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Y el sacerdote la ofrecerá sobre el altar, y quitarle ha la cabeza, y hará perfume sobre el altar, y su sangre será exprimida sobre la pared del altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Y quitarle ha el buche con las plumas, lo cual echará junto al altar hacia el oriente en el lugar de las cenizas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Y henderla ha por entre sus alas; mas no la partirá: y el sacerdote hará de ella perfume sobre el altar, sobre la leña que está sobre el fuego, y esto será holocausto, ofrenda encendida de olor de holganza a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Y cuando alguna persona ofreciere ofrenda de presente a Jehová, su ofrenda será flor de harina, sobre la cual echará aceite, y pondrá sobre ella incienso.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Y traerla ha a los sacerdotes, hijos de Aarón, y de allí tomará su puño lleno de su flor de harina; y de su aceite, con todo su incienso, y el sacerdote hará perfume de ello sobre el altar: y esto será ofrenda encendida de olor de holganza a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Y la sobra del presente será de Aarón y de sus hijos, santidad de santidades de las ofrendas encendidas de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, '¶ Y cuando ofrecieres ofrenda de presente cocida en horno, serán tortas de flor de harina sin levadura amasadas con aceite, y hojaldres sin levadura untadas con aceite.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, '¶ Mas si tu presente fuere ofrenda de sartén, será de flor de harina sin levadura amasada con aceite,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'La cual partirás en piezas, y echarás aceite sobre ella: esto será presente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, '¶ Y si tu presente fuere ofrenda de cazuela, hacerse ha de flor de harina con aceite.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Y traerás a Jehová el presente que se hará de estas cosas, y ofrecerlo has al sacerdote, el cual lo llegará al altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Y tomará el sacerdote de aquel presente su memorial, y hará perfume sobre el altar; y esto será ofrenda encendida de olor de holganza a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Y la sobra del presente será de Aarón y de sus hijos, santidad de santidades de las ofrendas encendidas de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, '¶ Ningún presente que ofreciereis a Jehová, será con levadura; porque de ninguna cosa leuda, ni de ninguna miel haréis ofrenda de perfume a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'En la ofrenda de las primicias las ofreceréis a Jehová; mas no subirán sobre el altar por olor de holganza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, '¶ Y toda ofrenda de tu presente, salarás con sal, y no harás que falte jamás la sal de la alianza de tu Dios de tu presente: en toda ofrenda tuya ofrecerás sal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, '¶ Y si ofrecieres a Jehová presente de primicias, tostarás al fuego las espigas verdes, y el grano majado ofrecerás por ofrenda de tus primicias.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Y pondrás sobre ella aceite, y pondrás también sobre ella incienso, y esto será presente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Y el sacerdote hará el perfume de su memorial de su grano majado, y de su aceite con todo su incienso, y esto será ofrenda encendida a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Y si su ofrenda fuere sacrificio de paces; si hubiere de ofrecer el sacrificio de vacas, macho, o hembra, sin tacha lo ofrecerá delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Y pondrá su mano sobre la cabeza de su ofrenda, y degollarla ha a la puerta del tabernáculo del testimonio, y los sacerdotes, hijos de Aarón, esparcirán su sangre sobre el altar al derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Luego ofrecerá del sacrificio de las paces por ofrenda encendida a Jehová el sebo que cubre los intestinos, y todo el sebo que está sobre los intestinos,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'Y los dos riñones, y el sebo que está sobre ellos, y sobre los ijares, y quitará el redaño que está sobre el hígado con los riñones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Y los hijos de Aarón harán de ello perfume sobre el altar con el holocausto que estará sobre la leña que está encima del fuego: y esto será ofrenda de olor de holganza a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, '¶ Mas si de ovejas fuere su ofrenda para sacrificio de paces a Jehová, macho o hembra, sin tacha lo ofrecerá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Si ofreciere cordero por su ofrenda, ofrecerlo ha delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'Y pondrá su mano sobre la cabeza de su ofrenda, y después la degollará delante del tabernáculo del testimonio: y los hijos de Aarón esparcirán su sangre sobre el altar al derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Y del sacrificio de las paces ofrecerá por ofrenda encendida a Jehová su sebo, y la cola entera, la cual quitará de delante el espinazo, y el sebo que cubre los intestinos, y todo el sebo que está sobre ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'Asimismo los dos riñones, y el sebo que está sobre ellos, y el que está sobre los ijares, y quitará el redaño de sobre el hígado con los riñones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Y el sacerdote hará de ello perfume sobre el altar; y esto será vianda de ofrenda encendida a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, '¶ Mas si cabra fuere su ofrenda, ofrecerla ha delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Y pondrá su mano sobre la cabeza de ella, y degollarla ha delante del tabernáculo del testimonio, y los hijos de Aarón esparcirán su sangre sobre el altar en derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Después ofrecerá de ella su ofrenda, por ofrenda encendida a Jehová, el sebo que cubre los intestinos, y todo el sebo que está sobre ellos,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'Y los dos riñones, y el sebo que está sobre ellos, y el que está sobre los ijares, y quitará el redaño de sobre el hígado con los riñones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Y el sacerdote hará perfume de ello sobre el altar: y esto será vianda de ofrenda encendida de olor de holganza a Jehová. Todo el sebo es de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, '¶ Estatuto perpetuo por vuestras edades en todas vuestras habitaciones: Ningún sebo, ni ninguna sangre comeréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Habla a los hijos de Israel, diciendo: cuando alguna persona pecare por yerro en alguno de los mandamientos de Jehová, que no se han de hacer, e hiciere alguno de ellos;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Si sacerdote ungido pecare, según el pecado del pueblo, ofrecerá por su pecado, que pecó, un novillo hijo de vaca perfecto a Jehová por expiación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Y traerá el novillo a la puerta del tabernáculo del testimonio delante de Jehová, y pondrá su mano sobre la cabeza del novillo, y degollarlo ha delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Y el sacerdote ungido tomará de la sangre del novillo, y traerla ha al tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Y mojará el sacerdote su dedo en la sangre, y esparcirá de aquella sangre siete veces delante de Jehová hacia el velo del santuario.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Y pondrá el sacerdote de aquesta sangre sobre los cuernos del altar del perfume aromático delante de Jehová, que está en el tabernáculo del testimonio; y toda la otra sangre del novillo echará al cimiento del altar del holocausto, que está a la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Y todo el sebo del novillo de la expiación tomará de él, el sebo que cubre los intestinos, y todo el sebo que está sobre ellos,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'Y los dos riñones, y el sebo que está sobre ellos, y el que está sobre los ijares, y el redaño de sobre el hígado quitará con los riñones,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'De la manera que se quita del buey del sacrificio de las paces, y hará el sacerdote perfume de ello sobre el altar del holocausto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Y el cuero del novillo, y toda su carne con su cabeza y sus piernas, y sus intestinos y su estiércol;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'Finalmente todo el novillo sacará fuera del campo a un lugar limpio, a donde se echan las cenizas, y quemarlo ha en fuego sobre la leña: en el lugar donde se echan las cenizas será quemado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, '¶ Y si toda la multitud de Israel hubiere errado, y el negocio fuere oculto a la congregación, y hubieren hecho alguno de los mandamientos de Jehová, que no se han de hacer, y hubieren pecado:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'Desde que fuere entendido el pecado sobre que pecaron, entonces la congregación ofrecerá un novillo hijo de vaca por expiación, y traerlo han delante del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Y los ancianos de la congregación pondrán sus manos sobre la cabeza del novillo delante de Jehová, y degollarán el novillo delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Y el sacerdote ungido meterá de la sangre del novillo en el tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Y mojará el sacerdote su dedo en la misma sangre, y esparcirá siete veces delante de Jehová hacia el velo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Y de aquella sangre pondrá sobre los cuernos del altar que está delante de Jehová en el tabernáculo del testimonio, y toda la otra sangre derramará al cimiento del altar del holocausto, que está a la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Y quitarle ha todo el sebo, y hará del perfume sobre el altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Y con el novillo hará como hizo del novillo de la expiación así hará de él; y así los expiará el sacerdote, y habrán perdón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Y sacará el novillo fuera del campo, y quemarlo ha como quemó el primer novillo; y esto será expiación de la congregación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, '¶ Y cuando pecare el príncipe, e hiciere por yerro alguno de todos los mandamientos de Jehová su Dios, que no se han de hacer, y pecare:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'Desde que le fuere notificado su pecado en que pecó, entonces ofrecerá por su ofrenda un macho de cabrío, macho perfecto;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Y pondrá su mano sobre la cabeza, del macho cabrío, y degollarlo ha en el lugar donde se degüella el holocausto delante de Jehová; y esto será expiación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Y tomará el sacerdote con su dedo de la sangre de la expiación, y pondrá sobre los cuernos del altar del holocausto: y la otra sangre derramará al cimiento del altar del holocausto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Y todo su sebo quemará sobre el altar, como el sebo del sacrificio de las paces: así lo expiará el sacerdote de su pecado, y habrá perdón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, '¶ Ítem, si alguna persona del pueblo de la tierra pecare por yerro, haciendo alguno de los mandamientos de Jehová, que no se han de hacer, y pecare:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'Desde que le fuere notorio su pecado que pecó, traerá por su ofrenda una cabra de las cabras, sin tacha, hembra, por su pecado que pecó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Y pondrá su mano sobre la cabeza de la expiación, y degollará la expiación en el lugar del holocausto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Luego tomará el sacerdote en su dedo de su sangre, y pondrá sobre los cuernos del altar del holocausto, y toda la otra sangre derramará al cimiento del altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Y quitarle ha todo su sebo, de la manera que fue quitado el sebo del sacrificio de las paces, y hará perfume el sacerdote sobre el altar en olor de holganza a Jehová; y así le reconciliará el sacerdote, y habrá perdón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Y si trajere cordero para su ofrenda por el pecado, hembra perfecta traerá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Y pondrá su mano sobre la cabeza de la expiación, y degollarla ha por expiación en el lugar donde se degüella el holocausto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Después tomará el sacerdote con su dedo de la sangre de la expiación, y pondrá sobre los cuernos del altar del holocausto; y toda la otra sangre derramará al cimiento del altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Y quitarle ha todo su sebo, como fue quitado el sebo del sacrificio de las paces, y hará el sacerdote perfume de ello sobre el altar en ofrenda encendida a Jehová; y así le reconciliará el sacerdote de su pecado, que pecó, y habrá perdón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Ítem, cuando alguna persona pecare, que hubiere oído la voz del juramento, y él fuere testigo que vio, o supo, si no lo denunciare, él llevará su pecado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Ítem, la persona que hubiere tocado en cualquiera cosa inmunda, sea cuerpo muerto de bestia inmunda, o cuerpo muerto de animal inmundo, o cuerpo muerto de serpiente inmunda, y ella no lo supiere, será inmunda y habrá pecado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'O si tocare hombre inmundo en cualquiera inmundicia suya, de que es inmundo, y no lo supiere, mas lo supiere después, habrá pecado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Ítem, la persona que jurare, pronunciando de labios de hacer mal, o bien en todas las cosas que el hombre pronuncia con juramento, y él no lo supiere, mas después lo entendiere, el que será culpado en una de estas cosas,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Y será, que cuando alguno pecare en alguna de estas cosas, confesará aquello en que pecó;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Y traerá su expiación a Jehová por su pecado que pecó, una cordera hembra de la manada, o una cabra de las cabras por expiación, y el sacerdote le reconciliará de su pecado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Y si no alcanzare para un cordero, traerá en expiación por su pecado que pecó, dos tórtolas, o dos palominos a Jehová; el uno para expiación, y el otro para holocausto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Y traerlos ha al sacerdote, el cual ofrecerá primero el que es por expiación, y quitará su cabeza de delante de su cuello, mas no apartará;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Y esparcirá de la sangre de la expiación sobre la pared del altar; y lo que sobrare de la sangre exprimirlo ha al cimiento del altar; y esto será expiación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Y del otro hará holocausto conforme al rito; y así le reconciliará el sacerdote de su pecado que pecó, y habrá perdón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Mas si no alcanzare su mano para dos tórtolas, o dos palominos, traerá por su ofrenda por su pecado que pecó, la diezma de un efa de flor de harina por expiación. No pondrá sobre ella aceite, ni pondrá sobre ella incienso, porque es expiación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Mas traerla ha al sacerdote, y el sacerdote tomará de ella su puño lleno para su memorial, y hará perfume sobre el altar sobre las otras ofrendas encendidas a Jehová; y esto será expiación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Y así le reconciliará el sacerdote de su pecado, que pecó, en alguna de estas cosas, y habrá perdón; y será del sacerdote, como el presente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, '¶ Habló más Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Cuando alguna persona hiciere prevaricación, y pecare por yerro en las cosas santificadas a Jehová, traerá por su expiación a Jehová un carnero sin tacha del ganado, conforme a tu estimación, de dos siclos de plata del siclo del santuario, por el pecado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Y lo que hubiere pecado del santuario, pagará, y añadirá sobre ella su quinto, y darlo ha al sacerdote, y el sacerdote le reconciliará con el carnero de la expiación, y habrá perdón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, '¶ Ítem, Si alguna persona pecare, e hiciere alguno de todos los mandamientos de Jehová, que no se han de hacer, y no lo supiere, y así pecó, llevará su pecado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Y traerá un carnero perfecto de las ovejas, conforme a tu estimación, por expiación, al sacerdote, y el sacerdote la reconciliará, de su yerro que erró sin saber, y habrá perdón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Pecado es, y pecando pecó a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Cuando alguna persona pecare, e hiciere prevaricación contra Jehová, y negare a su prójimo lo encomendado, o depuesto en mano, o robó, o que calumnió a su prójimo,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'O que halló lo perdido, y lo negare, y jurare falso en alguna de todas las cosas en que suele pecar el hombre,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Y será que cuando pecare, y ofendiere, volverá el robo que robó, o la calumnia que calumnió, o el depósito, que se le encomendó, o lo perdido que halló,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'O todo aquello sobre que hubiere jurado falso, y pagarlo ha por entero, y añadirá sobre ello su quinto, para aquel cuyo era, y pagarlo ha el día de su expiación:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Y por su expiación traerá a Jehová, un carnero sin tacha de las ovejas conforme a tu estimación, al sacerdote, para la expiación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Y el sacerdote le reconciliará delante de Jehová, y habrá perdón de cualquiera de todas las cosas, en que suele ofender el hombre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, '¶ Habló más Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Manda a Aarón y a sus hijos, diciendo: Esta es la ley del holocausto: Es holocausto, porque es encendido sobre el altar toda la noche hasta la mañana, y el fuego del altar arderá en él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'El sacerdote se vestirá su vestidura de lino, y vestirse ha pañetes de lino sobre su carne; y cuando el fuego hubiere consumido el holocausto, él apartará las cenizas de sobre el altar, y ponerlas ha junto al altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Después desnudarse ha sus vestiduras, y vestirse ha de otras vestiduras, y sacará las cenizas fuera del real al lugar limpio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Y el fuego encendido sobre el altar, no se apagará, mas el sacerdote pondrá en él leña cada mañana, y compondrá sobre él el holocausto, y quemará sobre él los sebos de las paces.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'El fuego arderá continuamente en el altar; no se apagará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, '¶ Ítem, esta es la ley del presente: Ofrecerlo han los hijos de Aarón delante de Jehová, delante del altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Y tomará de él con su puño, de la flor de harina del presente, y de su aceite, y todo el incienso, que estará sobre el presente, y hará perfume sobre el altar en olor de reposo por su memorial a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Y la resta de ella comerán Aarón y sus hijos, sin levadura se comerá en el lugar santo, en el patio del tabernáculo del testimonio la comerán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'No se cocerá con levadura: yo la he dado por su porción de mis ofrendas encendidas, santidad de santidades es como la expiación del pecado y como la expiación de la culpa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Todos los varones de los hijos de Aarón comerán de ella; fuero perpetuo será para vuestras generaciones de las ofrendas encendidas de Jehová: toda cosa que tocare en ellas será santificada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, '¶ Habló más Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Esta será la ofrenda de Aarón y de su hijos, que ofrecerán a Jehová el día que serán ungidos: La diezma de un efa de flor de harina, presente continuo, la mitad a la mañana y la mitad a la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'En sartén con aceite será hecha, frita la traerás, los pedazos cocidos del presente ofrecerás a Jehová en olor de holganza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Y el sacerdote ungido en su lugar, de sus hijos, la hará estatuto perpetuo de Jehová, toda se quemará en perfume.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Y todo presente de sacerdote será quemado todo, no se comerá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, '¶ Habló más Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Habla a Aarón, y a sus hijos, diciendo: Esta será la ley de la expiación del pecado: En el lugar donde será degollado el holocausto, será degollada la expiación por el pecado delante de Jehová, porque santidad de santidades es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'El sacerdote que la ofreciere por expiación, la comerá: en el lugar santo será comida, en el patio del tabernáculo del testimonio:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Todo lo que en su carne tocare, será santificado, y si cayere de su sangre sobre el vestido, aquello sobre que cayere, lavarás en el lugar santo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Y el vaso de barro, en que fuere cocida, será quebrado: y si fuere cocida en vaso de metal, será acicalado, y lavado con agua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Todo varón de los sacerdotes la comerá; santidad de santidades es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Y toda expiación de cuya sangre se metiere en el tabernáculo del testimonio para reconciliar en el santuario, no se comerá, con fuego será quemada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Ítem, esta será la ley de la expiación de la culpa: Será santidad de santidades.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'En el lugar donde degollaren el holocausto, degollarán la expiación de la culpa, y esparcirá su sangre sobre el altar en derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Y de ella ofrecerá todo su sebo, la cola, y el sebo que cubre los intestinos,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'Y los dos riñones, y el sebo que está sobre ellos, y el que está sobre los ijares; y el redaño de sobre el hígado quitará con los riñones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Y el sacerdote hará de ello perfume sobre el altar en ofrenda encendida a Jehová; y esta será expiación de la culpa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Todo varón de los sacerdotes la comerá; será comida en el lugar santo; porque es santidad de santidades.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, '¶ Como la expiación por el pecado así será la expiación de la culpa: una misma ley tendrán, será del sacerdote que habrá hecho la reconciliación con ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Y el sacerdote que ofreciere holocausto de alguno, el cuero del holocausto que ofreciere, será del sacerdote.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Ítem, todo presente que se cociere en horno, y todo el que fuere hecho en sartén, o en cazuela, será del sacerdote que lo ofreciere.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Ítem, todo presente amasado con aceite, y seco, será de todos los hijos de Aarón, tanto al uno como al otro,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, '¶ Ítem, esta será la ley del sacrificio de las paces que se ofrecerá a Jehová:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Si se ofreciere en hacimiento de gracias, ofrecerá por sacrificio de hacimiento de gracias tortas sin levadura amasadas con aceite, y hojaldres sin levadura untados con aceite, y flor de harina frita en tortas amasadas con aceite.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Con tortas de pan leudo ofrecerá su ofrenda en el sacrificio del hacimiento de gracias de sus paces.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Y de toda la ofrenda ofrecerá uno por ofrenda a Jehová: del sacerdote que esparciere la sangre de los pacíficos, de él será.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Mas la carne del sacrificio del hacimiento de gracias de sus pacíficos el día que se ofreciere, se comerá: no dejarán de ella nada para otro día.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Mas si el sacrificio de su ofrenda fuere voto, o voluntario, el día que ofreciere su sacrificio será comido, y lo que de él quedare, comerse ha el día siguiente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Y lo que quedare para el tercero día de la carne del sacrificio, será quemado en el fuego.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Y si se comiere algo de la carne del sacrificio de sus paces el tercero día, el que lo ofreciere no será acepto, ni le será contado: abominación será, y la persona que de él comiere, llevará su pecado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Y la carne que tocare a alguna cosa inmunda, no se comerá: será quemada en fuego: mas cualquiera limpio comerá de aquesta carne.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Y la persona que comiere la carne del sacrificio de paces, el cual es de Jehová, estando inmundo, aquella persona será cortada de sus pueblos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Ítem, la persona que tocare alguna cosa inmunda, en inmundicia de hombre, o en animal inmundo, o en toda abominación inmunda, y comiere de la carne del sacrificio de las paces, el cual es de Jehová, aquella persona será cortada de sus pueblos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, '¶ Habló más Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Habla a los hijos de Israel, diciendo: Ningún sebo de buey, ni de cordero, ni de cabra, comeréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'El sebo de animal mortecino, y el sebo del arrebatado se aparejará para todo uso, mas no lo comeréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Porque cualquiera que comiere sebo de animal, del cual se ofrece a Jehová ofrenda encendida, la persona que lo comiere, será cortada de sus pueblos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Ítem, ninguna sangre comeréis en todas vuestras habitaciones, así de aves como de bestias.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Cualquiera persona que comiere alguna sangre, la tal persona será cortada de sus pueblos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, '¶ Habló más Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Habla a los hijos de Israel, diciendo: El que ofreciere sacrificio de sus paces a Jehová, traerá su ofrenda del sacrificio de sus paces a Jehová;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Sus manos traerán las ofrendas encendidas a Jehová: traerá el sebo con el pecho: el pecho para mecerlo de mecedura delante de Jehová:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Y del sebo hará perfume el sacerdote en el altar; y el pecho será de Aarón, y de sus hijos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Y la espalda derecha daréis de los sacrificios de vuestras paces para ser apartada, para el sacerdote.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'El que de los hijos de Aarón ofreciere la sangre de las paces, y el sebo, de él será la espalda derecha en porción.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Porque el pecho de la mecedura, y la espalda de la apartadura yo lo he tomado de los hijos de Israel, de los sacrificios de sus paces, y lo he dado a Aarón el sacerdote, y a sus hijos, por estatuto perpetuo de los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Esta es la unción de Aarón, y la unción de sus hijos, de las ofrendas encendidas a Jehová desde el día que él los llegó para ser sacerdotes de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'Las cuales porciones mandó Jehová que les diesen, desde el día que él los ungió de entre los hijos de Israel por estatuto perpetuo por sus generaciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Esta es la ley del holocausto, del presente, de la expiación, por el pecado, y de la expiación de la culpa, y de las consagraciones, y del sacrificio de las paces.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'La cual mandó Jehová a Moisés en el monte de Sinaí, el día que mandó a los hijos de Israel que ofreciesen sus ofrendas a Jehová en el desierto de Sinaí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Habló más Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Toma a Aarón, y a sus hijos con él, y las vestiduras, y el aceite de la unción, y el novillo de la expiación, y los dos carneros, y el canastillo de los panes cenceños.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Y junta toda la congregación a la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'E hizo Moisés como Jehová le mandó: y la congregación se juntó a la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Y dijo Moisés a la congregación: Esto es lo que Jehová ha mandado hacer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Entonces Moisés hizo llegar a Aarón, y a sus hijos, y lavólos con agua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Y puso sobre él la túnica, y ciñóle con el cinto, después vistióle el manto, y puso sobre él el efod, y ciñóle con el cinto del efod, y apretóle con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Y púsole encima el pectoral, y puso en el pectoral el Urim y Tumim.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Después puso la mitra sobre su cabeza, y sobre la mitra delante de su rostro puso la plancha de oro, la corona de la santidad, como Jehová había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Y tomó Moisés el aceite de la unción, y ungió el tabernáculo, y todas las cosas que estaban en él, y santificólas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Y esparció de él sobre el altar siete veces, y ungió el altar, y todos sus vasos, y la fuente y su basa, para santificarlas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Y derramó del aceite de la unción sobre la cabeza de Aarón, y ungióle para santificarle.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Después Moisés hizo llegar los hijos de Aarón, y vistióles las túnicas, y ciñóles con cintos, y apretóles los chapeos, como Jehová lo había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'E hizo llegar el novillo de la expiación, y puso Aarón y sus hijos sus manos sobre la cabeza del novillo de la expiación:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Y degollólo, y Moisés tomó la sangre, y puso con su dedo sobre los cuernos del altar al derredor, y expió el altar, y echó la otra sangre al cimiento del altar, y santificólo para reconciliar sobre él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Después tomó todo el sebo que estaba sobre los intestinos, y el redaño del hígado, y los dos riñones, y el sebo de ellos, e hizo Moisés perfume sobre el altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Mas el novillo, y su cuero, y su carne, y su estiércol quemó con fuego fuera del real, como Jehová lo había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Después hizo llegar el carnero del holocausto; y Aarón y sus hijos pusieron sus manos sobre la cabeza del carnero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Y lo degolló, y esparció Moisés la sangre sobre el altar en derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Y cortó el carnero, en sus piezas; y Moisés hizo perfume de la cabeza, y piezas, y sebo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Y lavó en agua los intestinos y piernas; y quemó Moisés todo el carnero sobre el altar: holocausto es en olor de holganza, ofrenda encendida a Jehová, como Jehová lo había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Después hizo llegar el otro carnero, el carnero de las consagraciones; y Aarón y sus hijos pusieron sus manos sobre la cabeza del carnero:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Y lo degolló, y tomó Moisés de su sangre, y puso sobre la ternilla de la oreja derecha de Aarón, y sobre el dedo pulgar de su mano derecha, y sobre el dedo pulgar de su pie derecho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'E hizo llegar los hijos de Aarón, y puso Moisés de la sangre sobre la ternilla de sus orejas derechas, y sobre los pulgares de sus manos derechas, y sobre los pulgares de sus pies derechos: y esparció Moisés la otra sangre sobre el altar en derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Después tomó el sebo, y la cola, y todo el sebo que estaba sobre los intestinos, y el redaño del hígado, y los dos riñones y el sebo de ellos, y la espalda derecha.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Y del canastillo de los panes cenceños, que estaban delante de Jehová, tomó una torta sin levadura, y una torta de pan de aceite, y una hojaldre, y púsolo con el sebo, y con la espalda derecha.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Y púsolo todo en las manos de Aarón, y en las manos de sus hijos, e hízolo mecer en mecedura delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Después tomó aquellas cosas Moisés de las manos de ellos, e hizo perfume en el altar sobre el holocausto: son las consagraciones en olor de holganza, ofrenda encendida a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Y tomó Moisés el pecho, y meciólo en mecedura delante de Jehová: del carnero de las consagraciones aquella fue la parte de Moisés, como Jehová lo había mandado al mismo Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Luego tomó Moisés del aceite de la unción, y de la sangre, que estaba sobre el altar, y esparció sobre Aarón, sobre sus vestiduras, y sobre sus hijos, y sobre las vestiduras de sus hijos con él: y santificó a Aarón y a sus vestiduras, y a sus hijos, y a las vestiduras de sus hijos con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Y dijo Moisés a Aarón, y a sus hijos: Cocéd la carne a la puerta del tabernáculo del testimonio, y comédla allí con el pan, que está en el canastillo de las consagraciones, como yo he mandado, diciendo: Aarón y sus hijos la comerán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Y lo que sobrare de la carne y del pan, quemarlo heis con fuego.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'De la puerta del tabernáculo del testimonio no saldréis en siete días, hasta el día que se cumplieren los días de vuestras consagraciones: porque por siete días seréis consagrados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'De la manera que hoy se ha hecho, mandó hacer Jehová para expiaros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Y a la puerta del tabernáculo del testimonio estaréis día y noche por siete días, y haréis la guarda delante de Jehová, y no moriréis, porque así me ha sido mandado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'E hizo Aarón y sus hijos todas las cosas que mandó Jehová por mano de Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Y fue en el día octavo que Moisés llamó a Aarón y a sus hijos, y a los ancianos de Israel;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Y dijo a Aarón: Tómate un becerro, hijo de vaca, para expiación; y un carnero para holocausto, sin tacha, y ofréce los delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Y a los hijos de Israel hablarás, diciendo: Tomád un macho de cabrío para expiación, y un becerro, y un cordero de un año perfectos para holocausto:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Asimismo un buey, y un carnero para sacrificio de paces, que sacrifiqueis delante de Jehová, y un presente amasado en aceite, porque Jehová se apareció hoy a vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Y tomaron lo que mandó Moisés delante del tabernáculo del testimonio, y llegóse toda la congregación, y pusiéronse delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Entonces Moisés dijo: Esto es lo que mandó Jehová que hagáis, y la gloria de Jehová se os aparecerá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Y dijo Moisés a Aarón: Llégate al altar, y haz tu expiación, y tu holocausto: y haz la reconciliación por ti y por el pueblo: y haz la ofrenda del pueblo, y haz la reconciliación por ellos, como ha mandado Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Entonces llegóse Aarón al altar, y degolló su becerro de la expiación que era por él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Y los hijos de Aarón le llegaron la sangre, y él mojó su dedo en la sangre, y puso sobre los cuernos del altar: y la otra sangre derramó al cimiento del altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Y del sebo, y riñones, y redaño del hígado de la expiación hizo perfume sobre el altar; como Jehová lo había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Mas la carne y cuero quemó en fuego fuera del real.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Degolló asimismo el holocausto, y los hijos de Aarón le llegaron la sangre, la cual él esparció sobre el altar al derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Después le llegaron el holocausto por sus piezas, y la cabeza; y él hizo perfume sobre el altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Después lavó los intestinos, y las piernas, y quemólo con el holocausto sobre el altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, '¶ Ofreció también la ofrenda del pueblo, y tomó el macho cabrío de la expiación, que era del pueblo, y degollólo, y limpiólo como al primero.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Y ofreció el holocausto, e hizo según el rito.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Ofreció también el presente, e hinchió su mano de él, e hizo perfume sobre el altar allende del holocausto de la mañana.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Degolló asimismo el buey y el carnero, que era del pueblo, en sacrificio de paces: y los hijos de Aarón le llegaron la sangre, la cual él esparció sobre el altar al derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Y los sebos del buey, y del carnero, la cola, y la cubierta, y los riñones, y el redaño del hígado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Y pusieron los sebos sobre los pechos, y él quemó los sebos sobre el altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Empero los pechos y la espalda derecha meció Aarón con mecimiento delante de Jehová, como Jehová lo había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, '¶ Después Aarón alzó sus manos al pueblo y bendíjolos: y descendió de hacer la expiación, y el holocausto, y el sacrificio de las paces.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, '¶ Y vinieron Moisés y Aarón al tabernáculo del testimonio, y salieron, y bendijeron al pueblo: y la gloria de Jehová se apareció a todo el pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Y salió fuego de delante de Jehová, el cual consumió el holocausto y los sebos sobre el altar; y viéndolo todo el pueblo alabaron, y cayeron sobre sus faces.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Y los hijos de Aarón, Nadab y Abiú tomaron cada uno su incensario, y pusieron fuego en ellos, sobre el cual pusieron perfume, y ofrecieron delante de Jehová fuego extraño, que él nunca les mandó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Entonces salió fuego de delante de Jehová, que los quemó, y murieron delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Entonces dijo Moisés a Aarón: Esto es lo que habló Jehová, diciendo: En mis allegados me santificaré, y en presencia de todo el pueblo seré glorificado. Y Aarón calló.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Y llamó Moisés a Misael, y a Elisafán, hijos de Oziel, tio de Aarón, y díjoles: Llegáos y sacád a vuestros hermanos de delante del santuario fuera del campo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Y ellos llegaron, y sacáronlos con sus túnicas fuera del campo, como dijo Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, '¶ Entonces Moisés dijo a Aarón, y a Eleazar, y a Itamar, sus hijos: No descubráis vuestras cabezas, ni rompáis vuestros vestidos, y no moriréis ni se airará sobre toda la congregación: empero vuestros hermanos, toda la casa de Israel, lamentarán el incendio que Jehová ha hecho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Ni saldréis de la puerta del tabernáculo del testimonio, porque moriréis: por cuanto el aceite de la unción de Jehová está sobre vosotros. Y ellos hicieron conforme al dicho de Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, '¶ Y Jehová habló a Aarón, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Tú y tus hijos contigo no beberéis vino ni sidra, cuando hubiereis de entrar en el tabernáculo del testimonio, y no moriréis: estatuto perpetuo será por vuestras generaciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Y esto para hacer diferencia entre lo santo y lo profano, y entre lo inmundo y lo limpio;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'Y para enseñar a los hijos de Israel todos los estatutos, que Jehová les ha dicho por mano de Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, '¶ Y Moisés dijo a Aarón, y a Eleazar, y a Itamar, sus hijos, que habían quedado: Tomád el presente que queda de las ofrendas encendidas a Jehová y comédlo sin levadura junto al altar, porque es santidad de santidades.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Por tanto comerlo heis en el lugar santo, porque esto será fuero para ti, y fuero para tus hijos de las ofrendas encendidas a Jehová; porque así me ha sido mandado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Y el pecho de la mecedura, y la espalda del alzamiento comeréis en lugar limpio, tú y tus hijos y tus hijas contigo; porque por fuero para ti, y fuero para tus hijos son dados de los sacrificios de las paces de los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'La espalda del alzamiento, y el pecho de la mecedura con las ofrendas encendidas de los sebos traerán para que lo mezas con mecedura delante de Jehová: y será fuero perpetuo tuyo, y de tus hijos contigo, como Jehová lo ha mandado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, '¶ Y Moisés demandó el macho cabrío de la expiación, y hallóse que era quemado; y enojóse contra Eleazar e Itamar, los hijos de Aarón, que habían quedado, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '¿Por qué no comisteis la expiación en lugar santo? porque es santidad de santidades; y él la dio a vosotros para llevar la iniquidad de la congregación para que sean reconciliados delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Veis que su sangre no fue metida en el santuario de adentro: habíaisla de comer en el santuario, como yo mandé.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Y respondió Aarón a Moisés: He aquí, hoy han ofrecido su expiación, y su holocausto delante de Jehová, con todo eso me han acontecido estas cosas; pues si comiera la expiación hoy, ¿fuera acepto a Jehová?');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Y oyó Moisés esto, y aceptólo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Y habló Jehová a Moisés, y a Aarón, diciéndoles:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Hablád a los hijos de Israel, diciendo: Estos son los animales, que comeréis de todos los animales que están sobre la tierra:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Todo animal de pesuño, y que tiene los pesuños hendidos, y que rumia, de entre los animales, este comeréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Estos empero no comeréis de los que rumian, y de los que tienen pesuño: El camello; porque rumia, mas no tiene pesuño, tenerlo heis por inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Ítem, el conejo; porque rumia, mas no tiene pesuño, tenerlo heis por inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Ítem, la liebre; porque rumia, mas no tiene pesuño, tenerla heis por inmunda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'También el puerco; porque tiene pesuño, y es de pesuños hendidos, mas no rumia, tenerlo heis por inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'De la carne de ellos no comeréis, ni tocaréis su cuerpo muerto, tenerlos heis por inmundos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, '¶ Esto comeréis de todas las cosas que están en las aguas: Todas las cosas que tienen alas y escamas en las aguas de la mar, y en los ríos, aquellas comeréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Mas todas las cosas que no tienen alas, ni escamas, en la mar, y en los ríos, así de todo reptil de agua, como de toda cosa viviente que está en las aguas, tenerlas heis en abominación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Y seros han en abominación: de su carne no comeréis, y sus cuerpos muertos abominaréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Todo lo que no tuviere alas y escamas en las aguas tendréis en abominación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, '¶ Ítem, de las aves, estas tendréis en abominación, no se comerán, abominación serán: El águila, el azor, el esmerejón,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'El milano, y el buitre según su especie,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'Todo cuervo según su especie,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'El avestruz, y el mochuelo, y la garceta, y el gavilán según su especie,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'Y el halcón, y la gaviota, y la lechuza,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'Y el calamón, y el cisne, y el pelícano,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'Y la cigüeña, y el cuervo marino, según su especie, y la abubilla, y el murciélago.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, '¶ Todo reptil de ave que anduviere sobre cuatro pies tendréis en abominación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Empero esto comeréis de todo reptil de aves que anda sobre cuatro pies que tuviere piernas allende de sus pies, para saltar con ellas sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Estos comeréis de ellos: La langosta según su especie, y el langostín según su especie, y el haregol según su especie, y el hahgab según su especie.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Todo otro reptil de aves, que tenga cuatro pies, tendréis en abominación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, '¶ Y por estas cosas seréis inmundos: Cualquiera que tocare a sus cuerpos muertos, será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Ítem, cualquiera que llevare sus cuerpos muertos, lavará sus vestidos, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Todo animal de pesuño, mas que no tiene el pesuño hendido, ni rumia, tendréis por inmundo: cualquiera que los tocare, será inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Y cualquiera que anda sobre sus palmas de todos los animales que andan a cuatro pies, tendréis por inmundo: cualquiera que tocare sus cuerpos muertos, será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Y el que llevare sus cuerpos muertos, lavará sus vestidos, y será inmundo hasta la tarde: tenerlos heis por inmundos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Ítem, estos tendréis por inmundos de los reptiles que van arrastrando sobre la tierra: La comadreja, y el ratón, y la rana según su especie,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'Y el erizo, y el lagarto, y el caracol, y la babosa, y el topo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Estos tendréis por inmundos de todos los reptiles: cualquiera que los tocare, cuando fueren muertos, será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Y todo aquello sobre que cayere alguna cosa de ellos después de muertos, será inmundo, así vaso de madera, como vestido, o piel, o saco: cualquiera instrumento con que se hace obra, será metido en agua, y será inmundo hasta la tarde, y así será limpio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Ítem, todo vaso de barro dentro del cual cayere algo de ellos, todo lo que estuviere en él, será inmundo, y el vaso quebraréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Toda vianda que se come, sobre la cual viniere el agua, será inmunda: y toda bebida que se bebiere, en todo vaso será inmunda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Y todo aquello, sobre que cayere algo de su cuerpo muerto, será inmundo. El horno y la chimenea serán derribados: inmundos son, y por inmundos los tendréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Empero la fuente, o la cisterna donde se recojen aguas, serán limpias: mas lo que hubiere tocado en sus cuerpos muertos, será inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Ítem, si cayere algo de sus cuerpos muertos sobre alguna simiente sembrada, que estuviere sembrada, será limpia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Mas si hubiere puesta agua sobre la simiente, y cayere algo de sus cuerpos muertos sobre ella, tenerla heis por inmunda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Ítem, si algún animal que tuviereis para comer, se muriere, el que tocare su cuerpo muerto, será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Y el que comiere de su cuerpo muerto, lavará sus vestidos, y será inmundo hasta la tarde: asimismo el que sacare su cuerpo muerto, lavará sus vestidos, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Ítem, todo reptil que va arrastrando sobre la tierra, abominación es, no se comerá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Todo lo que anda sobre el pecho, y todo lo que anda sobre cuatro, o más pies, de todo reptil, que anda arrastrando sobre la tierra, no comeréis, porque son abominación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, '¶ No ensuciéis vuestras almas en ningún reptil, que anda arrastrando, ni os contaminéis en ellos, ni seáis inmundos por ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Porque yo soy Jehová vuestro Dios: por tanto vosotros os santificaréis, y seréis santos, porque yo soy santo: y no ensuciéis vuestras almas en ningún reptil, que anduviere arrastrando sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Porque yo soy Jehová, que os hago subir de la tierra de Egipto para seros por Dios. Seréis pues santos, porque yo soy santo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Esta es la ley de los animales, y de las aves, y de toda cosa viva, que se mueve en las aguas, y de toda cosa que anda arrastrando sobre la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Para hacer diferencia entre inmundo y limpio; y entre los animales que se pueden comer, y los animales que no se pueden comer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Habla a los hijos de Israel, diciendo: La mujer cuando concibiere, y pariere varón, será inmunda siete días: conforme a los días del apartamiento de su menstruo será inmunda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Y al octavo día circuncidará la carne de su prepucio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Y treinta y tres días estará en las sangres de su purgación: ninguna cosa santa tocará, ni vendrá al santuario, hasta que sean cumplidos los días de su purgación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Y si pariere hembra, será inmunda dos semanas, conforme a su apartamiento, y sesenta y seis días estará en las sangres de su purificación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, '¶ Y desde que los días de su purgación fueren cumplidos, por hijo, o por hija, traerá un cordero de un año para holocausto; y un palomino, o una tórtola para expiación, a la puerta del tabernáculo del testimonio, al sacerdote.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Y ofrecerlo ha delante de Jehová, y reconciliarla ha, y será limpia del flujo de su sangre. Esta es la ley de la que pariere macho, o hembra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Y si no alcanzare su mano asaz para cordero, entonces tomará dos tórtolas, o dos palominos, uno para holocausto, y otro para expiación: y reconciliarla ha el sacerdote, y será limpia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Y habló Jehová a Moisés, y a Aarón, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'El hombre, cuando hubiere en el cutis de su carne hinchazón, o postilla, o mancha blanca, que hubiere en el cutis de su carne como llaga de lepra, será traído a Aarón el sacerdote, o a uno de los sacerdotes sus hijos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Y el sacerdote mirará la llaga en el cutis de la carne: si el pelo en la llaga se volvió blanco, y la llaga pareciere más profunda que la tez de la carne, llaga de lepra es; y el sacerdote lo mirará, y le dará por inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Y si en el cutis de su carne hubiere mancha blanca, mas no pareciere más profunda que la tez, ni su pelo se hubiere vuelto blanco, entonces el sacerdote encerrará al llagado siete días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Y al séptimo día el sacerdote lo mirará: y si la llaga a su parecer, hubiere estancado, que la llaga no hubiere crecido en el cutis, entonces el sacerdote le encerrará por siete días la segunda vez.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Después el sacerdote la mirará al séptimo día la segunda vez; y si parece haberse oscurecido la llaga, y que no ha crecido la llaga en el cutis, entonces el sacerdote le dará por limpio: postilla era, y lavará sus vestidos, y será limpio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Mas si creciendo hubiere crecido la postilla en el cutis después que fue mostrado al sacerdote para ser limpio, será mirado otra vez del sacerdote:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Y el sacerdote lo mirará, y si la postilla hubiere crecido en el cutis, el sacerdote le dará por inmundo, lepra es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, '¶ Cuando hubiere llaga de lepra en el hombre, será traído al sacerdote;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Y el sacerdote mirará, y si pareciere hinchazón blanca en el cutis, la cual haya vuelto el pelo blanco, y hubiere sanidad de carne viva en la hinchazón,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'Lepra es envejecida en el cutis de su carne, y darle ha por inmundo el sacerdote, y no le encerrará, porque es inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Mas si la lepra hubiere reverdecido en el cutis, y la lepra cubriere todo el cutis del llagado desde su cabeza hasta sus pies a toda vista de ojos del sacerdote,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'Entonces el sacerdote mirará, y si la lepra hubiere cubierto toda su carne, dará por limpio al llagado: todo es vuelto blanco: limpio es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Mas el día que pareciere en él la carne viva, será inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Y el sacerdote mirará la carne viva, y darle ha por inmundo. ¿Carne viva es? inmundo es: lepra es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Mas cuando la carne viva tornare, y se volviere blanca, entonces vendrá al sacerdote;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Y el sacerdote mirará, y si la llaga se hubiere tornado blanca, el sacerdote dará la llaga por limpia, y él será limpio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, '¶ Y la carne cuando hubiere en ella, en su cutis alguna apostema, y se sanare.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'Y sucediere en el lugar de la apostema hinchazón blanca, o mancha blanca en bermejecida, será mostrado al sacerdote.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Y el sacerdote mirará, y si pareciere estar más baja que su tez, y su pelo se hubiere vuelto blanco, el sacerdote le dará por inmundo: llaga de lepra es, que reverdeció en la apostema.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Y si el sacerdote la considerare, y no pareciere en ella pelo blanco, ni estuviere más baja que la tez, antes estuviere oscura, entonces el sacerdote le encerrará por siete días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Y si se fuere extendiendo por el cutis, entonces el sacerdote le dará por inmundo: llaga es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Empero si la mancha blanca se estuviere en su lugar, que no haya crecido, quemadura de la apostema es: y el sacerdote le dará por limpio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, '¶ Ítem, la carne cuando en su cutis hubiere quemadura de fuego, y hubiere en la sanadura del fuego mancha blanca, bermeja, o blanca.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'El sacerdote la mirará, y si el pelo se hubiere vuelto blanco en la mancha, y pareciere estar más profunda que la tez, lepra es que reverdeció en la quemadura, y el sacerdote le dará por inmundo: llaga de lepra es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Mas si el sacerdote la mirare, y no pareciere en la mancha pelo blanco, ni estuviere más baja que la tez, antes estuviere oscura, encerrarle ha el sacerdote siete días:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Y al séptimo día el sacerdote la mirará: si se hubiere ido extendiendo por el cutis, el sacerdote le dará por inmundo: llaga de lepra es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Empero si la mancha se estuviere en su lugar y no se hubiere extendido en el cutis, antes estuviere oscura, hinchazón es de la quemadura: el sacerdote le dará por limpio, que señal de la quemadura es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, '¶ Ítem, cualquier hombre o mujer que le saliere llaga en la cabeza, o en la barba,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'El sacerdote mirará la llaga, y si pareciere estar más profunda que la tez, y el pelo en ella fuere rubio, delgado, entonces el sacerdote le dará por inmundo: tiña es, lepra es de la cabeza o de la barba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Mas cuando el sacerdote hubiere mirado la llaga de la tiña, y no pareciere estar más profunda que la tez, ni fuere en ella el pelo negro, el sacerdote encerrará al llagado de la tiña siete días:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Y al séptimo día el sacerdote mirará la llaga, y si la tiña no pareciere haberse extendido, ni hubiere en ella pelo rubio, ni pareciere la tiña más profunda que la tez,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'Entonces trasquilarle han, mas no trasquilarán la tiña: y encerrará el sacerdote al que tiene la tiña por siete días la segunda vez.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Y al séptimo día mirará el sacerdote la tiña, y si la tiña no hubiere crecido en el cutis, ni pareciere estar más profunda que la tez, el sacerdote le dará por limpio, y lavará sus vestidos, y será limpio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Empero si la tiña se hubiere ido extendiendo en el cutis después de su purificación,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Entonces el sacerdote la mirará, y si la tiña hubiere crecido en el cutis, no busque el sacerdote el pelo rubio; inmundo es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Mas si le pareciere que la tiña se está en su lugar, y que ha salido en ella el pelo negro, la tiña es sana, él será limpio, y el sacerdote le dará por limpio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, '¶ Ítem, cualquier hombre o mujer, cuando en el cutis de su carne hubiere manchas, manchas blancas,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'El sacerdote mirará, y si en el cutis de su carne parecieren manchas oscuras blancas, empeine es que reverdeció en el cutis; limpio es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, '¶ Ítem, el varón cuando se le pelare la cabeza, calvo es, limpio es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Y si a la parte de su rostro se le pelare la cabeza, antecalvo es, limpio es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Mas cuando en la calva o en la antecalva hubiere llaga blanca bermeja, lepra es que reverdece en su calva o en su antecalva.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Entonces el sacerdote lo mirará, y si pareciere la hinchazón de la llaga blanca bermeja, en su calva o antecalva, como el parecer de la lepra de la tez de la carne,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'Leproso es, inmundo es, el sacerdote le dará luego por inmundo: en su cabeza tiene su llaga.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, '¶ Y el leproso en quien hubiere tal llaga, sus vestidos serán rompidos, y su cabeza descubierta, y embozado pregonará: Inmundo, inmundo,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Todo el tiempo que la llaga estuviere en él, será inmundo, inmundo será: habitará solo, su morada será fuera del real.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, '¶ Ítem, cuando en el vestido hubiere llaga de lepra, en vestido de lana, o en vestido de lino,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'O en estambre, o en trama de lino, o de lana, o en piel, o en cualquiera obra de piel;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'Y que la llaga sea verde, o bermeja, en vestido, o en piel, o en estambre, o en trama, o en cualquiera obra de piel; llaga de lepra es, mostrarse ha al sacerdote:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Y el sacerdote mirará la llaga, y encerrará la cosa llagada siete días:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Y al séptimo día mirará la llaga: y si la llaga hubiere crecido en el vestido, o estambre, o en la trama, o en piel, o en cualquiera obra que se hace de pieles, lepra roedora es la tal llaga: inmunda será.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Será quemado el vestido, o estambre, o trama de lana, o de lino, o cualquiera obra de pieles, en que hubiere tal llaga; porque lepra roedora es, en fuego será quemada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Y si el sacerdote mirare, y no pareciere que la llaga se haya extendido en el vestido, o estambre, o en la trama, o en cualquiera obra de pieles,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'Entonces el sacerdote mandará que laven donde la llaga está, y encerrarle ha por siete días la segunda vez.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Y el sacerdote mirará después que la llaga fuere lavada, y si pareciere que la llaga no ha mudado su parecer, ni la llaga ha crecido, inmunda es, quemarla has en fuego: llaga es penetrante en su calva o en su antecalva.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Mas si el sacerdote la viere, y pareciere que la llaga se ha oscurecido después que fue lavada, cortarla ha del vestido o de la piel, o del estambre, o de la trama:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Y si más pareciere en el vestido, o estambre, o trama, o en cualquiera alhaja de pieles reverdeciendo en ella, quemarlo has en el fuego aquello donde hubiere tal llaga.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Empero el vestido, o estambre, o trama, o cualquiera cosa de piel, que lavares, y que la llaga se le quitare, lavarse ha segunda vez, y entonces será limpia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Esta es la ley de la llaga de la lepra del vestido de lana, o de lino, o del estambre, o de la trama, o de cualquiera cosa de piel, para que sea dado por limpio, o por inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Esta será la ley del leproso cuando se limpiare: Será traído al sacerdote:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'Y el sacerdote, saldrá fuera del real: y mirará el sacerdote, y verá, como es sana la llaga de la lepra del leproso:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'Y mandará el sacerdote, que se tomen para el que se limpia dos avecillas vivas, limpias, y palo de cedro, y grana, y hisopo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Y mandará el sacerdote matar la una avecilla en un vaso de barro, sobre aguas vivas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Y tomará el avecilla viva, y el palo de cedro, y la grana, y el hisopo, y mojarlo ha con el avecilla viva en la sangre de la avecilla muerta sobre las aguas vivas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Y esparcirá sobre el que se limpia de la lepra siete veces, y darle ha por limpio: y soltará al avecilla viva sobre la haz del campo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Y el que se limpia, lavará sus vestidos y raerá todos sus pelos, y lavarse ha con agua, y será limpio: y después entrará en el real, y morará fuera de su tienda siete días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Y será, que al séptimo día raerá todos sus pelos, su cabeza, y su barba, y las cejas de sus ojos: finalmente raerá todo su pelo, y lavará sus vestidos, y lavará su carne en aguas, y será limpio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Y el día octavo tomará dos corderos perfectos, y una cordera de un año sin tacha, y tres décimas de flor de harina para presente amasada con aceite, y un log de aceite.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Y el sacerdote que limpia, presentará al que se ha de limpiar con aquellas cosas delante de Jehová a la puerta del tabernáculo del testimonio;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Y tomará el sacerdote el un cordero, y ofrecerlo ha por expiación de la culpa con el log de aceite, y mecerlo ha todo con mecedura delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Y degollará al cordero en el lugar donde degüellan la expiación por el pecado, y el holocausto en el lugar del santuario, porque como la expiación por el pecado, así también la expiación por la culpa es del sacerdote: santidad de santidades es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Y tomará el sacerdote de la sangre de la expiación por la culpa, y pondrá el sacerdote sobre la ternilla de la oreja derecha del que se limpia, y sobre el pulgar de su mano derecha, y sobre el pulgar de su pie derecho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Asimismo tomará el sacerdote del log de aceite, y echará sobre la palma de su mano izquierda;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Y mojará su dedo derecho en el aceite, que tiene en su mano izquierda, y esparcirá del aceite con su dedo siete veces delante de Jehová:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Y de lo que quedare del aceite que tiene en su mano, pondrá el sacerdote sobre la ternilla de la oreja derecha del que se limpia, y sobre el pulgar de su mano derecha, y sobre el pulgar de su pie derecho sobre la sangre de la expiación por la culpa:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Y lo que quedare del aceite que tiene en su mano, pondrá sobre la cabeza del que se limpia, y así le reconciliará el sacerdote delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Y hará el sacerdote la expiación y limpiará al que se limpia de su inmundicia, y después degollará el holocausto:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Y hará subir el sacerdote el holocausto, y el presente sobre el altar, y así le reconciliará el sacerdote, y será limpio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, '¶ Mas si fuere pobre, que no alcanzare su mano, entonces tomará un cordero para expiación por la culpa para la mecedura para reconciliarse; y una décima de flor de harina amasada con aceite para presente, y un log de aceite;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Y dos tórtolas, o dos palominos, lo que alcanzare su mano; y el uno será para expiación por el pecado, y el otro para holocausto:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Las cuales cosas traerá al octavo día de su purificación al sacerdote a la puerta del tabernáculo del testimonio delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Y el sacerdote tomará el cordero de la expiación por la culpa, y el log de aceite, y mecerlo ha el sacerdote con mecedura delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Y degollará el cordero de la expiación por la culpa, y tomará el sacerdote de la sangre de la expiación por la culpa, y pondrá sobre la ternilla de la oreja derecha del que se limpia, y sobre el pulgar de su mano derecha, y sobre el pulgar de su pie derecho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Y el sacerdote echará del aceite sobre la palma de su mano izquierda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'Y esparcirá el sacerdote con su dedo derecho del aceite, que tiene en su mano izquierda siete veces delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Y el sacerdote pondrá del aceite, que tiene en su mano sobre la ternilla de la oreja derecha del que se limpia, y sobre el pulgar de su mano derecha, y sobre el pulgar de su pie derecho en el lugar de la sangre de la expiación por la culpa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Y lo que sobrare del aceite que el sacerdote tiene en su mano, ponerlo ha sobre la cabeza del que se limpia para reconciliarle delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Asimismo ofrecerá la una de las tórtolas, o de los palominos, lo que alcanzare su mano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'El uno de lo que alcanzare su mano, expiación por el pecado, y el otro en holocausto allende del presente, y así reconciliará el sacerdote al que se ha de limpiar delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Esta es la ley del que hubiere tenido llaga de lepra, cuya mano no alcanzare para limpiarse.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, '¶ Y habló Jehová a Moisés y a Aarón, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Cuando hubiereis entrado en la tierra de Canaán, la cual yo os doy en posesión, y yo pusiere llaga de lepra en alguna casa de la tierra de vuestra posesión,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'Vendrá aquel cuya fuera la casa, y dará aviso al sacerdote, diciendo: Como llaga ha aparecido en mi casa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Entonces mandará el sacerdote, y limpiarán la casa antes que el sacerdote entre a mirar la llaga, porque no sea contaminado todo lo que estuviere en la casa: y después el sacerdote entrará a mirar la casa:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Y mirará la llaga; y si parecieren llagas en las paredes de la casa verdes, profundas, o bermejas, las cuales parecieren más hondas que la haz de la pared,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'El sacerdote saldrá de la casa a la puerta de la casa, y cerrará la casa por siete días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Y al séptimo día volverá el sacerdote, y mirará: y si la llaga hubiere crecido en las paredes de la casa,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Entonces mandará el sacerdote, y arrancarán las piedras en las cuales estuviere la llaga, y echarlas han fuera de la ciudad en el lugar inmundo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Y hará descortezar la casa por de dentro al derredor, y el polvo, que descortezaren, derramarán fuera de la ciudad en el lugar inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Y tomarán otras piedras, y ponerlas han en el lugar de las piedras, y tomarán otra tierra y embarrarán la casa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Y si la llaga volviere a reverdecer en aquella casa, después que hizo arrancar las piedras, y descortezar la casa, y después que fue embarrada,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Entonces el sacerdote entrará, y mirará, y si pareciere haberse extendido la llaga en la casa, lepra roedora está en la tal casa; inmunda es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Entonces derribará la casa, sus piedras, y sus maderos, y todo el polvo de la casa; y sacarlo ha todo fuera de la ciudad a el lugar inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Y cualquiera que entrare en la tal casa en todos los días que la mandó cerrar, será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Y el que durmiere en la tal casa, lavará sus vestidos. Y el que comiere en la tal casa lavará sus vestidos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, '¶ Mas si entrare el sacerdote, y mirare, y viere que la llaga no se ha extendido en la casa después que fue embarrada, el sacerdote dará la casa por limpia, porque la llaga sanó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Y tomará para limpiar la casa dos avecillas, y palo de cedro, y grana, e hisopo;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Y degollará la una avecilla en un vaso de barro sobre aguas vivas;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Y tomará el palo de cedro, y el hisopo, y la grana, y el avecilla viva, y mojarlo ha todo en la sangre de la avecilla muerta y en las aguas vivas, y rociará la casa siete veces:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Y limpiará la casa con la sangre del avecilla, y con las aguas vivas, y con el avecilla viva, y el palo de cedro, y el hisopo, y la grana.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Y soltará la avecilla viva fuera de la ciudad sobre la haz del campo, y así reconciliará la casa, y será limpia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Esta es la ley de toda plaga de lepra, y de la tiña,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'Y de la lepra del vestido, y de la casa,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'Y de la hinchazón, y de la postilla, y de la mancha blanca;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'Para enseñar cuando es inmundo, y cuando es limpio: Esta es la ley de la lepra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Y habló Jehová a Moisés y a Aarón, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Hablád a los hijos de Israel y decídles: Cualquier varón, cuando su simiente manare de su carne, será inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Y esta será su inmundicia en su flujo: Si su carne distiló por causa de su flujo, o si su carne se cerró por causa de su flujo, él será inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Toda cama en que se acostare el que tuviere flujo, será inmunda: y toda cosa sobre que se sentare, será inmunda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Y cualquiera que tocare a su cama, lavará sus vestidos, y a sí se lavará con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Y el que se sentare sobre aquello en que se hubiere sentado el que tiene flujo, lavará sus vestidos: y a sí se lavará con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Ítem, el que tocare la carne del que tiene flujo, lavará sus vestidos, y a sí se lavará con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Ítem, si el que tiene flujo, escupiere sobre el limpio, lavará sus vestidos, y a sí se lavará con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Ítem, toda cabalgadura sobre que cabalgare el que tuviere flujo, será inmunda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Ítem, cualquiera que tocare cualquiera cosa que estuviere debajo de él, será inmundo hasta la tarde: y el que lo llevare, lavará sus vestidos, y a sí se lavará con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Ítem, todo aquel a quien tocare el que tiene flujo, y no lavare con agua sus manos, lavará sus vestidos, y a sí se lavará con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Ítem, el vaso de barro en que tocare el que tiene flujo, será quebrado, y todo vaso de madera será lavado con agua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, '¶ Y cuando se hubiere limpiado de su flujo el que tiene flujo, contarse ha siete días desde su purificación, y lavará sus vestidos, y lavará su carne en aguas vivas, y será limpio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Y el octavo día tomarse ha dos tórtolas, o dos palominos, y vendrá delante de Jehová a la puerta del tabernáculo del testimonio, y darlos ha al sacerdote:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Y el sacerdote los hará, el uno expiación, y el otro holocausto: y el sacerdote le reconciliará de su flujo delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, '¶ Ítem, el hombre, cuando saliere de él derramadura de simiente, lavará en aguas toda su carne, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Y todo vestido, o toda piel sobre la cual hubiere de la derramadura de la simiente, se lavará con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Y la mujer con la cual el varón tuviere ayuntamiento de simiente, ambos se lavarán con agua, y serán inmundos hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, '¶ Ítem, la mujer cuando tuviere flujo de sangre, y que su flujo fuere en su carne, siete días estará en su apartamiento; y cualquiera que tocare en ella, será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Y todo aquello sobre que ella se acostare en su apartamiento, será inmundo: y todo aquello sobre que se asentare, será inmundo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Ítem, cualquiera que tocare a su cama, lavará sus vestidos, y a sí se lavará con agua: y será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Ítem, cualquiera que tocare cualquiera alhaja, sobre la cual ella se hubiere sentado, lavará sus vestidos, y a sí se lavará con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Ítem, si alguna cosa estuviere sobre la cama, o sobre la silla en que ella se hubiere sentado, el que tocare en ella, será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Y si alguno durmiere con ella, y que la inmundicia de ella fuere sobre él, él será inmundo por siete días, y toda cama sobre que durmiere, será inmunda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Ítem, la mujer, cuando manare el flujo de su sangre por muchos días, fuera del tiempo de su costumbre, o cuando tuviere flujo de sangre más de su costumbre, todo el tiempo del flujo de su inmundicia será como en los días de su costumbre, inmunda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Toda cama en que durmiere todo el tiempo de su flujo, le será como la cama de su costumbre: Y toda alhaja sobre que se sentare, será inmunda conforme a la inmundicia de su costumbre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Cualquiera que tocare en ellas será inmundo: y lavará sus vestidos, y a sí se lavará con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Y cuando fuere limpia de su flujo, contarse ha siete días, y después será limpia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Y el octavo día tomarse ha dos tórtolas, o dos palominos, y traerlos ha al sacerdote a la puerta del tabernáculo del testimonio:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Y el sacerdote hará el uno expiación, y el otro holocausto, y reconciliarla ha el sacerdote delante de Jehová del flujo de su inmundicia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Y apartaréis los hijos de Israel de sus inmundicias, y no morirán por sus inmundicias, ensuciando mi tabernáculo, que está entre ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Esta es la ley del que tiene flujo de simiente, y del que sale derramadura de simiente, para ser inmundo a causa de ella;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'Y de la que padece su costumbre: y del que padeciere su flujo, sea macho, o sea hembra: y del hombre que durmiere con mujer inmunda.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Y habló Jehová a Moisés, después que murieron los dos hijos de Aarón, cuando se llegaron delante de Jehová, y murieron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Y Jehová dijo a Moisés: Di a Aarón tu hermano, que no entre en todo tiempo en el santuario del velo a dentro delante de la cubierta, que está sobre el arca, porque no muera: porque yo apareceré en la nube sobre la cubierta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Con esto entrará Aarón en el santuario: con un novillo hijo de vaca por expiación, y un carnero en holocausto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'La túnica santa de lino se vestirá, y sobre su carne tendrá pañetes de lino, y ceñirse ha el cinto de lino, y con la mitra de lino se cubrirá, que son las santas vestiduras: y lavará su carne con agua, y vestirlas ha.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Y de la congregación de los hijos de Israel tomará dos machos de las cabras para expiación, y un carnero para holocausto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Y hará llegar Aarón el novillo de la expiación que era suyo, y hará la reconciliación por sí y por su casa.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, '¶ Después tomará los dos machos cabríos, y presentarlos ha delante de Jehová, a la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Y echará suertes Aarón sobre los dos machos de cabrío, la una suerte por Jehová, y la otra suerte por Azazel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Y hará llegar Aarón el macho cabrío sobre el cual cayere la suerte por Jehová, y hacerlo ha por expiación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Y el macho de cabrío, sobre el cual cayere la suerte por Azazel, presentará vivo delante de Jehová, para hacer la reconciliación sobre él, para enviarlo a Azazel al desierto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Y hará llegar Aarón el novillo que era suyo para expiación, y hará la reconciliación por sí y por su casa, y degollará el novillo, que era suyo, por expiación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Después tomará el incensario lleno de brasas de fuego del altar de delante de Jehová, y sus puños llenos del perfume aromático molido, y meterlo ha del velo a dentro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Y pondrá el perfume sobre el fuego delante de Jehová, y la nube del perfume cubrirá la cubierta, que está sobre el testimonio, y no morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Después tomará de la sangre del novillo, y esparcirá con su dedo hacia la cubierta hacia el oriente: hacia la cubierta esparcirá de aquella sangre siete veces con su dedo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Después degollará el macho cabrío, que era del pueblo, para expiación, y meterá la sangre de él del velo adentro: y hará de su sangre, como hizo de la sangre del novillo, y esparcirá sobre la cubierta, y delante de la cubierta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Y limpiará el santuario de las inmundicias de los hijos de Israel, y de sus rebeliones, y de todos sus pecados: de la misma manera hará también al tabernáculo del testimonio; el cual mora entre ellos, entre sus inmundicias.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Y ningún hombre estará en el tabernáculo del testimonio, cuando él entrare a hacer la reconciliación en el santuario, hasta que él salga, y haya hecho la reconciliación por sí, y por su casa, y por toda la congregación de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Y saldrá al altar, que está delante de Jehová, y expiarlo ha, y tomará de la sangre del novillo, y de la sangre del macho de cabrío, y pondrá sobre los cuernos del altar al derredor.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Y esparcirá sobre él de la sangre con su dedo siete veces, y limpiarlo ha, y santificarlo ha de las inmundicias de los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Y cuando hubiere acabado de expiar el santuario, y el tabernáculo del testimonio, y el altar, hará llegar el macho cabrío vivo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Y pondrá Aarón ambas sus manos sobre la cabeza del macho de cabrío vivo, y confesará sobre él todas las iniquidades de los hijos de Israel, y todas sus rebeliones, y todos sus pecados, y ponerlos ha sobre la cabeza del macho cabrío, y enviarlo ha al desierto por mano de algún varón aparejado para esto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Y aquel macho de cabrío llevará sobre sí todas las iniquidades de ellos a tierra inhabitable, y enviará el macho cabrío al desierto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Después vendrá Aarón al tabernáculo del testimonio, y desnudarse ha las vestiduras de lino, que había vestido para entrar en el santuario, y ponerlas ha allí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Y lavará su carne con agua en el lugar del santuario, y vestirse ha sus vestidos: después saldrá, y hará su holocausto, y el holocausto del pueblo, y hará la reconciliación por sí y por el pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Y del sebo de la expiación hará perfume sobre el altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Y el que hubiere llevado el macho de cabrío a Azazel, lavará sus vestidos, y su carne lavará con agua, y después entrará en el real.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Y sacará fuera del real el novillo de la expiación por el pecado, y el macho cabrío de la expiación por la culpa, la sangre de los cuales fue metida para hacer la expiación en el santuario: y quemarán en el fuego sus pellejos, y sus carnes, y su estiércol:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Y el que lo quemare, lavará sus vestidos, y su carne lavará con agua, y después entrará en el real.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, '¶ Esto tendréis por estatuto perpetuo: En el mes séptimo a los diez del mes afligiréis vuestras personas, y ninguna obra haréis, el natural ni el extranjero, que peregrina entre vosotros;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Porque en este día os reconciliará para limpiaros: y seréis limpios de todos vuestros pecados delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Sábado de holganza será a vosotros, y afligiréis vuestras personas por estatuto perpetuo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Y hará la reconciliación el sacerdote que fuere ungido, y cuya mano hubiere sido llena para ser sacerdote en lugar de su padre, y vestirse ha las vestiduras de lino, las vestiduras santas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Y expiará el santo santuario, y el tabernáculo del testimonio: expiará también el altar, y los sacerdotes, y a todo el pueblo de la congregación expiará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Y esto tendréis por estatuto perpetuo para expiar los hijos de Israel de todos sus pecados una vez en el año. Y Moisés lo hizo como Jehová le mandó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Habla a Aarón, y a sus hijos, y a todos los hijos de Israel, y díles: Esto es lo que ha mandado Jehová, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Cualquier varón de la casa de Israel, que degollare buey, o cordero, o cabra en el real, o fuera del real,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'Y no lo trajere a la puerta del tabernáculo del testimonio para ofrecer ofrenda a Jehová delante del tabernáculo de Jehová, sangre será imputada al tal varón: sangre derramó; el tal varón será cortado de entre su pueblo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Porque traigan los hijos de Israel sus sacrificios que sacrificaren sobre la haz del campo: porque los traigan a Jehová a la puerta del tabernáculo del testimonio al sacerdote, y sacrifiquen sacrificios de paces ellos a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Y el sacerdote esparza la sangre sobre el altar de Jehová a la puerta del tabernáculo del testimonio, y haga perfume del sebo en olor de holganza a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Y nunca más sacrificarán sus sacrificios a los demonios, tras los cuales fornican: esto tendrán por estatuto perpetuo por sus edades.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Ítem, decirles has: Cualquier varón de la casa de Israel, o de los extranjeros, que peregrinan entre vosotros, que ofreciere holocausto, o sacrificio,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'Y no lo trajere a la puerta del tabernáculo del testimonio, para hacerlo a Jehová, el tal varón también, será cortado de sus pueblos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, '¶ Ítem, cualquier varón de la casa de Israel, y de los extranjeros que peregrinan entre ellos, que comiere alguna sangre, yo pondré mi rostro contra la persona, que comiere sangre, y yo la cortaré de entre su pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Porque el alma de la carne en la sangre está: y yo os la he dado para expiar vuestras personas sobre el altar: por lo cual la misma sangre expiará la persona:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Por tanto he dicho a los hijos de Israel: Ninguna persona de vosotros comerá sangre, ni el extranjero, que peregrina entre vosotros comerá sangre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Y cualquier varón de los hijos de Israel, y de los extranjeros, que peregrinan entre ellos que tomare caza de animal, o de ave, que sea de comer, derramará su sangre, y cubrirla ha con tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Porque el alma de toda carne en su sangre está su alma: por tanto he dicho a los hijos de Israel: No comeréis la sangre de ninguna carne, porque el alma de toda carne es su sangre: cualquiera que la comiere, será cortado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, '¶ Ítem, cualquiera persona que comiere cosa mortecina, o despedazada, así de los naturales como de los extranjeros, lavará sus vestidos, y a sí se lavará con agua, y será inmunda hasta la tarde, y limpiarse ha.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Y si no lavare, ni lavare su carne, llevará su iniquidad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Habla a los hijos de Israel, y díles: Yo soy Jehová vuestro Dios:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'No haréis como hacen en la tierra de Egipto, en la cual morasteis: ni haréis como hacen en la tierra de Canaán, en la cual yo os meto: ni andaréis en sus estatutos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Mis derechos haréis, y mis estatutos guardaréis andando en ellos: yo soy Jehová vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Por tanto mis estatutos y mis derechos guardaréis, los cuales haciendo el hombre, vivirá en ellos: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, '¶ Ningún varón se allegue a ninguna cercana de su carne, para descubrir las vergüenzas: yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Las vergüenzas de tu padre, o las vergüenzas de tu madre no descubrirás: tu madre es; no descubrirás sus vergüenzas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Las vergüenzas de la mujer de tu padre no descubrirás; las vergüenzas de tu padre son.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Las vergüenzas de tu hermana, hija de tu padre, o hija de tu madre, nacida en casa, o nacida fuera, no descubrirás sus vergüenzas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Las vergüenzas de la hija de tu hijo, o de la hija de tu hija, no descubrirás sus vergüenzas, porque tus vergüenzas son.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Las vergüenzas de la hija de la mujer de tu padre, engendrada de tu padre, tu hermana es, no descubrirás sus vergüenzas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Las vergüenzas de la hermana de tu padre no descubrirás: parienta de tu padre es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Las vergüenzas de la hermana de tu madre no descubrirás, porque parienta de tu madre es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Las vergüenzas del hermano de tu padre no descubrirás, no llegarás a su mujer: mujer del hermano de tu padre es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Las vergüenzas de tu nuera no descubrirás: mujer es de tu hijo, no descubrirás sus vergüenzas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Las vergüenzas de la mujer de tu hermano no descubrirás: vergüenzas son de tu hermano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Las vergüenzas de la mujer y de su hija no descubrirás: no tomarás la hija de su hijo, ni la hija de su hija para descubrir sus vergüenzas: parientas son, maldad es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Ítem, mujer con su hermana por concubina no tomarás para descubrir sus vergüenzas delante de ella en su vida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Ítem, a la mujer en el apartamiento de su inmundicia, no llegarás para descubrir sus vergüenzas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Ítem, a la mujer de tu prójimo no darás tu acostamiento en simiente, contaminándote en ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Ítem, no des de tu simiente para hacer pasar a Moloc: ni contamines el nombre de tu Dios. Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Ítem, con macho no te echarás como con mujer: abominación es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Ítem, con ningún animal tendrás ayuntamiento ensuciándote con él: ni mujer se pondrá delante de animal para ayuntarse con él: mezcla es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'En ninguna de estas cosas os ensuciaréis: porque en todas estas cosas se han ensuciado las gentes, que yo echo de delante de vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Y la tierra fue contaminada, y yo visité su maldad sobre ella; y la tierra vomitó a sus moradores.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Guardád pues vosotros mis estatutos, y mis derechos, y no hagáis ninguna de todas estas abominaciones, el natural ni el extranjero, que peregrina entre vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Porque todas estas abominaciones hicieron los hombres de la tierra, que fueron antes de vosotros, y la tierra fue contaminada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Y la tierra no os vomitará, por haberla contaminado, como vomitó a la gente, que fue antes de vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Porque cualquiera que hiciere alguna de todas estas abominaciones, las personas que tal hicieren, serán cortadas de entre su pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Guardád pues mi observancia no haciendo algo de las leyes de las abominaciones, que fueron hechas antes de vosotros, y no os ensuciéis en ellas: Yo Jehová, vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Habla a toda la congregación de los hijos de Israel, y díles: Santos seréis, porque santo soy yo, Jehová vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Cada uno temerá a su madre, y a su padre; y mis sábados guardaréis: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'No os volveréis a los ídolos, ni haréis para vosotros dioses de fundición: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Y cuando sacrificaréis sacrificio de paces a Jehová, de vuestra voluntad lo sacrificaréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'El día que lo sacrificaréis, será comido, y el día siguiente: y lo que quedare para el tercero día, será quemado en el fuego.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Y si se comiere el día tercero, será abominación: no será acepto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Y el que lo comiere, llevará su delito, por cuanto profanó la santidad de Jehová: y la tal persona será cortada de sus pueblos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Cuando segareis la siega de vuestra tierra, no acabarás de segar el rincón de tu haza, ni espigarás tu segada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Ítem, no rebuscarás tu viña, ni cogerás los granos de tu viña: para el pobre y para el extranjero los dejarás: Yo Jehová, vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'No hurtaréis: y no negaréis: y no mentiréis ninguno a su prójimo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Y no juraréis en mi nombre con mentira: ni ensuciarás el nombre de tu Dios: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'No oprimirás a tu prójimo, ni robarás. No se detendrá el trabajo del jornalero en tu casa hasta la mañana.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'No maldigas al sordo, y delante del ciego no pongas tropezón, mas habrás temor de tu Dios: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'No harás injusticia en el juicio: no tendrás respeto al pobre, ni honrarás la faz del grande: con justicia juzgarás a tu prójimo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'No andarás chismeando en tus pueblos. No te pondrás contra la sangre de tu prójimo: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'No aborrecerás a tu hermano en tu corazón: reprendiendo reprenderás a tu prójimo, y no consentirás sobre el pecado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'No te vengarás, ni guardarás la injuria a los hijos de tu pueblo; mas amarás a tu prójimo, como a ti mismo: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Mis estatutos guardaréis. A tu animal no harás ayuntar para misturas. Tu haza no sembrarás de misturas: y vestido de misturas de diversas cosas, no subirá sobre ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Ítem, el varón cuando se juntare con mujer de ayuntamiento de simiente, y ella fuere sierva desposada a alguno, y no fuere rescatada, ni le hubiere sido dada libertad, serán azotados: no morirán: por cuanto ella no es libre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Y traerá en expiación por su culpa a Jehová a la puerta del tabernáculo del testimonio un carnero por expiación:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Y el sacerdote le reconciliará con el carnero de la expiación delante de Jehová, por su pecado que pecó; y perdonarle ha su pecado, que pecó.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Ítem, cuando hubiereis entrado en la tierra, y plantareis todo árbol de comer, circuncidaréis su prepucio de su fruto: tres años os será incircunciso: su fruto no se comerá:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Y al cuarto año todo su fruto será santidad de loores a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Y al quinto año comeréis el fruto de él, para que os haga crecer su fruto: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'No comeréis con sangre. No seréis agoreros: ni adivinaréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'No trasquilaréis en derredor los rincones de vuestra cabeza: ni dañarás la punta de tu barba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Ítem, no haréis rasguño en vuestra carne en la muerte de alguno: ni pondréis en vosotros escritura de señal: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'No contaminarás a tu hija haciéndola fornicar, porque la tierra no fornique, y se hincha de maldad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Mis sábados guardaréis; y mi santuario tendréis en reverencia: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'No os volváis a los encantadores y a los adivinos: no los consultéis ensuciándoos en ellos: Yo Jehová, vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Delante de las canas te levantarás, y honrarás la faz del viejo, y de tu Dios habrás temor: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Ítem, cuando peregrinare contigo peregrino en vuestra tierra, no le oprimiréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Como a un natural de vosotros tendréis al peregrino que peregrinare entre vosotros, y ámale como a ti mismo: porque peregrinos fuisteis en la tierra de Egipto: Yo Jehová, vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'No hagáis injusticia en juicio, en medida, ni en peso, ni en medida.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Balanzas justas, piedras justas, efa justa, e hin justo tendréis: Yo Jehová, vuestro Dios, que os saqué de la tierra de Egipto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Guardád pues todos mis estatutos, y todos mis derechos, y hacédlos: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Ítem, dirás a los hijos de Israel: Cualquier varón de los hijos de Israel, y de los extranjeros, que peregrinan en Israel, que diere de su simiente a Moloc, morirá de muerte: el pueblo de la tierra le apedreará con piedras:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Y yo pondré mi rostro contra el tal varón, y le cortaré de entre su pueblo, por cuanto dio de su simiente a Moloc contaminando mi santuario, y ensuciando mi santo nombre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Y si escondiere el pueblo de la tierra sus ojos de aquel varón, que hubiere dado de su simiente a Moloc, para no matarle,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'Entonces yo pondré mi rostro contra aquel varón, y contra su familia, y cortarle he de entre su pueblo, con todos los que fornicaren tras él, fornicando tras Moloc.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, '¶ Ítem, la persona que se volviere a los encantadores, o adivinos para fornicar tras ellos, yo pondré mi rostro contra la tal persona, y yo la cortaré de entre su pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, '¶ Santificáos pues, y sed santos, porque yo Jehová soy vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Y guardád mis estatutos, y hacédlos: Yo Jehová, que os santifico.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, '¶ Porque cualquier varón que maldijere a su padre o a su madre, morirá de muerte: ¿a su padre, o a su madre maldijo? su sangre sobre él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, '¶ Ítem, el varón, que adulterare con la mujer de otro, que cometiere adulterio con la mujer de su prójimo, de muerte morirá el adúltero, y la adúltera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Ítem, cualquiera que se echare con la mujer de su padre, las vergüenzas de su padre descubrió, ambos morirán de muerte, su sangre sobre ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Ítem, cualquiera que durmiere con su nuera, ambos morirán de muerte, mistura hicieron, su sangre sobre ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Ítem, cualquiera que tuviere ayuntamiento con macho, como con mujer, abominación hicieron, ambos morirán de muerte, su sangre sobre ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Ítem, el que tomare a la mujer y a su madre, fealdad es; quemarán en fuego a él y a ellas, porque no haya fealdad entre vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Ítem, cualquiera que pusiere su ayuntamiento en bestia, morirá de muerte, y a la bestia mataréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Ítem, la mujer que se allegare a algún animal para tener ayuntamiento con él, matarás a la mujer y al animal: de muerte morirán, su sangre sobre ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Ítem, cualquiera que tomare a su hermana, hija de su padre, o hija de su madre, y viere sus vergüenzas, y ella viere las suyas, execrable cosa es; por tanto serán muertos en ojos de los hijos de su pueblo; ¿las vergüenzas de su hermana descubrió? su pecado llevará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Ítem, cualquiera que durmiere con mujer menstruosa, y descubriere sus vergüenzas, su fuente descubrió, y ella descubrió la fuente de su sangre; ambos serán cortados de entre su pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Las vergüenzas de la hermana de tu madre, o de la hermana de tu padre no descubrirás, por cuanto descubrió a su parienta: su iniquidad llevarán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Ítem, cualquiera que durmiere con la mujer del hermano de su padre, las vergüenzas del hermano de su padre descubrió: su pecado llevarán, sin hijos morirán:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Ítem, el que tomare la mujer de su hermano suciedad es, las vergüenzas de su hermano descubrió; sin hijos serán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, '¶ Guardád pues todos mis estatutos, y todos mis derechos, y hacédlos, y no os vomitará la tierra, en la cual yo os meto, para que habitéis en ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Y no andéis en los estatutos de la gente, que yo echaré de delante de vosotros: porque ellos hicieron todas estas cosas, y yo los tuve en abominación:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Y os he dicho a vosotros: Vosotros poseeréis la tierra de ellos, y yo la daré a vosotros, para que la poseáis por heredad, tierra que corre leche y miel: Yo Jehová vuestro Dios, que os he apartado de los pueblos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Por tanto vosotros haréis diferencia entre animal limpio e inmundo, y entre ave inmunda y limpia: y no ensuciéis vuestras personas en los animales, ni en las aves, ni en ninguna cosa que va arrastrando por la tierra, las cuales cosas yo os he apartado por inmundas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Serme heis pues santos, porque yo Jehová soy santo, y os he apartado de los pueblos, para que seáis míos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Y el hombre o la mujer, en los cuales hubiere espíritu Pitónico, o de adivinación, morirán de muerte: apedrearlos han con piedras, su sangre sobre ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Y Jehová dijo a Moisés: Habla a los sacerdotes, hijos de Aarón, y díles que por ninguna alma se contaminen en sus pueblos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Mas por su pariente cercano a sí, como por su madre, o por su padre, o por su hijo, o por su hija, o por su hermano,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'O por su hermana virgen cercana a sí, que no haya tenido varón, por ella se contaminará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'No se contaminará por el príncipe en sus pueblos ensuciándose.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'No harán calva en su cabeza, ni raerán la punta de su barba, ni en su carne harán rasguño.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Santos serán a su Dios, y no ensuciarán el nombre de su Dios, porque los fuegos de Jehová, el pan de su Dios ofrecen, por tanto serán santos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, '¶ Mujer ramera, o infame no tomarán: ni tomarán mujer repudiada de su marido: porque es santo a su Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Y santificarle has, porque el pan de tu Dios ofrece: santo será a ti, porque santo soy yo Jehová vuestro santificador.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, '¶ Ítem, la hija del varón sacerdote, cuando comenzare a fornicar, a su padre contamina, será quemada en fuego.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Ítem, el sumo sacerdote entre sus hermanos, sobre cuya cabeza fue derramado el aceite de la unción, y que hinchió su mano para vestir las vestiduras, no descubrirá su cabeza, ni romperá sus vestidos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Ni entrará a ninguna persona muerta, ni por su padre, o por su madre se contaminará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Ni saldrá del santuario, ni ensuciará el santuario de su Dios; porque la corona del aceite de la unción de su Dios está sobre él: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Ítem, él tomará mujer con su virginidad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Viuda, o repudiada, o infame, o ramera, estas no tomará: mas virgen tomará de sus pueblos: por mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Y no ensuciará su simiente en sus pueblos: porque yo Jehová soy el que le santifico.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, '¶ Ítem, Jehová habló a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Habla a Aarón, y díle: El varón de tu simiente en sus generaciones, en el cual hubiere falta, no se allegará para ofrecer el pan de su Dios:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Porque ningún varón, en el cual hubiere falta, se allegará: varón ciego, o cojo, o falto, o sobrado de nariz,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'O varón en el cual hubiere quebradura de pie, o quebradura de mano:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'O corcobado, o lagañoso, o que tuviere nube en el ojo, o que tuviere sarna, o empeine, o compañón quebrado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Ningún varón de la simiente de Aarón sacerdote, en el cual hubiere falta, se allegará para ofrecer las ofrendas encendidas de Jehová. ¿ Hay falta en él? no se allegará a ofrecer el pan de su Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'El pan de su Dios de las santidades de santidades, y las cosas santificadas comerá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Empero no entrará del velo adentro, ni se allegará al altar, por cuanto hay falta en él: y no ensuciará mi santuario, porque yo Jehová soy el que los santifico.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Y Moisés habló a Aarón, y a sus hijos, y a todos los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Y habló Jehová a Moisés, diciendo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Di a Aarón, y a sus hijos, que se abstengan de las santificaciones de los hijos de Israel; y que no ensucien mi santo nombre en lo que ellos me santifican: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Díles: En vuestras generaciones todo varón, que llegare, de toda vuestra simiente, a las santificaciones, que los hijos de Israel santificaren a Jehová, teniendo inmundicia sobre sí, su alma será cortada de delante de mí: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Cualquier varón de la simiente de Aarón, que fuere leproso, o gonorrea no comerá de las santificaciones hasta que sea limpio: y el que tocare cualquiera cosa inmunda de mortecino, o el varón del cual hubiere salido derramadura de simiente,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'O el varón, que hubiere tocado cualquiera reptil, por el cual será inmundo, o hombre por él cual será inmundo conforme a toda su inmundicia;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'La persona que lo tocare, será inmunda hasta la tarde: y no comerá de las santificaciones, antes que haya lavado su carne con agua.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Y cuando el sol se pusiere, limpiarse ha, y después comerá de las santificaciones, porque su pan es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Mortecino ni despedezado no comerá para contaminarse en ello: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Y guarden mi observancia, y no lleven pecado por ello, y mueran por ello cuando la profanaren: Yo Jehová, que los santifico.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, '¶ Ningún extraño comerá santificación: el huésped del sacerdote, ni el jornalero, no comerá santificación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Mas el sacerdote, cuando comprare persona de su dinero, esta comerá de ella, y el nacido en su casa, estos comerán de su pan.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Empero la hija del sacerdote cuando se casare con varón extraño, ella no comerá de la apartadura de las santificaciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Mas si la hija del sacerdote fuere viuda, o repudiada, y no tuviere simiente, y se hubiere vuelto a la casa de su padre, como en su mocedad, del pan de su padre comerá, y ningún extraño coma de él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Y el que comiere por yerro santificación, añadirá sobre ella su quinto, y darlo ha al sacerdote con la santificación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Y no contaminarán las santificaciones de los hijos de Israel, las cuales apartan para Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'Y no les harán llevar la iniquidad del pecado comiendo las santificaciones de ellos: porque yo Jehová soy el que los santifico.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, '¶ Ítem, habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Habla a Aarón, y a sus hijos, y a todos los hijos de Israel, y díles: Cualquier varón de la casa de Israel, y de los extranjeros en Israel que ofreciere su ofrenda por todos sus votos, y por todas sus ofrendas voluntarias, que ofrecieren a Jehová en holocausto:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'De vuestra voluntad ofreceréis sin tacha, macho, de vacas, de corderos, o de cabras:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Ninguna cosa en que haya falta ofreceréis, porque no será acepto por vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Ítem, el hombre, cuando ofreciere sacrificio de paces a Jehová, para ofrecer voto, o para ofrecer voluntariamente, de vacas, o de ovejas, perfecto, en el cual no habrá falta, será acepto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Ciego, o perniquebrado, o cortado, o berrugoso, o sarnoso, o roñoso, no ofreceréis estos a Jehová, ni pondréis de estos ofrenda encendida sobre el altar de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Buey, o carnero, que tenga de más, o de menos podrás ofrecer por ofrenda voluntaria: mas por voto, no será acepto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Herido, o magullado, rompido o cortado, no ofreceréis a Jehová, ni en vuestra tierra lo haréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Ítem, de mano de hijo de extranjero no ofreceréis el pan de vuestro Dios de todas estas cosas, porque su corrupción está en ellas, falta hay en ellas, no se os aceptarán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, '¶ Ítem, habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'El buey, o el cordero. o la cabra, cuando naciere, siete días estará debajo de su madre, mas desde el octavo día en adelante será acepto para ofrenda de sacrificio encendido a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Y buey, o carnero, no degollaréis en un día a él y a su hijo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, '¶ Ítem, cuando sacrificareis sacrificio de hacimiento de gracias a Jehová, de vuestra voluntad lo sacrificaréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'En el mismo día se comerá, no dejaréis de él para otro día: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, '¶ Y guardád mis mandamientos, y hacédlos: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Y no ensuciéis mi santo nombre, y yo me santificaré en medio de los hijos de Israel: Yo Jehová, que os santifico,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Que os saqué de la tierra de Egipto para ser vuestro Dios: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Habla a los hijos de Israel, y díles: Las solemnidades de Jehová, a las cuales convocaréis santas convocaciones, serán estas mis solemnidades.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Seis días se trabajará, y el séptimo día sábado de holganza será, convocación santa: ninguna obra haréis, sábado es de Jehová en todas vuestras habitaciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Estas son las solemnidades de Jehová, las convocaciones santas a las cuales convocaréis en sus tiempos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, '¶ En el mes primero, a los catorce del mes, entre las dos tardes, pascua a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, '¶ Y a los quince días de este mes, la solemnidad de las cenceñas a Jehová: siete días comeréis cenceñas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'El primer día tendréis santa convocación: ninguna obra servil haréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Y ofreceréis a Jehová siete días ofrenda encendida: el séptimo día será santa convocación: ninguna obra servil haréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Ítem, habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Habla a los hijos de Israel, y díles: Cuando hubiereis entrado en la tierra, que yo os doy, y segareis su segada, traeréis al sacerdote un omer por primicia de primicias de vuestra segada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'El cual mecerá el omer delante de Jehová para que seáis aceptos: el siguiente día del sábado lo mecerá el sacerdote.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Y el día que ofreciereis el omer, ofreceréis un cordero perfecto de un año en holocausto a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Con su presente, dos diezmas de flor de harina amasada con aceite en ofrenda encendida a Jehová para olor de holganza, y su derramadura de vino, la cuarta de un hin.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Y no comeréis pan, ni espiga tostada, ni tierna hasta este mismo día, hasta que hayáis ofrecido la ofrenda de vuestro Dios: estatuto perpetuo por vuestras edades en todas vuestras habitaciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, '¶ Y contaros heis desde el siguiente día del sábado, desde el día en que ofrecisteis el omer de la mecedura, siete semanas cumplidas serán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Hasta el siguiente día del sábado séptimo contaréis cincuenta días: entonces ofreceréis presente nuevo a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'De vuestras habitaciones traeréis el pan de la mecedura: dos décimas de flor de harina serán, leudo será cocido, primicias a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Y ofreceréis con el pan siete corderos perfectos de un año, y un novillo hijo de vaca, y dos carneros, serán holocausto a Jehová: y su presente, y sus derramaduras, en ofrenda encendida de olor de holganza a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Ítem, ofreceréis un macho de cabrío por expiación, y dos corderos de un año en sacrificio de paces.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Y el sacerdote los mecerá con el pan de las primicias, con mecedura delante de Jehová, con los dos corderos: santidad serán de Jehová para el sacerdote.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Y convocaréis en este mismo día, santa convocación os será: ninguna obra servil haréis: estatuto perpetuo en todas vuestras habitaciones por vuestras edades.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Y cuando segareis la segada de vuestra tierra, no acabarás de segar el rincón de tu haza, ni espigarás tu segada: para el pobre y para el extranjero la dejarás: Yo Jehová, vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, '¶ Ítem, habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Habla a los hijos de Israel, y díles: En el mes séptimo, al primero del mes tendréis sábado, la memoria de la jubilación, santa convocación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Ninguna obra servil haréis, y ofreceréis ofrenda encendida a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, '¶ Ítem, habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Empero a los diez de este mes séptimo será el día de las expiaciones: tendréis santa convocación, y afligiréis vuestras personas, y ofreceréis ofrenda encendida a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Ninguna obra haréis en este mismo día, porque es día de expiaciones, para reconciliaros delante de Jehová vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Porque toda persona, que no se afligiere en este día mismo, será cortada de sus pueblos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Y cualquiera persona, que hiciere cualquiera obra en este día mismo, yo destruiré la tal persona de entre su pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Ninguna obra haréis: estatuto perpetuo será por vuestras edades en todas vuestras habitaciones.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Sábado de holganza será a vosotros, y afligiréis vuestras personas a los nueve del mes en la tarde, de tarde a tarde holgaréis vuestro sábado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, '¶ Ítem, habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Habla a los hijos de Israel, y díles: A los quince de este mes séptimo será la solemnidad de las cabañas a Jehová por siete días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'El primer día será santa convocación: ninguna obra servil haréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Siete días ofreceréis ofrenda encendida a Jehová: el octavo día tendréis santa convocación, y ofreceréis ofrenda encendida a Jehová: fiesta es: ninguna obra servil haréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Estas son las solemnidades de Jehová a las cuales convocaréis santas convocaciones, para ofrecer ofrenda encendida a Jehová, holocausto y presente, sacrificio y derramaduras cada cosa en su tiempo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Allende de los sábados de Jehová, y allende de vuestros dones, y allende de todos vuestros votos, y allende de todas vuestras ofrendas voluntarias, que daréis a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Empero a los quince del mes séptimo, cuando hubiereis allegado el fruto de la tierra, haréis fiesta a Jehová por siete días: el primer día, sábado: y el día octavo, sábado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Y tomaros heis el primer día del fruto de algún árbol hermoso: ramos de palmas, y ramos de árboles espesos, y sauces de los arroyos, y haréis alegría delante de Jehová vuestro Dios por siete días.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Y haréis a él fiesta, a Jehová, por siete días cada un año, y estatuto perpetuo será por vuestras edades: en el mes séptimo la haréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'En cabañas habitaréis siete días: todo natural en Israel habitará en cabañas;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Para que sepan vuestros descendientes, que en cabañas hice yo habitar a los hijos de Israel, cuando los saqué de la tierra de Egipto: Yo Jehová, vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Y Moisés habló a los hijos de Israel de las solemnidades de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Ítem, habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Manda a los hijos de Israel, que te traigan aceite de olivas claro, molido, para la luminaria para encender las lámparas siempre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Fuera del velo del testimonio en el tabernáculo del testimonio las aderezará Aarón desde la tarde hasta la mañana delante de Jehová siempre: estatuto perpetuo por vuestras edades.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Sobre el candelero limpio pondrá en orden Aarón las lámparas delante de Jehová siempre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, '¶ Y tomarás flor de harina, y cocerás de ella doce tortas, cada torta será de dos décimas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Y ponerlas has en dos ordenes, seis en cada orden, sobre la mesa limpia delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Pondrás también sobre cada orden incienso limpio, y será para el pan por perfume, ofrenda encendida a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Cada día de sábado lo pondrá en orden delante de Jehová siempre, pacto sempiterno de los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Y será de Aarón y de sus hijos, los cuales lo comerán en el lugar santo: porque santidad de santidades es para él, de las ofrendas encendidas a Jehová por fuero perpetuo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, '¶ En aquella sazón salió un hijo de una mujer Israelita, el cual era hijo de un hombre Egipcio, entre los hijos de Israel; y riñeron en el real el hijo de la Israelita y un varón Israelita.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Y el hijo de la mujer Israelita declaró el nombre, y maldijo. Y trajéronlo a Moisés: (y su madre se llamaba Salomit, hija de Dabri de la tribu de Dan.)');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Y puesiéronle en la cárcel hasta que les fuese declarado por palabra de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Entonces Jehová habló a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Saca al blasfemo fuera del real, y todos los que lo oyeron, pongan sus manos sobre la cabeza de él, y apedréele toda la congregación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, '¶ Y a los hijos de Israel hablarás, diciendo: Cualquier varón, que dijere mal a su Dios, llevará su iniquidad.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Y el que pronunciare el nombre de Jehová, morirá de muerte; toda la congregación le apedreará, así el extranjero como el natural: si pronunciare el nombre, que muera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, '¶ Y el hombre que hiriere a cualquiera persona humana, que muera de muerte.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Y el que hiriere a algún animal, restituirlo ha, animal por animal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Ítem, el que hiciere mancha a su prójimo, como hizo, así le sea hecho.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Quebradura por quebradura, ojo por ojo, diente por diente, como señaló al hombre, así sea él señalado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'El que hiriere a algún animal, restituirlo ha: mas el que hiriere a hombre, que muera.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Un mismo derecho tendréis: como el extranjero, así será el natural: porque yo Jehová, vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Y habló Moisés a los hijos de Israel, y ellos sacaron al blasfemo fuera del real, y apedreáronle con piedras: y los hijos de Israel hicieron según que Jehová había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Ítem, Jehová habló a Moisés en el monte de Sinaí, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Habla a los hijos de Israel, y díles: Cuando hubiereis entrado en la tierra, que yo os doy, la tierra descansará descanso a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Seis años sembrarás tu tierra, y seis años podarás tu viña, y cogerás sus frutos;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Y el séptimo año la tierra tendrá sábado de holganza, sábado a Jehová: no sembrarás tu tierra, ni podarás tu viña.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Lo que de suyo se naciere en tu segada, no lo segarás: y las uvas de tu apartadura no vendimiarás: año de holganza será a la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Mas el sábado de la tierra os será para comer, a ti, y a tu siervo, y a tu sierva, y a tu criado, y a tu extranjero, que moraren contigo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Y a tu animal, y a la bestia que hubiere en tu tierra, será todo su fruto para comer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, '¶ Y contarte has siete semanas de años, siete veces siete años, y serte han los días de las siete semanas de años cuarenta y nueve años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Y harás pasar la trompeta de jubilación en el mes séptimo; a los diez del mes, el día de las expiaciones, haréis pasar trompeta por toda vuestra tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Y santificaréis el año cincuenta, y pregonaréis libertad en la tierra a todos sus moradores: este os será jubileo: y volveréis cada uno a su posesión; y cada uno volverá a su familia.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'El año de los cincuenta años os será jubileo: no sembraréis, ni segaréis lo que naciere de suyo en la tierra, ni vendimiaréis sus apartaduras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Porque es jubileo: santo será a vosotros: el fruto de la tierra comeréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'En este año del jubileo volveréis cada uno a su posesión.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, '¶ Y cuando vendiereis algo a vuestro prójimo, o compraréis de mano de vuestro prójimo, no engañe ninguno a su hermano.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Conforme al número de los años después del jubileo comprarás de tu prójimo: conforme al número de los años de los frutos te venderá él a ti.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Conforme a la multitud de los años aumentarás el precio, y conforme a la diminución de los años disminuirás el precio: porque el número de los frutos te ha de vender él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Y no engañe ninguno a su prójimo: mas tendrás temor de tu Dios, porque yo soy Jehová vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Y hacéd mis estatutos, y guardád mis derechos, y hacédlos, y habitaréis sobre la tierra seguros:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Y la tierra dará su fruto, y comeréis hasta hartura, y habitaréis sobre ella seguros:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Y si dijereis: ¿Qué comeremos el séptimo año? He aquí, no hemos de sembrar, ni hemos de coger nuestros frutos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Entonces yo os enviaré mi bendición el año sexto, y hará fruto por tres años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Y sembraréis el año octavo, y comeréis del fruto añejo hasta el año noveno: hasta que venga su fruto comeréis del añejo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, '¶ Y la tierra no se venderá rematadamente: porque la tierra es mía, que vosotros peregrinos y extranjeros sois conmigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Por tanto en toda la tierra de vuestra posesión daréis remisión a la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, '¶ Cuando tu hermano empobreciere, y vendiere algo de su posesión, vendrá su rescatador, su pariente más cercano, y rescatará lo que su hermano vendiere.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Y el varón, cuando no tuviere rescatador, si alcanzare después su mano, y hallare lo que basta para su rescate;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'Entonces contará los años de su venta, y volverá lo que quedare al varón a quien vendió, y volverá a su posesión.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Mas si no alcanzare su mano lo que basta para que vuelva a él, lo que vendió estará en poder del que lo compró hasta el año del jubileo, y al jubileo saldrá, y él volverá a su posesión.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Ítem, el varón que vendiere casa de morada en ciudad cercada, su remisión será hasta acabarse el año de su venta: un año será su remisión.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Y sino fuere rescatada dentro de un año entero, la casa que estuviere en ciudad que tuviere muro, quedará rematadamente al que la compró para sus descendientes: no saldrá en el jubileo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Mas las casas de las aldeas, que no tienen muro al derredor, serán estimadas como una haza de tierra: tendrán remisión, y saldrán en el jubileo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, '¶ Mas de las ciudades de los Levitas, y de las casas de las ciudades, que poseyeren, los Levitas habrán remisión siempre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Y el que comprare de los Levitas, la venta de la casa, y de la ciudad de su posesión saldrá en el jubileo, por cuanto la casa de las ciudades de los Levitas es la posesión de ellos entre los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Mas la tierra del ejido de sus ciudades no se venderá, porque es perpetua posesión de ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, '¶ Ítem, cuando tu hermano empobreciere, y acostare su mano a ti, tú le recibirás: como peregrino y extranjero vivirá contigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'No tomarás usura de él, ni aumento: mas habrás temor de tu Dios, y tu hermano vivirá contigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'No le darás tu dinero a usura, ni tu vitualla a aumento:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Yo Jehová vuestro Dios, que os saqué de la tierra de Egipto para daros la tierra de Canaán, para ser vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Ítem, cuando tu hermano empobreciere estando contigo, y se vendiere a ti, no le harás servir como siervo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Como criado, como extranjero estará contigo: hasta el año del jubileo te servirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Entonces saldrá de contigo él y sus hijos consigo, y volverá a su familia, y a la posesión de sus padres se volverá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Porque son mis siervos, los cuales yo saqué de la tierra de Egipto: no serán vendidos como siervos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'No te enseñorearás de él con dureza, mas habrás temor de tu Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, '¶ Ítem, tu siervo o tu sierva, que tuvieres serán de las gentes, que están en vuestro al derredor: de ellos compraréis siervos y siervas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Y también de los hijos de los forasteros, que viven entre vosotros compraréis: y de los que del linaje de ellos son nacidos en vuestra tierra, que están con vosotros: los cuales tendréis por posesión.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Y poseerlos heis por juro de heredad para vuestros hijos después de vosotros para tener posesión, para siempre os serviréis de ellos: empero en vuestros hermanos los hijos de Israel, cada uno en su hermano, no os enseñorearéis en él con dureza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, '¶ Ítem, cuando la mano del peregrino y extranjero, que está contigo, alcanzare, y tu hermano que está con él, empobreciere, y se vendiere al peregrino o extranjero, que está contigo, o a la raza del linaje del extranjero,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'Después que se hubiere vendido, tendrá redención: uno de sus hermanos le rescatará;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'O su tio, o el hijo de su tio le rescatará, o el cercano de su carne, de su linaje, le rescatará: o si su mano alcanzare, él se redimirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Y contará con el que le compró desde el año que se vendió a él hasta el año del jubileo: y apreciarse ha el dinero de su venta conforme al número de los años, y hacerse ha con él conforme al tiempo de un criado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Si aun fueren muchos años, conforme a ellos volverá su rescate del dinero por el cual se vendió.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Y si quedare poco tiempo hasta el año del jubileo, entonces contará con él, y volverá su rescate conforme a sus años.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Como cogido de año por año hará con él, no se enseñoreará en él duramente delante de tus ojos:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Mas si no se redimiere en ellos, saldrá en el año del jubileo él, y sus hijos con él.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Porque mis siervos son los hijos de Israel, mis siervos son, que yo saqué de la tierra de Egipto: Yo Jehová, vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'No haréis para vosotros ídolos, ni escultura, ni os levantaréis título, ni pondréis en vuestra tierra piedra pintada para inclinaros a ella: porque yo Jehová soy vuestro Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Guardád mis sábados, y tenéd en reverencia mi santuario: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, '¶ Si anduviereis en mis decretos, y guardareis mis mandamientos, y los hiciereis,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'Yo daré vuestra lluvia en su tiempo, y la tierra dará su fruto, y el árbol del campo dará su fruto:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Y la trilla os alcanzará a la vendimia, y la vendimia alcanzará a la sementera, y comeréis vuestro pan a hartura, y habitaréis seguros en vuestra tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Y yo daré paz en la tierra; y dormiréis, y no habrá quien os espante: y haré quitar las malas bestias de vuestra tierra: y por vuestra tierra no pasará espada.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Y perseguiréis a vuestros enemigos, y delante de vosotros caerán a cuchillo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Y cinco de vosotros perseguirán a ciento, y ciento de vosotros perseguirán a diez mil, y vuestros enemigos caerán a cuchillo delante de vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Porque yo me volveré a vosotros, y haceros he crecer, y multiplicaros he, y afirmaré mi concierto con vosotros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Y comeréis añejo envejecido, y sacaréis fuera lo añejo a causa de lo nuevo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Y pondré mi morada en medio de vosotros, y mi alma no os abominará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Y andaré entre vosotros, y yo seré vuestro Dios, y vosotros seréis mi pueblo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Yo Jehová, vuestro Dios, que os saqué de la tierra de Egipto, que no fueseis sus siervos: y rompí los látigos de vuestro yugo, y os he hecho andar el rostro alto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, '¶ Empero si no me oyereis, ni hiciereis todos estos mis mandamientos,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'Y si abominareis mis decretos, y vuestra alma menospreciare mis derechos no haciendo todos mis mandamientos, e invalidando mi concierto;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'Yo también haré con vosotros esto: Enviaré sobre vosotros terror, hética, y calentura, que consuman los ojos, y atormenten el alma: y sembraréis en balde vuestra simiente, porque vuestros enemigos lo comerán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Y pondré mi ira sobre vosotros, y seréis heridos delante de vuestros enemigos; y los que os aborrecen se enseñorearán de vosotros, y huiréis sin que haya quien os persiga.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Y si aun con estas cosas no me oyereis, yo tornaré a castigaros siete veces por vuestros pecados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Y quebrantaré la soberbia de vuestra fortaleza, y tornaré vuestro cielo como hierro, y vuestra tierra como metal.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Y vuestra fuerza se consumirá en vano, que vuestra tierra no dará su fruto, y los árboles de la tierra no darán su fruto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Y si anduviereis conmigo al encuentro y no me quisiereis oír, yo añadiré sobre vosotros plagas siete veces según vuestros pecados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Y enviaré contra vosotros bestias fieras, que os deshijen, y talen vuestros animales, y os apoquen, y vuestros caminos sean desiertos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Y si con estas cosas no me fuereis castigados, mas aun anduviereis conmigo al encuentro,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'Yo también andaré con vosotros al encuentro y heriros he también siete veces al encuentro por vuestros pecados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Y meteré sobre vosotros espada vengadora de la venganza del concierto, y juntaros heis a vuestras ciudades, y yo enviaré pestilencia entre vosotros, y seréis entregados en mano del enemigo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Cuando yo os quebrantaré el bordón del pan, cocerán diez mujeres vuestro pan en un horno, y volverán vuestro pan por peso: y comeréis, y no os hartaréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Y si con esto no me oyereis, mas todavía anduviereis conmigo al encuentro,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'Yo andaré con vosotros a ira de al encuentro, y castigaros he también yo siete veces por vuestros pecados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Y comeréis las carnes de vuestros hijos, y las carnes de vuestras hijas comeréis.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Y destruiré vuestros altos, y talaré vuestras imágines, y pondré vuestros cuerpos muertos sobre los cuerpos muertos de vuestros ídolos, y mi alma os abominará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Y pondré vuestras ciudades en desierto, y asolaré vuestros santuarios, y no oleré el olor de vuestra holganza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Y yo asolaré la tierra, que se espanten de ella vuestros enemigos, que moran en ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Y a vosotros esparciré por las gentes, y desenvainaré espada en pos de vosotros: y vuestra tierra estará asolada, y vuestras ciudades serán desierto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Entonces la tierra holgará sus sábados todos los días que estuviere asolada, y vosotros en la tierra de vuestros enemigos: entonces la tierra sabatizará, y holgará sus sábados.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Todo el tiempo que estará asolada, holgará lo que no holgó en vuestros sábados mientras habitabais en ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Y los que quedaren de vosotros, yo meteré cobardía en sus corazones en la tierra de sus enemigos, que el sonido de una hoja movida los perseguirá, y huirán como de una espada, y caerán sin haber quien los persiga.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Y tropezarán los unos en los otros como delante de una espada sin haber quien los persiga, y no podréis resistir delante de vuestros enemigos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Y pereceréis entre las gentes, y la tierra de vuestros enemigos os consumirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Y los que quedaren de vosotros se desleirán en las tierras de vuestros enemigos por su iniquidad, y por la iniquidad de sus padres, con ellos serán desleídos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, '¶ Y confesarán su iniquidad, y la iniquidad de sus padres, por su prevaricación con que prevaricaron contra mí: y también porque anduvieron conmigo al encuentro.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'También yo habré andado con ellos al encuentro, y los habré metido en la tierra de sus enemigos: y entonces se humillará su corazón incircunciso, y rogarán por su pecado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Y yo me acordaré de mi concierto con Jacob, y asimismo de mi concierto con Isaac, y también de mi concierto con Abraham me acordaré, y habré memoria de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Que la tierra estará desamparada de ellos, y holgará sus sábados estando yerma a causa de ellos: y ellos rogarán por su pecado: por cuanto menospreciaron mis derechos, y el alma de ellos tuvo fastidio de mis decretos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Y aun con todo esto estando ellos en tierra de sus enemigos, yo no los deseché, ni los abominé para consumirlos invalidando mi concierto con ellos: porque yo Jehová soy su Dios.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Antes me acordaré de ellos por el concierto antiguo, cuando los saqué de la tierra de Egipto en ojos de las gentes para ser su Dios: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Estos son los decretos, derechos, y leyes que dio Jehová entre sí y los hijos de Israel en el monte de Sinaí por mano de Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Habla a los hijos de Israel, y díles: Cuando alguno hiciere voto a Jehová según la estimación de las personas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Tu estimación será, el macho de veinte años hasta sesenta, será tu estimación cincuenta siclos de plata, al siclo del santuario.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Y si fuere hembra, la estimación será treinta siclos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Y si fuere de cinco años hasta veinte, tu estimación será, el macho, veinte siclos: y la hembra, diez siclos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Y si fuere de un mes hasta cinco años, tu estimación será, el macho, cinco siclos de plata; y por la hembra, tu estimación será tres siclos de plata.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Mas si fuere de sesenta años arriba, por el macho tu estimación será quince siclos: y la hembra diez siclos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Mas si fuere más pobre que tu estimación, entonces será puesto delante del sacerdote, y el sacerdote lo apreciará: conforme a lo que alcanzare la mano del votante lo apreciará el sacerdote.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, '¶ Y si fuere animal de que se ofrece ofrenda a Jehová, todo lo que se diere de él a Jehová, será santo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'No será mudado ni trocado bueno por malo, ni malo por bueno: y si se trocare un animal por otro, él y su trueque será santo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Y si fuere cualquiera animal inmundo de que no se ofrece ofrenda a Jehová, entonces el animal será puesto delante del sacerdote,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'Y el sacerdote lo apreciará, sea bueno, o sea malo, conforme a la estimación del sacerdote así será.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Y si lo hubieren de redimir, añadirán su quinto allende de tu estimación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, '¶ Ítem, cuando alguno santificare su casa por santificación a Jehová, el sacerdote la apreciará, sea buena o sea mala: como el sacerdote la apreciare, así quedará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Mas si el santificante redimiere su casa, añadirá el quinto del dinero de tu estimación sobre ella, y será suya.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, '¶ Ítem, si alguno santificare de la tierra de su posesión a Jehová, tu estimación será conforme a su sembradura, un coro de sembradura de cebada se apreciará en cincuenta siclos de plata.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Y si santificare su tierra desde el año del jubileo, conforme a tu estimación quedará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Mas si después del jubileo santificare su tierra, entonces el sacerdote contará con el dinero conforme a los años que quedaren hasta el año del jubileo, y sacarse ha de tu estimación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Y si quisiere redimir la tierra el que la santificó, añadirá el quinto del dinero de tu estimación sobre ella, y quedársele ha.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Mas si él no redimiere la tierra, y si la tierra se vendiere a otro, no la redimirá más.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Empero cuando saliere el jubileo, la tierra será santa a Jehová como tierra de anatema, la posesión de ella será del sacerdote.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Mas si santificare alguno a Jehová la tierra que él compró, que no era de la tierra de su herencia,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'Entonces el sacerdote contará con él la cantidad de tu estimación hasta el año del jubileo, y aquel día dará tu estimación consagrada a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'En el año del jubileo volverá la tierra a aquel de quien él la compró, cuya era la herencia de la tierra.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Y todo lo que apreciares será conforme al siclo del santuario: el siclo tiene veinte óbolos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, '¶ Empero el primogénito de los animales, que por la primogenitura es de Jehová, nadie lo santificará: sea buey, u oveja, de Jehová es.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Mas si fuere de los animales inmundos, redimirlo han conforme a tu estimación, y añadirán sobre ella su quinto: y si no lo redimieren, venderse ha conforme a tu estimación.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, '¶ Empero ningún anatema, que alguno santificare a Jehová de todo lo que tuviere, de hombres, y animales, y de las tierras de su posesión, no se venderá, ni se redimirá. Todo anatema será santidad de santidades a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Cualquier anatema de hombres que se consagrare, no será redimido: de muerte morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, '¶ Ítem, todas las décimas de la tierra de la simiente de la tierra, del fruto de los árboles, de Jehová son: santidad a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Y si alguno quisiere redimir algo de sus décimas, añadirá su quinto sobre ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Y toda décima de vacas, o de ovejas de todo lo que pasa de bajo de vara, la décima será santidad a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'No mirará si es bueno, o malo, ni lo trocará: y si lo trocare, ello y su trueque será santificación, no se redimirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Estos son los mandamientos que mandó Jehová a Moisés para los hijos de Israel en el monte de Sinaí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Y habló Jehová a Moisés en el desierto de Sinaí en el tabernáculo del testimonio, en el primero del mes segundo, en el segundo año de su salida de la tierra de Egipto, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Tomád la copia de toda la congregación de los hijos de Israel por sus familias, por las casas de sus padres, por la cuenta de los nombres, todos los varones por sus cabezas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'De veinte años y arriba, todos los que salen a la guerra en Israel; contarlos heis tú y Aarón por sus cuadrillas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Y estarán con vosotros un varón de cada tribu, cada uno que sea cabeza de la casa de sus padres.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Y estos son los nombres de los varones, que estarán con vosotros. De Rubén: Elisur, hijo de Seduer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'De Simeón: Salamiel, hijo de Surisaddai.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'De Judá: Nahasón, hijo de Aminadab.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'De Isacar: Natanael, hijo de Suar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'De Zabulón: Eliab, hijo de Helón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'De los hijos de José: de Efraím: Elisama, hijo de Ammiud: de Manasés: Gamaliel, hijo de Fadassur.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'De Ben-jamín: Abidán, hijo de Gedeón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'De Dan: Ahiezer, hijo de Ammisaddai.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'De Aser: Fegiel, hijo de Ocrán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'De Gad: Eliasaf, hijo de Dehuel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'De Neftalí: Ahira, hijo de Enán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Estos eran los nombrados de la congregación, príncipes de las tribus de sus padres, capitanes de los millares de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Tomó pues Moisés y Aarón a estos varones, que fueron declarados por sus nombres:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'Y juntaron toda la congregación en el primero del mes segundo, y fueron juntados por sus linajes, por las casas de sus padres, por la cuenta de los nombres, de veinte años y arriba, por sus cabezas,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Como Jehová lo había mandado a Moisés: y contólos en el desierto de Sinaí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Y fueron los hijos de Rubén, primogénito de Israel, sus generaciones, por sus familias, por las casas de sus padres, conforme a la cuenta de los nombres por sus cabezas, todos los varones de veinte años y arriba, todos los que podían salir a la guerra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'Los contados de ellos, de la tribu de Rubén, cuarenta y seis mil y quinientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'De los hijos de Simeón, sus generaciones, por sus familias, por las casas de sus padres, los contados de él conforme a la cuenta de los nombres por sus cabezas, todos varones de veinte años y arriba, todos los que podían salir a la guerra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Los contados de ellos, de la tribu de Simeón, cincuenta y nueve mil y trescientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'De los hijos de Gad, sus generaciones, por sus familias, por las casas de sus padres, conforme a la cuenta de los nombres, de veinte años y arriba, todos los que podían salir a la guerra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Los contados de ellos, de la tribu de Gad, cuarenta y cinco mil y seiscientos y cincuenta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'De los hijos de Judá, sus generaciones, por sus familias, por las casas de sus padres, conforme a la cuenta de los nombres, de veinte años y arriba, todos los que podían salir a la guerra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Los contados de ellos, de la tribu de Judá, setenta y cuatro mil y seiscientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'De los hijos de Isacar, sus generaciones, por sus familias, por las casas de sus padres, conforme a la cuenta de los nombres, de veinte años y arriba, todos los que podían salir a la guerra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Los contados de ellos, de la tribu de Isacar, cincuenta y cuatro mil y cuatrocientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'De los hijos de Zabulón, sus generaciones, por sus familias, por las casas de sus padres, conforme a la cuenta de los nombres, de veinte años y arriba, todos los que podían salir a la guerra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Los contados de ellos, de la tribu de Zabulón, cincuenta y siete mil y cuatrocientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'De los hijos de José, de los hijos de Efraím, sus generaciones, por sus familias, por las casas de sus padres, conforme a la cuenta de los nombres, de veinte años y arriba, todos los que podían salir a la guerra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Los contados de ellos, de la tribu de Efraím, cuarenta mil y quinientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'De los hijos de Manasés, sus generaciones, por sus familias, por las casas de sus padres, conforme a la cuenta de los nombres, de veinte años y arriba, todos los que podían salir a la guerra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Los contados de ellos, de la tribu de Manasés, treinta y dos mil y doscientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'De los hijos de Ben-jamín, sus generaciones, por sus familias, por las casas de sus padres, conforme a la cuenta de los nombres, de veinte años y arriba, todos los que podían salir a la guerra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Los contados de ellos, de la tribu de Ben-jamín, treinta y cinco mil y cuatrocientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'De los hijos de Dan, sus generaciones, por sus familias, por las casas de sus padres, conforme a la cuenta de los nombres, de veinte años y arriba, todos los que podían salir a la guerra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Los contados de ellos, de la tribu de Dan, sesenta y dos mil y sietecientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'De los hijos de Aser, sus generaciones, por sus familias, por las casas de sus padres, conforme a la cuenta de los nombres, de veinte años y arriba, todos los que podían salir a la guerra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Los contados de ellos, de la tribu de Aser, cuarenta y un mil y quinientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'De los hijos de Neftalí, sus generaciones, por sus familias, por las casas de sus padres, conforme a la cuenta de los nombres, de veinte años y arriba, todos los que podían salir a la guerra;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Los contados de ellos, de la tribu de Neftalí, cincuenta y tres mil y cuatrocientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Estos fueron los contados, que contó Moisés, y Aarón y los doce varones príncipes de Israel, un varón por casa de sus padres fueron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Y fueron todos los contados de los hijos de Israel, por las casas de sus padres, de veinte años y arriba, todos los que podían salir a la guerra en Israel;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Fueron todos los contados seiscientos y tres mil, y quinientos y cincuenta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, '¶ Mas los Levitas no fueron contados entre ellos por la tribu de sus padres.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Empero tú no contarás la tribu de Leví, ni tomarás la cuenta de ellos entre los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Mas tú pondrás a los Levitas en el tabernáculo del testimonio, y sobre todos sus vasos, y sobre todas las cosas, que les pertenecen: ellos llevarán el tabernáculo y todos sus vasos, y ellos servirán en él, y asentarán sus tiendas al derredor del tabernáculo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Y cuando el tabernáculo partiere, los Levitas lo desarmarán: y cuando el tabernáculo parare, los Levitas lo armarán: y el extraño que se llegare, morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Y los hijos de Israel asentarán sus tiendas cada uno en su escuadrón, y cada uno junto a su bandera por sus cuadrillas;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Mas los Levitas asentarán las suyas al rededor del tabernáculo del testimonio, y no habrá ira sobre la congregación de los hijos de Israel: y los Levitas tendrán la guarda del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'E hicieron los hijos de Israel conforme a todas las cosas, que Jehová mandó a Moisés: así lo hicieron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Y habló Jehová a Moisés, y a Aarón, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Los hijos de Israel asentarán sus tiendas cada uno junto a su bandera según las enseñas de las casas de sus padres: desviados al derredor del tabernáculo del testimonio asentarán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Estos asentarán al Levante, al oriente, la bandera del ejército de Judá por sus escuadrones; y el príncipe de los hijos de Judá será Nahasón, hijo de Aminadab.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Su escuadrón, los contados de ellos serán setenta y cuatro mil y seiscientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Junto a él asentarán la tribu de Isacar: y el príncipe de los hijos de Isacar será Natanael, hijo de Suar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Y su escuadrón, sus contados, cincuenta y cuatro mil y cuatrocientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'La tribu de Zabulón, y el príncipe de los hijos de Zabulón será Eliab, hijo de Helón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Y su escuadrón, sus contados, cincuenta y siete mil y cuatrocientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Todos los contados en el ejército de Judá, ciento y ochenta y seis mil y cuatrocientos por sus escuadrones: irán delante.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'La bandera del ejército de Rubén al mediodía por sus escuadrones: y el príncipe de los hijos de Rubén será Elisur, hijo de Sedeur:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Y su escuadrón, sus contados, cuarenta y seis mil y quinientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Y asentarán junto a él la tribu de Simeón: y el príncipe de los hijos de Simeón será Salamiel, hijo de Surisaddai.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Y su escuadrón, los contados de ellos, cincuenta y nueve mil y trescientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Ítem, la tribu de Gad: y el príncipe de los hijos de Gad será Eliasaf, hijo de Rehuel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Y su escuadrón, y los contados de ellos, cuarenta y cinco mil y seiscientos y cincuenta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Todos los contados en el ejército de Rubén, ciento y cincuenta y un mil y cuatro cientos y cincuenta por sus escuadrones: estos irán los segundos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Luego irá el tabernáculo del testimonio, el campo de los Levitas en medio de los ejércitos: de la manera que asientan el campo, así caminarán, cada uno en su lugar, junto a sus banderas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'La bandera del ejército de Efraím por sus escuadrones, al occidente: y el príncipe de los hijos de Efraím será Elisama, hijo de Ammiud.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Y su escuadrón, y los contados de ellos, cuarenta mil y quinientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Junto a él estará la tribu de Manasés: y el príncipe de los hijos de Manasés será Gamaliel, hijo de Fadassur.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Y su escuadrón, y los contados de ellos, treinta y dos mil y doscientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Ítem, la tribu de Ben-jamín: y el príncipe de los hijos de Ben-jamín será Abidán, hijo de Gedeón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Y su escuadrón, y los contados de ellos, treinta y cinco mil y cuatrocientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Todos los contados en el ejército de Efraím, ciento y ocho mil y ciento, por sus escuadrones: estos irán los terceros.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'La bandera del ejército de Dan estará al aquilón por sus escuadrones: y el príncipe de los hijos de Dan será Ahiezer, hijo de Ammisaddai.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Y su escuadrón, y los contados de ellos, sesenta y dos mil y setecientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Junto a él asentarán la tribu de Aser: y el príncipe de los hijos de Aser será Fegiel, hijo de Ocrán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Y su escuadrón, y los contados de ellos, cuarenta y un mil y quinientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Ítem, la tribu de Neftalí: y el príncipe de los hijos de Neftalí será Ahira, hijo de Enán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Y su escuadrón, y los contados de ellos, cincuenta y tres mil y cuatrocientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Todos los contados en el ejército de Dan, ciento y cincuenta y siete mil y seiscientos: estos irán los postreros tras sus banderas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Estos son los contados de los hijos de Israel, por las casas de sus padres, todos contados por ejércitos, por sus escuadrones, seiscientos y tres mil y quinientos y cincuenta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Mas los Levitas no fueron contados entre los hijos de Israel, como Jehová lo mandó a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'E hicieron los hijos de Israel conforme a todas las cosas que Jehová mandó a Moisés: así asentaron el campo por sus banderas, y así marcharon cada uno por sus familias, según las casas de sus padres.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Y estas son las generaciones de Aarón, y de Moisés, desde que Jehová habló a Moisés en el monte de Sinaí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Y estos son los nombres de los hijos de Aarón: El primogénito, Nadab: y Abiú, Eleazar, e Itamar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Estos son los nombres de los hijos de Aarón, sacerdotes ungidos, cuyas manos él hinchió para administrar el sacerdocio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Mas Nadab y Abiú murieron delante de Jehová cuando ofrecieron fuego extraño delante de Jehová en el desierto de Sinaí: y no tuvieron hijos: y Eleazar e Itamar hubieron el sacerdocio delante de Aarón su padre.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, '¶ Y Jehová habló a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Haz llegar la tribu de Leví, y házla estar delante de Aarón el sacerdote, para que le administren;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Y guarden la observancia de él, y la observancia de toda la congregación delante del tabernáculo del testimonio: para que administren en el servicio del tabernáculo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Y guarden todas las alhajas del tabernáculo del testimonio, y la guarda de los hijos de Israel, y administren en el servicio del tabernáculo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Y darás los Levitas a Aarón y a sus hijos, dados, dados a él por los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Y a Aarón y a sus hijos constituirás, que guarden su sacerdocio. Y el extraño que se llegare, morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Ítem, Jehová habló a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Y, he aquí, yo he tomado los Levitas de entre los hijos de Israel en lugar de todos los primogénitos que abrieren la matriz, de los hijos de Israel: los Levitas serán míos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Porque mío es todo primogénito desde el día que yo maté todos los primogénitos en la tierra de Egipto, yo santifiqué a mí todos los primogénitos en Israel, así de hombres como de animales, míos serán: Yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, '¶ Ítem, Jehová habló a Moisés en el desierto de Sinaí, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Cuenta los hijos de Leví por las casas de sus padres, por sus familias: contarás todos los varones de un mes y arriba.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Y Moisés los contó conforme a la palabra de Jehová como le fue mandado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Y los hijos de Leví fueron estos por sus nombres: Gersón, y Caat, y Merari.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Y los nombres de los hijos de Gersón por sus familias son estos: Lebni, y Simeí.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Y los hijos de Caat por sus familias: Amram, y Jesaar, y Hebrón, y Oziel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Ítem, los hijos de Merari por sus familias: Moholi, y Musi. Estas son las familias de Leví por las casas de sus padres.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'De Gersón: la familia de Lebni y la de Semeí. Estas son las familias de Gersón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Los contados de ellos conforme a la cuenta de todos los varones de un mes y arriba; los contados de ellos fueron siete mil y quinientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Las familias de Gersón asentarán sus tiendas a las espaldas del tabernáculo al occidente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Y el príncipe de la casa del padre de los Gersonitas será Eliasaf, hijo de Lael.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'A cargo de los hijos de Gersón en el tabernáculo del testimonio será el tabernáculo y la tienda, y su cubierta, y el pabellón de la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'Ítem, las cortinas del patio, y el pabellón de la puerta del patio que está junto al tabernáculo, y junto al altar al derredor, asimismo sus cuerdas para todo su servicio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Y de Caat era la familia Amramítica, y la familia Isaarítica, y la familia Hebronítica, y la familia Ozielítica. Estas son las familias Caatíticas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Por la cuenta de todos los varones de un mes y arriba, ocho mil y seiscientos que tenían la guarda del santuario.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Las familias de los hijos de Caat asentarán al lado del tabernáculo al mediodía.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Y el príncipe de la casa del padre de las familias de Caat será Elisafán, hijo de Oziel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Y a cargo de ellos será el arca, y la mesa, y el candelero, y los altares, y los vasos del santuario con que ministran; y el velo, con todo su servicio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Y el principal de los príncipes de los Levitas será Eleazar, hijo de Aarón el sacerdote, prepósito de los que tienen la guarda del santuario.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'De Merari fue la familia Moholítica, y la familia Musítica. Estas fueron las familias de Merari.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Y los contados de ellos conforme a la cuenta de todos los varones de un mes y arriba fueron seis mil y doscientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Y el príncipe de la casa del padre de las familias de Merari será Suriel, hijo de Abijaiel: asentarán al lado del tabernáculo al aquilón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Y a cargo de la guarda de los hijos de Merari serán las tablas del tabernáculo, y sus barras, y sus columnas, y sus basas y todas sus alhajas con todo su servicio;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Y las columnas del patio en derredor, y sus basas, y sus estacas, y sus cuerdas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, '¶ Y los que asentarán delante del tabernáculo al oriente, delante del tabernáculo del testimonio al levante, serán Moisés, y Aarón, y sus hijos teniendo la guarda del santuario por la guarda de los hijos de Israel: y el extraño que se llegare, morirá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Todos los contados de los Levitas, que contó Moisés, y Aarón, conforme a la palabra de Jehová, por sus familias, todos los varones de un mes y arriba fueron veinte y dos mil.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, '¶ Y Jehová dijo a Moisés: Cuenta todos los primogénitos varones de los hijos de Israel de un mes y arriba, y toma la cuenta de los nombres de ellos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Y tomarás los Levitas para mí, yo Jehová, en lugar de todos los primogénitos de los hijos de Israel: y los animales de los Levitas en lugar de todos los primogénitos de los animales de los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Y contó Moisés, como Jehová le mandó, todos los primogénitos de los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Y fueron todos los primogénitos varones, conforme a la cuenta de los nombres, de un mes y arriba, conforme a su cuenta, veinte y dos mil y doscientos y setenta y tres.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Ítem, habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Toma los Levitas en lugar de todos los primogénitos de los hijos de Israel, y los animales de los Levitas en lugar de sus animales, y los Levitas serán míos: yo Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Y por los rescates de los doscientos y setenta y tres, que sobrepujan a los Levitas los primogénitos de los hijos de Israel,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Tomarás cinco siclos por cabeza; conforme al siclo del santuario tomarás, el siclo veinte óbolos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Y aquel dinero darás a Aarón, y a sus hijos, por los rescates de los que de ellos sobran.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Y Moisés tomó el dinero del rescate de los que sobraron de más de los redimidos de los Levitas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Y recibió de los primogénitos de los hijos de Israel en dinero mil y trescientos y sesenta y cinco siclos, conforme al siclo del santuario.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Y Moisés dio el dinero de los rescates a Aarón y a sus hijos conforme al dicho de Jehová, de la manera que Jehová había mandado a Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Y habló Jehová a Moisés y a Aarón, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Toma la cuenta de los hijos de Caat de entre los hijos de Leví, por sus familias, por las casas de sus padres.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'De edad de treinta años y arriba hasta cincuenta años, todos los que entran en compañía para hacer obra en el tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Este será el oficio de los hijos de Caat en el tabernáculo del testimonio, en el lugar santísimo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Cuando se hubiere de mudar el campo, vendrá Aarón, y sus hijos, y desarmarán el velo de la tienda, y cubrirán con él el arca del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Y pondrán sobre ella la cobertura de pieles de tejones, y extenderán encima el paño todo de cárdeno, y ponerle han sus barras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Y sobre la mesa de la proposición extenderán el paño cárdeno, y pondrán sobre ella las escudillas, y los cucharones, y los tazones, y las cubiertas, y el pan continuo estará sobre ella.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Y extenderán sobre ello el paño de carmesí colorado, y cubrirlo han con la cubierta de pieles de tejones, y ponerle han sus barras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Y tomarán el paño cárdeno, y cubrirán el candelero de la luminaria, y sus candilejas, y sus despabiladeras, y sus paletas, y todos sus vasos del aceite con que se sirve.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Y ponerlo han con todos sus vasos en la cubierta de pieles de tejones, y ponerlo han sobre las barras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Y sobre el altar de oro extenderán el paño cárdeno, y cubrirlo han con la cubierta de pieles de tejones, y ponerle han sus barras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Y tomarán todos los vasos de servicio, de que se sirven en el santuario, y ponerlos han en el paño cárdeno, y cubrirlos han con la cubierta de pieles de tejones, y ponerlos han sobre las barras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Y quitarán la ceniza del altar, y extenderán sobre él el paño de púrpura.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Y pondrán sobre él todos sus instrumentos de que se sirve: las paletas, los garfios, los braseros, y los tazones, todos los vasos del altar: y extenderán sobre él la cobertura de pieles de tejones, y ponerlo han sobre las barras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Y en acabando Aarón y sus hijos de cubrir el santuario, y todos los vasos del santuario, cuando el campo se hubiere de mudar, vendrán después así los hijos de Caat para llevar: y no tocarán el santuario, que morirán. Estas serán las cargas de los hijos de Caat en el tabernáculo del testimonio:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Empero al cargo de Eleazar, hijo de Aarón el sacerdote, será el aceite de la luminaria, y el perfume aromático, y el presente continuo, y el aceite de la unción: el cargo de todo el tabernáculo, y de todo lo que está en él, en el santuario y en sus vasos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Ítem, habló Jehová a Moisés, y a Aarón, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'No cortaréis la tribu de las familias de Caat de entre los Levitas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Mas esto haréis con ellos, para que vivan, y no mueran: Cuando llegaren al lugar santísimo, vendrán Aarón y sus hijos, y ponerlos han a cada uno en su oficio y en su cargo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'No entrarán para ver, cuando cubrieren las cosas santas, que morirán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Ítem, habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Toma la cuenta de los hijos de Gersón también a ellos por las casas de sus padres, por sus familias:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'De edad de treinta años y arriba, hasta cincuenta años los contarás, todos los que entran en compañía para hacer obra en el tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Este será el oficio de las familias de Gersón para ministrar, y para llevar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Llevarán las cortinas del tabernáculo, y el tabernáculo del testimonio, su cobertura, y la cubierta de pieles de tejones, que está sobre él encima, y el pabellón de la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'Y las cortinas del patio, y el pabellón de la puerta del patio, que está sobre el tabernáculo, y sobre el altar al derredor, y sus cuerdas, y todos los instrumentos de su servicio, y todo lo que será hecho para ellos, y servirán.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Conforme al dicho de Aarón y de sus hijos será todo el ministerio de los hijos de Gersón en todas sus cargas, y en todo su servicio: y encomendarles heis en guarda todas sus cargas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Este es el servicio de las familias de los hijos de Gersón en el tabernáculo del testimonio: y la guarda de ellos será por mano de Itamar, hijo de Aarón sacerdote.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Los hijos de Merari, contarlos has por sus familias, por las casas de sus padres;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Desde el que es de edad de treinta años y arriba, hasta el que es de edad de cincuenta años, los contarás, todos los que entran en compañía para hacer obra en el tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Y esta será la guarda de su cargo para todo su servicio en el tabernáculo del testimonio: Las tablas del tabernáculo, y sus barras, y sus columnas, y sus basas:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'Ítem, las columnas del patio al derredor, y sus basas, y sus estacas, y sus cuerdas, con todos sus instrumentos, y todo su servicio: y contaréis por sus nombres todos los vasos de la guarda de su cargo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Este será el servicio de las familias de los hijos de Merari para todo su ministerio en el tabernáculo del testimonio por mano de Itamar, hijo de Aarón el sacerdote.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, '¶ Y contó Moisés y Aarón y los príncipes de la congregación a los hijos de Caat por sus familias, y por las casas de sus padres,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Desde el de edad de treinta años y arriba, hasta el de edad de cincuenta años, todos los que entran en compañía para ministrar en el tabernáculo del testimonio:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Y fueron los contados de ellos por sus familias dos mil y sietecientos y cincuenta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Estos fueron los contados de las familias de Caat: todos los que ministran en el tabernáculo del testimonio, los cuales contaron Moisés y Aarón como lo mandó Jehová, por mano de Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Y los contados de los hijos de Gersón por sus familias, y por las casas de sus padres,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'Desde el de edad de treinta años y arriba, hasta el de edad de cincuenta años, todos los que entran en compañía para ministrar en el tabernáculo del testimonio,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Los contados de ellos por sus familias, por las casas de sus padres, fueron dos mil y seiscientos y treinta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Estos son los contados de las familias de los hijos de Gersón, todos los que ministran en el tabernáculo del testimonio, los cuales contaron Moisés y Aarón por mandado de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Y los contados de las familias de los hijos de Merari por sus familias, por las casas de sus padres,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'Desde el de edad de treinta años y arriba, hasta el de edad de cincuenta años, todos los que entran en compañía para ministrar en el tabernáculo del testimonio,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Los contados de ellos por sus familias fueron tres mil y doscientos.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Estos fueron los contados de las familias de los hijos de Merari, los cuales contaron Moisés y Aarón como lo mandó Jehová, por la mano de Moisés.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Todos los contados de los Levitas, que contaron Moisés y Aarón, y los príncipes de Israel por sus familias, y por las casas de sus padres,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'Desde el de edad de treinta años y arriba, hasta el de edad de cincuenta años, todos los que entraban para servir en el servicio, y tener cargo de obra en el tabernáculo del testimonio,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Los contados de ellos fueron ocho mil y quinientos y ochenta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Como lo mandó Jehová por mano de Moisés fueron contados, cada uno según su oficio, y según su cargo, los cuales él contó como le fue mandado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Ítem, Jehová habló a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Manda a los hijos de Israel que echen del campo a todo leproso y a todos los que padecen flujo de simiente, y a todo contaminado sobre muerto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Así hombres como mujeres echaréis: fuera del campo los echaréis, porque no contaminen el campo de aquellos entre los cuales yo habito.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Y los hijos de Israel lo hicieron así, que los echaron fuera del campo: como Jehová dijo a Moisés, así lo hicieron los hijos de Israel.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, '¶ Ítem, habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Habla a los hijos de Israel: El hombre o la mujer que hicieren alguno de todos los pecados de los hombres, haciendo prevaricación contra Jehová, y pecare aquella persona,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Confesarán sus pecados que hicieron, y restituirán su culpa enteramente, y añadirán su quinto sobre ello, y darlo han a aquel contra quien pecaron.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Y si aquel varón no tuviere redentor al cual el delito sea restituido, el delito se restituirá a Jehová, al sacerdote, allende del carnero de las expiaciones con el cual lo expiará.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Y toda ofrenda de todas las santificaciones, que los hijos de Israel ofrecieren al sacerdote, suya será.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Y lo santificado de cualquiera, suyo será: y lo que cualquiera diere al sacerdote, suyo será.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, '¶ Ítem, Jehová habló a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Habla a los hijos de Israel, y díles: Cuando la mujer de alguno errare, e hiciere traición contra él,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'Que alguno se hubiere echado con ella por ayuntamiento de simiente, y su marido no lo hubiere visto por haberse ella contaminado ocultamente, ni hubiere testigo contra ella, ni ella hubiere sido tomada,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Si viniere sobre él espíritu de celo, y tuviere celos de su mujer, habiéndose ella contaminado; o viniere sobre él espíritu de celo, y tuviere celos de su mujer, no habiéndose ella contaminado;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Entonces el marido traerá su mujer al sacerdote, y traerá su ofrenda con ella, una diezma de un efa de harina de cebada: no echará sobre ella aceite, ni pondrá sobre ella incienso; porque es presente de celos, presente de recordación, que trae en memoria pecado:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Y el sacerdote la hará llegar, y la hará poner delante de Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Y tomará el sacerdote del agua santa en un vaso de barro; y tomará también el sacerdote del polvo que hubiere en el suelo del tabernáculo, y echarlo ha en el agua:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Y hará el sacerdote estar en pie a la mujer delante de Jehová, y descubrirá la cabeza de la mujer, y pondrá sobre sus manos el presente de la recordación, que es el presente de celos, y el sacerdote tendrá en la mano las aguas amargas malditas;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Y el sacerdote la conjurará y la dirá: Si ninguno hubiere dormido contigo, y si no te has apartado de tu marido a inmundicia, sé limpia de estas aguas amargas malditas;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Mas si te has apartado de tu marido, y te has contaminado, y alguno hubiere puesto en ti su simiente fuera de tu marido;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'El sacerdote conjurará a la mujer de conjuro de maldición, y dirá a la mujer: Jehová te dé en maldición, y en conjuración en medio de tu pueblo, haciendo Jehová a tu muslo que caiga, y a tu vientre que se te hinche,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Y estas aguas malditas entren en tus entrañas, y hagan hinchar tu vientre, y caer tu muslo. Y la mujer dirá, Amén, Amén.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Y el sacerdote escribirá estas maldiciones en un libro, y desleirlas ha con las aguas amargas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Y dará a beber a la mujer las aguas amargas malditas, y las aguas malditas entrarán en ella por amargas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Y tomará el sacerdote de la mano de la mujer el presente de los celos, y mecerlo ha delante de Jehová, y ofrecerlo ha delante del altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Y el sacerdote tomará un puño del presente en memoria de ella, y hará perfume de ello sobre el altar, y después dará a beber las aguas a la mujer.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Y darle ha a beber las aguas; y será, que si fuere inmunda, y hubiere hecho traición contra su marido, las aguas malditas entrarán en ella en amargura, y su vientre se hinchará, y su muslo caerá; y la tal mujer será por maldición en medio de su pueblo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Mas si la mujer no fuere inmunda, mas fuere limpia, ella será libre, y asementará simiente.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Esta es la ley de los celos, cuando la mujer errare en poder de su marido, y se contaminare:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'O, del marido, sobre el cual pasare espíritu de celo, y tuviere celos de su mujer, y la presentare delante de Jehová; el sacerdote la hará toda esta ley.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Y aquel varón será libre de iniquidad, y la mujer llevará su pecado.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Y habló Jehová a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Habla a los hijos de Israel, y díles: El hombre, o la mujer, cuando se apartare haciendo voto de Nazareo, para apartarse a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Apartarse ha de vino y de sidra: vinagre de vino, ni vinagre de sidra no beberá, ni beberá algún licor de uvas, ni tampoco comerá uvas frescas ni secas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Todo el tiempo de su Nazareato, de todo lo que se hace de vid de vino, desde los granillos hasta el hollejo, no comerá.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Todo el tiempo del voto de su Nazareato no pasará navaja sobre su cabeza, hasta que sean cumplidos los días de su apartamiento a Jehová: santo será, dejará crecer las guedejas del cabello de su cabeza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Todo el tiempo que se apartare a Jehová, no entrará a persona muerta.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Sobre su padre, ni sobre su madre, sobre su hermano, ni sobre su hermana, no se contaminará con ellos cuando murieren; porque consagración de su Dios tiene sobre su cabeza.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Todo el tiempo de su Nazareato será santo a Jehová.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Y si alguno muriere de súbito junto a él, contaminará la cabeza de su Nazareato: por tanto el día de su purificación raerá su cabeza: al séptimo día la raerá:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Y el día octavo traerá dos tórtolas, o dos palominos al sacerdote, a la puerta del tabernáculo del testimonio:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Y el sacerdote hará el uno en expiación y el otro en holocausto: y expiarlo ha de lo que pecó sobre el muerto, y santificará su cabeza en aquel día:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Y consagrará a Jehová los días de su Nazareato, y traerá un cordero de un año en expiación por la culpa, y los días primeros serán anulados, por cuanto fue contaminado su Nazareato.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, '¶ Esta es pues la ley del Nazareo: El día que se cumpliere el tiempo de su Nazareato, vendrá a la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Y ofrecerá por su ofrenda a Jehová un cordero sin tacha de un año en holocausto, y una cordera sin defecto de un año en expiación, y un carnero perfecto por paces.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Ítem, un canastillo de cenceñas, tortas de flor de harina amasadas con aceite, y hojaldres cenceñas untadas con aceite, y su presente, y sus derramaduras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Y el sacerdote lo ofrecerá delante de Jehová, y hará su expiación y su holocausto.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Y hará el carnero en sacrificio de paces a Jehová, con el canastillo de las cenceñas: hará asimismo el sacerdote su presente, y sus derramaduras.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Entonces el Nazareo raerá a la puerta del tabernáculo del testimonio la cabeza de su Nazareato; y tomará los cabellos de la cabeza de su Nazareato, y ponerlos ha sobre el fuego, que está debajo del sacrificio de las paces.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Después tomará el sacerdote la espalda cocida del carnero, y una torta sin levadura del canastillo, y una hojaldre sin levadura, y ponerlo ha sobre las manos del Nazareo, después que fuere raído su Nazareato.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Y mecerlo ha de mecedura el sacerdote delante de Jehová, lo cual será santidad para el sacerdote allende del pecho de la mecedura, y de la espalda de la apartadura: y después beberá vino el Nazareo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Esta es la ley del Nazareo, que hiciere voto de su ofrenda a Jehová por su Nazareato, allende de lo que su mano alcanzare: según el voto que hiciere, así hará conforme a la ley de su Nazareato.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Ítem, Jehová habló a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, '¶ Habla a Aarón, y a sus hijos, y díles: Así bendeciréis a los hijos de Israel, diciéndoles:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Jehová te bendiga, y te guarde:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Haga resplandecer Jehová su rostro sobre ti, y haya de ti misericordia:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Jehová alce a ti su rostro, y ponga en ti paz.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Y pondrán mi nombre sobre los hijos de Israel, y yo los bendeciré.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Y aconteció, que cuando Moisés, hubo acabado de levantar el tabernáculo; y ungídolo, y santificádolo con todos sus vasos; asimismo el altar con todos sus vasos, y ungídolos, y santificádolos;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Entonces los príncipes de Israel, las cabezas de las casas de sus padres, los cuales eran los príncipes de las tribus que estaban sobre los contados, ofrecieron:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Y trajeron sus ofrendas delante de Jehová seis carros cubiertos, y doce bueyes, cada dos príncipes un carro, y cada uno un buey, lo cual ofrecieron delante del tabernáculo.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Y Jehová habló a Moisés, diciendo:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Tóma lo de ellos, y será para el servicio del tabernáculo del testimonio: y darlo has a los Levitas, a cada uno conforme a su ministerio.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Entonces Moisés recibió los carros y los bueyes, y diólo a los Levitas.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Dos carros y cuatro bueyes dio a los hijos de Gersón, conforme a su ministerio:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Y los cuatro carros y ocho bueyes dio a los hijos de Merari conforme a su ministerio debajo de la mano de Itamar, hijo de Aarón sacerdote.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Y a los hijos de Caat no dio nada, porque llevaban sobre sí en los hombros el servicio del santuario.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, '¶ Y ofrecieron los príncipes a la dedicación del altar el día que fue ungido, ofrecieron los príncipes su ofrenda delante del altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Y Jehová dijo a Moisés: El un príncipe un día, y el otro príncipe otro día, ofrecerán su ofrenda a la dedicación del altar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Y el que ofreció su ofrenda el primer día fue Nahasón, hijo de Amminadab de la tribu de Judá:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Y fue su ofrenda, un plato de plata de peso de ciento y treinta siclos, y un jarro de plata de setenta siclos, al siclo del santuario, ambos llenos de flor de harina amasada con aceite para presente:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Un cucharón de oro de diez siclos lleno de perfume,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Un becerro hijo de vaca, un carnero, un cordero de un año para holocausto;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Un macho de cabrío para expiación;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'Y para sacrificio de paces dos bueyes, cinco carneros, cinco machos cabríos, cinco corderos de un año. Esta fue la ofrenda de Nahasón, hijo de Amminadab.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'El segundo día ofreció Natanael, hijo de Suar, príncipe de Isacar:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Ofreció por su ofrenda, un plato de plata de ciento y treinta siclos de peso, un jarro de plata de setenta siclos, al siclo del santuario, ambos llenos de flor de harina amasada con aceite para presente:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Un cucharón de oro de diez siclos lleno de perfume,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Un becerro hijo de vaca, un carnero, un cordero de un año para holocausto;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Un macho de cabrío para expiación;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'Y para sacrificio de paces, dos bueyes, cinco carneros, cinco machos cabríos, cinco corderos de un año. Esta fue la ofrenda de Natanael, hijo de Suar.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'El tercero día, el príncipe de los hijos de Zabulón, Eliab, hijo de Helón:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Y fue su ofrenda, un plato de plata de ciento y treinta siclos de peso, un jarro de plata de setenta siclos, al siclo del santuario, ambos llenos de flor de harina amasada con aceite para presente:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'Un cucharón de oro de diez siclos lleno de perfume,');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'Un becerro hijo de vaca, un carnero, un cordero de un año para holocausto;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'Un macho de cabrío para expiación;');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'Y para sacrificio de paces, dos bueyes, cinco carneros, cinco machos cabríos, cinco corderos, de un año. Esta fue la ofrenda de Eliab, hijo de Helón.');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'El cuarto día, el príncipe de los hijos de Rubén, Elisur, hijo de Sedeur:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Y fue su ofrenda, un plato de plata de ciento y treinta siclos de peso, un jarro de plata de setenta siclos, al siclo del santuario, ambos llenos de flor de harina amasada con aceite para presente:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'Un cucharón de oro de diez siclos lleno de perfume.');
