INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'El décimo día el príncipe de los hijos de Dan, Ahiezer, hijo de Ammisaddai:');
INSERT INTO `SpaRV1865_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Y fue su ofrenda, un plato de plata de ciento y treinta siclos de peso, un jarro de plata de setenta siclos, al siclo del santuario, ambos llenos de flor de harina amasada con aceite para presente:');
